INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('0ff2858d-02b4-43fd-82bc-35d0aef6ba33', 86, 'Segreti di produzione', 'Il guardaroba di fortuna di Stallone', 'Nel primo atto del film, quando Rambo indossa il celebre poncho antipioggia strappato, non si trattava di un capo sartoriale elaborato. La costumista del film ricavò quel pezzo iconico tagliando e bruciacchiando un normale telo di plastica per la spazzatura trovato sul set a Hope.', 'Special TV Making of Rambo: First Blood del 1982', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:08.789648+00:00'),
('b5f226e5-c3cc-4790-bbb5-98ab58a472ae', 86, 'Casting & Scelte', 'Kirk Douglas sostituito all''ultimo minuto', 'Il ruolo del Colonnello Samuel Trautman fu originariamente assegnato a Kirk Douglas, che girò persino alcune scene nei primi giorni di produzione. Tuttavia, a causa di divergenze artistiche con Stallone sul finale del film e sul destino del protagonista, Douglas abbandonò il set e fu prontamente sostituito da Richard Crenna.', 'Autobiografia di Kirk Douglas e interviste storiche a Ted Kotcheff', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:08.789648+00:00'),
('edf0a687-8a09-413e-830b-39b27b94261e', 86, 'Curiosità & Retroscena', 'L''ipotetico finale originale con il suicidio', 'Il film avrebbe dovuto seguire fedelmente il romanzo di David Morrell, in cui Rambo muore suicida facendosi uccidere da Trautman. Dopo aver proiettato questa versione ai primi test audience, la reazione del pubblico fu talmente negativa che Stallone e il regista decisero di rigirare d''urgenza il finale, salvando il personaggio per i sequel.', 'Archivi di test screening della Orion Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:08.789648+00:00'),
('01879ad1-f780-46e0-b69e-d2b319e80a22', 86, 'Aneddoti dal set', 'Il maiale e le fiamme nel bosco', 'Nella drammatica scena in cui Rambo viene interrogato nella stazione di polizia e i poliziotti usano un rasoio elettrico per intimidirlo, il panico dell''attore era parzialmente reale poiché la lama del rasoio era vera e funzionante, sebbene schermata per evitare tagli profondi. Inoltre, lo svenimento olfattivo dell''attore fu accentuato dal forte odore di ammoniaca usato per simulare i prodotti di pulizia.', 'Intervista d''archivio a Brian Dennehy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:08.789648+00:00'),
('a12d9ff3-2902-43ab-a4c4-7b879d523840', 91, 'Casting & Scelte', 'Il debutto cinematografico di John Lithgow', 'Il film segna l''esordio sul grande schermo per John Lithgow, nel ruolo del socio in affari Robert La Salle, un''interpretazione che diede ufficialmente il via alla sua fortunata carriera cinematografica a Hollywood.', 'Note di produzione e biografia ufficiale dell''attore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:27.925148+00:00'),
('f574419c-9d9b-4784-a4c2-c3b923b635f7', 91, 'Curiosità & Retroscena', 'La scelta della locazione fiorentina', 'Le riprese italiane si svolsero principalmente a Firenze, sfruttando la suggestiva cornice di Piazza della Signoria e della Basilica di San Miniato al Monte, luoghi chiave per ricreare la stessa atmosfera della San Francisco di ''Vertigo''.', 'Archivio storico della produzione e resoconti di lavorazione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:27.925148+00:00'),
('5a212ac0-502a-46b9-ab92-21eaae97eddf', 91, 'Segreti di produzione', 'La sfida della colonna sonora di Bernard Herrmann', 'Bernard Herrmann compose una partitura orchestrale imponente e intensamente romantica, considerata da molti una delle sue vette artistiche, che ottenne una nomination postuma agli Oscar come Miglior Colonna Sonora.', 'Archivio ufficiale dell''Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:27.925148+00:00'),
('13905bf3-db31-46fa-aedf-24fc37b04edf', 91, 'Aneddoti dal set', 'Il rapporto complesso tra Brian De Palma e Bernard Herrmann', 'Brian De Palma ha spesso raccontato di come Bernard Herrmann fosse estremamente esigente durante le sessioni di registrazione della colonna sonora, arrivando a pretendere precisioni millimetriche sincronizzate con i movimenti di macchina.', 'Interviste audio di Brian De Palma nei contenuti speciali home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:27.925148+00:00'),
('0acd435e-1f79-49c3-803c-1ca6fc538fbf', 103, 'Casting & Scelte', 'La preparazione estrema di Daniel Day-Lewis', 'Per prepararsi al ruolo di Occhio di Falco, Daniel Day-Lewis visse per settimane nei boschi della Carolina del Nord prima delle riprese, imparando a cacciare, scuoletare animali, costruire canoe e a usare un moschetto di tipo Kentucky a avancarica in ogni condizione atmosferica.', 'Documentario ufficiale ''The Making of The Last of the Mohicans''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:00.569655+00:00'),
('6b7783a6-959e-40f3-b47f-4f87888f9b13', 103, 'Casting & Scelte', 'L''addio di Bruce Willis al ruolo principale', 'Prima che Daniel Day-Lewis fosse scritturato, gli studios avevano considerato diversi attori di primo piano per la parte di Nathaniel Poe, tra cui Bruce Willis, che fu valutato nei primi stadi di sviluppo del progetto prima che la produzione virasse verso un approccio più storico e autoriale.', 'Archivi di casting di Hollywood e biografie di Michael Mann', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:00.569655+00:00'),
('15d21013-26f2-43b6-bd16-58a356dc555b', 103, 'Segreti di produzione', 'La riproduzione accurata delle armi storiche', 'Il dipartimento di armeria guidato da Simon Atherton realizzò repliche esatte dei fucili, dei tomahawk e delle pistole a pietra focaia del 1757, consultando storici militari e musei canadesi per garantire che ogni dettaglio balistico e visivo fosse coerente con l''epoca.', 'Articolo di American Rifleman sulla produzione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:00.569655+00:00'),
('6076ba18-cac6-4f0a-8905-5dcce93c890b', 103, 'Aneddoti dal set', 'Le difficoltà climatiche sul set delle cascate', 'La celebre sequenza della cascata fu girata nei pressi del fiume Du Chute e delle cascate di Pisgah in condizioni meteorologiche proibitive, con temperature gelide che costrinsero la troupe a utilizzare mute termiche nascoste sotto i costumi d''epoca per gli attori nelle scene in acqua.', 'Commento audio del regista Michael Mann nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:00.569655+00:00'),
('82574d2b-5fc8-4a0e-a235-e9dd1f37be5f', 103, 'Curiosità & Retroscena', 'La sostituzione del montaggio originale', 'Michael Mann fu costretto a rimontare drasticamente il film a ridosso dell''uscita cinematografica a causa delle insistenze della 20th Century Fox, arrivando a produrre diverse versioni che portarono il regista a rilasciare un Director''s Cut definitivo nel 2010 per ripristinare la sua visione originale.', 'Note storiche sul montaggio e comunicati stampa della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:00.569655+00:00'),
('47c1483c-72e2-47b3-bae8-56c14b87f4be', 87, 'Casting & Scelte', 'La riscrittura di James Cameron', 'La prima bozza della sceneggiatura fu scritta da James Cameron, il quale aveva inserito un compagno spalla di nome Eric e un tono molto più orientato alla fantascienza d''azione. Sylvester Stallone riscrisse ampiamente il copione rimuovendo la spalla comica/action e concentrando tutta la centralità sul dramma solitario di Rambo.', 'Interviste d''archivio di James Cameron e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:13.999462+00:00'),
('f2ca3eb4-182f-424a-977f-258612a1e7a6', 87, 'Casting & Scelte', 'Il rifiuto del ruolo di Co Bao da parte di altre attrici', 'Prima di affidare la parte della guerrigliera Co Bao a Julia Nickson, la produzione valutò diverse giovani attrici asiatiche e americane di origine asiatica. Alcune rinunciarono a causa dei rigidi impegni di ripresa nella giungla messicana, considerati troppo faticosi e isolati.', 'Documentario sul casting del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:13.999462+00:00'),
('cc81c77f-63eb-47c4-908c-b9137d58ee13', 87, 'Aneddoti dal set', 'Le riprese nella giungla messicana e i problemi di salute', 'Le riprese si svolsero a Guerrero, in Messico, dove la troupe e il cast dovettero affrontare temperature elevatissime, umidità estrema e problemi legati alla dissenteria. Lo stesso Sylvester Stallone si ammalò durante le sequenze nel fiume, ma continuò a girare per non rallentare la tabella di marcia.', 'Making-of ufficiale ''We Get to Win This Time''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:13.999462+00:00'),
('39cb84a8-b1e2-4a05-b074-48df5d992b6b', 87, 'Segreti di produzione', 'L''uso dei pirotecnici e il rispetto per i luoghi', 'Gli esplosivi e le cariche pirotecniche usate per simulare i bombardamenti nella giungla furono rigorosamente controllati da esperti militari per evitare danni ecologici permanenti nell''area protetta messicana scelta come location. Molti alberi finti in schiuma furono aggiunti per essere fatti esplodere al posto della vegetazione reale.', 'Note di produzione e reparti speciali effetti pirotecnici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:13.999462+00:00'),
('7e492da4-51c0-4c57-bf45-e99e052a1e8d', 87, 'Curiosità & Retroscena', 'L''ispirazione per il titolo originale e politico', 'Il titolo originale del film, ''Rambo: First Blood Part II'', fu fortemente voluto per collegarsi direttamente al primo film, ma rifletteva anche il clima politico dell''era Reagan riguardo alla questione irrisolta dei prigionieri di guerra dispersi in Vietnam.', 'Archivio storico di Hollywood e recensioni dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:13.999462+00:00'),
('20e24759-5f05-4283-ab65-7823ef1d6f7d', 87, 'Citazioni & Easter Egg', 'Il brano musicale vincitore e i Razzie Awards', 'Nonostante il grande successo commerciale e la candidatura all''Oscar per la migliore canzone originale ''Peace in Our Life'', il film ottenne anche diverse nomination e premi ai Razzie Awards, inclusi peggior film e peggior attore per Sylvester Stallone, evidenziando la spaccatura della critica dell''epoca.', 'Database ufficiale dei Razzie Awards e Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:13.999462+00:00'),
('9e533b4b-1dc6-4257-b7d2-5e2656d40f57', 87, 'Effetti speciali & Trucco', 'L''elicottero sovietico fittizio', 'Il temibile elicottero d''attacco sovietico Mi-24 Hind pilotato dai cattivi nel film non era un vero velivolo sovietico, bensì un elicottero americano modificato con pannelli in fibra di vetro, ali finte e armamenti posticci per ingannare lo spettatore.', 'Commento audio del regista George P. Cosmatos', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:40:13.999462+00:00'),
('f4757398-f1f9-4ab9-96fb-9b2782f387d0', 87, 'Segreti di produzione', 'Il coltello iconico disegnato da Jimmy Lile', 'Il celebre coltello da sopravvivenza usato da Rambo in questo capitolo fu appositamente progettato e realizzato dal celebre coltellinaio Jimmy Lile. Rispetto al primo film, la lama fu resa più lunga e robusta per riflettere la natura più aggressiva e militare della missione.', 'Cataloghi ufficiali di memorabilia cinematografica e interviste a Jimmy Lile', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:40:13.999462+00:00'),
('44ac3858-a600-41b7-90f7-a2c1617e68d3', 92, 'Casting & Scelte', 'La sostituzione last-minute di Anna Magnani', 'Inizialmente Luchino Visconti aveva pensato ad Anna Magnani per il ruolo della protagonista Giovanna Bragana. L''attrice dovette tuttavia rifiutare la parte a causa della sua gravidanza avanzata, portando alla scelta di Clara Calamai.', 'Biografie storiche e memorie di Luchino Visconti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:31.419442+00:00'),
('a1b6f334-1e82-43f5-b264-c629f0b82c6f', 92, 'Curiosità & Retroscena', 'La censura fascista e la furia dei produttori', 'Il film urtò profondamente la sensibilità del regime fascista per la rappresentazione cruda, misera e disperata dell''Italia popolare. Alla prima proiezione a Roma, il Vittorio Mussolini ufficiale del regime pare sia fuggito indignato gridando allo scandalo.', 'Documenti storici d''archivio e recensioni dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:31.419442+00:00'),
('856a4e70-a631-4e3f-be10-67ed3bf83d0e', 92, 'Segreti di produzione', 'La distruzione delle copie da parte del regime', 'Verso la fine della guerra, il regime cercò di sequestrare e distruggere i negativi di ''Ossessione''. La pellicola fu salvata grazie a stratagemmi rocamboleschi, nascondendo bobine in luoghi sicuri per evitarne la perdita definitiva.', 'Studi di storia del cinema italiano e retroscena della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:31.419442+00:00'),
('6a9d5ac0-b382-4573-814c-6ef32ef2bf64', 111, 'Casting & Scelte', 'Il rifiuto di Matthew McConaughey per il ruolo di Jack', 'Prima che la parte di Jack Dawson fosse affidata a Leonardo DiCaprio, James Cameron aveva fortemente considerato Matthew McConaughey per il ruolo principale maschile. L''attore fece anche un provino ufficiale insieme a Kate Winslet, ma lo studio preferì puntare su DiCaprio.', 'Dichiarazioni pubbliche di Kate Winslet e Matthew McConaughey in vari talk show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:16.395705+00:00'),
('15811544-2c20-41d6-bdc3-a82e6c05ff72', 111, 'Casting & Scelte', 'Gwyneth Paltrow e le trattative per Rose', 'Prima che Kate Winslet ottenesse la parte di Rose DeWitt Bukater dopo una campagna assidua fatta di lettere e chiamate al regista, la produzione offrì inizialmente il ruolo a Gwyneth Paltrow, la quale declinò l''offerta per altri impegni cinematografici.', 'Interviste retrospettive di Gwyneth Paltrow e note di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:16.395705+00:00'),
('d53af0e5-f90b-48c7-8ba3-23f5c88374d2', 111, 'Segreti di produzione', 'La vera mano nei disegni di Jack', 'I disegni che Jack realizza nel film, incluso il celebre ritratto nudo di Rose, non sono stati opera di Leonardo DiCaprio. L''autore reale di tutti i bozzetti presenti nel portfolio di Jack fu il regista James Cameron in persona, che era un talentuoso disegnatore prima di dedicarsi al cinema.', 'Commento audio del regista nel DVD ufficiale e documentari sul making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:16.395705+00:00'),
('4719889b-61b5-4aba-b5f7-bf9bcbceda05', 367, 'Segreti di produzione', 'L''uso di lenti anamorfiche vintage per il Virgil', 'Per accentuare il senso di claustrofobia del Virgil, il direttore della fotografia ha utilizzato lenti anamorfiche Lomo degli anni ''70, modificate per ridurre la distanza minima di messa a fuoco e catturare i dettagli dei volti in spazi estremamente ristretti.', 'Note tecniche di produzione, Making-of ufficiale ''Inside the Virgil''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T16:14:40.167506+00:00'),
('81e29691-383e-4ed6-86ea-d25b28464849', 88, 'Curiosità & Retroscena', 'La modifica della dedica finale', 'Il film si chiudeva originariamente con una dedica ai ''coraggiosi combattenti della libertà dell''Afghanistan''. A seguito della fine della Guerra Fredda e degli eventi geopolitici successivi, la dedica fu modificata nelle riedizioni home video successive per evitare controversie politiche.', 'Note di produzione e recensioni retrospettive', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:17.24848+00:00'),
('b04687e5-c47b-42b3-aa40-dfe655ca58ef', 88, 'Segreti di produzione', 'L''uso massiccio dei veicoli modificati', 'Per simulare i mezzi corazzati sovietici in Afghanistan, la produzione modificò pesantemente veicoli commerciali e camion civili israeliani, aggiungendo finte torrette, corazze in vetroresina e cannoni posticci.', 'Documentario sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:17.24848+00:00'),
('44187f08-560e-448f-a57e-e837b97fda80', 88, 'Casting & Scelte', 'Il cameo mancato di Kurtwood Smith', 'L''attore Kurtwood Smith, noto per aver interpretato Clarence Boddicker in RoboCop, fu inizialmente considerato per il ruolo del malvagio supervisore sovietico Zaysen, prima che la parte venisse affidata a Marc de Jonge.', 'Archivi di casting di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:17.24848+00:00'),
('c5b2eaee-eb3b-48db-b087-bb5d7aaff515', 88, 'Aneddoti dal set', 'La tensione sul set con i veri elicotteri militari', 'Durante le riprese nel deserto, la produzione noleggiò elicotteri militari che venivano pilotati da ex membri dell''aeronautica. Le manovre a basse quota richieste dalla sceneggiatura generarono momenti di forte tensione per la sicurezza della troupe.', 'Interviste alla troupe nel documentario d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:17.24848+00:00'),
('fbd34056-9a2a-4af5-9e30-b91952bf5afd', 88, 'Curiosità & Retroscena', 'L''ispirazione geopolitica della sceneggiatura', 'Sylvester Stallone e il co-sceneggiatore Sheldon Lettich trassero ispirazione per la trama dai reportage giornalistici dell''epoca che documentavano la resistenza dei guerriglieri mujaheddin contro l''invasione sovietica.', 'Intervista a Sylvester Stallone per Cinefantastique', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:17.24848+00:00'),
('67f9c26f-8e20-421b-8c3f-af0d3b976182', 97, 'Curiosità & Retroscena', 'La censura sul costume di Iras', 'L''attrice Danielle Francis, che interpretava la cortigiana egiziana Iras, indossava costumi così succinti per l''epoca che la censura in diversi Stati americani e in Europa impose modifiche immediate o il taglio totale di alcune inquadrature per indecenza.', 'Note d''archivio della censura cinematografica degli anni Venti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:35.569484+00:00'),
('f2d77be6-b180-49cc-a03b-f772bf5a0451', 97, 'Aneddoti dal set', 'Le comparse di Cinecittà ante litteram', 'Durante le riprese romane presso gli stabilimenti della Fotofilm, la produzione assunse migliaia di veri soldati del Regio Esercito italiano come comparse per le scene di massa, garantendo una disciplina militare rigorosa ma creando non pochi problemi logistici per la lingua.', 'Memorie di produzione della Goldwyn Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:35.569484+00:00'),
('23f813a2-28c1-4405-8cf6-62bb256e49d6', 97, 'Aneddoti dal set', 'L''infortunio di Francis X. Bushman con i cavalli', 'Francis X. Bushman, che interpretava l''antagonista Messala, era un esperto cavallerizzo ma rischiò seriamente di essere calpestato dai suoi stessi cavalli arabi durante le prove preliminari della corsa delle bighe a Roma, a causa di un cedimento del terreno.', 'Autobiografia di Francis X. Bushman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:35.569484+00:00'),
('bbd1ed32-281d-41c7-8bd0-5c0687c9163e', 97, 'Segreti di produzione', 'La ricostruzione della Gerusalemme sul litorale laziale', 'Per evitare i costi proibitivi di una trasferta in Medio Oriente, la produzione fece costruire enormi e costose scenografie riproducenti la città di Gerusalemme e i palazzi di Pilato direttamente sulle spiagge di Anzio, sfruttando la luce naturale del litorale italiano.', 'Documentario storico sul cinema muto hollywoodiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:35.569484+00:00'),
('a6af2089-4e59-4738-8434-2846ecc7817d', 97, 'Effetti speciali & Trucco', 'Il trucco ortopedico per le comparse lebbrose', 'Per la toccante sequenza della valle dei lebbrosi, il reparto trucco guidato da specialisti dell''epoca utilizzò protesi in gesso e cere speciali applicate sui volti di decine di veri mutilati e disoccupati reclutati a Roma, ottenendo un realismo impressionante e raccapricciante per gli standard del muto.', 'Archivio storico degli effetti speciali della MGM', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:35.569484+00:00'),
('001ef9c1-362a-42d1-bd88-347cb3b8d84f', 97, 'Citazioni & Easter Egg', 'La colonna sonora sincronizzata di Carl Davis', 'Anche se il film nacque come opera muta con accompagnamento orchestrale dal vivo nel 1925, il celebre compositore Carl Davis realizzò nel 1988 una nuova partitura sinfonica ufficiale basata sui temi originali di William Axt, appositamente sincronizzata per le riedizioni in home video e televisive.', 'Note di copertina dell''edizione restaurata in home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:35.569484+00:00'),
('3deb3eb6-26b1-4d04-8a1e-16c9a095b444', 115, 'Casting & Scelte', 'Il ruolo di Mia Wallace scritto per Virginia Madsen', 'Quentin Tarantino aveva originariamente scritto il personaggio di Mia Wallace pensando a Virginia Madsen, ma l''attrice dovette rifiutare la parte. Successivamente furono considerate anche Michelle Pfeiffer, Daryl Hannah e Joan Cusack prima di affidare definitivamente il ruolo a Uma Thurman.', 'Intervista ufficiale di Quentin Tarantino e note di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:28.773081+00:00'),
('eb29e639-75b9-416b-bded-fce2f4a7fed4', 115, 'Effetti speciali & Trucco', 'La finta siringa di adrenalina', 'Durante la celebre e drammatica sequenza in cui Vincent Vega inietta l''adrenalina nel petto di Mia Wallace, John Travolta non ha affatto conficcato l''ago nel torace di Uma Thurman. Per motivi di sicurezza e per l''effetto scenico, la telecamera ha ripreso la scena al contrario: l''attore ha estratto la siringa dal petto con un movimento rapido, che è stato poi invertito in fase di montaggio.', 'Commento audio del regista e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:28.773081+00:00'),
('165b612b-3f07-4fd4-bf90-5783299c270c', 115, 'Aneddoti dal set', 'L''improvvisazione della Bibbia di Samuel L. Jackson', 'Il celebre passo biblico di Ezechiele 25:17 recitato da Jules Winnfield non è interamente tratto dalla vera Bibbia, ma fu in gran parte riscritto e riadattato dallo stesso Samuel L. Jackson insieme a Quentin Tarantino, fondendo versetti biblici con elementi tratti dai film di arti marziali di Sonny Chiba.', 'Intervista a Samuel L. Jackson sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:28.773081+00:00'),
('ec785dc4-252d-4976-b857-1e80765f44f6', 115, 'Segreti di produzione', 'Il braccio finto del portafoglio di Jules', 'Nel portafoglio di Jules Winnfield, reso celebre dalla scritta ''Bad Motherfucker'', vi era un riferimento diretto al film ''Shaft'' di Gordon Parks, ma durante la celebre rapina iniziale nella tavola calda, la pistola brandita da Samuel L. Jackson fu nascosta in un apposito supporto per non affaticare l''attore durante i lunghi piani sequenza.', 'Documentario di produzione Miramax', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:28.773081+00:00'),
('88f646fa-2cac-4d68-822b-643cdc15a827', 115, 'Citazioni & Easter Egg', 'La giacca di cuoio di Butch e l''omaggio a 8 e 1/2', 'La sequenza in cui il pugile Butch Coolidge cammina per strada con una giacca di cuoio è un omaggio visivo esplicito al capolavoro di Federico Fellini ''8 ½'', confermando la vasta cinefilia di Quentin Tarantino integrata nei dettagli di messa in scena.', 'Note di regia e analisi critica del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:28.773081+00:00'),
('71fcd74b-1569-4d1e-a86f-eb3347ba9cf6', 89, 'Aneddoti dal set', 'L''uso di veri rifugiati Karen come comparse', 'Per garantire il massimo realismo e rispettare la drammaticità del conflitto in corso, Sylvester Stallone ha scelto di ingaggiare come comparse veri rifugiati appartenenti all''etnia Karen, fuggiti dalle persecuzioni in Birmania e residenti nei campi profughi lungo il confine thailandese.', 'Documentario ''It''s a Long Road: Making of John Rambo''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:20.647115+00:00'),
('0a2e4c70-aa73-450e-bb98-22b8b2d15790', 89, 'Segreti di produzione', 'Proiettili veri e munizioni a salve', 'Durante le riprese delle scene d''azione nella giungla thailandese, la produzione ha impiegato centinaia di migliaia di colpi a salve, ma l''uso di armi autentiche ha richiesto la presenza costante di esperti balistici dell''esercito locale per evitare incidenti mortali.', 'Note di produzione Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:20.647115+00:00'),
('0ed429b6-8a1e-4993-81ce-a3a2cbc29b96', 89, 'Segreti di produzione', 'Il ritorno della mitragliatrice Browning M2', 'Il celebre climax in cui Rambo utilizza una mitragliatrice pesante Browning M2 calibro .50 montata su un furgone riprende fedelmente le specifiche tattiche della fine del secondo e del terzo capitolo della saga, ma con una cura artigianale nella gestione del rinculo modificato per la sicurezza di Stallone.', 'Commento audio del regista Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:20.647115+00:00'),
('5203d310-4c06-4994-9c71-582f53a448cf', 89, 'Casting & Scelte', 'Il rifiuto iniziale del ritorno di Rambo', 'Sylvester Stallone ha ammesso in diverse interviste promozionali di aver esitato a lungo prima di accettare di interpretare nuovamente il personaggio vent''anni dopo ''Rambo III'', temendo che il pubblico percepisse il film come un''operazione nostalgica fuori tempo massimo.', 'Intervista a Sylvester Stallone per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:20.647115+00:00'),
('ec95bbec-c974-4c4d-9ccb-6d087bd08b26', 89, 'Effetti speciali & Trucco', 'L''autenticità delle armi da taglio tradizionali', 'Il machete e i coltelli da combattimento utilizzati nel film non sono oggetti di scena in gomma o plastica per la maggior parte delle inquadrature ravvicinate, ma veri strumenti fabbricati da artigiani locali thailandesi specializzati in coltelleria tradizionale.', 'Special feature ''The Weaponry of Rambo'' nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:20.647115+00:00'),
('e47ec384-e1aa-47b1-989c-5519316111c1', 110, 'Aneddoti dal set', 'La finta ferrovia e il kilt', 'Durante le riprese delle scene di battaglia, una troupe televisiva girò un''inquadratura in cui compariva per errore un treno moderno sullo sfondo, poi rimosso in post-produzione. Inoltre, un persistente mito metropolitano sostiene che gli attori indossassero biancheria intima sotto i kilt, smentito però da diverse interviste del cast che confermano la rigorosa aderenza alla tradizione scozzese per motivi di realismo.', 'Commento audio del regista Mel Gibson nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:11.98799+00:00'),
('9bdd6e9a-c01d-48fb-bf37-f50b54320eff', 110, 'Casting & Scelte', 'Il rifiuto iniziale di Mel Gibson alla regia', 'Paramount Pictures voleva che Mel Gibson dirigesse il film solo a patto che interpretasse anche William Wallace, ma inizialmente l''attore aveva accettato di fare solo il regista perché si riteneva troppo adulto per la parte del protagonista ventenne. Dopo un lungo lavoro di convinzione da parte dei produttori, Gibson accettò il doppio ruolo, modificando parzialmente la percezione anagrafica del personaggio storico.', 'Documentario ''The Making of Braveheart'' (1995)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:11.98799+00:00'),
('a119d479-e1ae-47e6-8b24-3d008900d7f9', 110, 'Effetti speciali & Trucco', 'I cavalli meccanici nella carica di cavalleria', 'Per evitare maltrattamenti agli animali durante le violuste sequenze di carica e impatto delle battaglie, la produzione fece costruire appositi cavalli meccanici pesanti oltre 90 chili e spinti da motori pneumatici. Questi automi venivano impiegati nelle scene in cui i destrieri venivano travolti o caricati, garantendo la sicurezza delle comparse e rispettando i rigorosi standard della protezione animali.', 'Note di produzione e archivi della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:11.98799+00:00'),
('597ae229-9d64-490e-8f01-ee7d3fb9118b', 110, 'Casting & Scelte', 'Jason Patric e la parte sfumata', 'Prima che Mel Gibson si assicurasse il ruolo principale, l''attore Jason Patric fu seriamente preso in considerazione per interpretare William Wallace, arrivando a un passo dalla firma del contratto. Tuttavia, problemi di programmazione e divergenze artistiche fecero saltare l''accordo, aprendo la strada a Gibson sia dietro che davanti la macchina da presa.', 'Rivista Variety - Archivio casting 1994', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:11.98799+00:00'),
('c0d280c7-0daf-4802-ae26-1e2fb0b965b5', 110, 'Segreti di produzione', 'L''uso massiccio dei riservisti dell''esercito irlandese', 'Poiché le scene di massa richiedevano migliaia di comparse addestrate a muoversi in formazione e a usare le spade con una certa coordinazione, la produzione ingaggiò circa 1.600 membri della Riserva della Forza di Difesa Irlandese. I militari vennero integrati sul set come soldati inglesi e scozzesi, portando una disciplina impeccabile durante le complesse riprese coreografiche.', 'Intervista al produttore Bruce Davey per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:11.98799+00:00'),
('d6377c23-7a64-4210-80f3-2a8bcc8f9621', 110, 'Curiosità & Retroscena', 'Il taglio della censura per la violenza esplicita', 'Il montaggio originale consegnato da Mel Gibson alla Motion Picture Association of America (MPAA) ottenne inizialmente un severo divieto ai minori non accompagnati (NC-17) a causa della natura eccessivamente sanguinosa e brutale delle esecuzioni e dei duelli. Gibson dovette tagliare circa venti secondi di immagini splatter per ottenere il visto di censura R, necessario per la distribuzione commerciale nelle sale americane.', 'Archivi ufficiali MPAA e dichiarazioni di Mel Gibson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:41:11.98799+00:00'),
('65c7871d-a5fc-4929-9cec-d6a9572a9532', 116, 'Casting & Scelte', 'La sostituzione in corsa di Samantha Morton', 'Durante tutte le riprese sul set, Joaquin Phoenix ha recitato interamente le sue scene con l''attrice Samantha Morton, che si trovava fisicamente in una stanza isolata fuori campo a interpretare Samantha. Solo in fase di post-produzione, Spike Jonze si è reso conto che la dinamica necessitava di un cambiamento, decidendo di sostituire la Morton con Scarlett Johansson e rigirando/rimontando di fatto l''intero film basandosi sulla nuova voce.', 'Intervista ufficiale a Spike Jonze per Vulture', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:33.178631+00:00'),
('35f9226f-365a-496b-b77f-6bf180cb0126', 346, 'Curiosità & Retroscena', 'L''assenza della pioggia nel climax', 'Nonostante l''intera indagine si svolga in una città cupa e piovosa per riflettere il degrado morale, la lunga sequenza finale nel deserto alla luce del sole cocente fu voluta da Fincher per aumentare il senso di disagio, togliendo agli spettatori e ai protagonisti il riparo visivo della pioggia e delle ombre.', 'Intervista al direttore della fotografia Darius Khondji su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:07.969091+00:00'),
('8a3acb59-8e40-458b-878d-f7408f945eeb', 90, 'Casting & Scelte', 'Il cameo mancato di Jean-Claude Van Damme e le voci sui villain', 'Nelle prime fasi di sviluppo, prima che la trama si concentrasse sul traffico di esseri umani in Messico, circolarono voci non confermate su un possibile coinvolgimento di Jean-Claude Van Damme come antagonista principale, ipotesi poi smentita quando la produzione ha scelto Sergio Peris-Mencheta e Óscar Jaenada per i ruoli dei fratelli Martinez.', 'Report di produzione e interviste al casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:24.664259+00:00'),
('3565b0b1-df90-43a8-8f4f-37e974bb6878', 90, 'Citazioni & Easter Egg', 'Il tributo visivo a Taxi Driver attraverso i costumi', 'All''inizio del film, l''aspetto di John Rambo con la giacca militare sbiadita e l''aria disillusa è un chiaro omaggio visivo al Travis Bickle interpretato da Robert De Niro nel capolavoro di Martin Scorsese ''Taxi Driver'' del 1976.', 'Analisi visiva ufficiale e note della costumista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:24.664259+00:00'),
('e30f341a-2bc9-4eec-9297-e5d0c76488aa', 90, 'Segreti di produzione', 'L''uso estensivo delle pistole a salve modificate', 'Per garantire la massima sicurezza durante le sparatorie all''interno del ranch ricostruito, la troupe degli armaioli ha utilizzato repliche appositamente modificate per sparare colpi a salve ad altissima intensità, riducendo al minimo i rischi per le comparse ma mantenendo l''effetto visivo del rinculo reale.', 'Special sui reparti speciali del making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:24.664259+00:00'),
('5ca78b9e-ab54-47cf-812b-c0b572fd19ba', 90, 'Effetti speciali & Trucco', 'Il lavoro sui corpi contusi con il make-up prostetico', 'Per rendere credibili le ferite e le ecchimosi di Sylvester Stallone nel violento scontro finale, il reparto trucco guidato da Bill Corso ha impiegato protesi in silicone avanzate e sangue fittizio a base di sciroppo e coloranti testato per non macchiare i costumi di scena durante i ciak ripetuti.', 'Diario di bordo del reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:24.664259+00:00'),
('562a77a9-df1c-4471-88aa-47524de87b62', 99, 'Casting & Scelte', 'La presenza fisica di Rodrigo Santoro come Gesù', 'L''attore brasiliano Rodrigo Santoro ha accettato di interpretare Gesù Cristo affrontando un rigoroso regime di isolamento fisico e spirituale sul set di Matera. Per mantenere l''autenticità visiva, Santoro ha indossato protesi minime e ha dovuto sopportare ore di trucco quotidiano per le sequenze della crocifissione.', 'Note di produzione ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:42.659124+00:00'),
('62a64974-a632-450d-a4ff-165e4cb7b0d8', 99, 'Aneddoti dal set', 'L''infortunio sul set di Morgan Freeman', 'Durante le riprese a Cinecittà, Morgan Freeman, che interpreta il mentore Ilderim, ha subito una leggera distorsione a causa dei costumi pesanti e del terreno irregolare dell''arena. La produzione ha dovuto riorganizzare temporaneamente il piano di lavorazione per permettere all''attore di completare le sue scene senza sforzi eccessivi.', 'Reportage dal set di Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:42.659124+00:00'),
('92681aa6-d9cd-4efd-a7d0-41ed90c8df2e', 99, 'Segreti di produzione', 'L''uso delle telecamere GoPro nella corsa delle bighe', 'Il regista Timur Bekmambetov ha posizionato telecamere GoPro e action cam direttamente sui corpi dei cavalli e lungo i lati delle bighe per catturare riprese in prima persona ad alta velocità. Questa scelta tecnica mirava a replicare visivamente l''immersione tipica dei videogiochi moderni per coinvolgere il pubblico più giovane.', 'Intervista tecnica a Timur Bekmambetov per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:42.659124+00:00'),
('b5cdf31b-8d48-480f-a472-3d26209b53e4', 99, 'Segreti di produzione', 'La scelta di Cinecittà per ricreare Gerusalemme e Roma', 'La produzione ha scelto di girare gran parte del film negli storici studi di Cinecittà a Roma e nelle zone limitrofe come Matera. Questa decisione ha permesso alla troupe di sfruttare le maestose scenografie già esistenti e le maestranze locali esperte in kolossal storici.', 'Comunicato stampa ufficiale MGM e Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:42.659124+00:00'),
('d945643e-f319-4ea2-a9f1-50c3310ae5ad', 99, 'Casting & Scelte', 'Il casting internazionale e multietnico', 'Per conferire maggiore realismo storico rispetto al kolossal del 1959, i produttori Mark Burnett e Roma Downey hanno voluto un cast fortemente diversificato e internazionale, includendo attori britannici, iraniani, brasiliani e americani per riflettere la natura cosmopolita dell''Impero Romano.', 'The Hollywood Reporter - Special Casting Report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:42.659124+00:00'),
('27106c43-197d-4a71-8c57-a36fb7cfd504', 117, 'Aneddoti dal set', 'La reazione autentica dei giovani attori durante il pianto', 'Durante la drammatica scena in cui gli studenti apprendono della tragica morte di Neil Perry, il regista Peter Weir chiese a Robert Sean Leonard di non avvisare i colleghi del cast su come avrebbe interpretato il suo crollo emotivo, ottenendo reazioni di shock e lacrime del tutto genuine da parte di Ethan Hawke e degli altri ragazzi.', 'Commento audio del regista Peter Weir nell''edizione DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:37.531218+00:00'),
('b8b205ba-eee3-4f42-be6b-7176ada83fac', 117, 'Segreti di produzione', 'La rigorosa immersione temporale imposta dal regista', 'Per mantenere intatta l''atmosfera del 1959 e favorire l''affiatamento del cast, Peter Weir vietò ai giovani attori di ascoltare musica moderna o di usare gerghi contemporanei per tutta la durata delle riprese, costringendoli a vivere quasi come veri collegiali dell''epoca.', 'Documentario sul making-of incluso nell''edizione anniversario del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:37.531218+00:00'),
('f549fe7c-f98a-4bea-ba12-3ec365df8e27', 117, 'Casting & Scelte', 'Il provino improvvisato di Ethan Hawke', 'Ethan Hawke ottenne la parte di Todd Anderson grazie a un''audizione in cui dimostrò una grande timidezza naturale sul momento, tratto che convinse Peter Weir a sceglierlo immediatamente per impersonare il ragazzo più insicuro della classe.', 'Intervista retrospettiva a Ethan Hawke per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:37.531218+00:00'),
('fe99e8e1-8558-47c0-b005-01dca805ca8f', 117, 'Curiosità & Retroscena', 'Le rigide restrizioni meteorologiche sul set nel Delaware', 'Sebbene il film sia ambientato nel Vermont, le riprese si sono svolte principalmente presso la St. Andrew''s School a Middletown, nel Delaware. La produzione ha dovuto affrontare un inverno insolitamente mite e privo di neve, costringendo la troupe a utilizzare grandi quantità di neve artificiale e plastica per le scene invernali.', 'Note di produzione ufficiali della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:37.531218+00:00'),
('d7008166-149a-4403-a9fe-a407e73e04dc', 117, 'Casting & Scelte', 'Il cameo mancato di Liam Neeson', 'Prima che la produzione optasse per Peter Weir alla regia, Liam Neeson era stato preso in considerazione per interpretare il ruolo del professor John Keating quando il progetto era ancora nelle mani di un altro studio cinematografico.', 'Archivi di pre-produzione della Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:37.531218+00:00'),
('7474d9a6-4a88-4b99-8cc6-21f7ec4abaa3', 117, 'Citazioni & Easter Egg', 'L''ispirazione letteraria di Walt Whitman', 'Il celebre saluto ''O capitano! Mio capitano!'' ripreso dalla poesia di Walt Whitman dedicata ad Abraham Lincoln viene utilizzato da Keating come metafora per guidare i ragazzi all''autonomia di pensiero e alla rottura del conformismo accademico.', 'Analisi letteraria ufficiale della sceneggiatura di Tom Schulman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:37.531218+00:00'),
('7b29b955-6bc1-452f-9c52-9e8482936d07', 98, 'Effetti speciali & Trucco', 'La finta calvizie di Hugh Griffith', 'L''attore gallese Hugh Griffith, che vinse l''Oscar come miglior attore non protagonista per il ruolo dello sceicco Ilderim, dovette sottoporsi a lunghe sedute di trucco giornaliere per applicare una calotta cranica e una folta barba grigia, dato che nella realtà aveva una folta chioma e un aspetto ben diverso.', 'Note di produzione MGM e documentario ''Ben-Hur: The Making of an Epic''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:39.216816+00:00'),
('14a4cf25-cd35-47b1-bf7d-0fcc0a8043e7', 98, 'Casting & Scelte', 'Il rifiuto di Paul Newman', 'Prima che la parte principale venisse affidata a Charlton Heston, il ruolo di Giuda Ben-Hur fu rifiutato da Paul Newman. L''attore dichiarò pubblicamente di non sentirsi a proprio agio nell''indossare i costumi storici e le tuniche previste dal kolossal.', 'Archivi storici di casting della Metro-Goldwyn-Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:39.216816+00:00'),
('2596ecf5-95ef-414f-8d5c-eb384fed772d', 98, 'Segreti di produzione', 'Il modellino in scala del Circo di Antiochia', 'La celebre e monumentale sequenza della corsa delle bighe non fu interamente girata in un set reale: gran parte delle inquadrature panoramiche del Circo di Antiochia utilizzavano complessi modellini in scala ridotta combinati con effetti di pittura su vetro.', 'Libro ''The Cinema of William Wyler'' e speciali home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:39.216816+00:00'),
('b8ca67aa-7fe3-497d-bf47-483088746060', 98, 'Aneddoti dal set', 'I cavalli lipizzani prestati dall''esercito', 'Per la famosa corsa delle bighe, la produzione dovette importare e addestrare decine di cavalli provenienti da diverse nazioni europee, inclusi preziosi esemplari di razza lipizzana forniti temporaneamente per le riprese.', 'Diari di produzione di stunt e coordinamento equino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:39.216816+00:00'),
('f4c24467-e704-4b12-9daa-6c93a3741b7f', 98, 'Curiosità & Retroscena', 'Il doppiaggio italiano d''autore', 'La versione italiana del film vanta un adattamento e un doppiaggio leggendari curati da ditte storiche romane, con voci celebri come quella di Gualtiero De Angelis su Charlton Heston, divenuti pietre miliari della storia del doppiaggio italiano.', 'Enciclopedia del Doppiaggio italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:39.216816+00:00'),
('24d463ca-4335-4e4f-a3b5-eb8bb655ba3f', 135, 'Casting & Scelte', 'Il debutto cinematografico di Sage Stallone', 'Sage Stallone, il vero figlio di Sylvester Stallone, fu scelto per interpretare Robert Balboa Jr. La dinamica padre-figlio sullo schermo rifletteva in parte la loro reale relazione complessa, un aspetto che Sylvester ha ammesso aver portato molta tensione ma anche autenticità emotiva sul set.', 'Note di produzione e interviste ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:44.536614+00:00'),
('4037950e-4152-4817-aef6-4f9d565ad39c', 135, 'Casting & Scelte', 'La scelta reale di Tommy Morrison', 'Per il ruolo del rivale Tommy ''The Machine'' Gunn, Sylvester Stallone scelse il vero pugile professionista e futuro campione dei pesi massimi WBO Tommy Morrison, preferendolo a numerosi attori professionisti per garantire la massima autenticità nei combattimenti.', 'Documentario ''The Making of Rocky V''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:44.536614+00:00'),
('b3f62bb3-4ab8-496e-9884-512512b5d369', 135, 'Curiosità & Retroscena', 'Il ritorno del regista originale John G. Avildsen', 'John G. Avildsen, che aveva diretto il primo film premio Oscar del 1976 ma aveva rifiutato i capitoli successivi diretti dallo stesso Stallone, tornò alla regia di Rocky V per chiudere idealmente il cerchio e riportare la saga alle atmosfere drammatiche e realistiche delle origini.', 'Press kit ufficiale United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:44.536614+00:00'),
('12b161d2-f8b2-4455-a772-119f52aa9c88', 135, 'Aneddoti dal set', 'L''infortunio reale sul set tra Stallone e Morrison', 'Durante le riprese della brutale rissa di strada finale, la fisicità e l''inesperienza cinematografica di Tommy Morrison causarono contusioni reali e colpi accidentali a Sylvester Stallone, il quale subì ferite che richiesero cure mediche durante la produzione.', 'Commento audio del regista e interviste a Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:44.536614+00:00'),
('5dc4aac8-9f33-4548-8615-4eae6eeed32c', 135, 'Curiosità & Retroscena', 'Il finale alternativo con la morte di Rocky', 'Nella sceneggiatura originale di Sylvester Stallone, il film doveva concludersi con la tragica morte di Rocky Balboa sull''ambulanza a causa dei danni cerebrali subiti. La produzione e lo studio decisero di cambiare il finale all''ultimo momento per lasciare il protagonista in vita.', 'Archivi di sceneggiatura e interviste di Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:44.536614+00:00'),
('92bcfa4e-c219-42b8-8b7a-31103d8acaae', 135, 'Segreti di produzione', 'La scelta di girare nuovamente nei veri quartieri di Philadelphia', 'A differenza dei capitoli precedenti in cui molte scene di quartiere venivano ricostruite in studio a Los Angeles, per Rocky V la troupe tornò a girare nei veri quartieri svantaggiati di Philadelphia per catturare il vero degrado urbano e la povertà che giustificavano la rovina finanziaria del protagonista.', 'Note di produzione e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:44.536614+00:00'),
('17f07f3b-56e8-424a-b68e-56f95ad77134', 135, 'Casting & Scelte', 'La partecipazione di pugili professionisti', 'Oltre a Tommy Morrison, il film vanta la presenza di veri volti del pugilato professionistico dell''epoca, come l''ex campione del mondo WBA dei pesi massimi Jimmy Young, che appare in brevi scene di contorno per dare maggiore credibilità all''ambiente della palestra di Uniondale.', 'Crediti ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:42:44.536614+00:00'),
('57dd4b53-ab56-49d4-8460-027aad6d35b2', 135, 'Effetti speciali & Trucco', 'Il ruolo minore di Richard Gant e il suo look', 'Per caratterizzare il mefistofelico manager George Washington Duke, il dipartimento trucco e costumi si ispirò ai magnati della boxe degli anni ''80 e ai predicatori televisivi, arricchendo il personaggio con abiti sfarzosi e anelli vistosi per accentuare il contrasto con la semplicità di Rocky.', 'Note di produzione del reparto costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:42:44.536614+00:00'),
('ff678606-ef32-41ab-b1c4-64afbc2da629', 347, 'Curiosità & Retroscena', 'L''assenza del vero John Nash sul set', 'Il vero John Nash e sua moglie Alicia visitarono il set cinematografico solo a riprese quasi ultimate, per evitare che la loro presenza potesse condizionare o inibire l''interpretazione di Russell Crowe e Jennifer Connelly.', 'Intervista al matematico John Nash nel documentario del making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:11.921586+00:00'),
('4c9928f0-6d55-4fd9-b751-297b5c36dba4', 347, 'Segreti di produzione', 'La gestione delle allucinazioni visive', 'Per distinguere chiaramente le allucinazioni di Nash dalla realtà per lo spettatore, il direttore della fotografia Roger Deakins e il regista Ron Howard hanno utilizzato una palette di colori desaturata e fredda nelle scene in cui compaiono i personaggi immaginari come Charles e Parcher.', 'American Cinematographer, articolo tecnico di approfondimento', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:11.921586+00:00'),
('20037581-b1ce-4b8b-b253-3536094cc15f', 347, 'Aneddoti dal set', 'La scena del dormitorio e la finestra', 'Durante la celebre sequenza in cui i colleghi di Princeton cercano di far ricoverare Nash strappandogli i lavori dalla tasca, l''improvvisazione fisica degli attori portò a contusioni reali e a una tensione palpabile sul set, voluta da Howard per aumentare il realismo della scena.', 'Featurette ''The Making of A Beautiful Mind''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:11.921586+00:00'),
('3f125388-a681-47ea-a1b0-7adff4672dbd', 100, 'Casting & Scelte', 'La leggenda metropolitana su Max Schreck', 'Circolò a lungo la bizzarra teoria secondo cui Max Schreck fosse uno pseudonimo per celare la vera identità di un vero vampiro, alimentata dal fatto che il cognome ''Schreck'' in tedesco significa ''orrore'' o ''paura''. In realtà, Max Schreck era un attore di teatro tedesco realmente esistito, associato alla compagnia di Max Reinhardt.', 'Archivi storici della Berlino teatrale e biografie di Max Schreck', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:47.845452+00:00'),
('50a23983-1569-45ae-93db-a67e8e04ac62', 100, 'Curiosità & Retroscena', 'La causa legale per violazione di copyright', 'La vedova di Bram Stoker, Florence Stoker, intentò una causa legale contro la produzione per aver adattato ''Dracula'' senza autorizzazione e senza aver acquistato i diritti d''autore. Il tribunale le diede ragione, ordinando la distruzione del master e delle copie, ma alcune stampe sopravvissero clandestinamente all''estero.', 'Atti giudiziari della causa Florence Stoker vs Prana-Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:47.845452+00:00'),
('91e1b454-97f6-4008-907e-bec67c8afac6', 100, 'Casting & Scelte', 'Il cambio dei nomi dei personaggi', 'Per cercare di eludere il copyright sul romanzo di Bram Stoker, lo sceneggiatore Henrik Galeen modificò i nomi di quasi tutti i personaggi principali. Jonathan Harker divenne Thomas Hutter, Mina fu ribattezzata Ellen, e il conte Dracula fu trasformato nel conte Orlok.', 'Confronto testuale tra la sceneggiatura originale e il romanzo Dracula', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:47.845452+00:00'),
('a77b004e-87c1-4b7b-a7d8-58c7ecfe9805', 100, 'Aneddoti dal set', 'Le riprese in esterni in Slovacchia', 'Per ricreare l''atmosfera sinistra dei Carpazi, la troupe si recò realmente in Europa orientale, girando alcune sequenze iconiche nel nord dell''Ungheria e nei monti Tatra, oggi in Slovacchia. Il Castello di Orava fece da sfondo per la spettrale fortezza del conte Orlok.', 'Note di produzione e diari di viaggio della troupe della Prana-Film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:47.845452+00:00'),
('94eed84f-a510-428e-bf1a-687aa04eaf86', 100, 'Effetti speciali & Trucco', 'L''uso innovativo della tecnica del negativo', 'Per accentuare il senso di soprannaturale e il disagio visivo durante il viaggio in carrozza di Hutter nella terra dei fantasmi, Murnau utilizzò una pellicola impressionata in negativo. Questo artificio ottico rese il paesaggio spettrale, con alberi bianchi su un cielo nero.', 'Analisi tecniche e restauri della Friedrich-Wilhelm-Murnau-Stiftung', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:47.845452+00:00'),
('3ce0a68c-29cb-454b-b61a-50c8250342a9', 100, 'Effetti speciali & Trucco', 'Il trucco artigianale del Conte Orlok', 'Il make-up di Max Schreck, curato da Albin Grau, prevedeva orecchie a punta, un naso adunco e protesi ungueali estese che trasformavano l''attore in un roditore antropomorfo. A differenza dei successivi vampiri cinematografici eleganti, Orlok doveva richiamare visivamente la peste e i ratti.', 'Bozzetti originali di Albin Grau e documentari sul trucco nel muto', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:47.845452+00:00'),
('f745b0e7-cccf-4dcd-825a-8b2eca4f14b7', 100, 'Segreti di produzione', 'La dissolvenza a passo di lumaca', 'Per filmare il movimento innaturale del carro che trasportava il vampiro, la troupe rallentò drasticamente i fotogrammi al secondo in fase di ripresa. Questo effetto di accelerazione e scatto, combinato con la recitazione rigida di Schreck, contribuì all''inquietudine del movimento del personaggio.', 'Manuale tecnico della produzione cinematografica tedesca degli anni ''20', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:40:47.845452+00:00'),
('399cad38-1ae6-4efe-ac8d-e26f2390da16', 100, 'Curiosità & Retroscena', 'Il contributo occultista di Albin Grau', 'Il co-produttore e scenografo Albin Grau era un appassionato di occultismo ed esoterismo. Introdusse simboli cabalistici e riferimenti massonici nei contratti, nei titoli di testa e nei documenti cartacei mostrati nel film, infondendo alla pellicola un''autentica aura di mistero nero.', 'Biografie di Albin Grau e studi sulla cultura Weimar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:40:47.845452+00:00'),
('89d9b9f4-c9bb-4750-b035-e10ed3e31f01', 144, 'Casting & Scelte', 'La ricerca decennale di Quentin Tarantino per Hans Landa', 'Quentin Tarantino ha dichiarato di aver temuto che il personaggio di Hans Landa fosse ''scrittore-impossibile'', un ruolo talmente complesso che nessun attore avrebbe potuto interpretare adeguatamente, al punto che stava quasi per rinunciare al film prima che Christoph Waltz si presentasse ai provini.', 'Intervista ufficiale di Quentin Tarantino per il rilascio del film nel 2009', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:22.44437+00:00'),
('7d6c9a8c-2cb9-413a-8a62-c5d543f64d34', 144, 'Casting & Scelte', 'Diane Kruger scelta all''ultimo minuto dopo il rifiuto di Leonardo DiCaprio', 'Inizialmente Quentin Tarantino aveva pensato a Leonardo DiCaprio per il ruolo del colonnello Hans Landa prima di optare per un attore di madrelingua tedesca. Per il ruolo dell''attrice spia Bridget von Hammersmark, l''attrice tedesca Diane Kruger dovette sostenere un provino a Berlino dopo che il regista aveva inizialmente dubitato di lei a causa della sua partecipazione a film hollywoodiani commerciali.', 'Note di produzione ufficiali e festival di Cannes 2009', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:22.44437+00:00'),
('3e83e9ef-7a40-4bad-b7f9-d1e3e9b42aad', 144, 'Aneddoti dal set', 'Il vero strangolamento di Diane Kruger da parte di Quentin Tarantino', 'Nella celebre e drammatica sequenza in cui il colonnello Landa strangola Bridget von Hammersmark, Quentin Tarantino ha voluto girare la scena personalmente per ottenere un realismo visivo assoluto, stringendo fisicamente le mani attorno al collo dell''attrice Diane Kruger mentre le telecamere riprendevano i suoi veri segni di soffocamento.', 'Commento audio del regista e interviste al cast nel making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:22.44437+00:00'),
('4650383b-994d-4446-a022-e7b49fe2ae05', 144, 'Segreti di produzione', 'Il finto fumo delle sigarette di scena e le norme europee', 'A causa delle rigide normative europee sul fumo nei luoghi di lavoro chiusi adottate durante le riprese negli studi Babelsberg di Berlino, gli attori non potevano fumare veri tabacchi nelle scene girate in ambienti interni. Il dipartimento di scenografia e gli oggetti di scena dovettero ricorrere a sigarette a base di erbe non tabagiche appositamente prodotte per il cinema.', 'Reportage dal set della troupe di produzione di Berlino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:22.44437+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('aedfaeb2-f32c-458e-8c08-58929040ea94', 144, 'Effetti speciali & Trucco', 'La cicatrice di Eli Roth e il metodo per la scena del cinema', 'Per la brutale scena in cui il sergente Donny Donowitz (noto come ''L''orso ebraico'', interpretato dal regista Eli Roth) incide la fronte del soldato tedesco Werner Rachtman, gli effetti speciali ricorsero a protesi in lattice avanzate e a tubicini di sangue finto controllati a pressione per simulare il distacco chirurgico della carne.', 'Making-of ufficiale e documentario sul trucco di Greg Nicotero', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:22.44437+00:00'),
('37cf85c9-7c44-4811-a679-1b6a8680f134', 144, 'Citazioni & Easter Egg', 'L''omaggio a Gillo Pontecorvo e ''La battaglia di Algeri''', 'Quentin Tarantino ha inserito molteplici riferimenti strutturali e visivi a ''La battaglia di Algeri'' (1966) di Gillo Pontecorvo, considerandolo uno dei film fondamentali sulla guerriglia urbana e sulla resistenza clandestina che ha ispirato la tattica militare spietata della cellula guidata da Aldo Raine.', 'Interviste retrospettive e analisi della colonna sonora e della regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:22.44437+00:00'),
('8e21ab9b-98bc-42b8-b1c6-339cb2ab4774', 101, 'Effetti speciali & Trucco', 'La colonia di undicimila topi tinti di bianco', 'Per rappresentare l''invasione dei ratti nella città di Wismar, la produzione importò undicimila topi da laboratori ungheresi. Poiché i ratti grigi originali non risultavano sufficientemente visibili nelle sequenze notturne, il truccatore e gli assistenti dovettero immergere ogni singolo animale in una soluzione di candeggina e perossido per tingerli di bianco, causando però la morte di molti esemplari a causa della tossicità.', 'Documentario di making-of e interviste d''archivio a Werner Herzog', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:53.50304+00:00'),
('c47e3744-fb0a-4d1c-834d-7e28a755846f', 101, 'Segreti di produzione', 'La versione bilingue girata contemporaneamente', 'Werner Herzog pretese di girare ogni singola scena due volte: una prima volta in lingua inglese e subito dopo in tedesco. Questa scelta fu dettata dalla volontà di garantire la massima commerciabilità internazionale del film senza ricorrere al doppiaggio, costringendo gli attori principali, in particolare Klaus Kinski e Bruno Ganz, a recitazioni doppie per ogni ciak.', 'Note di produzione ufficiali e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:53.50304+00:00'),
('01a669e6-1775-4fb3-84d5-e09bc74063b3', 101, 'Effetti speciali & Trucco', 'Le quattro ore di trucco quotidiane per Kinski', 'Il celebre truccatore giapponese Reiko Kruk fu ingaggiato per ricreare sul volto di Klaus Kinski il look iconico del Nosferatu originale di Max Schreck. Kinski doveva sottoporsi a oltre quattro ore di applicazione di protesi in lattice, denti finti appuntiti e una calotta cranica glabra ogni singolo giorno di riprese.', 'Libro biografico e documentario ''Klaus Kinski: My Fiend''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:53.50304+00:00'),
('55882576-30bd-4b26-95ed-ebeef0b5fe8d', 101, 'Casting & Scelte', 'Il rifiuto iniziale di Bruno Ganz', 'Prima di assegnare il ruolo di Jonathan Harker a Bruno Ganz, Werner Herzog aveva pensato ad altri attori del teatro tedesco. Ganz accettò la parte solo dopo aver discusso a lungo con il regista sulla necessità di dare al personaggio una fragilità psicologica e un senso di ineluttabilità superiori rispetto al romanzo originale.', 'Intervista retrospettiva a Bruno Ganz', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:53.50304+00:00'),
('e6ea9636-c158-444d-9ce4-def6673d328b', 101, 'Citazioni & Easter Egg', 'L''omaggio dichiarato al capolavoro di Murnau', 'Molte inquadrature del film di Herzog sono calchi visivi esatti, quasi delle riproduzioni pittoriche, delle inquadrature originali del ''Nosferatu'' del 1922 di F.W. Murnau. Herzog non ha mai nascosto l''intento di voler realizzare un vero e proprio remake devozionale per nobilitare la storia del cinema tedesco.', 'Saggi critici sul cinema di Werner Herzog e analisi comparate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:40:53.50304+00:00'),
('53287eab-204d-42f4-b97b-23f9ab4eda07', 101, 'Aneddoti dal set', 'Le tensioni continue tra Herzog e Kinski', 'Il rapporto burrascoso tra il regista e l''attore protagonista raggiunse picchi estremi durante la lavorazione, alimentato dalle bizze di Kinski e dalle sue scenate furiose sul set olandese e cecoslovacco. Herzog arrivò persino a minacciare pubblicamente Kinski con una pistola durante le riprese pur di costringerlo a rispettare gli orari e la concentrazione.', 'Documentario ''Mein liebster Feind'' (Il mio nemico preferito) di Werner Herzog', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:40:53.50304+00:00'),
('12b51a42-b781-415b-94de-316a16460afc', 101, 'Aneddoti dal set', 'L''uso dei pipistrelli vivi sul set', 'Durante alcune scene in interni, la troupe utilizzò veri pipistrelli vivi forniti da un esperto zoologo locale. Gli animali crearono non pochi problemi di gestione tecnica e spavento tra le comparse, volando liberamente intorno alle macchine da presa da 35mm dell''epoca.', 'Diario di bordo della troupe e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:40:53.50304+00:00'),
('b2b16e50-7ac5-4f28-9ddf-3689dbc091e4', 129, 'Casting & Scelte', 'La scelta iniziale di Gérard Depardieu', 'Prima che Sergio Leone assegnasse il ruolo di Max a James Woods, il regista aveva incontrato e considerato seriamente Gérard Depardieu per la parte, ma l''accordo non si concretizzò.', 'Biografie ufficiali e note di produzione di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:33.610625+00:00'),
('40c4fd61-e33f-4b20-b36a-554d9d0bc73b', 129, 'Aneddoti dal set', 'Il brano di Ennio Morricone ascoltato sul set', 'Sergio Leone era solito fare ascoltare le malinconiche melodie composte da Ennio Morricone direttamente agli attori durante le riprese delle scene più drammatiche per aiutarli a entrare nell''atmosfera emotiva desiderata.', 'Documentario ''Sergio Leone: Cinema, Cinema'' e note del siffatto Making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:33.610625+00:00'),
('51dd55b3-9b87-47e2-a439-77af95574d71', 129, 'Segreti di produzione', 'La ricostruzione del Lower East Side a Cinecittà', 'Gran parte delle imponenti sequenze ambientate nella New York degli anni ''20 non furono girate negli Stati Uniti, ma in un set mastodontico e dettagliatissimo appositamente costruito negli studi di Cinecittà a Roma.', 'Archivi storici di Cinecittà e speciali di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:33.610625+00:00'),
('21d2193f-a1fb-49f5-a080-ce452cd0f7c5', 129, 'Casting & Scelte', 'Il rifiuto del ruolo di Noodles da parte di Dustin Hoffman', 'Nelle primissime fasi di sviluppo del progetto negli anni ''70, Sergio Leone aveva pensato a Dustin Hoffman per il ruolo del protagonista Noodles, ma l''attore declinò l''offerta.', 'Interviste storiche a Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:33.610625+00:00'),
('1514819d-99cf-416f-98d3-9951b8ade29f', 129, 'Curiosità & Retroscena', 'La versione cinematografica mutilata per il mercato USA', 'Per la prima uscita nelle sale americane, la distribuzione ridusse drasticamente il film a circa 139 minuti e ne modificò la struttura narrativa cronologica, scatenando le proteste di pubblico e critica prima del ripristino della versione integrale.', 'Note storiche sulla distribuzione cinematografica e recensioni d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:33.610625+00:00'),
('30e89175-f341-483c-917b-29f418a72508', 129, 'Effetti speciali & Trucco', 'L''invecchiamento complesso del cast', 'Il celebre truccatore premio Oscar Manlio Rocchetti si occupò di trasformare radicalmente gli attori per coprire l''arco temporale di decenni, lavorando ore al giorno con protesi in lattice avanzate per l''epoca.', 'Crediti ufficiali e interviste al reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:33.610625+00:00'),
('b57c5436-2c18-46b6-8d62-637bbc0df864', 140, 'Casting & Scelte', 'La scelta iniziale di Scarlett Johansson', 'Prima che il ruolo di Ewa Cybulska fosse assegnato a Marion Cotillard, James Gray aveva pensato proprio a Scarlett Johansson, con cui aveva già collaborato in ''Two Lovers'', ma l''attrice dovette rinunciare per conflitti di programmazione.', 'Dichiarazioni ufficiali di James Gray durante il press tour', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:02.083399+00:00'),
('f40bce49-5220-408b-8522-92158288763a', 140, 'Segreti di produzione', 'La fotografia ispirata alla pittura e a Kodak', 'Il direttore della fotografia Darius Khondji ha studiato a fondo le lastre autochrome dei primi del Novecento e le fotografie d''archivio di Lewis Hine per Ellis Island, lavorando digitalmente per replicare la grana e le tonalità calde dei vecchi processi fotografici.', 'Note di produzione e interviste a Darius Khondji su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:02.083399+00:00'),
('09eb98a7-19ab-4d2e-9c1d-c83852580056', 140, 'Citazioni & Easter Egg', 'L''omaggio a ''Il padrino - Parte II''', 'Le sequenze iniziali ambientate a Ellis Island e l''arrivo degli immigrati sono un esplicito omaggio visivo e tematico alla seconda parte de ''Il padrino'' di Francis Ford Coppola, in particolare alla scena dell''arrivo del giovane Vito Corleone.', 'Analisi critiche e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:02.083399+00:00'),
('82c5503a-4d51-43de-841d-fa2436b0f053', 102, 'Effetti speciali & Trucco', 'L''uso di vere specie di ratti sul set', 'Per garantire il massimo realismo visivo ed evitare l''abuso di CGI, la produzione ha impiegato migliaia di veri ratti addestrati per le sequenze ambientate a Wisborg, coordinati da esperti di animali sul set.', 'Note di produzione ufficiali Focus Features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:40:56.281086+00:00'),
('42f4cc2a-8b6d-460f-9ac5-d30876a6c470', 102, 'Segreti di produzione', 'L''ispirazione pittorica di Caspar David Friedrich', 'Il regista Robert Eggers e il direttore della fotografia Jarin Blaschke hanno studiato a fondo i dipinti romantici del XIX secolo, in particolare le opere di Caspar David Friedrich, per definire la palette cromatica e la composizione delle inquadrature in esterni.', 'Intervista di Jarin Blaschke a American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:40:56.281086+00:00'),
('699c3956-0eb3-4e2d-a4c7-ac8b98ccde72', 102, 'Curiosità & Retroscena', 'La consulenza storica sul folklore dei vampiri', 'Prima di iniziare le riprese, Robert Eggers ha consultato storici ed esperti di folklore mitteleuropeo per assicurarsi che i rituali di protezione contro i vampiri e le credenze popolari rispecchiassero fedelmente le fonti del XIX secolo.', 'Pressbook ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:40:56.281086+00:00'),
('fb832d31-9a8b-40c5-933b-06479d2e6eeb', 102, 'Segreti di produzione', 'Le riprese nei Barrandov Studios di Praga', 'La troupe ha sfruttato i celebri Barrandov Studios di Praga, storicamente legati a una lunga tradizione di cinema gotico e fantastico europeo, per costruire imponenti set interni tra cui la cripta del Conte Orlok.', 'Reportage di produzione da Praga', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:40:56.281086+00:00'),
('a8f56f97-3cf1-4c39-a9cc-31944c381465', 136, 'Casting & Scelte', 'La storica rivalità e complicità tra Flynn e de Havilland', 'Questo film segna la settima e penultima apparizione sul grande schermo della celebre coppia formata da Errol Flynn e Olivia de Havilland. La loro chimica sullo schermo era alimentata da un profondo affetto e da una giocosa complicità fuori dal set, che durò per tutta la loro vita.', 'Autobiografia di Olivia de Havilland e archivi di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:47.792126+00:00'),
('691e94e8-b3f9-4ad3-a5a6-1140ece9f062', 136, 'Curiosità & Retroscena', 'La licenza poetica sulla morte di Custer', 'Il finale del film mostra eroicamente George Armstrong Custer che muore combattendo coraggiosamente fino all''ultimo respiro nella Battaglia di Little Bighorn. Storicamente, tuttavia, le testimonianze dei nativi americani indicano che Custer fu probabilmente uno dei primi a cadere e non pronunciò mai l''epico discorso finale mostrato nella pellicola.', 'Saggi storici sulla Battaglia di Little Bighorn e note di sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:47.792126+00:00'),
('ac88c2f0-56c0-4199-9c7a-5dd4ed8c09dd', 136, 'Aneddoti dal set', 'Il rapporto teso tra Raoul Walsh e Errol Flynn', 'Il regista Raoul Walsh e la star Errol Flynn condivisero spesso momenti di intensa goliardia ma anche forti scontri legati all''etica lavorativa di Flynn, noto per fare le ore piccole la notte. Walsh riusciva tuttavia a incanalare l''energia spericolata dell''attore per ottenere performance carismatiche e cariche di spavalderia.', 'Biografie ufficiali di Raoul Walsh e memo interni della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:47.792126+00:00'),
('1d53f99d-51d5-4054-9ce1-bb72792799a8', 136, 'Segreti di produzione', 'L''uso massiccio di cavalli addestrati e stuntmen professionisti', 'Per ricreare le complesse sequenze belliche della Guerra di Secessione e la carica finale, la produzione impiegò centinaia di cavalli appositamente addestrati e una troupe di stuntmen specializzati nelle cadute ''cossacche'', supervisionati direttamente da Raoul Walsh per garantire impatto visivo e spettacolarità.', 'Production notes e bollettini di lavorazione della Warner Bros. Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:47.792126+00:00'),
('668f7d97-d1c7-42fd-b8d2-917ac81de0c7', 141, 'Aneddoti dal set', 'La tensione reale tra Robert Shaw e Richard Dreyfuss', 'I rapporti sul set tra Robert Shaw (Quint) e Richard Dreyfuss (Hooper) erano notoriamente tesi anche a telecamere spente, a causa di una reciproca antipatia alimentata dai frequenti scherzi e dai commenti pungenti di Shaw. Questa reale ostilità finì per riflettersi perfettamente nella chimica conflittuale dei loro personaggi a bordo della Orca.', 'Documentario ''The Making of Jaws'' e interviste retrospettive al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:07.404422+00:00'),
('63726123-e8a3-411d-a5ae-8d4f5f6e4dcc', 141, 'Aneddoti dal set', 'L''improvvisazione del celebre monologo della USS Indianapolis', 'Il potentissimo monologo in cui Quint racconta il tragico affondamento della USS Indianapolis fu frutto di un lavoro collettivo di scrittura: lo sceneggiatore Howard Sackler, l''attore Robert Shaw e il drammaturgo John Milius contribuirono a perfezionare il testo, trasformando un pezzo tecnico in uno dei momenti drammatici più intensi della storia del cinema.', 'Note di produzione e biografie ufficiali di Steven Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:07.404422+00:00'),
('0f86eca7-849a-42a8-a44b-a3e902f1604e', 141, 'Segreti di produzione', 'I problemi di bilancio e i ritardi dello squalo meccanico', 'Soprannominato ironicamente ''Bruce'' in onore dell''avvocato di Spielberg, Bruce Ramer, lo squalo meccanico costò circa 250.000 dollari ma fallì ripetutamente i test in mare aperto a causa dell''acqua salata che corrodeva i circuiti pneumatici, facendo sforare il budget iniziale di milioni di dollari e triplicando i giorni di ripresa previsti.', 'Archivi Universal Pictures e libro ''Jaws: Memories from Martha''s Vineyard''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:07.404422+00:00'),
('c5b7cf62-ebea-4292-84a2-30d886db1465', 141, 'Casting & Scelte', 'Charlton Heston in lizza per il ruolo di Martin Brody', 'Prima che Roy Scheider venisse ingaggiato, la produzione offrì il ruolo del capo della polizia Martin Brody a Charlton Heston. Spielberg tuttavia si oppose fermamente, ritenendo che la forte personalità e l''aria eroica di Heston avrebbero reso inverosimile la paura del personaggio nei confronti dell''acqua e degli squali.', 'Documentario ''The Making of Jaws'' e registri di casting Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:07.404422+00:00'),
('e1091bc5-d6ce-45ff-a5e1-52212c077eff', 141, 'Citazioni & Easter Egg', 'Il cameo del regista nei panni del radioamatore', 'Nella sequenza in cui la spiaggia viene presa dal panico dopo un falso allarme causato da due ragazzi con una pinna finta, la voce che si sente trasmettere via radio comunicando l''emergenza al capo Brody appartiene allo stesso Steven Spielberg.', 'Commento audio del regista nell''edizione Blu-ray/DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:07.404422+00:00'),
('5e3ec1a8-c449-4b36-b0c6-b1af23ddd814', 141, 'Effetti speciali & Trucco', 'L''uso di subacquei in miniatura per simulare le dimensioni dello squalo', 'Per enfatizzare le proporzioni gigantesche del predatore quando attaccava le gabbie o i sommozzatori, il direttore della fotografia della seconda unità Joe Alves utilizzò stuntmen di statura molto bassa all''interno di gabbie in scala ridotta, affiancati da modellini di squali proporzionalmente più piccoli.', 'Making-of ufficiale e manuali di effetti speciali della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:07.404422+00:00'),
('5b9fb7b4-54e0-42e9-ad13-5a193857a40b', 141, 'Casting & Scelte', 'Il rifiuto del ruolo di Hooper da parte di Jon Voight e Jeff Bridges', 'Prima di affidare la parte del giovane biologo marino Matt Hooper a Richard Dreyfuss, Steven Spielberg e i produttori presero seriamente in considerazione diversi attori di grido, tra cui Jon Voight, Jeff Bridges e Timothy Bottoms, i quali rifiutarono tutti l''offerta per conflitti di agenda o disinteresse.', 'Registri di produzione e biografia autorizzata di Steven Spielberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:43:07.404422+00:00'),
('3fea8cc8-5881-4020-85c6-88791802d753', 109, 'Casting & Scelte', 'Il rifiuto del ritorno di Tommy O''Dell', 'Il regista e sceneggiatore Tom Shadyac, che diresse il primo capitolo, decise di non tornare dietro la macchina da presa e rifiutò anche di scrivere il sequel, lasciando il testimone a Steve Oedekerk perché non amava realizzare seguiti.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:06.423452+00:00'),
('4c2e1474-37f4-41fd-81f9-e1846231a8ad', 109, 'Segreti di produzione', 'La scelta del pipistrello bianco', 'Il raro pipistrello bianco Chicca (White Bat) al centro della trama si ispira al vero vampiro bianco (Ectophylla alba), una specie nativa dell''Honduras e del Centro America, sebbene nel film l''azione si svolga in Africa.', 'Commento audio del regista Steve Oedekerk', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:06.423452+00:00'),
('590e2fc4-e534-4835-84be-b1e4bdcd2ef2', 109, 'Citazioni & Easter Egg', 'L''ispirazione da Apocalypse Now nella scena del fiume', 'La memorabile sequenza in cui Ace Ventura naviga sul fiume su una piccola imbarcazione circondato dalla nebbia e dai mercenari è una parodia diretta del celebre viaggio sul fiume di Willard in Apocalypse Now di Francis Ford Coppola.', 'Analisi visiva e recensione di Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:06.423452+00:00'),
('33a0af78-5f50-4afb-bbb2-b02ddb92a9ff', 109, 'Effetti speciali & Trucco', 'Il costume termico di gomma', 'Durante la famosissima sequenza della fuoriuscita dal finto rinoceronte meccanico, Jim Carrey ha dovuto sopportare temperature equatoriali estreme all''interno di un guscio in vetroresina e lattice che non lasciava filtrare l''aria.', 'Documentario Behind the Scenes: The Making of Ace Ventura 2', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:06.423452+00:00'),
('c6e7bd09-5b92-46d8-96c9-e2bec31cd059', 109, 'Casting & Scelte', 'Il cameo vocale di Bob Gunton', 'L''attore Bob Gunton, noto per aver interpretato il direttore Norton in Le ali della libertà, accettò il ruolo del console Vincent Cadby principalmente per poter lavorare a fianco della star comica Jim Carrey in un registro completamente demenziale.', 'Intervista promozionale a Bob Gunton del 1995', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:06.423452+00:00'),
('b011538f-0c44-46be-8ae4-fff6fe8095a0', 112, 'Curiosità & Retroscena', 'La riscrittura del finale in seguito alla fusione con l''universo Cloverfield', 'Originariamente il film si concludeva con la scoperta che l''esterno non era contaminato ma semplicemente pacifico, senza alcuna invasione aliena. Il famigerato finale con l''astronave fu aggiunto in seguito, quando la Bad Robot decise di collegare lo script originale alla proprietà intellettuale di Cloverfield.', 'Note di produzione e interviste ufficiali a J.J. Abrams', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:18.731989+00:00'),
('410fca6d-1c7a-4885-a11b-298d23994af6', 112, 'Citazioni & Easter Egg', 'La spilla di Pac-Man come omaggio ai videogiochi', 'Sulla tuta che Michelle indossa nella parte finale del film è chiaramente visibile una spilla di Pac-Man. Il regista Dan Trachtenberg, noto per il suo background legato alla cultura geek e al mondo dei videogiochi, ha voluto inserire questo piccolo dettaglio come tocco personale.', 'Commento audio del regista Dan Trachtenberg', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:18.731989+00:00'),
('6ae5af4d-e8f7-453e-bef5-57e938f2ebb5', 120, 'Citazioni & Easter Egg', 'L''ispirazione per il visore E.D.I.T.H.', 'Gli iconici occhiali da sole ereditati da Tony Stark presentano una montatura ispirata direttamente a quelli indossati da Elton John nella sua celebre carriera e richiamano il look di Gene Hackman nel ruolo di Lex Luthor in Superman.', 'Note di produzione Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:50.341064+00:00'),
('80d0e493-bfcd-438e-902c-4706e0dfc240', 120, 'Aneddoti dal set', 'La cicatrice reale di Tom Holland', 'Durante una sequenza d''azione acrobatica sul set, Tom Holland ha urtato accidentalmente contro una telecamera fissa, procurandosi un taglio sul sopracciglio sinistro che ha richiesto leggeri interventi di correzione digitale in post-produzione.', 'Intervista ufficiale nel press tour', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:50.341064+00:00'),
('9fae72a2-b88c-4011-8f4b-df9f17ae29b1', 120, 'Citazioni & Easter Egg', 'Il nome in codice di Nick Fury', 'Durante la sequenza in cui Nick Fury recluta Peter, l''identificativo sul suo passaporto temporaneo riporta riferimenti numerici nascosti che omaggiano l''anno della prima apparizione a fumetti di Samuel L. Jackson nel circuito Ultimate Marvel.', 'Analisi visiva e contenuti extra Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:50.341064+00:00'),
('9f77ed04-1d3c-4965-98ae-7f2f4212f3f4', 120, 'Curiosità & Retroscena', 'L''addio temporaneo al MCU', 'Poco dopo l''uscita del film nel 2019, i negoziati tra Sony Pictures e i Marvel Studios subirono una momentanea rottura pubblica che rischiò di escludere definitivamente Spider-Man dai futuri progetti corali del Marvel Cinematic Universe, prima del successivo accordo.', 'Comunicati stampa ufficiali e report di settore Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:50.341064+00:00'),
('a610be06-4d06-4b2d-9f7f-33485c233836', 120, 'Aneddoti dal set', 'L''improvvisazione nella scena del bar', 'La conversazione tra Peter Parker e Quentin Beck all''interno del pub a Praga contiene diverse battute estemporanee recitate da Jake Gyllenhaal per rendere il legame di mentore e protetto più naturale e spontaneo.', 'Commento audio del regista Jon Watts', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:50.341064+00:00'),
('628cc33e-bc0b-4803-9b69-a13627eb5a6a', 120, 'Segreti di produzione', 'I droni di Mysterio e il design militare', 'I droni d''attacco controllati da Mysterio tramite il sistema E.D.I.T.H. sono stati modellati dai reparti artistici fondendo l''estetica dei moderni UAV militari con le forme geometriche dei fumetti originali di Steve Ditko.', 'Art of the Movie Book', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:50.341064+00:00'),
('d0bee186-c853-4886-a521-4ba76a561f0c', 125, 'Aneddoti dal set', 'Il ritorno di Carrie-Anne Moss alla motocicletta', 'Per prepararsi alle spettacolari scene in moto in cui trasporta Neo, Carrie-Anne Moss ha dovuto riprendere gli allenamenti intensivi di guida su due ruote mesi prima dell''inizio delle riprese a San Francisco, lavorando a stretto contatto con il coordinatore degli stunt Guy Norris.', 'Making-of ufficiale e note di produzione Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:13.733451+00:00'),
('97632225-b911-4c3c-a62a-f99892f8b24f', 125, 'Citazioni & Easter Egg', 'Il legame di famiglia nella sequenza iniziale', 'Nella scena in cui il personaggio di Bugs osserva ologrammi nel suo rifugio, compaiono riferimenti visivi e nomi che omaggiano direttamente membri della troupe e collaboratori storici delle sorelle Wachowski, nascosti come easter egg digitali.', 'Analisi visive ufficiali e commenti della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:13.733451+00:00'),
('653ea0a3-70a8-4e07-9cc3-4463632a27fa', 125, 'Segreti di produzione', 'L''ispirazione per il design di Modalità', 'Il bar virtuale ''Modalità'' dove Neo incontra nuovamente Morpheus è stato progettato dalla scenografa J.P. Giicka per richiamare visivamente i locali di San Francisco frequentati da Lana Wachowski, fondendo l''estetica cyberpunk classica con elementi di design contemporaneo.', 'Art of Matrix Resurrections - Artbook ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:13.733451+00:00'),
('64fcbd14-e67b-469d-8be7-80a2586fcf80', 125, 'Casting & Scelte', 'La scelta della canzone iniziale dei Jefferson Airplane', 'Lana Wachowski ha voluto fortemente l''utilizzo del brano ''White Rabbit'' dei Jefferson Airplane come leitmotiv sonoro per sottolineare il risveglio di Thomas Anderson, richiamando esplicitamente i temi psichedelici e di alterazione della realtà del primo film del 1999.', 'Note sulla colonna sonora ufficiale e interviste alla regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:13.733451+00:00'),
('d48cfdb4-47a1-41b2-b237-6ec694040786', 111, 'Aneddoti dal set', 'Lo schiaffo reale di Kate Winslet a Billy Zane', 'Durante la scena in cui Rose colpisce Caledon Hockley (Billy Zane) con uno schiaffo mentre lui cerca di trattenerla, la sceneggiatura originaria prevedeva l''uso di un finto schiaffo o di una sberla attutita. Tuttavia, per ottenere una reazione più autentica e realistica, Kate Winslet decise di colpirlo realmente in faccia.', 'Speciali dietro le quinte e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:16.395705+00:00'),
('1b40f0d3-b0ab-4428-b11a-da4983deb191', 111, 'Effetti speciali & Trucco', 'Il modellino in scala e la distruzione programmata', 'Per girare le sequenze più spettacolari dell''affondamento senza rischiare la vita degli attori nelle scene d''azione più pericolose, la produzione costruì un modellino parziale della nave in scala 1:20 lungo oltre 150 metri, montato su un sistema idraulico capace di spezzarlo in due tronconi.', 'Documentario ufficiale ''Titanic: Breaking New Ground'' e registri di produzione della Digital Domain', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:16.395705+00:00'),
('09308d57-0ee5-405b-abc3-7d029c40759d', 111, 'Citazioni & Easter Egg', 'Il vero cane di James Cameron nelle riprese', 'Il cane di razza Spitz che compare in alcune scene a bordo della nave non era un animale addestrato di agenzia, ma il cane di proprietà dello stesso regista James Cameron, inserito nel film come piccolo cameo nascosto.', 'Curiosità e note di produzione incluse nelle edizioni Blu-ray celebrative', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:16.395705+00:00'),
('de8cdba4-4300-423b-9684-6e6aa75c15f3', 111, 'Curiosità & Retroscena', 'La durata della proiezione identica alla tragedia reale', 'La durata della versione cinematografica del film, esclusi i titoli di coda, è esattamente di 2 ore e 40 minuti, ovvero lo stesso identico tempo impiegato dal vero transatlantico Titanic per colare a picco dopo l''impatto con l''iceberg nel 1912.', 'Analisi storiche e tecniche ufficiali della distribuzione Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:41:16.395705+00:00'),
('ad443c73-7f83-441b-804f-dd7e617c0117', 114, 'Casting & Scelte', 'La voce fuori campo originale e la scelta di Sam Elliott', 'I fratelli Coen scrissero il ruolo dello ''Straniero'' (The Stranger) pensando specificamente a Sam Elliott, pur non conoscendolo personalmente, dopo aver visto la sua interpretazione in ''Il grinta'' del 1969. L''attore accettò immediatamente la parte senza nemmeno leggere l''intero copione, affascinato dal tono unico della sceneggiatura.', 'Commento audio del Blu-ray e interviste promozionali ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:24.69781+00:00'),
('a5dca51c-f62a-421c-8f85-ca02ea928f6f', 114, 'Aneddoti dal set', 'La genesi del cane di Walter e il prestito dal rifugio', 'Il cane di razza Basset Hound che appare in diverse scene insieme a Walter Sobchak (John Goodman) fu trovato grazie a un''agenzia di casting per animali. Sul set si chiamava ufficialmente Baron, ma la troupe e gli attori faticavano a farlo rispondere ai comandi durante le riprese, richiedendo l''intervento costante del suo addestratore fuori campo.', 'Note di produzione e documentario ''The Lebowski Fest Chronicles''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:24.69781+00:00'),
('3e4d8e3f-790a-4e6b-b567-b7f01cca6b5f', 119, 'Segreti di produzione', 'L''ispirazione per il design delle ali dell''Avvoltoio', 'Per conferire un aspetto più realistico e minaccioso alle ali meccaniche di Adrian Tooms, il dipartimento artistico guidato dal capo dello sviluppo visivo Ryan Meinerding si è ispirato alla silhouette dei bombardieri militari stealth e ai veri movimenti dei rapaci.', 'The Art of Spider-Man: Homecoming - Official Artbook', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:46.506122+00:00'),
('00935113-3e49-40e5-accc-696b8dd15efd', 119, 'Aneddoti dal set', 'La voce originale di Happy Hogan e le battute improvvisate', 'Jon Favreau ha spesso improvvisato le sue battute nei panni di Happy Hogan, in particolare nelle scene in cui discute frustrato al telefono con Tony Stark riguardo alla supervisione di Peter Parker, attingendo alla sua esperienza di regista nei Marvel Studios.', 'Audio commentario del regista Jon Watts', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:46.506122+00:00'),
('7f8e2530-1229-4d8b-8087-6186180fbb9b', 119, 'Citazioni & Easter Egg', 'Il riferimento a Star Wars nell''interrogatorio della polizia', 'Durante la sequenza in cui Aaron Davis viene immobilizzato con la ragnatela e interrogato da Spider-Man nel parcheggio, il modo in cui il criminale reagisce e parla capovolto è un chiaro omaggio visivo e di tono alle classiche dinamiche di interrogatorio dei film d''azione anni ''80.', 'Analisi ufficiale e visual commentary della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:46.506122+00:00'),
('2bc8d2be-a407-48a0-a559-ef7121ede1de', 124, 'Aneddoti dal set', 'La ripresa del pugno nel fango', 'Durante il titanico scontro finale tra Neo e l''Agente Smith sotto la pioggia, Keanu Reeves e Hugo Weaving dovettero girare per quasi tre settimane in set allagati e fangosi. Weaving riportò la rottura di una costola e vari stiramenti muscolari a causa dell''intensità dei combattimenti corpo a corpo.', 'Commento audio del cast e documentario Roots of the Matrix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:10.134855+00:00'),
('29cd5d70-fcae-48f7-8a23-bbeee6eec024', 124, 'Casting & Scelte', 'Il rifiuto del ruolo di Persephone', 'Prima che Monica Bellucci ottenesse l''iconica parte di Persephone, le sorelle Wachowski avevano inizialmente offerto il ruolo all''attrice asiatica Michelle Yeoh, la quale dovette declinare l''offerta a causa di pregressi conflitti di programmazione con altri progetti cinematografici.', 'Note di produzione ufficiali Warner Bros', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:10.134855+00:00'),
('e7884212-7625-4767-ac98-0088a89a2a16', 124, 'Effetti speciali & Trucco', 'La tecnica di stunt per il Super Burly Brawl', 'Per realizzare i combattimenti aerei in cui centinaia di cloni dell''Agente Smith si scontrano con Neo, la produzione ha combinato la cattura di movimento avanzata con sculture digitali dei volti degli stuntmen, soprannominate internamente dal team di digitalizzazione come la ''virtual stunt crew''.', 'Making-of Behind the Revolution VFX', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:10.134855+00:00'),
('810f9a78-1559-436a-a6ee-8af272e70630', 124, 'Segreti di produzione', 'La skyline di Zion ricostruita in miniatura', 'Anziché affidarsi esclusivamente alla computer grafica, la sequenza in cui la città sotterranea di Zion viene invasa dalle macchine ha utilizzato enormi miniature fisiche dettagliate costruite nei teatri di posa di Sydney, integrate con elementi digitali in post-produzione.', 'Articolo di American Cinematographer del 2003', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:10.134855+00:00'),
('a438833d-25c1-49be-8f3d-6814dc6786a1', 124, 'Casting & Scelte', 'Il cameo di Jada Pinkett Smith e la cicatrice', 'Jada Pinkett Smith, interprete del capitano Niobe, si sottoponeva quotidianamente a oltre due ore di trucco per applicare la complessa protesi della cicatrice sul viso e per gestire le sue elaborate treccine, pesanti quasi due chili quando bagnate durante le scene d''azione.', 'Intervista al reparto trucco e parrucco nel DVD di Revolutions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:10.134855+00:00'),
('af974125-21ee-45c1-b534-9d778a3293a4', 124, 'Citazioni & Easter Egg', 'Il riferimento biblico nei nomi delle navi', 'La nave pilotata da Niobe, la Logos, prende il nome dal termine greco che significa ''verbo'' o ''ragione'', inserendosi nella fitta rete di allegorie filosofiche e religiose volute dalle registe per l''intera trilogia.', 'Analisi ufficiale dei simboli della trilogia di Matrix', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:10.134855+00:00'),
('5a3082f6-6f96-4a46-93a9-283efac12c1b', 113, 'Casting & Scelte', 'La scelta iniziale di Elizabeth Debicki', 'L''attrice Elizabeth Debicki è stata fortemente voluta dal regista Julius Onah e dai produttori per il ruolo di Mina Jensen grazie alla sua impressionante statura e alla sua versatilità drammatica, ritenute perfette per trasmettere la vulnerabilità e la pericolosità del suo personaggio multidimensionale.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:22.107244+00:00'),
('45e1cb8b-9ee7-4781-be61-3fc61436e9b5', 113, 'Aneddoti dal set', 'L''uso dei cavi di sospensione e il dolore fisico', 'Gli attori principali, tra cui Gugu Mbatha-Raw e David Oyelowo, hanno dovuto trascorrere settimane appesi a imbracature e cavi d''acciaio per simulare l''assenza di gravità, riportando lividi e affaticamento muscolare nonostante l''uso di stunt double per le scene più dinamiche.', 'Intervista nel dietro le quinte del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:22.107244+00:00'),
('73008c3f-532c-40cd-9909-28b6c410a8fa', 113, 'Effetti speciali & Trucco', 'Il trucco prostetico per il braccio di Mundy', 'Per la complessa sequenza in cui il personaggio di Chris O''Dowd (Mundy) subisce bizzarri eventi legati al suo braccio, la produzione ha utilizzato protesi in silicone avanzate e animatronics controllati da remoto, combinati con effetti visivi digitali per le transizioni più cruente.', 'Making-of ufficiale degli effetti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:22.107244+00:00'),
('6f6692ff-1ade-430b-9d7b-8ebaab470fa8', 113, 'Segreti di produzione', 'Il design claustrofobico dei set rotanti', 'Per ricreare la stazione spaziale Cloverfield, la scenografa J.J. Abrams e il suo team hanno costruito set parzialmente rotanti ispirati ai classici della fantascienza come ''Alien'' e ''2001: Odissea nello spazio'', limitando deliberatamente gli spazi per aumentare la tensione psicologica.', 'Articolo di approfondimento su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:22.107244+00:00'),
('a237591f-a17b-47c9-adca-8de34b04a766', 113, 'Citazioni & Easter Egg', 'Il tributo visivo a Ridley Scott', 'All''interno del laboratorio della stazione spaziale si possono notare alcuni monitor e pulsantiere che riproducono fedelmente il design dei computer della Nostromo di ''Alien'', inseriti dalla troupe come omaggio esplicito al cinema sci-fi degli anni Settanta.', 'Analisi visiva e DVD Audio Commentary', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:22.107244+00:00'),
('83afa31d-181a-42be-a97a-e7bb0acbb632', 118, 'Aneddoti dal set', 'La chitarra antica distrutta sul set', 'Durante la scena in cui Kurt Russell distrugge la chitarra suonata da Jennifer Jason Leigh, lo strumento utilizzato non era una copia di scena, bensì una preziosa chitarra Martin del 1870 presa in prestito dal Martin Guitar Museum. L''attore non sapeva che il cimelio storico dovesse essere sostituito da una replica prima dello schianto, lasciando l''attrice e i curatori del museo sinceramente sotto choc.', 'Dichiarazione ufficiale del sound mixer Mark Ulano e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:42.882081+00:00'),
('7f7a93be-0676-4ad5-81cb-0d61694225e6', 118, 'Casting & Scelte', 'Il leak della sceneggiatura e il rischio di cancellazione', 'All''inizio del 2014, la sceneggiatura del film fu trafugata e distribuita online, spingendo Tarantino a dichiarare furiosamente di voler abbandonare il progetto e pubblicare il testo come romanzo. L''autore cambiò idea dopo aver organizzato una lettura pubblica a scopo benefico del copione con il cast al completo al LACMA di Los Angeles, un successo tale da convincerlo a riprendere la lavorazione.', 'Intervista ufficiale di Quentin Tarantino a Deadline', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:42.882081+00:00'),
('2ef8bbe5-8fa9-4290-a155-c405e5c6bfa0', 118, 'Aneddoti dal set', 'Jennifer Jason Leigh e la vera neve in bocca', 'Per mantenere il massimo realismo durante la sequenza in cui il suo personaggio viene trascinato nella neve e coperto dagli agenti atmosferici, Jennifer Jason Leigh ha rifiutato in molte occasioni gli stunt double. Ha recitato con neve finta a base di cellulosa mista a vera neve portata sul set, ingerendo detriti e lottando realmente con il fango ghiacciato.', 'Making-of ufficiale ''Beyond the Snow''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:42.882081+00:00'),
('be743324-1f3e-4e46-8f91-c8174981afd6', 118, 'Casting & Scelte', 'Il cameo di Channing Tatum e la segretezza del ruolo', 'La presenza di Channing Tatum nel ruolo del fuorilegge Jody Domergue fu tenuta rigorosamente nascosta dalla produzione per evitare spoiler sulla trama e sulla struttura dei personaggi. L''attore fu aggiunto all''ultimo minuto ed escluso persino dai materiali promozionali preliminari.', 'Note di produzione e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:42.882081+00:00'),
('0908b130-ca50-40b6-93cf-d591e38fd0a4', 118, 'Citazioni & Easter Egg', 'L''omaggio a ''La cosa'' di John Carpenter', 'Il film presenta numerosi legami con il cult fantascientifico ''La cosa'' di John Carpenter: oltre alla scelta di ingaggiare Kurt Russell come protagonista e Ennio Morricone per la colonna sonora (che riutilizzò anche brani scartati da quel film), l''intera dinamica di sospetto reciproco tra sconosciuti bloccati nel gelo ricalca fedelmente le premesse della pellicola del 1982.', 'Commento audio e analisi comparativa del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:42.882081+00:00'),
('a1e19fbc-dd36-4791-a90f-721575e31046', 118, 'Curiosità & Retroscena', 'La scelta di Ennio Morricone e la vittoria all''Oscar', 'Ennio Morricone accettò di comporre la colonna sonora originale per Tarantino dopo anni di rifiuti verso il cinema hollywoodiano contemporaneo. Il celebre maestro italiano vinse il premio Oscar come Miglior Colonna Sonora nel 2016, segnando la sua prima vittoria in assoluto in una competizione ufficiale dell''Academy per una colonna sonora originale.', 'Discorso di accettazione e comunicato stampa dell''Academy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:42.882081+00:00'),
('2a99bb67-ef42-4ebb-8a9e-198b4b36ead5', 118, 'Segreti di produzione', 'Gli abiti storici realizzati da Courtney Wise', 'La costumista Courtney Wise ha studiato meticolosamente i registri fotografici dell''era post-Guerra Civile per ricreare abiti autentici capaci di resistere alle sollecitazioni estreme del finto fango e del sangue finto. Ogni cappotto e giacca di lana pesante fu cucito a mano con tessuti d''epoca per evitare qualsiasi anacronismo tessile.', 'Featurette sui costumi nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:41:42.882081+00:00'),
('b62f3779-5cc0-49b6-b940-739ca8d9abc8', 128, 'Casting & Scelte', 'Il rifiuto iniziale di Eli Wallach', 'Sergio Leone aveva inizialmente pensato a Eli Wallach per il ruolo del bandito Juan Miranda, visto il grande successo del loro sodalizio in ''Il buono, il brutto, il cattivo''. Tuttavia, l''attore rifiutò la parte, aprendo la strada all''ingaggio di Rod Steiger.', 'Biografie ufficiali e note di produzione di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:29.834497+00:00'),
('d2019f96-2b76-481e-89a7-9e253a1fac0f', 128, 'Casting & Scelte', 'La rinuncia alla regia di Peter Bogdanovich', 'Prima che Sergio Leone decidesse di dirigere personalmente il film, la produzione aveva affidato la regia a Peter Bogdanovich. Tuttavia, le divergenze artistiche con Leone (che figurava come produttore) portarono all''allontanamento di Bogdanovich e al ritorno di Leone dietro la macchina presa.', 'Documentari storici sulla produzione di Leone e archivi UA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:29.834497+00:00'),
('0144cc51-ece5-4d09-b8ee-efc6abc6aff8', 128, 'Casting & Scelte', 'Jason Robards e la parte di John Mallory', 'Per il ruolo del dinamitardo irlandese John Mallory fu inizialmente considerato Jason Robards, attore con cui Leone aveva già lavorato in ''C''era una volta il West''. La produzione optò poi per James Coburn per conferire al personaggio un dinamismo fisico differente.', 'Note di casting degli archivi United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:29.834497+00:00'),
('ab7cbfa5-45df-4e65-9781-6879ee991330', 115, 'Casting & Scelte', 'Il numero di telefono di Mia Wallace dimenticato', 'Il numero di telefono che Mia Wallace scrive su un tovaglietto per darlo a Vincent Vega apparteneva in realtà a una segreteria telefonica di proprietà della produzione, configurandosi come uno dei primi celebri easter egg telefonici del cinema indipendente anni ''90.', 'Archivio di produzione Miramax Films', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:28.773081+00:00'),
('7c4560cd-a0c0-4a94-b81c-6feb51169c4c', 123, 'Casting & Scelte', 'La preparazione marziale di Carrie-Anne Moss', 'Prima di iniziare le riprese, l''attrice Carrie-Anne Moss ha dovuto sottoporsi a sei mesi di allenamento intensivo e rigoroso sotto la guida del leggendario coordinatore degli stunt Yuen Woo-ping. Durante una sessione di prove, si ruppe una costola ma decise di non rivelarlo alla produzione per paura di essere sostituita.', 'Documentario ''The Matrix Reloaded: Enter the Matrix'' (Making-of ufficiale)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:04.835433+00:00'),
('5fecaaac-b924-400f-b702-6115d080ef4f', 123, 'Segreti di produzione', 'La costruzione dell''autostrada privata', 'Poiché non era permesso girare le pericolose sequenze di inseguimento sulle vere autostrade californiane, la produzione ha speso circa 2,5 milioni di dollari per costruire da zero un tratto di autostrada lungo quasi due miglia, completo di rampe e barriere, utilizzando una ex base militare a Alameda, in California.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:04.835433+00:00'),
('37e6e54a-2097-4fb9-b591-7df2d0e7309d', 123, 'Citazioni & Easter Egg', 'Il cameo di Cornel West', 'Il celebre filosofo e attivista afroamericano Cornel West appare nel film in un piccolo ruolo cameo interpretando il consigliere West. Le sorelle Wachowski erano così grandi ammiratrici dei suoi saggi sulla filosofia e sulla razza da aver inserito i suoi libri nelle letture obbligatorie per l''intero cast durante la pre-produzione del primo film.', 'Commento audio del filosofo Ken Wilber e del critico filmico nel DVD speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:04.835433+00:00'),
('2d4e5604-208f-4cc1-b1f7-9a22cecc733f', 123, 'Aneddoti dal set', 'L''infortunio di Keanu Reeves sul set', 'Keanu Reeves ha subito una grave distorsione alla caviglia durante le prove per la monumentale scena del combattimento tra Neo e le centinaia di cloni dell''Agente Smith (noto come il ''Burly Brawl''). Per evitare di bloccare la produzione, le riprese della sequenza furono riorganizzate spostando prima le inquadrature che richiedevano meno mobilità per l''attore.', 'Intervista al regista e al supervisore degli stunt Chad Stahelski', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:04.835433+00:00'),
('3ed44bd6-a33b-4c2d-8566-3cc522ec1675', 123, 'Effetti speciali & Trucco', 'La genesi del sistema di codifica ''Universal Capture''', 'Per realizzare la scena del ''Burly Brawl'' e consentire ai computer di replicare digitalmente Hugo Weaving e le sue controfigure, gli effetti speciali della ESC Entertainment hanno inventato una nuova tecnologia di scansione volumetrica chiamata ''Universal Capture'', in grado di catturare l''espressione facciale e l''illuminazione da molteplici angolazioni simultaneamente.', 'Documentario tecnico sugli effetti visivi di John Gaeta nel cofanetto Ultimate Matrix Collection', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:04.835433+00:00'),
('0fb1e826-9039-4f00-bd3d-e001429619f0', 123, 'Casting & Scelte', 'Jada Pinkett Smith e il ruolo scritto su misura', 'Il personaggio del capitano Niobe fu scritto originariamente con Jada Pinkett Smith in mente, dopo che l''attrice aveva fatto un provino di grande successo per il ruolo di Trinity nel primo film del 1999, poi assegnato a Carrie-Anne Moss. Le sorelle Wachowski vollero fortemente la Pinkett Smith nel sequel per valorizzare le sue spiccate doti atletiche.', 'Intervista promozionale a Jada Pinkett Smith per la premiere del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:04.835433+00:00'),
('232c2365-c0fa-4139-8c3d-1e1bc69708fd', 123, 'Curiosità & Retroscena', 'Il videogioco collegato alla trama', 'La sequenza in cui il personaggio di Jada Pinkett Smith, Niobe, si lancia con la sua nave attraverso un tunnel per consegnare una chiave cruciale è stata concepita in tandem con il videogioco ''Enter the Matrix''. Le riprese delle scene d''intermezzo del gioco furono girate contemporaneamente alla produzione cinematografica, utilizzando gli stessi set e attori.', 'Making-of del videogioco ''Enter the Matrix'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:42:04.835433+00:00'),
('a5839537-d880-469b-8aaf-c44c3ca2b93a', 123, 'Segreti di produzione', 'L''imponente set del club Hell', 'Il set della sequenza d''apertura all''interno del locale sotterraneo ''Hell'' fu costruito interamente all''interno di un enorme teatro di posa a Sydney, in Australia, richiedendo mesi di falegnameria e la progettazione di impianti idraulici complessi per le cascate d''acqua che fanno da sfondo al combattimento tra Trinity e i vampiri.', 'Libro ''The Art of The Matrix'' e intervista allo scenografo Owen Paterson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:42:04.835433+00:00'),
('cd480312-e421-4be1-a045-b47a6bd762d1', 134, 'Aneddoti dal set', 'La vera rissa verbale con Hulk Hogan alla premiere', 'Durante le riprese dell''incontro benefico sul ring tra Rocky e Thunderlips, interpretato da Hulk Hogan, i due lottatori usarono colpi coreografati ma molto intensi che costrinsero Hogan a sottoporsi a cure mediche per costole incrinate. Anni dopo, Hogan rivelò che Stallone lo aveva avvertito di ''andare sul sicuro'', ma la fisicità imponente rese quasi impossibile evitare contatti reali sul set.', 'Intervista retrospettiva a Hulk Hogan / Documentario Making of Rocky III', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:39.776087+00:00'),
('9d545031-d9e2-4e57-a728-f87d1a7a5ad2', 134, 'Segreti di produzione', 'La statua di bronzo donata a San Diego', 'La grande statua di Rocky Balboa commissionata per il film fu realizzata dallo scultore A. Thomas Schomberg. Dopo la fine della produzione, Stallone donò la statua alla città di Philadelphia, dove fu collocata originariamente in cima alle scale del Philadelphia Museum of Art prima di essere spostata in seguito a polemiche sulla sua natura commerciale.', 'Note di produzione ufficiali United Artists / Archivi storici di Philadelphia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:39.776087+00:00'),
('075f9f68-0177-4f48-bf76-3c94a7c75ab0', 134, 'Casting & Scelte', 'Il provino fortuito di Mr. T a Los Angeles', 'Laurence Tureaud, noto come Mr. T, fu scoperto da Sylvester Stallone quasi per caso mentre partecipava a una competizione televisiva intitolata ''America''s Toughest Bouncer'' (Il guardiano più duro d''America). Stallone rimase così colpito dalla sua presenza scenica e dalle sue battute taglienti da offrirgli immediatamente il ruolo di Clubber Lang.', 'Autobiografia di Mr. T / Speciale DVD di Rocky III', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:39.776087+00:00'),
('0735d80d-7134-4b1a-97af-8894b6a4d78f', 134, 'Aneddoti dal set', 'L''infortunio alla spalla durante gli allenamenti', 'Nella sequenza in cui Apollo Creed allena Rocky a Los Angeles sulla spiaggia, Sylvester Stallone subì una grave distorsione alla spalla sinistra durante una scena di corsa e stretching sulla sabbia. La produzione dovette interrompere brevemente le riprese per permettere all''attore di sottoporsi a terapie intensive prima di riprendere il set.', 'Diario di bordo della troupe / Commento audio del regista Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:39.776087+00:00'),
('094a9f87-4607-424b-a2a7-4a32462096c9', 348, 'Effetti speciali & Trucco', 'La cicatrice protesica di Tom Cruise', 'Il truccatore premio Oscar Michèle Burke ha ideato una protesi facciale in silicone estremamente sottile per ricreare le gravi lesioni al viso di David, applicandola quotidianamente all''attore con un processo che richiedeva oltre tre ore di lavorazione.', 'Documentario sul making-of ''Prelude to a Dream''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:15.136143+00:00'),
('235306c3-b301-447f-9d49-29bb22374dfc', 116, 'Segreti di produzione', 'L''ispirazione per i pantaloni a vita alta', 'La costumista Casey Storm ha disegnato i caratteristici pantaloni a vita alta di Theodore non per seguire una moda futuristica esagerata, ma ispirandosi a una tendenza reale osservata tra gli hipster di Los Angeles e Brooklyn durante la fase di preparazione. Questa scelta stilistica serviva a dare al personaggio un aspetto leggermente infantile, antiquato e vulnerabile, incapace di integrarsi del tutto con i tempi.', 'Note di produzione ufficiali e intervista a Casey Storm per Dazed', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:33.178631+00:00'),
('bac12cf7-e842-44de-8f1e-de9b4df17c28', 116, 'Segreti di produzione', 'L''assenza dei computer tradizionali', 'Per enfatizzare l''immersione totale in un mondo dominato da intelligenze artificiali vocali e auricolari, Spike Jonze e il direttore della fotografia Hoyte van Hoytema hanno deciso di eliminare quasi del tutto la presenza di mouse, tastiere e monitor tradizionali di grandi dimensioni in tutto il film.', 'Commento audio del regista e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:33.178631+00:00'),
('1080a677-c9e4-4a30-9063-352f959fc733', 116, 'Aneddoti dal set', 'I pantaloni di Joaquin Phoenix e la post-produzione', 'Joaquin Phoenix ha dovuto indossare nuovamente quei particolari pantaloni a vita alta diversi mesi dopo la fine delle riprese principali, in quanto Spike Jonze richiese alcune sessioni di riprese aggiuntive per raccordare i cambi di sceneggiatura legati al passaggio da Samantha Morton a Scarlett Johansson.', 'Intervista a Joaquin Phoenix per GQ', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:33.178631+00:00'),
('d3cbf383-40ae-4257-b5ee-02b33ac6a9a0', 116, 'Casting & Scelte', 'La cancellazione del cameo di Chris Pratt', 'Chris Pratt aveva originariamente girato un ruolo secondario nel film interpretando Paul, un collega di lavoro di Theodore con cui quest''ultimo intrattiene brevi conversazioni in ufficio. Tuttavia, in fase di montaggio finale, Spike Jonze ha deciso di tagliare quasi tutte le scene in ufficio per focalizzarsi esclusivamente sulla relazione intima tra Theodore e Samantha.', 'Curiosità di produzione e IMDb Trivia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:33.178631+00:00'),
('317b63dd-59f3-43c2-a3f8-04938c062589', 116, 'Curiosità & Retroscena', 'Il premio Oscar per la scenografia a K.K. Barrett e Austin Gorg', 'Il film ha vinto il prestigioso Premio Oscar per la migliore scenografia nel 2014, un riconoscimento particolarmente significativo per un''opera che ha evitato la classica estetica cyberpunk distopica e cupa, optando invece per un futuro luminoso, pulito, caldo e incredibilmente vicino alla nostra realtà.', 'Archivio ufficiale dell''Academy Awards', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:33.178631+00:00'),
('175b5b3d-d459-401d-af20-395ee7c04705', 121, 'Effetti speciali & Trucco', 'La cicatrice reale di Tom Holland sulla fronte', 'Durante le riprese di un''intensa sequenza d''azione, Tom Holland ha urtato accidentalmente contro una telecamera subendo una contusione che ha richiesto l''applicazione di trucco correttivo e protesico per mascherare il gonfiore temporaneo sul volto dell''attore.', 'Note di produzione e interviste al reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:54.113844+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('0c7986d5-39e1-4695-bf25-f05e6b13f898', 121, 'Casting & Scelte', 'Il ritorno di Jamie Foxx e il nuovo look senza l''iconico blu', 'Quando il regista Jon Watts ha proposto a Jamie Foxx di tornare a interpretare Electro, l''attore ha posto come condizione principale l''abbandono della colorazione interamente blu vista in ''The Amazing Spider-Man 2'', preferendo un aspetto più umano ed energetico con scariche elettriche gialle.', 'Intervista ufficiale a Jamie Foxx per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:54.113844+00:00'),
('7677c596-8eff-4b0b-a11b-bbbcfe111f97', 121, 'Casting & Scelte', 'Il cameo dei fratelli di Tom Holland tagliato dal montaggio finale', 'Il fratello minore di Tom Holland, Harry Holland, aveva girato un cameo nei panni di un ladro che viene sollevato in aria da Spider-Man durante una sequenza acrobatica, ma la scena è stata quasi interamente tagliata nel montaggio cinematografico per ragioni di ritmo narrativo, sebbene sia rimasta visibile in alcune versioni preliminari.', 'Dichiarazioni di Tom Holland al Tonight Show di Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:54.113844+00:00'),
('d53975f7-a1c6-4b2a-8625-e8502d22ce21', 126, 'Casting & Scelte', 'Il rifiuto di Charles Bronson e Henry Fonda', 'Sergio Leone aveva inizialmente pensato a Charles Bronson per il ruolo di Sentenza e a Henry Fonda per quello del ''Buono'', ma entrambi rifiutarono l''offerta; Bronson preferì recitare in Quella sporca dozzina, spingendo Leone a richiamare Lee Van Cleef e a puntare nuovamente su Clint Eastwood.', 'Biografie ufficiali e interviste storiche a Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:18.007858+00:00'),
('89b933fa-6298-4543-bcee-69fb5f0e291f', 126, 'Segreti di produzione', 'La polvere da sparo autentica per gli effetti', 'Per rendere le esplosioni e i duelli più realistici, la produzione utilizzò veri carichi di polvere nera controllati da esperti artificieri spagnoli, disseminando micro-cariche esplosive sui costumi degli attori e nel terreno del set di Almería.', 'Note di produzione e documentari d''archivio sulla trilogia del dollaro', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:18.007858+00:00'),
('d65d9195-b8e9-40c9-910a-ab72fd7d8b55', 126, 'Aneddoti dal set', 'L''improvvisazione dei sigari Toscanello', 'Clint Eastwood conservava lo stesso mozzicone di sigaro toscano in tasca per tutte le riprese della trilogia senza mai accenderlo nelle scene in cui non era espressamente richiesto, contribuendo a definire l''iconica estetica trasandata del personaggio.', 'Commento audio del film e interviste a Clint Eastwood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:18.007858+00:00'),
('e04a2955-d268-463e-8481-86c65b380929', 126, 'Aneddoti dal set', 'La finta pioggia di Almería e il fango reale', 'Le riprese nel fango durante le sequenze della prigionia e del campo di concentramento richiesero l''impiego di autobotti antincendio locali per bagnare continuamente il terreno desertico della Spagna meridionale, creando condizioni di lavoro estenuanti per il cast.', 'Diari di lavorazione della troupe di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:18.007858+00:00'),
('22c9750c-a31d-46f3-a823-fa11965a5fd9', 126, 'Segreti di produzione', 'Il doppiaggio in post-produzione e l''assenza di presa diretta', 'Come prassi consolidata del cinema italiano dell''epoca, l''intero film fu girato rigorosamente senza registrare l''audio in presa diretta; ogni battuta, inclusi i dialoghi in inglese di Eastwood e Van Cleef, fu doppiata in studio successivamente.', 'Archivi storici di Cinecittà e storia del doppiaggio italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:18.007858+00:00'),
('7bdfeb6a-191d-4997-991d-30894d4c57ae', 126, 'Curiosità & Retroscena', 'Ennio Morricone e la musica composta prima delle riprese', 'Il celebre e rivoluzionario tema musicale composto da Ennio Morricone fu scritto e registrato prima ancora che le riprese principali iniziassero, permettendo a Sergio Leone di far ascoltare la colonna sonora agli attori direttamente sul set per ispirare la loro recitazione.', 'Interviste documentario a Ennio Morricone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:18.007858+00:00'),
('163ca152-b441-4b51-87b3-03f3df0ca114', 137, 'Aneddoti dal set', 'Jean Reno al volante', 'Durante le riprese delle sequenze di guida spericolata, l''attore Jean Reno ha insistito per guidare personalmente in molte scene d''azione, impressionando i piloti professionisti ingaggiati per il film grazie alla sua abilità e freddezza al volante.', 'Contenuti speciali e making-of dell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:52.036009+00:00'),
('54851ca3-72f6-4bf8-b939-c4b1c9990b28', 122, 'Casting & Scelte', 'Il rifiuto di Will Smith', 'A Will Smith fu inizialmente offerto il ruolo di Neo, ma l''attore declinò l''offerta per recitare in Wild Wild West (1999), una decisione che in seguito ha ammesso di non rimpiangere poiché sentiva che all''epoca non avrebbe avuto la maturità artistica per valorizzare il progetto.', 'Intervista ufficiale di Will Smith sul suo canale YouTube e documentari di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:41:59.224008+00:00'),
('eb1a40c6-8e60-4e7b-8de0-4ea2e7bcc648', 122, 'Aneddoti dal set', 'Il training di arti marziali di quattro mesi', 'Prima di iniziare le riprese principali a Sydney, l''intero cast principale (inclusi Keanu Reeves e Carrie-Anne Moss) fu sottoposto a quattro mesi di addestramento intensivo sotto la guida del leggendario coordinatore degli stunt Yuen Woo-ping, lavorando sei ore al giorno per apprendere il wire-fu e le tecniche di combattimento.', 'Making-of ufficiale ''The Making of The Matrix'' presente nei contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:41:59.224008+00:00'),
('bf2df852-5878-494a-b1fe-535ae403fada', 122, 'Aneddoti dal set', 'La polmonite e la frattura al collo di Keanu Reeves', 'Keanu Reeves ha girato gran parte delle scene iniziali del film mentre soffriva di una grave forma di polmonite e indossava un collare ortopedico a causa di un''operazione chirurgica per una fusione spinale subita poco prima delle riprese, motivo per cui non poteva eseguire alcuni movimenti di rotazione del collo.', 'Intervista a Keanu Reeves per la promozione del film e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:41:59.224008+00:00'),
('cc0d5e02-daf2-4cf5-8ca0-6e5456e5baaa', 122, 'Segreti di produzione', 'Il codice verde ispirato ai ricettari di sushi', 'Il celebre codice digitale a cascata che apre il film non è un linguaggio informatico complesso, bensì opera del production designer Simon Whiteley, il quale scannerizzò i caratteri katakana giapponesi dai ricettari di sushi di sua moglie e li rielaborò digitalmente.', 'Intervista a Simon Whiteley per Wired e documentario sul design visivo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:41:59.224008+00:00'),
('00f54d46-6963-443b-b900-21e1e26d3006', 122, 'Casting & Scelte', 'Sean Connery e l''offerta per il ruolo di Morpheus', 'Prima che la parte venisse affidata a Laurence Fishburne, i produttori offrirono il ruolo di Morpheus a Sean Connery, il quale rifiutò categoricamente dichiarando di non aver capito assolutamente nulla della complessa sceneggiatura scritta dalle sorelle Wachowski.', 'Dichiarazioni pubbliche di Sean Connery e retroscena di casting ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:41:59.224008+00:00'),
('23462c82-0a0c-4821-826c-2171d8d8dfbf', 122, 'Effetti speciali & Trucco', 'La scena della hall e gli effetti pratici', 'La spettacolare sparatoria nella hall dell''edificio governativo non fece ricorso esclusivamente al computer: gran parte delle colonne, dei marmi e degli arredi furono fatti esplodere utilizzando cariche di pirotecnica reale e ripetuti rallentamenti di camera per catturare le schegge in volo.', 'Commento audio del regista e supervisor degli effetti speciali John Gaeta', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:41:59.224008+00:00'),
('091c47f9-de5e-4abd-a81d-156dfbdeae33', 122, 'Citazioni & Easter Egg', 'Il numero civico di Oracle come Easter Egg', 'L''appartamento in cui vive l''Oracolo porta il numero 303, un chiaro riferimento biblico al capitolo 3, versetto 3 del Vangelo di Giovanni (''In verità, in verità ti dico, se uno non rinaesc da alto, non può vedere il regno di Dio''), che anticipa il tema della rinascita di Neo.', 'Analisi critiche ufficiali e libri di approfondimento sul simbolismo del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:41:59.224008+00:00'),
('26966383-e6fe-47db-8f37-a700455336e4', 127, 'Casting & Scelte', 'Il rifiuto iniziale di Al Mulock per il ruolo di Snaky', 'L''attore Al Mulock, che interpreta uno dei membri della banda di Frank nella sequenza d''apertura, fu inizialmente contattato da Sergio Leone con qualche esitazione a causa del suo carattere imprevedibile. Mulock si tolse tragicamente la vita durante la post-produzione del film gettandosi dalla finestra del suo albergo a Guadix, in Spagna, indossando ancora il costume di scena.', 'Documentario Sergio Leone: The Way West e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:25.097279+00:00'),
('9469e220-dafd-45df-a969-89ee1873f673', 127, 'Casting & Scelte', 'La scelta di Jack Elam per il pistolero calmo', 'Per il celebre ruolo di Steve, il pistolero che attende l''arrivo del treno insieme agli altri sgherri nella stazione di Flagstone, Sergio Leone volle fortemente il caratterista Jack Elam, celebre per il suo strabismo caratteristico che accentuava la bizzarria e la minacciosietà del personaggio.', 'Note di produzione e archivi della United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:25.097279+00:00'),
('76d6bf68-c77f-45e1-8db3-85b275dd6baf', 127, 'Aneddoti dal set', 'Il vento artificiale e la polvere di Almería', 'Durante le riprese nel deserto di Tabernas ad Almería, in Spagna, la troupe dovette fronteggiare raffiche di vento naturali fortissime che venivano ulteriormente potenziate da enormi elicotteri e macchine del vento per creare le celebri e polverose atmosfere desolate della cittadina di Flagstone.', 'Making-of ufficiale e diari di troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:25.097279+00:00'),
('9fa5b544-dfe1-4b05-96fa-3e891aecd801', 127, 'Segreti di produzione', 'La torre di controllo della ferrovia costruita da zero', 'La stazione ferroviaria di Sweetwater e la torre di controllo furono interamente costruite ex novo in scala reale nel deserto spagnolo da Carlo Simi, scenografo storico di Leone, per permettere le complesse riprese in esterni e l''interazione con veri treni d''epoca fatti arrivare appositamente.', 'Archivio storico di Carlo Simi e commento audio del critico Christopher Frayling', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:25.097279+00:00'),
('8265618a-e82b-439f-8ee7-e6580b8b17fc', 127, 'Effetti speciali & Trucco', 'Gli occhi azzurri di Henry Fonda e le lenti a contatto', 'Per aumentare l''impatto visivo della spietatezza di Frank, Sergio Leone aveva inizialmente pensato di far indossare a Henry Fonda delle lenti a contatto scure per nascondere i suoi celebri occhi azzurri. Fu lo stesso attore a convincere il regista a mantenerli naturali, ottenendo un contrasto ancora più gelido tra il suo sguardo mite e la crudeltà dei suoi atti.', 'Interviste d''archivio a Henry Fonda e biografia di Christopher Frayling', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:25.097279+00:00'),
('a97116a2-382b-46dd-a837-29de6e50a6bc', 127, 'Citazioni & Easter Egg', 'L''omaggio visivo ai classici di John Ford', 'L''arrivo di Jill McBain (Claudia Cardinale) alla stazione di Flagstone e l''inquadratura in cui scende dal treno e attraversa la sala d''attesa sono un esplicito omaggio visivo e strutturale ai film classici di John Ford, in particolare a ''Sentieri selvaggi'' e ''Un uomo tranquillo''.', 'Analisi critiche e saggi sul cinema di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:25.097279+00:00'),
('ce3beb0f-c89b-4c19-a7a9-9f03f88e11ca', 127, 'Segreti di produzione', 'Il treno storico noleggiato dalle ferrovie spagnole', 'La locomotiva a vapore e le carrozze utilizzate nella sequenza iniziale e in tutto il film non erano modellini, ma un vero treno d''epoca perfettamente funzionante noleggiato dalla Renfe (le ferrovie spagnole) e riverniciato appositamente per la produzione.', 'Note di produzione della Rafran Cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:42:25.097279+00:00'),
('ca4fe913-c87e-4b14-a077-a0daa36d2434', 348, 'Aneddoti dal set', 'L''uso di brani musicali sul set', 'Come sua consuetudine per favorire l''immersione emotiva degli attori, Cameron Crowe faceva suonare altoparlanti portatili con la colonna sonora e brani rock classici direttamente durante le riprese delle scene drammatiche.', 'Intervista di Cameron Crowe a Rolling Stone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:15.136143+00:00'),
('5b95168a-c09b-4ece-91ae-b383bde42560', 124, 'Curiosità & Retroscena', 'L''addio alle scene di combattimento di Carrie-Anne Moss', 'Carrie-Anne Moss subì un infortunio alla gamba durante le prove preliminari delle scene d''azione a Sydney, costringendo la produzione a riorganizzare l''intero calendario delle riprese per permetterle di completare le sequenze più pericolose senza aggravare il trauma.', 'Documentario Behind the Matrix: The MTV Special', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:42:10.134855+00:00'),
('adac0724-a8aa-4609-8fd5-de23201e85cb', 124, 'Effetti speciali & Trucco', 'La sfida dei server di rendering', 'La sequenza finale della pioggia e del cielo digitale di Matrix Revolutions ha richiesto una potenza di calcolo senza precedenti per l''epoca, costringendo la casa di effetti visivi ESC Entertainment a costruire una nuova farm di server dedicata esclusivamente a gestire i riflessi sulle gocce d''acqua.', 'Cinefex Magazine n. 96', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:42:10.134855+00:00'),
('7b5e3192-161b-4828-8b3b-31f6047b1bc6', 143, 'Casting & Scelte', 'Il rifiuto di Lorraine Gary', 'Lorraine Gary, che aveva interpretato Ellen Brody nei primi due capitoli della saga, declinò l''offerta di riprendere il suo ruolo in questo terzo film. Il suo personaggio fu quindi escluso dalla sceneggiatura, lasciando spazio unicamente ai figli Sean e Michael.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:16.855876+00:00'),
('ed0d1503-4a06-4a34-b4a5-864c88640d33', 143, 'Segreti di produzione', 'L''uso pionieristico del sistema ArriVision 3D', 'Per girare il film in 3D stereoscopico, il regista Joe Alves e il direttore della fotografia James A. Contner utilizzarono il sistema ArriVision 3D, che richiedeva l''uso di due cineprese montate insieme. Questa configurazione ingombrante creò enormi problemi logistici nelle riprese subacquee all''interno delle vasche di SeaWorld.', 'American Cinematographer Magazine, 1983', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:16.855876+00:00'),
('4f883e80-f79a-45a6-beac-015d57d5b6a4', 143, 'Effetti speciali & Trucco', 'Il malfunzionamento dello squalo meccanico', 'Come nei capitoli precedenti, il grosso squalo meccanico (ribattezzato ''Bruce III'') subì frequenti guasti a causa dell''acqua salata e della pressione. Molte sequenze in cui lo squalo sfonda il vetro di controllo dovettero essere riprogettate all''ultimo minuto utilizzando miniature e riprese in studio.', 'Documentario ''The Making of Jaws 3-D'' e interviste alla troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:16.855876+00:00'),
('b5d5d196-bd9f-4f12-90e8-b75c638e7c68', 143, 'Casting & Scelte', 'Il cameo mancato di Richard Dreyfuss', 'Ai produttori sarebbe piaciuto coinvolgere Richard Dreyfuss riproducendo il suo personaggio di Matt Hooper dal primo film, ma l''attore declinò categoricamente l''offerta, rifiutandosi di prendere parte al progetto.', 'Archivi storici di produzione Universal e biografie del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:16.855876+00:00'),
('1d8ac853-9ee7-4754-86b2-16a797f147e4', 143, 'Curiosità & Retroscena', 'La riscrittura di Richard Matheson e Carl Gottlieb', 'La sceneggiatura originale, concepita da John Flynn e Guerdon Trueblood, prevedeva una commedia satirica intitolata ''Jaws 3, People 0'' dove lo squalo attaccava una cittadina di provincia. Il progetto fu completamente stravolto e riscritto da Richard Matheson e Carl Gottlieb per spostare l''ambientazione nel parco acquatico.', 'Cinefex Magazine e interviste agli sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:16.855876+00:00'),
('691cc6a8-80aa-4c85-8475-a306db9a427a', 143, 'Segreti di produzione', 'I problemi di proiezione nelle sale cinematografiche', 'All''uscita nelle sale, l''effetto 3D soffrì enormemente a causa della scarsa qualità della proiezione in polarizzazione doppia in molti cinema dell''epoca. Spesso gli spettatori si lamentavano di forte stanchezza visiva e sfarfallii dell''immagine, compromettendo il successo commerciale iniziale.', 'Variety, recensioni cinematografiche dell''agosto 1983', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:16.855876+00:00'),
('c4a66d6b-2d63-41c6-9a03-4b87970e0cd6', 143, 'Casting & Scelte', 'Lea Thompson e il debutto cinematografico', 'L''attrice Lea Thompson, qui nel ruolo della sciatrice d''acqua Kelly Ann Bukowski, ottenne la sua primissima apparizione cinematografica in questo film. Poco dopo avrebbe raggiunto la celebrità internazionale grazie a ''Ritorno al futuro'' (1985).', 'Crediti ufficiali del film e interviste retrospettive all''attrice', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:43:16.855876+00:00'),
('639d057f-237a-496a-bbe0-f9f5499d70c6', 148, 'Casting & Scelte', 'La scelta iniziale di Peter Weir per Aubrey', 'Prima che Russell Crowe venisse ufficialmente ingaggiato per il ruolo del Capitano Jack Aubrey, la produzione aveva considerato seriamente attori del calibro di Hugh Jackman o Liam Neeson per guidare la HMS Surprise.', 'Note di produzione ufficiali della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:39.436235+00:00'),
('0e2f9cb3-e62c-4cd0-b17d-c1a80bd96fc4', 148, 'Aneddoti dal set', 'Il mal di mare della troupe', 'Durante le riprese in mare aperto al largo di Rosarito, in Messico (nella stessa gigantesca piscina usata per Titanic), gran parte della troupe tecnica e delle comparse ha sofferto costantemente di grave mal di mare a causa del movimento idraulico delle piattaforme e delle repliche navali.', 'Special di Making-of nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:39.436235+00:00'),
('d2e4a732-15a8-4404-acc5-6bc34701c8ef', 148, 'Curiosità & Retroscena', 'L''autenticità del gergo navale', 'Per mantenere il massimo rigore filologico con i romanzi di Patrick O''Brian, gli attori dovettero imparare a usare correttamente la terminologia nautica della Royal Navy del 1805, assistiti da storici navali presenti a tempo pieno sul set.', 'Intervista al consulente storico Dean King', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:39.436235+00:00'),
('e781c6b4-ec75-43af-80d9-70a5a3427f7b', 148, 'Segreti di produzione', 'Modelli in scala e vasche di prova', 'Gran parte delle sequenze di tempesta e dei combattimenti navali complessi non sono stati realizzati interamente in CGI, ma adoperando sofisticati modelli in scala ridotta di 25 piedi filmati all''interno di enormi vasche d''acqua con effetti di pioggia e vento artificiali.', 'Documentario sugli effetti speciali di Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:39.436235+00:00'),
('f257ccc0-1241-4987-ba79-8bef03e9dfa7', 148, 'Aneddoti dal set', 'L''infortunio di Paul Bettany', 'Paul Bettany, che interpreta il chirurgo di bordo Stephen Maturin, ha rischiato seriamente di annegare durante le riprese di una scena in cui la sua giacca pesante lo ha trascinato sott''acqua, venendo prontamente salvato dalle troupe di sommozzatori di soccorso.', 'Commento audio del regista Peter Weir', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:39.436235+00:00'),
('8ff3fc88-6986-405d-a1a4-79d74a55bccf', 148, 'Segreti di produzione', 'La cura maniacale per i costumi d''epoca', 'La costumista Wendy Stites ha fatto tessere a mano gran parte dei tessuti utilizzati per le uniformi della Royal Navy, impiegando tecniche di tintura vegetale dell''epoca per evitare l''effetto ''lucido'' dei tessuti sintetici moderni sotto la luce naturale.', 'Intervista alla costumista Wendy Stites nei contenuti extra', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:39.436235+00:00'),
('2876ac24-a15d-4abf-89ef-b724232ca69d', 148, 'Curiosità & Retroscena', 'Le vere specie delle Galápagos', 'Poiché le riprese non si sono svolte direttamente sulle vere isole Galápagos per via delle rigide normative di protezione ambientale, la troupe ha dovuto ricreare la flora e la fauna locale utilizzando sia location costiere messicane che iguane e tartarughe addestrate in studio.', 'Diario di bordo della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:43:39.436235+00:00'),
('84434266-43cc-4721-bff6-90bef6b453ce', 125, 'Curiosità & Retroscena', 'Il cameo dei registi di seconda unità', 'Diversi stuntman di lungo corso e membri chiave della seconda unità di regia, che avevano già lavorato ai capitoli originali della trilogia, hanno fatto brevi apparizioni cameo non accreditate tra la folla nelle scene ambientate a San Francisco.', 'Accrediti della troupe e documentario sul backstage', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:13.733451+00:00'),
('95b38565-e7db-4d56-92df-bda77ac6f256', 348, 'Citazioni & Easter Egg', 'Il cameo di Steven Spielberg', 'Il celebre regista Steven Spielberg appare brevemente in un cameo non accreditato nella sequenza della festa di compleanno iniziale, interpretando uno degli invitati che salutano David Aames.', 'Acccrediti nei titoli di coda e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:15.136143+00:00'),
('06b00214-0a95-44e4-bfd9-3c5e67315f12', 348, 'Curiosità & Retroscena', 'L''ispirazione per il titolo e i quadri', 'Il titolo del film fa riferimento a un celebre dipinto di Claude Monet, ''La passeggiata (Argenteus)'' o ''Vanilla Sky'', menzionato nel film per descrivere il cielo peculiare che appare nei sogni lucidi del protagonista.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:15.136143+00:00'),
('45bfa094-0ac9-4294-8553-919224ec5ec4', 367, 'Effetti speciali & Trucco', 'La gestione del sangue sintetico ad alta viscosità', 'Il team degli effetti speciali ha sviluppato una miscela di sangue sintetico a base di sciroppo di glucosio e coloranti alimentari che non seccava sotto le luci calde del set, permettendo di mantenere la continuità visiva nelle sequenze d''azione prolungate.', 'Featurette ''The Art of Gore'' nel Blu-ray ufficiale', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 6, '2026-11-03T16:14:40.167506+00:00'),
('b73199a6-a81c-497b-bb59-eab3b10181b9', 367, 'Aneddoti dal set', 'L''improvvisazione di Myha''la nella scena della cucina', 'Nella sequenza del confronto in cucina, Myha''la ha improvvisato l''uso di un utensile da cucina come arma di fortuna, una scelta che ha costretto lo stunt coordinator a modificare la coreografia del combattimento in tempo reale per garantire la sicurezza sul set.', 'Commento audio del regista Kirill Sokolov, edizione home video', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 7, '2026-11-03T16:14:40.167506+00:00'),
('0f48e92d-0f48-48f4-856b-9470ed8ec000', 367, 'Citazioni & Easter Egg', 'Omaggio visivo a Why Don''t You Just Die!', 'Il numero civico del Virgil è 1989, un riferimento diretto all''anno di nascita del regista Kirill Sokolov e un omaggio nascosto al suo film d''esordio ''Why Don''t You Just Die!'', visibile su una targa metallica all''ingresso dell''edificio.', 'Analisi visiva e trivia su IMDb, novembre 2026', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 8, '2026-11-03T16:14:40.167506+00:00'),
('95eae22d-a6da-4ccd-8f60-c2dd764311d4', 128, 'Aneddoti dal set', 'I dissapori sul set tra Leone e Rod Steiger', 'Il rapporto sul set tra Sergio Leone e Rod Steiger fu particolarmente teso a causa dei differenti metodi di recitazione: Steiger, legato all''Actors Studio, chiedeva continue motivazioni psicologiche per le sue azioni, mentre Leone privilegiava la componente visiva e la stilizzazione del personaggio.', 'Interviste retrospettive a Rod Steiger e biografie del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:29.834497+00:00'),
('c6c029c9-ad01-4d1a-b2e2-d12115c6374d', 128, 'Aneddoti dal set', 'La sparatoria nel fango e le condizioni climatiche', 'Molte delle sequenze ambientate nella zona rurale messicana furono girate nella regione di Almería in Spagna in condizioni meteorologiche avverse, trasformando il terreno in un pantano fangoso che rese estremamente faticose le riprese delle scene d''azione per gli attori e le comparse.', 'Reportage di produzione e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:29.834497+00:00'),
('ddc87112-6a25-40ae-afac-59a8d3fdfb84', 128, 'Segreti di produzione', 'L''uso estensivo delle cave di Almería', 'Per ricostruire gli scenari polverosi e aridi della rivoluzione messicana, la troupe utilizzò le cave di gesso e le zone desertiche nei dintorni di Almería e Guadix, luoghi storici già sfruttati da Leone e da altri registi per gli spaghetti western.', 'Location scout report e guide storiche ai set cinematografici spagnoli', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:29.834497+00:00'),
('f77b2bd7-a5ba-43b3-a30f-2ab37541cad3', 128, 'Segreti di produzione', 'La ricostruzione della banca di Mesa Verde', 'La monumentale sequenza della banca di Mesa Verde, dove Juan Miranda viene costretto a fare la rapina, richiese la costruzione di una facciata scenografica imponente progettata dallo scenografo Carlo Simi, integrando interni in studio e set esterni reali.', 'Archivio storico e progetti di Carlo Simi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:42:29.834497+00:00'),
('0f46b758-b3f5-48ee-be7a-012c5f449e10', 128, 'Citazioni & Easter Egg', 'Omaggio esplicito a John Ford', 'In diverse sequenze del film, in particolare nella caratterizzazione del personaggio di John Mallory e nella gestione dei paesaggi naturali ampi, Sergio Leone inserisce chiare citazioni visive al cinema western classico di John Ford, omaggiando i suoi maestri d''oltreoceano.', 'Analisi critiche e saggi sul cinema di Sergio Leone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:42:29.834497+00:00'),
('50c9acb3-490a-4858-9bf5-929db23ca90e', 128, 'Curiosità & Retroscena', 'Il riferimento storico alla rivoluzione di Zapata e Villa', 'Sebbene i protagonisti siano personaggi di finzione, il contesto socio-politico del film trae ispirazione diretta dalle figure reali di Emiliano Zapata e Pancho Villa, riflettendo la disillusione di Leone nei confronti delle rivoluzioni tradite dai poteri forti.', 'Note storiche e interviste promozionali del regista all''uscita del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:42:29.834497+00:00'),
('58ace0b9-b3df-4224-bae1-8d3840d25393', 139, 'Casting & Scelte', 'La cancellazione del nome giapponese per il mercato occidentale', 'Nel romanzo originale di Kotaro Isaka, la maggior parte dei personaggi chiave aveva nomi tradizionali giapponesi, ma i produttori decisero di occidentalizzare i nomi (come nel caso di Tangerine e Lemon) per rendere il cast corale più immediatamente riconoscibile dal pubblico internazionale, scatenando inizialmente qualche dibattito tra i fan dei libri.', 'Note di produzione ufficiali Sony Pictures e interviste all''autore Kotaro Isaka', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:58.589001+00:00'),
('1d1fe2cf-bbce-4d05-a651-071d603a7c8e', 139, 'Segreti di produzione', 'La tuta bianca immacolata di Brad Pitt e i ricambi multipli', 'La costumista Sarah Evelyn ha rivelato che la celebre giacca e i pantaloni beige chiari indossati da Brad Pitt per tutta la durata del film hanno richiesto la creazione di oltre settanta copie identiche sul set per gestire l''accumulo di sangue finto, polvere e strappi causati dalle continue sequenze d''azione.', 'Intervista della costumista Sarah Evelyn a Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:58.589001+00:00'),
('af7c9064-9a9d-4326-b2f9-34541b3b8cb4', 139, 'Citazioni & Easter Egg', 'L''ispirazione visiva tratta da Akira Kurosawa', 'Il regista David Leitch e il direttore della fotografia Jonathan Sela hanno studiato attentamente la messa in scena dei drammi giapponesi classici, in particolare i film di Akira Kurosawa, per gestire la tensione all''interno degli spazi claustrofobici dei vagoni ferroviari, bilanciando il caos visivo con una rigorosa simmetria delle inquadrature.', 'Commento audio del regista David Leitch nell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:58.589001+00:00'),
('9a8e7d26-6c3a-485c-a957-46b56fa61d63', 139, 'Effetti speciali & Trucco', 'La cicatrice e il trucco prostetico di Aaron Taylor-Johnson', 'Il look di Tangerine, caratterizzato da barba curata e dettagli sartoriali britannici, è stato completato da leggeri ritocchi prostetici sul viso dell''attore per accentuare i segni della sua vita da sicario veterano, applicati quotidianamente dai reparti di trucco in meno di venti minuti.', 'Making-of ufficiale incluso nei contenuti speciali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:58.589001+00:00'),
('ec6e2c44-00eb-4dda-9826-d77b75d88e03', 139, 'Segreti di produzione', 'L''uso esteso delle pareti a LED al posto dei green screen', 'Invece di ricorrere interamente al tradizionale chroma key verde per simulare il treno in corsa a oltre trecento chilometri orari, la produzione ha utilizzato enormi pannelli a LED attorno ai set dei vagoni per proiettare sfondi in movimento reale, fornendo agli attori un''illuminazione dinamica naturale e autentici riflessi sui finestrini.', 'Featurette tecnica di produzione e reportage di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:58.589001+00:00'),
('0191b0e2-cc45-4b9b-8f6c-eeaf4f923f1a', 149, 'Curiosità & Retroscena', 'La colonna sonora degli Oliver Onions', 'Il celebre brano portante ''Dune Buggy'', composto e cantato dal duo Guido e Maurizio De Angelis (noto come Oliver Onions), ottenne un successo straordinario nelle classifiche discografiche tedesche, rimanendo nella Top 10 per settimane e vendendo centinaia di migliaia di copie.', 'Note di produzione e archivio storico RCA Italiana', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:42.862061+00:00'),
('f18b9f1e-be52-4c18-bbde-4ab48f953be2', 149, 'Aneddoti dal set', 'L''infortunio sul set di Terence Hill', 'Durante le riprese delle sequenze d''azione, Terence Hill rischiò seriamente un infortunio alla schiena a causa di una caduta mal calcolata durante una zuffa coreografata, costringendo la produzione a fermare temporaneamente i piani di lavorazione per un giorno.', 'Report di produzione e interviste d''archivio al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:42.862061+00:00'),
('a43cf7fc-c705-45e5-8308-b40b8dcc1c9a', 149, 'Casting & Scelte', 'La scelta del titolo internazionale', 'Nei mercati di lingua inglese il film fu distribuito con il titolo ''Watch Out, We''re Mad!'', modificando la minaccia letterale italiana in un''espressione idiomatica più orecchiabile per il pubblico anglosassone, pur mantenendo intatta la fama del duo.', 'Documentazione ufficiale di distribuzione internazionale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:42.862061+00:00'),
('ddbc5df9-f781-4015-bfa8-c16fd102adbc', 149, 'Segreti di produzione', 'L''uso delle doppie vetture', 'Per girare le spericolate scene di guida e la sequenza in cui la Dune Buggy viene distrutta dagli scagnozzi del Capo, la produzione fece costruire non uno ma ben due esemplari di riserva identici, utilizzati esclusivamente per gli stunt più pericolosi.', 'Libro di memorie sul cinema di Bud Spencer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:42.862061+00:00'),
('d50f85bd-ab06-47bc-b7c4-20960c3ef7b9', 133, 'Aneddoti dal set', 'L''infortunio sul set di Brad Pitt durante le scene d''azione', 'Durante le riprese delle sequenze in cui Cliff Booth ripara l''antenna televisiva sul tetto della casa di Rick Dalton, Brad Pitt ha subito una distorsione alla caviglia a causa della scivolosità delle tegole artificiali. L''incidente ha richiesto una breve pausa nella programmazione delle scene fisiche più impegnative.', 'Diario di produzione e interviste al cast sul making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:35.71274+00:00'),
('5660f60a-dedf-4cf9-a9ee-13b83dfc4bdd', 138, 'Casting & Scelte', 'Il rifiuto di Paul Thomas Anderson', 'Quentin Tarantino aveva inizialmente offerto la regia di Jackie Brown a Paul Thomas Anderson, grande estimatore di Elmore Leonard, ma questi declinò l''offerta preferendo concentrarsi sul suo progetto personale ''Boogie Nights''.', 'Interviste retrospettive di Paul Thomas Anderson e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:42:54.763+00:00'),
('12caf9b4-18d1-4e82-8987-9c2c1d6dd1ed', 138, 'Citazioni & Easter Egg', 'La scelta musicale di Bobby Womack', 'La celebre canzone ''Across 110th Street'' di Bobby Womack, usata nei titoli di testa e di coda, fu scelta da Tarantino non solo per il suo profondo legame con il cinema blaxploitation degli anni ''70, ma come tributo diretto all''omonimo film poliziesco del 1972.', 'Commento audio del regista nel DVD/Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:54.763+00:00'),
('53e0acd8-c02a-4bea-a2ec-a492fe32d092', 138, 'Casting & Scelte', 'Il vero passato cinematografico di Pam Grier', 'Nel film, quando Max Cherry regala a Jackie un nastro di Delfonics, lei menziona di aver visto i loro concerti a Detroit; un riferimento che strizza l''occhio alla reale carriera musicale e alla giovinezza della Grier nell''ambiente soul e R&B.', 'Documentario ''How Jackie Brown Was Made''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:54.763+00:00'),
('d69e1e38-287c-4c25-b99b-47f37058ce3a', 138, 'Aneddoti dal set', 'L''improvvisazione della battuta di Michael Keaton', 'Durante la scena in cui Ray Nicolette (Michael Keaton) discute con l''agente dell''ATF Mark Dargus, alcune delle battute più taglienti sul conto di Ordell Robbie furono il risultato di brevi e stimolanti sessioni di improvvisazione concesse da Tarantino sul set.', 'Note di produzione e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:54.763+00:00'),
('1bf92e69-59b4-4215-bbc1-8b24d5256984', 153, 'Aneddoti dal set', 'La registrazione in solitaria di Tom Hanks', 'Tom Hanks ha registrato la maggior parte delle sue battute tra una pausa e l''altra delle riprese di film vincitori di Oscar come ''Philadelphia'' e ''Forrest Gump'', spesso lavorando di notte o volando negli studi Pixar nei fine settimana.', 'Commento audio del regista John Lasseter nell''edizione speciale DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:58.448827+00:00'),
('6935323e-c376-47c8-be77-aefd4909dd2f', 153, 'Casting & Scelte', 'Billy Crystal e l''occasione mancata', 'John Lasseter offrì inizialmente il ruolo di Buzz Lightyear a Billy Crystal, il quale rifiutò la parte. Anni dopo, l''attore ha ammesso che si è trattato del più grande rimpianto della sua carriera, un errore a cui pose rimedio accettando con entusiasmo di doppiare Mike Wazowski in ''Monsters & Co.''', 'Intervista ufficiale a Billy Crystal per il Tonight Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:58.448827+00:00'),
('ae04f4c9-a780-4f58-877c-5efbf36e2da9', 153, 'Citazioni & Easter Egg', 'Il cameo della lampada Luxo Jr.', 'La celebre lampada da scrivania saltellante Luxo Jr., protagonista dell''omonimo cortometraggio del 1986 che ha lanciato la Pixar, fa una breve apparizione nella cameretta di Andy all''inizio del film, posizionata sopra una mensola.', 'Analisi visiva ufficiale ed Easter Egg documentati della Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:58.448827+00:00'),
('2afab5d4-4582-401c-bbac-ffcc07b7155b', 153, 'Citazioni & Easter Egg', 'Il tappeto ispirato a The Shining', 'Il motivo geometrico del tappeto dei corridoi nella casa di Sid Phillips è un omaggio diretto al celebre motivo esagonale del pavimento dell''Overlook Hotel nel capolavoro horror ''The Shining'' di Stanley Kubrick.', 'Documentario di produzione Pixar e registri visivi ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:58.448827+00:00'),
('a318fc8c-c353-4de2-b8b8-34c0baa3c85a', 153, 'Segreti di produzione', 'L''ispirazione per il design di Buzz Lightyear', 'Il design della tuta spaziale di Buzz Lightyear non fu ispirato solo dai giocattoli degli anni ''60 e ''70, ma anche dalle tute reali indossate dagli astronauti delle missioni Apollo e dai colori delle confezioni di caramelle giapponesi.', 'Art of Toy Story - Libro d''arte ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:58.448827+00:00'),
('aeb83a4c-8fa6-4b73-a4c8-a1d3c5e96dd5', 153, 'Casting & Scelte', 'La scelta iniziale di Paul Newman per Woody', 'Prima che Tom Hanks fosse scritturato, i produttori valutarono attivamente grandi icone di Hollywood per dare voce al cowboy Woody, tra cui Paul Newman, la cui presenza avrebbe conferito un tono completamente diverso al personaggio.', 'Archivi storici di pre-produzione della Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:58.448827+00:00'),
('6975532f-e714-46e3-8723-19ee902ecc99', 353, 'Curiosità & Retroscena', 'Il vero incidente aereo della FedEx', 'La drammatica sequenza dello schianto dell''aereo cargo nel Pacifico fu realizzata con straordinario realismo tecnico, sebbene la vera Federal Express avesse espressamente richiesto che l''aereo precipitato non somigliasse in modo identico ai propri velivoli reali per motivi di pubbliche relazioni e sicurezza del marchio.', 'Note di produzione e archivi storici della Twentieth Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:23.624263+00:00'),
('70d2b4e8-cdae-45d0-a971-9eecbecbc6a3', 353, 'Segreti di produzione', 'L''assenza totale di colonne sonore nella parte centrale', 'Il compositore Alan Silvestri scelse di non utilizzare alcuna musica orchestrale per l''intera ora centrale del film ambientata sull''isola deserta, affidando la costruzione della tensione emotiva e dell''atmosfera unicamente ai suoni naturali della natura, delle onde e del vento registrati in presa diretta.', 'Note di copertina della colonna sonora ufficiale di Alan Silvestri', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:23.624263+00:00'),
('96abb7a1-df0c-4321-adad-508e71802d29', 361, 'Aneddoti dal set', 'Le condizioni estreme di caldo sul set', 'Le riprese si svolsero nel Texas rurale durante l''estate del 1973 con temperature che superavano regolarmente i 40°C. A causa del budget limitato, l''aria condizionata della casa non poteva essere accesa per via del rumore, costringendo cast e troupe a lavorare in condizioni di soffocamento e con scarsa ventilazione.', 'Documentario ''The Texas Chainsaw Massacre: A Family Portrait''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:51.983757+00:00'),
('aece367d-6b2f-49c4-b8df-4256af43433d', 361, 'Effetti speciali & Trucco', 'Il vero sangue usato nella scena della cena', 'Durante la famigerata sequenza della cena con la famiglia cannibale, l''attrice Marilyn Burns si tagliò realmente il dito perché la finta capsula di sangue non fuoriusciva correttamente e l''attore Jim Siedow, nei panni del Vecchio, usò un vero rasoio per bucarle il dito e prelevare sangue reale per la scena.', 'Commento audio del regista Tobe Hooper', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:51.983757+00:00'),
('4fe94058-deb0-4759-8d99-45d52e321206', 361, 'Retroscena di produzione', 'L''odore nauseabondo degli interni', 'Per arredare la casa della famiglia di cannibali, lo scenografo Robert A. Burns utilizzò centinaia di vere ossa di animali e pelli in decomposizione raccolte nei dintorni. L''odore sul set divenne così insopportabile e putrescente che molti membri della troupe furono costretti a indossare maschere antigas o a vomitare durante le riprese.', 'Libro ''The Texas Chain Saw Massacre: The Official Companion'' di Stephen Hand', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:51.983757+00:00'),
('0f088e46-cccd-4578-82ba-908dd47c5fb6', 134, 'Curiosità & Retroscena', 'L''uso del brano ''Eye of the Tiger'' rifiutato in un primo momento', 'Sylvester Stallone aveva inizialmente chiesto ai Queen di poter utilizzare il brano ''Another One Bites the Dust'' come canzone principale del film. Di fronte al rifiuto della band britannica, Stallone si rivolse al gruppo rock Survivor, commissionando loro un brano che rispecchiasse il ritmo dei pugni, dando vita alla celebre ''Eye of the Tiger''.', 'Intervista a Jim Peterik dei Survivor / Note storiche della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:39.776087+00:00'),
('f6025370-8dcc-433b-9486-887cbc629bce', 152, 'Casting & Scelte', 'La scelta iniziale di Wolfgang Petersen', 'Prima di firmare per dirigere questo adattamento, Wolfgang Petersen era stato considerato per dirigere il film originale del 1972 ''L''avventura del Poseidon'', ma rifiutò l''offerta perché era impegnato con altri progetti in Europa.', 'Audio commento del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:53.943163+00:00'),
('df48fc2f-eecf-4c9b-b048-3351ace2bca4', 152, 'Aneddoti dal set', 'L''immersione continua della troupe', 'Gran parte delle riprese si è svolta all''interno di enormi serbatoi d''acqua nei Warner Bros. Studios, costringendo cast e troupe a indossare mute da sub sotto i costumi di scena e a trascorrere intere giornate completamente bagnati.', 'Documentario sul making-of del film ''The Poseidon Adventure: The Art of the Disaster''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:53.943163+00:00'),
('e9897dea-48da-4464-89cd-fdcfda7195bd', 152, 'Segreti di produzione', 'La progettazione dei set rotanti', 'Per simulare il capovolgimento della nave, il production designer William Sandell ha realizzato set montati su piattaforme cardaniche capaci di ruotare di 180 gradi, permettendo agli attori di interagire con scenografie realmente in movimento.', 'Note di produzione e pressbook ufficiale della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:53.943163+00:00'),
('639a52f2-32a9-4c03-ba09-11fef048a6ab', 152, 'Citazioni & Easter Egg', 'Il cameo vocale di Wolfgang Petersen', 'Il regista Wolfgang Petersen appare in un piccolo cameo non accreditato nella sequenza iniziale del film, prestando la propria voce agli annunci trasmessi dagli altoparlanti della nave nei momenti precedenti al disastro.', 'Trivia e sezioni speciali dell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:53.943163+00:00'),
('c3504f60-d917-44de-821b-5885585a0976', 152, 'Effetti speciali & Trucco', 'L''uso estensivo di stuntmen professionisti', 'Data la pericolosità delle sequenze con tonnellate d''acqua in pressione che si riversavano nei corridoi, la produzione ha impiegato oltre quaranta stuntmen professionisti coordinati da Simon Crane per le scene più rischiose.', 'Intervista al coordinatore degli stuntmen nel booklet di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:53.943163+00:00'),
('6a49423a-26ab-4024-93c6-754cd2025385', 355, 'Segreti di produzione', 'La struttura cromatica basata sui fumetti', 'Il direttore della fotografia Eduardo Serra e il regista M. Night Shyamalan hanno diviso rigorosamente la palette cromatica dei personaggi in base ai tropi dei fumetti: il verde scuro e freddo per David Dunn, l''ocra e il viola regale per Elijah Price (Mr. Glass), e l''arancione/rosso caldo per la moglie Audrey.', 'Commento audio del regista nel DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:27.622809+00:00'),
('1a3be48d-9220-46eb-aa4b-415aa6269edc', 355, 'Casting & Scelte', 'Il rifiuto del ruolo di David Dunn da parte di altri divi', 'Prima che Bruce Willis venisse ingaggiato, la sceneggiatura scritta appositamente per lui fu valutata da altri attori di primo piano a Hollywood, tra cui Nicolas Cage e Gary Oldman, i quali declinarono l''offerta prima che Shyamalan si decidesse a contattare direttamente Willis.', 'Archivi di produzione Touchstone Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:27.622809+00:00'),
('abc82572-b655-4c27-8a0d-f0ab25452d99', 355, 'Aneddoti dal set', 'La sequenza dell''incidente ferroviario senza tagli', 'La scena iniziale dell''incidente del treno Eastrail 177 è stata girata utilizzando un lunghissimo piano sequenza all''interno del vagone, realizzato con una telecamera montata su una speciale gru a braccio estensibile per seguire il caos dell''impatto senza stacchi di montaggio.', 'Documentario dietro le quinte ''The Making of Unbreakable''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:27.622809+00:00'),
('366af4e7-dbb6-48b9-821b-e48a90831f92', 355, 'Curiosità & Retroscena', 'L''ispirazione per il titolo e la struttura a trilogia mancata', 'Shyamalan aveva originariamente concepito Unbreakable come il primo capitolo di una trilogia epica sui cinecomics realistici; tuttavia, a causa dei modesti incassi iniziali rispetto al fenomeno ''The Sixth Sense'', i piani per i sequel furono accantonati per quasi vent''anni prima di trovare conclusione con ''Split'' (2016) e ''Glass'' (2019).', 'Interviste stampa per l''uscita cinematografica di Glass', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:27.622809+00:00'),
('d61fa98b-0780-45cb-90c5-7d2c997d58a1', 355, 'Aneddoti dal set', 'I reali problemi fisici di Samuel L. Jackson incorporati nel personaggio', 'A causa di una grave operazione alla spalla subita poco prima delle riprese, Samuel L. Jackson indossava un tutore nascosto sotto gli abiti e manteneva una postura estremamente rigida; la produzione decise di integrare questa limitazione fisica nella sceneggiatura, giustificandola con la fragilità ossea estrema della malattia di Elijah.', 'Note di produzione ufficiali Buena Vista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:27.622809+00:00'),
('41b22ebb-c47e-4d91-9471-16e543f3a747', 355, 'Citazioni & Easter Egg', 'Il significato nascosto dei numeri nei titoli di coda', 'Nelle sequenze finali del film, prima del testo scorrevole, compaiono delle statistiche mediche e di sopravvivenza che riprendono fedelmente i dati reali sui disastri ferroviari storici registrati dal National Transportation Safety Board americano.', 'Analisi tecnica del montaggio e trivia ufficiali IMDb', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:27.622809+00:00'),
('556b30fa-78b8-44a1-8491-aebf03dea4a7', 364, 'Casting & Scelte', 'Il coinvolgimento di Robert Pattinson nel progetto', 'Robert Pattinson è stato la prima scelta del regista Lance Oppenheim per interpretare Chris Hansen, dopo che il regista ha espresso il desiderio di esplorare la dualità tra l''immagine pubblica rassicurante del conduttore e l''ossessione voyeuristica del format televisivo.', 'Note di produzione ufficiali A24 e intervista su Variety', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T16:15:16.104217+00:00'),
('92da40a1-dc84-4127-85cf-7720d0d3a527', 364, 'Curiosità & Retroscena', 'Ricostruzione filologica del format To Catch a Predator', 'Per garantire l''autenticità visiva, la produzione ha utilizzato telecamere a circuito chiuso dell''epoca e ha replicato meticolosamente le scenografie delle case utilizzate da Dateline NBC nel 2006, consultando archivi di registrazioni originali per studiare l''illuminazione grezza tipica dei reality show dei primi anni 2000.', 'Intervista al direttore della fotografia in American Cinematographer', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T16:15:16.104217+00:00'),
('1afbe9dd-2f90-4015-b254-94d5528ade73', 364, 'Aneddoti dal set', 'Il debutto cinematografico di Phoebe Bridgers', 'La cantautrice Phoebe Bridgers è stata selezionata personalmente da Oppenheim per un ruolo di supporto, segnando il suo debutto in un lungometraggio narrativo dopo la sua esperienza nel cortometraggio ''I Know the End'' e vari contributi musicali per il cinema.', 'Comunicato stampa ufficiale del cast A24', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T16:15:16.104217+00:00'),
('c317b305-e458-4121-b4a6-b4dc93d461ec', 364, 'Segreti di produzione', 'Utilizzo di materiale d''archivio originale', 'Il film integra sequenze tratte dai veri segmenti di ''To Catch a Predator'' trasmessi da NBC, ottenute tramite accordi di licenza specifici per mantenere il tono documentaristico e il contrasto tra la finzione narrativa e la realtà cruda del materiale d''archivio.', 'Note di produzione e crediti del film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T16:15:16.104217+00:00'),
('7b1a6d94-9478-4da0-869c-23cc4871f5bc', 357, 'Casting & Scelte', 'La scelta iniziale di Wolfgang Petersen', 'Prima che Wolfgang Petersen si impegnasse ufficialmente nella regia del film, la Warner Bros. aveva valutato altri cineasti, tra cui bozze di sviluppo che vedevano Sidney Pollack associato al progetto quando i diritti del libro di Sebastian Junger furono acquistati per la prima volta.', 'Production Notes Warner Bros. / Variety archives', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:52:35.621312+00:00'),
('1e8e3b26-d7c1-4b31-b856-b9dbfd60cc29', 357, 'Aneddoti dal set', 'Le riprese nel Warner Bros. Water Tank', 'La celebre sequenza in cui la nave affronta l''onda anomala è stata girata nella gigantesca piscina per esterni degli studi Warner Bros. a Burbank, nota come Ventures Ranch, dove la produzione ha installato complessi sistemi idraulici capaci di muovere milioni di galloni d''acqua.', 'Making-of ufficiale ''The Perfect Storm: HBO First Look''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:52:35.621312+00:00'),
('022eaed4-bf0c-49f7-b581-8fc7020c2619', 137, 'Casting & Scelte', 'Il rifiuto di Jean-Paul Belmondo', 'Al leggendario attore francese Jean-Paul Belmondo fu inizialmente offerto un ruolo di primo piano nel film, ma rifiutò l''offerta, spingendo la produzione a ripiegare su altre icone del cinema europeo.', 'Note di produzione e biografie ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:42:52.036009+00:00'),
('02f36380-735b-4d9c-91ad-a858f9615151', 137, 'Aneddoti dal set', 'La ferita sul set di Robert De Niro', 'Robert De Niro si procurò una vera ferita a una mano durante le riprese della celebre scena in cui il suo personaggio, Sam, si estrae da solo un proiettile dal fianco usando pinze e filo di sutura, dimostrando il suo leggendario metodo di recitazione.', 'Intervista al regista John Frankenheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:42:52.036009+00:00'),
('53541531-50a4-46c0-adef-d4d8156c2276', 137, 'Segreti di produzione', 'L''uso dei veri armamenti', 'Il regista John Frankenheimer pretese che tutte le armi da fuoco utilizzate nel film fossero armi reali caricate a salve piuttosto che repliche, per garantire un peso e un rinculo autentici nelle mani degli attori durante le sparatorie.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:42:52.036009+00:00'),
('4901a92a-c104-4eb4-b702-445d36c92b9d', 137, 'Casting & Scelte', 'La riscrittura di David Mamet', 'Il celebre commediografo e sceneggiatore David Mamet ha lavorato pesantemente sulla sceneggiatura firmata da J.D. Zeik, ma chiese e ottenne di accreditare il suo lavoro con lo pseudonimo di Richard Weisz nei titoli di testa.', 'Archivio storico della Writers Guild of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:42:52.036009+00:00'),
('25587688-1dad-49b9-b5f0-d65c4770985d', 137, 'Segreti di produzione', 'Il vero passaporto cinematografico', 'I documenti, i passaporti e le carte d''identità falsi mostrati nel corso del film furono realizzati da esperti di contraffazione ingaggiati dalla produzione per replicare fedelmente i veri standard di sicurezza europei dell''epoca.', 'Documentario sulla realizzazione degli oggetti di scena', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:42:52.036009+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('19a4c403-820d-49bb-b05a-cb8d8fb3ff39', 142, 'Casting & Scelte', 'Il licenziamento del primo regista John Hancock', 'John Hancock fu originariamente ingaggiato per dirigere il film e girò per circa tre settimane prima di essere licenziato dai dirigenti della Universal. La produzione riteneva che la sua visione fosse troppo cupa e che le riprese con i bambini fossero troppo lente, portando alla sua sostituzione con Jeannot Szwarc.', 'Documentario ''The Making of Jaws 2'' e archivi di produzione Universal', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:12.200358+00:00'),
('10b41239-15b9-4339-a048-d5784b031827', 142, 'Curiosità & Retroscena', 'La riscrittura del copione a opera di Howard Sackler e Dorothy Tristan', 'Dopo l''arrivo del regista Jeannot Szwarc e l''allontanamento di John Hancock, la sceneggiatura fu ampiamente riscritta da Howard Sackler e Dorothy Tristan. Venne modificato il tono complessivo, spostando il fulcro narrativo sul pericolo costante che minacciava il gruppo di adolescenti in mare aperto.', 'Note di produzione ufficiali e libri retrospettivi sul franchise', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:12.200358+00:00'),
('85ef485a-f6c4-4e7d-997b-a568ef12f8d8', 142, 'Effetti speciali & Trucco', 'I problemi con il funzionamento dello squalo meccanico', 'Esattamente come nel primo capitolo, il mastodontico squalo meccanico (ribattezzato ''Bruce'' dalla troupe) soffrì di innumerevoli guasti dovuti all''acqua salata corrosiva della Florida. Molti degli attacchi dovettero essere girati suggerendo la presenza del predatore tramite pinne artificiali trainate da cavi e soggettive subacquee.', 'Special TV ''The Making of Jaws 2'' e interviste agli effetti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:12.200358+00:00'),
('49b56171-85ae-4a0e-901b-e142c288ce22', 142, 'Aneddoti dal set', 'L''insofferenza del cast giovanile per le lunghe ore in acqua', 'I giovani attori che interpretavano i velisti dovettero trascorrere settimane intere immersi nelle acque dell''oceano Atlantico e del Golfo del Messico a Navarre. A causa della prolungata esposizione all''acqua salata e al freddo, molti di loro soffrirono di infezioni alle orecchie e scompensi fisici durante le riprese.', 'Interviste retrospettive al cast giovanile nei contenuti extra dell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:12.200358+00:00'),
('f48e8cf3-497a-4bea-b1ea-581d929450e9', 142, 'Casting & Scelte', 'Il ritorno negato di Richard Dreyfuss', 'Richard Dreyfuss fu interpellato per riprendere il ruolo dell''oceanografo Matt Hooper, ma rifiutò categoricamente l''offerta. L''attore decise di non partecipare al sequel per concentrarsi su progetti cinematografici differenti come ''Incontri ravvicinati del terzo tipo'' e ''Goodbye & Amen''.', 'Biografia ufficiale di Richard Dreyfuss e interviste promozionali d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:12.200358+00:00'),
('7aa72306-84d8-4bd9-bed7-280015ef008d', 142, 'Segreti di produzione', 'La scena del cavo elettrico morsicato dallo squalo', 'Il climax del film in cui lo squalo morde il cavo dell''alta tensione e viene fulminato fu ideato per offrire una chiusura spettacolare ma plausibile. Per realizzare l''effetto della scarica elettrica, la troupe combinò esplosivi subacquei controllati con sequenze di montaggio serrate.', 'Storyboards originali e note di regia di Jeannot Szwarc', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:12.200358+00:00'),
('15a245b3-be1d-415a-a74b-16d6ff056631', 147, 'Casting & Scelte', 'La genesi del personaggio ispirata a Ron Charlton', 'Paul Hogan ideò il personaggio di Mick Dundee dopo aver incontrato Rodney Ansell, un sopravvissuto dell''outback australiano che visse per due mesi isolato nella natura selvaggia nel 1977. La sceneggiatura fu scritta da Hogan insieme a Ken Shadie e John Cornell in sole tre settimane.', 'Note di produzione ufficiali e documentario biografico su Paul Hogan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:35.012324+00:00'),
('03365747-512c-467b-bc72-ca36bb2d73db', 147, 'Segreti di produzione', 'Il budget ridotto autofinanziato', 'Il film fu finanziato in gran parte in modo indipendente da Paul Hogan e dal suo socio John Cornell, raccogliendo circa 8,8 dollari australiani tramite investitori privati per evitare il controllo creativo totale degli studios di Hollywood nelle fasi iniziali.', 'Archivio storico della Film Victoria e interviste alla produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:35.012324+00:00'),
('c5f57988-f845-4915-ac0d-687eb47a0449', 357, 'Curiosità & Retroscena', 'Il training con i veri pescatori di Gloucester', 'Per calarsi al meglio nei panni dei loro personaggi, George Clooney e Mark Wahlberg hanno trascorso diversi giorni a bordo di veri pescherecci d''altura a Gloucester prima dell''inizio delle riprese, affrontando il mare mosso del Nord Atlantico per comprendere la fatica reale del mestiere.', 'Audio commento del regista Wolfgang Petersen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:35.621312+00:00'),
('567938b2-76d7-4350-87e6-42244da5601a', 140, 'Curiosità & Retroscena', 'Il titolo originale e le modifiche distributive', 'Il film è uscito internazionalmente con il titolo ''The Immigrant'', ma in Italia è stato distribuito come ''C''era una volta a New York'' per richiamare le atmosfere epiche e nostalgiche care al cinema di Sergio Leone.', 'Comunicati stampa Lucky Red per la distribuzione italiana', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:02.083399+00:00'),
('13e75cdf-989e-42a3-85b1-87e45167be78', 357, 'Effetti speciali & Trucco', 'L''impiego pionieristico della CGI integrata', 'Industrial Light & Magic (ILM) ha combinato per la prima volta in modo così massiccio riprese in vasca con elementi digitali avanzati, creando simulazioni d''acqua e spruzzi oceanici tramite computer grafica che all''epoca rappresentavano la frontiera più avanzata del settore cinematografico.', 'Cinefex Magazine n. 83', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:35.621312+00:00'),
('0a35557d-90c1-4bf8-b2f8-1a00f4d5acc5', 357, 'Citazioni & Easter Egg', 'Il tributo finale alle reali vittime', 'Nei titoli di coda del film, la produzione ha inserito una dedica solenne e l''elenco dei veri membri dell''equipaggio dell''Andrea Gail e dei soccorritori della Guardia Costiera deceduti durante la tempesta del 1991, rispettando la memoria storica dei pescatori di Gloucester.', 'Titoli di coda ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:35.621312+00:00'),
('d25ea384-15c5-4d0f-9836-3acfea84dd25', 364, 'Effetti speciali & Trucco', 'Trasformazione fisica di Robert Pattinson', 'Il team di trucco ha lavorato per ricreare l''estetica televisiva del 2006, utilizzando protesi sottili e tecniche di color correction digitale per emulare la qualità video a bassa risoluzione delle telecamere nascoste dell''epoca, distinguendola dalla fotografia cinematografica principale.', 'Intervista al reparto trucco e post-produzione su IndieWire', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T16:15:16.104217+00:00'),
('c225a98f-66b5-4c0e-8c84-5d2089d9e6b0', 141, 'Aneddoti dal set', 'Il falso squalo che terrorizzava i bagnanti reali', 'Durante le riprese a Martha''s Vineyard, la troupe costruì un finto squalo trainato da una barca per effettuare test di inquadratura. Diversi turisti e residenti locali, ignari della finzione cinematografica, scambiarono l''oggetto per un vero predatore scatenando il panico lungo la costa prima che la produzione intervenisse a chiarire.', 'Cronache locali di Martha''s Vineyard e interviste alla troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:43:07.404422+00:00'),
('edd080d8-e38e-41df-89df-3bcc7af953ef', 146, 'Casting & Scelte', 'Dustin Hoffman quasi nei panni di Deckard', 'Prima che la parte del protagonista Rick Deckard fosse affidata a Harrison Ford, il regista Ridley Scott e i produttori discussero a lungo con Dustin Hoffman per il ruolo principale. Le trattative durarono mesi, ma il progetto sfumò a causa di divergenze creative sulla caratterizzazione del personaggio.', 'Documentario ''Dangerous Days: Making Blade Runner''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:30.854042+00:00'),
('deb6c77d-b856-4412-a2cf-83a175640ca5', 146, 'Effetti speciali & Trucco', 'Il malfunzionamento degli occhi riflettenti', 'Per ottenere il caratteristico bagliore rosso negli occhi dei replicanti, il direttore della fotografia Jordan Cronenweth utilizzò la tecnica della ''retro-riflessione'' ideata da Fritz Lang in Metropolis. Sul set si verificò però un problema costante: i minuscoli specchi semi-riflettenti posti davanti agli obiettivi della macchina da presa richiedevano un allineamento millimetrico quasi impossibile da mantenere con i movimenti di camera.', 'American Cinematographer, intervista a Jordan Cronenweth', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:30.854042+00:00'),
('88d09f8f-bf90-4a42-b6f4-a3f3dbdfc2d1', 146, 'Aneddoti dal set', 'La tensione sul set tra Harrison Ford e Sean Young', 'I rapporti tra Harrison Ford e Sean Young durante le riprese furono notoriamente tesi, arrivando al punto che la troupe soprannominò la celebre scena d''amore tra Deckard e Rachael ''The Hate Scene'' (la scena dell''odio). L''attrice ha confermato in seguito che la freddezza e la distanza tra i due attori riflettevano perfettamente l''inquietudine e la vulnerabilità dei loro personaggi.', 'Libro biografico ''Future Noir: The Making of Blade Runner'' di Paul M. Sammon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:30.854042+00:00'),
('5c65d1b5-96fe-48e9-a518-3c400edc5320', 146, 'Segreti di produzione', 'Il modello in miniatura del Bradbury Building', 'La memorabile sequenza finale all''interno del celebre edificio di Los Angeles fu realizzata in gran parte combinando interni reali con complessi modelli in scala ridotta costruiti nei laboratori della Douglas Trumbull. Gli artisti degli effetti speciali inserirono minuscoli getti di vapore e fumo per simulare la pioggia acida e l''atmosfera decadente della Los Angeles del 2019.', 'Cinefex Issue No. 9, 1982', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:30.854042+00:00'),
('531fee63-10cb-4f98-b82e-863245c51f30', 146, 'Citazioni & Easter Egg', 'Il nome di Deckard tratto da un romanzo di Philip K. Dick', 'Il cognome del protagonista Rick Deckard non fu inventato dagli sceneggiatori Hampton Fancher e David Peoples, ma fu tratto direttamente da un saggio di saggistica del 1968 scritto da Jesse Bier intitolato ''The Rise and Fall of American Humor'', che Philip K. Dick aveva letto e tenuto come riferimento prima di scrivere il romanzo ''Il cacciatore di androidi''.', 'Archivi ufficiali di Philip K. Dick e note di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:30.854042+00:00'),
('ef8d079f-9ab9-40f1-bb64-da2f6a73a176', 146, 'Curiosità & Retroscena', 'L''ispirazione per il veicolo Spinner', 'Il celebre veicolo volante della polizia di Los Angeles, lo ''Spinner'', fu disegnato dal celebre concept artist Syd Mead. Per conferire alla vettura un aspetto futuristico ma profondamente radicato nel design industriale, Mead unì elementi stilistici derivati dagli elicotteri militari AH-64 Apache con dettagli aerodinamici ispirati alle auto sportive di lusso.', 'Artbook ''Sentinel: The Art of Syd Mead''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:30.854042+00:00'),
('304083dd-5a2d-418e-8e2f-3fd5d7df61b5', 146, 'Curiosità & Retroscena', 'Il cambio radicale del montaggio e il lieto fine imposto', 'A causa dei pessimi risultati dei test screening iniziali, i dirigenti della Tandem Productions imposero a Ridley Scott di aggiungere una voce fuori campo esplicativa e una sequenza finale con un ''lieto fine'' solare, utilizzando immagini di repertorio estratte dal montaggio iniziale del film ''Shining'' di Stanley Kubrick.', 'Note di produzione e interviste ufficiali di Ridley Scott per il Director''s Cut', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:43:30.854042+00:00'),
('9365e596-89c4-4b65-a0fc-218f27195b77', 358, 'Aneddoti dal set', 'Le riprese nei luoghi autentici italiani', 'La troupe girò in numerose località italiane storiche, tra cui Roma (compreso il Caffè Dinelli), Venezia, Napoli, Ischia (che rappresentava la fittizia Mongibello) e Procida, affrontando non poche difficoltà logistiche per bloccare il traffico moderno e ricreare l''atmosfera del 1958.', 'Diario di bordo delle riprese di Anthony Minghella', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:39.042173+00:00'),
('8612c649-fd27-4f7a-b0b3-eb2f65bd59b0', 358, 'Citazioni & Easter Egg', 'Il cameo vocale di Guy Masterson', 'All''interno della pellicola compaiono diversi piccoli camei e collaborazioni con attori teatrali britannici amici del regista, inseriti nei momenti conviviali delle feste a Roma e Sanremo per dare un tono internazionale e autentico agli espatriati.', 'Credit di produzione e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:39.042173+00:00'),
('b7cb4373-4e2f-4946-8c57-02c4e21a894c', 366, 'Casting & Scelte', 'Il provino di Brooke Smith per Catherine Martin', 'Per ottenere il ruolo di Catherine Martin, Brooke Smith dovette aumentare di circa 10 chili e, durante il provino, Jonathan Demme le chiese di recitare la scena della prigionia in un pozzo reale costruito appositamente per testare la sua reazione claustrofobica.', 'Commento audio del regista e del cast nell''edizione Criterion Collection', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 6, '2026-11-03T16:16:21.584532+00:00'),
('b2d1a7f5-920f-43c9-818e-e01a4e4f6d16', 366, 'Segreti di produzione', 'La collaborazione con l''FBI', 'La produzione ricevette una collaborazione senza precedenti dall''FBI, che permise alla troupe di girare all''interno della vera Accademia dell''FBI a Quantico, Virginia, e fornì consulenza tecnica per rendere realistici i protocolli di indagine e l''uso delle armi da fuoco.', 'Documentario ''Inside the Labyrinth: The Making of The Silence of the Lambs''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 7, '2026-11-03T16:16:21.584532+00:00'),
('44d0a04e-5182-469c-adff-531f68d6b8f1', 366, 'Effetti speciali & Trucco', 'La creazione del costume di pelle umana', 'Il costume indossato da Buffalo Bill, composto da pezzi di pelle umana, fu realizzato dal supervisore agli effetti speciali di trucco Carl Fullerton utilizzando lattice, silicone e capelli umani veri, applicati singolarmente per simulare l''effetto di un patchwork macabro.', 'Note di produzione e intervista a Carl Fullerton su Cinefex Magazine', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 8, '2026-11-03T16:16:21.584532+00:00'),
('dde2d020-f860-4648-899b-02cf8cad6642', 366, 'Aneddoti dal set', 'Il silenzio di Anthony Hopkins durante le riprese', 'Per mantenere l''intensità del personaggio, Anthony Hopkins evitava di socializzare con Jodie Foster tra un ciak e l''altro, rimanendo spesso immobile e in silenzio nella sua cella di vetro per incutere un reale senso di disagio alla co-protagonista.', 'Intervista a Jodie Foster per il 25° anniversario del film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 9, '2026-11-03T16:16:21.584532+00:00'),
('b929cda6-32a6-42c4-8f73-74a5cd5789bf', 147, 'Casting & Scelte', 'La scelta della protagonista Linda Kozlowski', 'Prima di assegnare il ruolo della giornalista Sue Charlton a Linda Kozlowski, che all''epoca era un''attrice teatrale quasi sconosciuta a New York, i produttori valutarono diverse attrici di calibro maggiore, ma la chimica immediata con Paul Hogan durante i provini convinse il regista Peter Faiman.', 'Commento audio del regista Peter Faiman nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:35.012324+00:00'),
('81450e22-41a5-4269-ae4c-86b932006c10', 147, 'Aneddoti dal set', 'L''improvvisazione della celebre battuta sul bidet', 'La scena in cui Mick Dundee scambia un bidet per una vasca per lavarsi i piedi o un abbeveratoio nel bagno del lussuoso hotel fu arricchita da battute improvvisate da Paul Hogan, basate sul vero stupore che un abitante dell''outback avrebbe provato di fronte ai moderni sanitari urbani.', 'Making-of ''The Making of Crocodile Dundee'' e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:35.012324+00:00'),
('ec62b198-4987-4930-8b52-7daa3a4da4d3', 147, 'Aneddoti dal set', 'I veri aborigeni locali sul set', 'Per garantire autenticità alle sequenze ambientate nel territorio aborigeno, la produzione coinvolse membri reali della comunità locale e l''attore David Gulpilil, esperto danzatore e figura chiave per il rispetto delle tradizioni indigene durante le riprese nel Kakadu.', 'Note di produzione e documentari sul cinema australiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:35.012324+00:00'),
('04f1dc5d-3c02-48d7-8b1a-d87cd0d0ca4c', 147, 'Curiosità & Retroscena', 'Il montaggio alternato per il mercato statunitense', 'Per la distribuzione negli Stati Uniti curata dalla Paramount, il film fu leggermente rimontato e ridoppiato in alcune parti per rendere lo slang australiano più comprensibile al pubblico americano, sostituendo termini locali troppo oscuri con vocaboli più neutri.', 'Archivio storico della censura cinematografica e note di distribuzione Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:35.012324+00:00'),
('c05838f5-a208-4682-a3bf-5d84375a3786', 150, 'Aneddoti dal set', 'La cicatrice sul mento di Josh Brolin', 'Durante le riprese di una scena d''azione sul set, Josh Brolin ha accidentalmente colpito se stesso con un''arma di scena, procurandosi una piccola ferita al mento. L''attore ha continuato a girare senza fermare la produzione, e il piccolo segno è rimasto visibile in alcune inquadrature del film.', 'Intervista ufficiale dal backstage e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:45.630529+00:00'),
('fd0fa24b-7a03-4996-bbf8-3b8cba92b4d7', 150, 'Segreti di produzione', 'I costumi di Jacqueline West e i tessuti ispirati al Medioevo', 'La costumista nominata all''Oscar Jacqueline West ha tratto ispirazione dai dipinti di Francisco Goya e dai manoscritti medioevali per disegnare i abiti delle diverse fazioni. Per la casata Atreides ha utilizzato tessuti pesanti e colorazioni sobrie che richiamano lo stile militare russo e ottomano.', 'Articolo di approfondimento di Vanity Fair sui costumi di Dune', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:45.630529+00:00'),
('ccac212e-54ac-4e60-87c7-fd690f341e1d', 150, 'Curiosità & Retroscena', 'Il doppiaggio in lingua Fremen registrato ex novo', 'Gli attori che recitavano nella lingua inventata dei Fremen (il Chakobsa) hanno dovuto seguire lezioni intensive con il linguista David J. Peterson. Per garantire la massima naturalezza, gran parte dei dialoghi in lingua nativa è stata registrata nuovamente in sala di doppiaggio con microfoni ravvicinati per enfatizzare il timbro gutturale.', 'Making-of ufficiale ''The Sound of Dune''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:45.630529+00:00'),
('6eb04ccd-381b-4046-a3a8-03e2b91469cd', 359, 'Citazioni & Easter Egg', 'Omaggio a Mario Bava e ai classici Hammer', 'Tim Burton ha apertamente dichiarato di essersi fortemente ispirato ai film horror gotici della Hammer Film Productions e ai capolavori del cinema horror italiano di Mario Bava, in particolare per l''uso espressivo e surreale delle gelatine colorate (rosso e verde acceso) sulla fotografia.', 'Intervista ufficiale di Tim Burton per American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:52:42.709549+00:00'),
('dbb0464d-cf73-4ac1-a52b-bee49a93b0e9', 359, 'Segreti di produzione', 'La neve artificiale sul set inglese', 'Le riprese si sono svolte interamente nel Regno Unito tra i Leavesden Studios e l''Hertfordshire. Poiché la sceneggiatura richiedeva un''atmosfera costantemente gelida e innevata, la troupe ha dovuto fare larghissimo uso di carta di riso triturata e plastica biodegradabile per simulare cumuli di neve persistenti anche durante le giornate più miti.', 'Reportage di produzione e bollettini tecnici dei Leavesden Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:42.709549+00:00'),
('cc918e1b-b7a2-48b7-8aa7-9fe5f4aeee9d', 359, 'Aneddoti dal set', 'I movimenti coreografati di Johnny Depp', 'Per enfatizzare la natura goffa, ipersensibile e intellettuale di Ichabod Crane rispetto ai rudi abitanti del villaggio, Johnny Depp ha studiato una gestualità specifica ispirata alla recitazione di attori del cinema muto come Buster Keaton e Charlie Chaplin, evitando deliberatamente le scene d''azione fisiche tradizionali.', 'Intervista a Johnny Depp nel making-of ufficiale dell''edizione speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:42.709549+00:00'),
('467ff38c-5537-4524-a076-f6f5b3a37d6e', 366, 'Citazioni & Easter Egg', 'Il riferimento al vero serial killer Ed Gein', 'Il personaggio di Buffalo Bill è un amalgama di diversi serial killer reali, ma il dettaglio della pelle cucita è un riferimento diretto a Ed Gein, il cui caso ispirò anche il personaggio di Norman Bates in Psycho di Alfred Hitchcock.', 'Analisi del film di Thomas Harris e biografia criminale di Ed Gein', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 10, '2026-11-03T16:16:21.584532+00:00'),
('b6ed0517-d34a-4410-be55-0af298ff001b', 149, 'Citazioni & Easter Egg', 'Omaggio ai gangster movie classici', 'Il personaggio del ''Capo'' interpretato da Donald Pleasence e i suoi modi da raffinato despota mafioso racchiudono numerosi cliché e sottili citazioni parodistiche dei classici gangster movie hollywoodiani degli anni ''30 e ''40.', 'Analisi critica e retrospettiva cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:42.862061+00:00'),
('df68d343-c92e-45de-85ac-36094e5fce32', 154, 'Segreti di produzione', 'Il quasi-disastro della cancellazione dei dati', 'Nel 1998, durante la produzione, un comando di eliminazione accidentale (''rm * -r'' sulla cartella principale) sui server della Pixar cancellò circa il 90% dei file sorgente del film, azzerando mesi di lavoro. Il disastro fu evitato grazie a Galyn Susman, supervisore tecnico, che aveva una copia di backup a casa perché lavorava da remoto per accudire il figlio neonato.', 'Documentario ufficiale e interviste al team tecnico Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:03.804955+00:00'),
('cfef5767-9f08-46dd-8dc3-49260de6bea6', 154, 'Curiosità & Retroscena', 'La voce originale di Woody rifiutata', 'Prima che Tom Hanks fosse definitivamente ingaggiato per il primo film e confermato per il sequel, il primissimo provino per Woody fu fatto da Paul Reubens (noto come Pee-wee Herman). La sua interpretazione iniziale risultò però troppo stridula e lontana dal tono desiderato dai produttori.', 'Libro ''The Pixar Touch'' di David A. Price', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:03.804955+00:00'),
('f878fd33-af49-4a2b-903e-2dd7c2f1dbad', 154, 'Citazioni & Easter Egg', 'L''omaggio a Star Wars nella scena dell''ascensore', 'Nel duello tra il Buzz Lightyear originale e la sua versione ''cintura di utilità'' nella scatola, la rivelazione in cui Zurg dichiara di essere il padre di Buzz ricalca esattamente la celebre scena di ''Star Wars: Episodio V - L''Impero colpisce ancora''. Subito dopo, i due giocattoli replicano persino la posa di Luke Skywalker e Darth Vader sul condotto di aerazione.', 'Commento audio del regista John Lasseter nel DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:03.804955+00:00'),
('733ffcbc-5fa3-4376-9725-a796e7bc09fa', 154, 'Citazioni & Easter Egg', 'Il cameo della lampada Luxo Jr.', 'Nella sequenza iniziale in cui Buzz combatte nel videogioco spaziale, la telecamera inquadra brevemente una scrivania su cui è appoggiata la celebre lampada da tavolo Luxo Jr., protagonista del primo cortometraggio e storica mascotte del logo animato della Pixar.', 'Analisi visiva e contenuti extra del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:03.804955+00:00'),
('ceec30d8-1c1f-42cd-b352-70265ccd4159', 154, 'Casting & Scelte', 'La sostituzione dell''attore di Slinky Dog', 'Jim Varney, che aveva doppiato l''amato cane a molla Slinky nel primo film, era gravemente malato di cancro durante la lavorazione del sequel e purtroppo morì nel 2000. Per completare le registrazioni, la produzione assunse l''attore Blake Clark, amico intimo di Varney, la cui voce imitava quasi alla perfezione il timbro originale.', 'Note di produzione ufficiali Disney/Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:03.804955+00:00'),
('a9660b85-51a4-4099-b848-0fbba3e79469', 154, 'Citazioni & Easter Egg', 'Il camion della Pizza Planet', 'Il celebre furgone di consegne della Pizza Planet, apparso per la prima volta nel film d''esordio del 1995, fa la sua ricomparsa anche in questo capitolo quando Rex, Slinky, Mr. Potato Head e Hamm attraversano la strada in città per raggiungere il negozio di giocattoli di Al.', 'Guida ufficiale agli Easter Egg Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:03.804955+00:00'),
('6f88466a-b56a-436c-bc17-58d63c9bc097', 154, 'Casting & Scelte', 'La scelta di Joan Cusack per Jessie', 'John Lasseter voleva fortemente l''attrice Joan Cusack per il ruolo della cowgirl Jessie, avendo in mente la sua inconfondibile energia vocale e la capacità di trasmettere un entusiasmo travolgente unito a momenti di grande malinconia, come dimostrato nella sequenza musicale ''When She Loved Me''.', 'Making-of ufficiale ''The Making of Toy Story 2''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:03.804955+00:00'),
('cf20a648-c38c-4888-966d-73606a8e3bcf', 154, 'Citazioni & Easter Egg', 'La parodia di 2001: Odissea nello spazio', 'All''inizio del film, quando Rex gioca al videogioco di Buzz Lightyear affrontando l''Imperatore Zurg, la sequenza in cui il dinosauro si arrabbia e calpesta il controller con la zampa riprende chiaramente le movenze delle scimmie monolitiche del capolavoro di Stanley Kubrick.', 'Riferimenti cinematografici ufficiali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:44:03.804955+00:00'),
('432ca662-f5bb-45d5-bab0-7559cabb7efe', 361, 'Curiosità & Retroscena', 'Il rifiuto del rating G e la classificazione R', 'Tobe Hooper sperava inizialmente di ottenere un visto d''ingresso PG (Parental Guidance) edulcorando la violenza visiva, ma la MPAA assegnò comunque il divieto ai minori di 17 anni non accompagnati (R-rated), spingendo la produzione a puntare decisamente su toni più crudi.', 'Note di produzione e archivi MPAA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:52:51.983757+00:00'),
('ba574ec1-c8e7-4cb0-9c9d-3b9e0519607f', 361, 'Casting & Scelte', 'Il compenso simbolico per il cast', 'Gran parte del giovane cast principale lavorò per percentuali irrisorie sui futuri profitti (mai realmente incassati per via di frodi contabili della distribuzione iniziale) e per paghe giornaliere bassissime, ritrovandosi a dormire nello stesso motel economico o direttamente nella casa usata come set.', 'Interviste retrospettive a Marilyn Burns e Teri McMinn', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:52:51.983757+00:00'),
('22d2cdca-3f24-419c-b584-eaecbe012c21', 361, 'Casting & Scelte', 'L''improvvisazione dell''attore John Dugan', 'John Dugan, che interpretava il Nonno centenario, dovette sottoporsi a sessioni di sei ore di trucco prostetico quotidiano. Per mantenere la concentrazione e l''isolamento sul set, l''attore evitava di parlare con il resto del cast anche al di fuori delle riprese.', 'Making-of ''Flesh Wounds: Seven Stories of the Saw''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:52:51.983757+00:00'),
('4da24176-a3c1-4b15-81dd-a453ec6668d1', 361, 'Segreti di produzione', 'La scelta di girare in 16mm', 'Il film fu girato principalmente in pellicola 16mm a grana grossa per poi essere gonfiato in 35mm per la distribuzione cinematografica. Questa scelta tecnica non fu dettata solo dal budget ridotto, ma conferì all''opera un''estetica sporca, grezza e simile a un cinegiornale o a un documentario snuff.', 'Intervista al direttore della fotografia Daniel Pearl', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:52:51.983757+00:00'),
('0ee99152-0cb8-4dde-a44f-18306d75a03c', 268, 'Casting & Scelte', 'Il provino di Chase Infiniti', 'Chase Infiniti è stata selezionata per il ruolo dopo che Paul Thomas Anderson ha visionato personalmente oltre 200 provini inviati da agenzie indipendenti di Los Angeles, cercando un volto non ancora associato a produzioni mainstream per mantenere il realismo del personaggio.', 'Intervista ufficiale di Paul Thomas Anderson per Variety, 2025', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:31:27.444253+00:00'),
('98d09985-1e68-46af-8016-aa20c35096ca', 268, 'Aneddoti dal set', 'La gestione del traffico a Eureka', 'Durante le riprese in esterni a Eureka, California, la produzione ha dovuto negoziare con le autorità locali per chiudere un intero isolato per tre giorni consecutivi, utilizzando esclusivamente veicoli d''epoca reperiti da collezionisti privati per evitare anacronismi visivi.', 'Note di produzione del Blu-ray ufficiale', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T17:31:27.444253+00:00'),
('d5117000-3b25-4248-9b64-07861cb0a183', 268, 'Segreti di produzione', 'L''uso di lenti anamorfiche Panavision', 'Per ottenere la resa visiva specifica degli anni ''90, il direttore della fotografia ha utilizzato un set di lenti Panavision C-Series modificate, che presentano aberrazioni cromatiche uniche non replicabili con ottiche moderne.', 'Articolo tecnico su American Cinematographer, 2025', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 6, '2026-11-03T17:31:27.444253+00:00'),
('c4b04408-b5fd-45be-b425-360b2774306c', 151, 'Casting & Scelte', 'Il rifiuto iniziale di Florence Pugh', 'Florence Pugh era la prima scelta di Denis Villeneuve per il ruolo della Principessa Irulan, ma l''attrice ha inizialmente dovuto declinare l''offerta a causa di conflitti di programmazione con le riprese di ''Oppenheimer''. Successivamente, grazie a una riorganizzazione dei calendari di produzione, è riuscita a salire a bordo del progetto.', 'Intervista ufficiale a Denis Villeneuve per Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:43:50.538538+00:00'),
('e4f1c174-d8d0-46be-abb5-2c7292bf56ec', 151, 'Aneddoti dal set', 'La spada laser di Paul e il training con Richard Ryan', 'Timothée Chalamet ha dovuto sottoporsi a mesi di addestramento intensivo con il rinomato coordinatore degli stunt Richard Ryan, noto per il suo lavoro in ''Sherlock Holmes'' e ''Star Wars''. L''obiettivo era sviluppare uno stile di combattimento unico per i Fremen, basato su movimenti fluidi ma letali con i coltelli Crysknife.', 'Featurette ''The Stunts of Dune: Part Two'' nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:43:50.538538+00:00'),
('d38701db-a206-4643-be34-03e91fb8f9c6', 151, 'Effetti speciali & Trucco', 'Il trucco speciale delle sopracciglia di Austin Butler', 'Per rendere il personaggio di Feyd-Rautha completamente alieno e privo di peli, l''attore Austin Butler doveva sottoporsi ogni giorno a oltre tre ore di trucco prostetico. Il capo del reparto trucco Donald Mowat ha confermato che non sono state usate tecniche digitali per rimuovere ciglia e sopracciglia, ma un lavoro meticoloso di calchi e coperture in silicone.', 'Dietro le quinte ufficiale di Make-Up Artists and Hair Stylists Guild', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:43:50.538538+00:00'),
('006c100f-1e24-41b7-ba63-83d3f683cef8', 151, 'Segreti di produzione', 'L''ispirazione visiva per il pianeta Giedi Prime', 'Le sequenze ambientate sul pianeta natale degli Harkonnen, Giedi Prime, girate interamente con una speciale cinepresa a infrarossi, traggono ispirazione dalle fotografie scattate nei laboratori scientifici e dai filmati d''archivio di test nucleari degli anni ''50, per evocare un mondo sterile e privo di vita organica.', 'Commento audio del direttore della fotografia Greig Fraser', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:43:50.538538+00:00'),
('6fe5fb4b-d6ac-4890-9464-3682da2e0117', 151, 'Aneddoti dal set', 'La guida al verme delle sabbie e le riprese con i cavi', 'La celebre sequenza in cui Paul Atreides cavalca per la prima volta un verme delle sabbie ha richiesto la costruzione di un enorme rig meccanico lungo oltre trenta metri. Timothée Chalamet ha dovuto recitare legato a imbragature complesse per simulare il movimento sussultorio della creatura, guidato unicamente dalle indicazioni del reparto effetti speciali.', 'Articolo di approfondimento su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:43:50.538538+00:00'),
('1436de2b-4f14-4d2c-9352-3564c158c185', 151, 'Citazioni & Easter Egg', 'Il cameo nascosto di Tim Blake Nelson', 'L''attore Tim Blake Nelson era stato originariamente ingaggiato per interpretare il conte Hasimir Fenring in una serie di scene chiave che approfondivano i intrighi politici della corte imperiale. A causa del montaggio finale e della durata eccessiva del film, la sua sotto-trama è stata tagliata e il suo personaggio è quasi del tutto scomparso dalla versione cinematografica.', 'Intervista a Tim Blake Nelson per The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:43:50.538538+00:00'),
('13485b6a-2c08-45fd-a259-904a9177f93e', 151, 'Segreti di produzione', 'La creazione della lingua Fremen con David J. Peterson', 'Il linguista David J. Peterson, già noto per aver creato il Dothraki per ''Il Trono di Spade'', ha espanso notevolmente il vocabolario della lingua Fremen (Chakobsa) per questo secondo capitolo, creando centinaia di nuovi termini per permettere agli attori di dialogare fluentemente durante le scene senza ricorrere al doppiaggio in post-produzione.', 'Note di produzione ufficiali della Legendary Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:43:50.538538+00:00'),
('8d403c38-9042-4973-8515-38abc08b04a0', 290, 'Casting & Scelte', 'L''adattamento dal saggio ''The Nazi and the Psychiatrist''', 'Il film diretto da James Vanderbilt è basato sul libro d''inchiesta del 2013 ''The Nazi and the Psychiatrist'' scritto da Jack El-Hai, che ha fornito i diari originali e i resoconti clinici inediti di Douglas Kelley.', 'Note di produzione ufficiali e interviste all''autore del saggio Jack El-Hai', TRUE, 'IA (Admin)', 'IA Verificata', 3, 11, '2026-11-02T17:18:33.761048+00:00'),
('c3182613-7cbf-43b0-b0dc-1d4f5399a856', 290, 'Effetti speciali & Trucco', 'La trasformazione fisica e il trucco protesico per Russell Crowe', 'Per impersonare il gerarca Hermann Göring, l''attore Russell Crowe è stato sottoposto a lunghe sedute giornaliere di trucco prostetico per replicare la corporatura appesantita e i tratti somatici caratteristici del famigerato politico nazista negli ultimi mesi della sua vita.', 'Dichiarazioni della produzione e reportage fotografici dal set ungherese', TRUE, 'IA (Admin)', 'IA Verificata', 3, 12, '2026-11-02T17:18:33.761048+00:00'),
('239cb260-6000-4efe-9db3-285589cdea0f', 290, 'Segreti di produzione', 'Il budget e il sostegno finanziario internazionale', 'La produzione indipendente ha beneficiato di importanti sgravi fiscali e fondi di coproduzione erogati dal governo ungherese tramite il National Film Institute of Hungary, permettendo la complessa ricostruzione storica della sala del tribunale e del complesso carcerario.', 'Rivista di settore Variety e report finanziari del cinema ungherese', TRUE, 'IA (Admin)', 'IA Verificata', 4, 13, '2026-11-02T17:18:33.761048+00:00'),
('6e58c1a6-9e9d-438f-a883-05257884180a', 290, 'Curiosità & Retroscena', 'L''accuratezza dei verbali originali del tribunale', 'Gli sceneggiatori e i consulenti storici della produzione hanno attinto direttamente ai documenti originali desecretati conservati negli archivi nazionali americani e britannici, utilizzando i verbali reali delle trascrizioni processuali per i dialoghi in aula.', 'Intervista al regista James Vanderbilt e note di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 3, 14, '2026-11-02T17:18:33.761048+00:00'),
('12de7776-758a-4270-af17-db5497806e57', 290, 'Aneddoti dal set', 'Il lavoro di ricerca psicologica di Rami Malek', 'Per calarsi nei panni dello psichiatra Douglas Kelley, l''attore premio Oscar Rami Malek ha consultato archivi di psicologia militare e lettere personali della famiglia Kelley per comprendere la pressione emotiva subita dal medico durante i colloqui con i criminali di guerra.', 'Intervista promozionale con Rami Malek per Entertainment Weekly', TRUE, 'IA (Admin)', 'IA Verificata', 1, 15, '2026-11-02T17:18:33.761048+00:00'),
('ce5add83-2d1a-441e-842a-2f6bfba59b91', 268, 'Effetti speciali & Trucco', 'Ricostruzione invecchiamento digitale', 'Per le sequenze ambientate sedici anni prima, il team di effetti visivi ha evitato il de-aging digitale totale, preferendo l''uso di protesi in silicone applicate da Kazu Hiro per mantenere la texture naturale della pelle sotto la luce della pellicola 35mm.', 'Making-of ufficiale ''The Craft of Battle''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 7, '2026-11-03T17:31:27.444253+00:00'),
('02cd4697-d837-4b51-a7d4-fefa18a5f257', 268, 'Citazioni & Easter Egg', 'Omaggio alla filmografia di Anderson', 'Il numero di targa dell''auto guidata dal personaggio di Leonardo DiCaprio è ''1970-PTA'', un riferimento diretto all''anno di nascita del regista, inserito come firma discreta nella scenografia.', 'Analisi visiva del film su Sight & Sound', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 8, '2026-11-03T17:31:27.444253+00:00'),
('38d852cb-ff7b-4004-b5ee-ae42820951aa', 155, 'Casting & Scelte', 'La voce originale di Barbie', 'Jodi Benson, celebre per aver doppiato la Sirenetta della Disney, è tornata a prestare la voce a Barbie esattamente come aveva fatto in Toy Story 2, confermando l''iconico legame con il personaggio.', 'Crediti ufficiali del film e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:08.606121+00:00'),
('8a7652df-32f5-4d43-9337-06878857145e', 155, 'Citazioni & Easter Egg', 'Il cameo di Lee Unkrich nel finale', 'Il regista Lee Unkrich ha inserito un piccolo omaggio personale all''interno della stanza di Bonnie, dove compare un disegno che ritrae una scimmia simile a quella vista al Sunnyside, realizzato dai figli del regista.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:08.606121+00:00'),
('86761012-2983-4f93-80cc-178438d54c6a', 155, 'Segreti di produzione', 'La simulazione dei sacchi della spazzatura', 'Per la complessa scena della discarica, gli animatori hanno dovuto studiare e programmare un software specifico per riprodurre fedelmente la consistenza e il fruscio dei sacchi di plastica neri sotto pressione.', 'Documentario ''The Making of Toy Story 3'' contenuto nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:08.606121+00:00'),
('db0b6189-3662-4805-b07c-56f501c1503c', 155, 'Citazioni & Easter Egg', 'Il codice segreto A113', 'Come da tradizione Pixar, il celebre codice A113 (riferimento all''aula del California Institute of Arts frequentata da molti animatori) compare sulla targa dell''auto guidata da <i>Mom</i> (la madre di Andy).', 'Analisi visiva ufficiale e IMDb Goofs/Easter Eggs', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:08.606121+00:00'),
('0a6cf7f4-4ecc-49f4-af23-262d409cbd00', 155, 'Curiosità & Retroscena', 'La consulenza di Hayao Miyazaki', 'Durante le prime fasi di sviluppo, John Lasseter ha chiesto consiglio al leggendario regista dello Studio Ghibli Hayao Miyazaki su come gestire il personaggio di Totoro, che appare nel film sotto forma di peluche giocattolo.', 'Intervista a John Lasseter pubblicata su Entertainment Weekly nel 2010', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:08.606121+00:00'),
('7b12c44f-a6ca-4295-9a4f-149a7e4a1764', 164, 'Casting & Scelte', 'Il provino di Heath Ledger per Gabriel Martin', 'Heath Ledger ottenne la parte del figlio maggiore Gabriel Martin dopo aver impressionato il regista Roland Emmerich e il produttore Dean Devlin con la sua intensità fisica e la sua abilità nell''equitazione durante le audizioni a Los Angeles. L''attore australiano rifiutò l''uso di controfigure per la maggior parte delle scene a cavallo.', 'Commento audio del DVD e note di produzione della Columbia Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:41.835341+00:00'),
('0427e79e-c8a0-4e7f-9964-d560d2ef535a', 164, 'Aneddoti dal set', 'Le ferite sul set di Mel Gibson', 'Durante le riprese delle sequenze di battaglia in Carolina del Sud, Mel Gibson si ferì accidentalmente a una mano a causa di un malfunzionamento minore di una carica esplosiva di polvere da sparo impiegata per simulare l''impatto dei proiettili. L''attore ricevette cure mediche sul posto e tornò a girare nello stesso giorno senza rallentare la tabella di marcia della troupe.', 'Reportage dal set della rivista American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:41.835341+00:00'),
('e47f7c2e-571e-438a-b4c2-54853d33325d', 164, 'Segreti di produzione', 'La ricostruzione della piantagione di Benjamin Martin', 'La maestosa casa colonica e la piantagione di Benjamin Martin furono interamente costruite da zero in un''area rurale vicino a Charleston, in Carolina del Sud, utilizzando legname d''epoca e tecniche di costruzione del XVIII secolo per garantire l''autenticità visiva richiesta dal direttore della fotografia Caleb Deschanel.', 'Special ''The Making of The Patriot'' presente nell''edizione speciale Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:41.835341+00:00'),
('6c13e045-0442-48ff-bb37-5781c12f4ddb', 164, 'Segreti di produzione', 'L''uso massiccio di comparse locali e veterani', 'Per le sequenze delle battaglie campali, la produzione ha impiegato oltre 500 comparse locali in Carolina del Sud, tra cui molti membri di associazioni di rievocazione storica americana, i quali hanno fornito preziosi consigli su come i soldati dell''epoca manovrassero le pesanti baionette e i fucili a pietra focaia.', 'Production Notes ufficiali della Columbia Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:41.835341+00:00'),
('30e2eaf0-9b9d-4d57-aa6f-7901d3afefbf', 164, 'Curiosità & Retroscena', 'La collaborazione con Roland Emmerich e la svolta drammatica', 'Sebbene Roland Emmerich fosse celebre per blockbuster catastrofici ad alto tasso di CGI come ''Independence Day'', accettò di dirigere ''The Patriot'' per cimentarsi con un dramma storico in costume, imponendo tuttavia una forte enfasi visiva e dinamica sulle sequenze d''azione per mantenere il ritmo tipico del cinema commerciale.', 'Intervista a Roland Emmerich per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:41.835341+00:00'),
('d7225940-625c-413e-93f3-b690e0ab95c1', 164, 'Effetti speciali & Trucco', 'Il trucco delle ferite e degli effetti di sangue', 'Il reparto trucco guidato da Rick Baker ha dovuto gestire migliaia di applicazioni di protesi in lattice e sangue fucsia-scuro specifico per la pellicola cinematografica, studiato appositamente per apparire come vero sangue coagulato sotto la luce naturale del sole della Carolina del Sud.', 'Documentario sugli effetti speciali nel backstage del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:41.835341+00:00'),
('d4ce7b1a-ab3c-4886-89b7-1a41305c0bc6', 174, 'Segreti di produzione', 'La consulenza storica e antropologica', 'Per garantire il massimo rigore nella rappresentazione dei rituali tribali e della vita nell''VIII secolo a.C., la produzione si è avvalsa della supervisione di storici e archeologi specializzati nelle origini di Roma.', 'Note di produzione ufficiali Groenlandia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:05.349149+00:00'),
('86f517a7-2ab5-445b-8385-ffc36941303e', 174, 'Casting & Scelte', 'La scelta dei volti non convenzionali', 'Il regista Matteo Rovere ha cercato attori con tratti somatici arcaici e poco patinati, evitando deliberatamente volti troppo moderni o noti al grande pubblico per mantenere intatta la credibilità storica dei personaggi.', 'Intervista al regista Matteo Rovere per Ciak', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:05.349149+00:00'),
('2c8b8c32-2642-4770-8699-7b1417924b35', 174, 'Segreti di produzione', 'Il lavoro sulle sonorità della natura', 'Il sound design del film ha evitato l''uso di sintetizzatori digitali, privilegiando strumenti acustici primitivi, percussioni in legno e cuoio, e registrazioni ambientali reali per ricreare il paesaggio sonoro dell''epoca.', 'Special sul sound design del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:05.349149+00:00'),
('c114e563-f9a0-4ddf-9ec6-bbf964732e32', 174, 'Aneddoti dal set', 'La gestione delle comparse nei combattimenti', 'Le comparse impiegate nelle scene di battaglia tra le tribù sono state sottoposte a un addestramento militare antico durato settimane sotto la guida di stuntmen professionisti, imparando a muoversi come un unico corpo coeso.', 'Making-of ufficiale ''Il primo re''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:05.349149+00:00'),
('f977fac3-8573-4c47-9e71-36d56c175f5b', 156, 'Casting & Scelte', 'La riscrittura totale dopo l''addio di Rashida Jones e Will McCormack', 'Nel 2017 le sceneggiatrici originali Rashida Jones e Will McCormack abbandonarono il progetto citando differenze creative e questioni culturali, costringendo la Pixar a una profonda revisione della trama romantica tra Woody e Bo Peep.', 'Comunicato ufficiale e report di Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:11.947812+00:00'),
('7c8d4129-f18b-4011-b693-57f72ae3fcaa', 156, 'Casting & Scelte', 'Il debutto alla regia cinematografica di Josh Cooley', 'Toy Story 4 segna il debutto alla regia per un lungometraggio di Josh Cooley, che in precedenza aveva lavorato come artista di storyboard e co-sceneggiatore di Inside Out, diventando il primo regista non di nome John Lasseter a dirigere un capitolo del franchise.', 'Note di produzione ufficiali Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:11.947812+00:00'),
('82381140-a35a-4396-a9fd-993de5d19664', 156, 'Segreti di produzione', 'La sfida tecnica dei riflessi nell''antiquariato', 'Per la sequenza del negozio di antiquariato, i reparti di illuminazione e rendering della Pixar hanno dovuto sviluppare un nuovo sistema di gestione della luce per calcolare accuratamente i riflessi speculari su oltre 10.000 oggetti diversi presenti contemporaneamente sullo schermo.', 'Documentario ''Making of Toy Story 4'' su Disney+', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:11.947812+00:00'),
('9c04b99b-02d8-4bf8-b7d5-f3773fa7ca82', 156, 'Citazioni & Easter Egg', 'Il cameo della tazza di Luxo Jr.', 'All''interno del negozio di antiquariato è possibile intravedere brevemente la classica tazza con il logo di Luxo Jr. e della Pixar, un omaggio tradizionale inserito dagli animatori in ogni singolo film dello studio.', 'Analisi ufficiale degli Easter Egg Pixar', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:11.947812+00:00'),
('b5aeb4a4-bbe8-4d4b-bc1c-9098d4bfebac', 166, 'Casting & Scelte', 'Il provino di Matthew McConaughey per un altro ruolo', 'Inizialmente Matthew McConaughey si presentò ai provini per interpretare l''avvocato dell''accusa Rufus Buckley (ruolo poi andato a Kevin Spacey). Fu solo dopo aver letto il copione che convinse il regista Joel Schumacher a fargli fare un provino per la parte del protagonista Jake Brigance.', 'Intervista retrospettiva a Matthew McConaughey e note di produzione Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:45.944394+00:00'),
('5e5ad333-d5f0-4fe2-8f56-fe4bfe4caf99', 166, 'Casting & Scelte', 'La scelta iniziale per il giudice O''鲈', 'Prima che il ruolo del giudice Omar Noose fosse assegnato a Charles S. Dutton, la produzione aveva valutato diversi caratteristi veterani di Hollywood, tra cui Gene Hackman, per dare maggiore autorevolezza e rigidità alla figura che presiede il tribunale.', 'Archivio di pre-produzione e casting notes della Warner Bros. (1995)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:45.944394+00:00'),
('0c5cd488-5d25-4438-bdec-e0164a2cd3c6', 166, 'Aneddoti dal set', 'Il vero avvocato di John Grisham sul set', 'Per assicurarsi che il gergo legale e le procedure processuali del Mississippi fossero rappresentati con assoluta precisione, l''autore del romanzo originale John Grisham visitò regolarmente il set di Canton, offrendo consulenza diretta al cast e alla troupe.', 'Making-of ufficiale incluso nell''edizione Home Video speciale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:45.944394+00:00'),
('4982be39-3b63-4f6d-a92a-a09f8dc39918', 166, 'Aneddoti dal set', 'Il caldo soffocante durante le riprese in tribunale', 'Le scene ambientate nell''aula del tribunale furono girate durante un''estate particolarmente torrida nel Mississippi; l''edificio storico non disponeva di un impianto di aria condizionata adeguato, costringendo la troupe a usare ventilatori silenziosi nascosti e quintali di trucco per tamponare il sudore degli attori.', 'Commento audio del regista Joel Schumacher nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:45.944394+00:00'),
('d70ba7a7-ae4b-4df8-be8d-9477bc3b70ce', 166, 'Curiosità & Retroscena', 'Le tensioni sul set tra Joel Schumacher e la produzione', 'Joel Schumacher dovette lottare duramente con i produttori per mantenere la durata e la crudezza di alcune sequenze chiave, inclusi i dialoghi espliciti sul movente razziale, poiché lo studio temeva un divieto ai minori troppo restrittivo al botteghino.', 'Articolo di retroscena cinematografico su Entertainment Weekly (1996)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:45.944394+00:00'),
('5bcbac3b-5142-40c2-a73b-9fd7419f8571', 166, 'Casting & Scelte', 'La preparazione di Samuel L. Jackson', 'Per entrare nei panni di Carl Lee Hailey, un padre distrutto dal dolore e dalla sete di giustizia sommaria, Samuel L. Jackson studiò approfonditamente i processi storici reali legati ai crimini d''odio nel Sud degli Stati Uniti durante gli anni Sessanta.', 'Intervista promozionale a Samuel L. Jackson per la première di Los Angeles', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:45.944394+00:00'),
('cb835ff6-506e-498f-b933-76b405de55a4', 176, 'Segreti di produzione', 'Il cappotto originale di Al Capone', 'Per aumentare il realismo storico, Robert De Niro indossò durante le riprese un autentico cappotto di cashmere che era appartenuto al vero Al Capone, fornito dalla sartia della famiglia.', 'Commento audio del regista Brian De Palma e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:10.145088+00:00'),
('794005e8-4439-460c-a3d2-1638f0c2209d', 176, 'Casting & Scelte', 'Bob Hoskins come prima scelta per Al Capone', 'Prima che Robert De Palma ingaggiasse Robert De Niro, il ruolo di Al Capone fu offerto a Bob Hoskins. Quando De Niro accettò, la produzione pagò a Hoskins una penale di 200.000 dollari per il disturbo.', 'Intervista retrospettiva a Bob Hoskins e biografie ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:10.145088+00:00'),
('f9dcce01-da0e-4fef-9577-d36cf9250e13', 176, 'Aneddoti dal set', 'L''improvvisazione del discorso alla mazza da baseball', 'La celebre sequenza in cui Al Capone tiene un discorso a tavola prima di colpire a morte un socio con una mazza da baseball fu in gran parte improvvisata da Robert De Niro, cogliendo di sorpresa gli attori presenti sulla scena.', 'Making-of ufficiale ''The Men Who Made the Movie'' e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:10.145088+00:00'),
('16806235-239f-4f92-b509-b112699c840d', 176, 'Casting & Scelte', 'Il rifiuto di Mickey Rourke e Harrison Ford', 'Prima di affidare la parte di Eliot Ness a Kevin Costner, la produzione prese in seria considerazione Mickey Rourke, Harrison Ford e Don Johnson, ma tutti rifiutarono l''offerta per altri impegni cinematografici.', 'Archivi di casting di Hollywood e biografia di Brian De Palma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:10.145088+00:00'),
('8606a5c1-0fe9-482b-a915-95424cca5ccb', 176, 'Curiosità & Retroscena', 'Il premio Oscar a Sean Connery', 'Grazie alla sua interpretazione del veterano poliziotto Jim Malone, Sean Connery vinse l''unico Premio Oscar della sua carriera come miglior attore non protagonista nel 1988.', 'Database ufficiale Academy Awards (Premi Oscar)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:10.145088+00:00'),
('217549c1-f2fc-4ffd-9920-1856556fed47', 176, 'Citazioni & Easter Egg', 'La carrozzina sulla scalinata come omaggio alla Corazzata Potëmkin', 'La celebre sparatoria alla stazione ferroviaria di Chicago, con la carrozzina che precipita lungo la scalinata, è un esplicito omaggio e citazione visiva della famosa sequenza della scalinata di Odessa nel capolavoro muto di Sergej Ejzenštejn.', 'Analisi critiche ufficiali e note di regia di Brian De Palma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:10.145088+00:00'),
('cf0feb1c-4ef9-4445-8a03-110c6398fc71', 176, 'Aneddoti dal set', 'Il giubbotto antiproiettile improvvisato di Kevin Costner', 'Durante le riprese delle scene d''azione, Kevin Costner indossava un rudimentale giubbotto antiproiettile nascosto sotto l''abito d''epoca, poiché l''attore insistette per girare molte delle sue acrobazie in prima persona.', 'Interviste sul set e documentario d''archivio della Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:10.145088+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('9d626591-d3dd-40d8-bba3-6b9bc0370d2a', 158, 'Casting & Scelte', 'Il provino iniziale di Cillian Murphy per Bruce Wayne', 'Prima di essere scelto come il villain Jonathan Crane / Spaventapasseri, Cillian Murphy sostenne un provino per la parte di Bruce Wayne/Batman. Sebbene i realizzatori sapessero che non aveva la stazza fisica adatta per il Cavaliere Oscuro, Christopher Nolan volle comunque farlo audizionare per vederlo in azione e convincere lo studio del suo talento magnetico.', 'Commento audio del regista e documentario ''Genesis of the Bat'' nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:17.022771+00:00'),
('aaa18b3b-9f60-4a9f-9e88-5b2bff7a62e3', 158, 'Aneddoti dal set', 'L''infortunio di Christian Bale con la Batmobile', 'Durante le riprese notturne a Chicago, un conducente locale ubriaco finì per schiantarsi contro il modello in scala reale del Tumbler (la Batmobile). L''impatto distrusse parte della carrozzeria del veicolo corazzato, costringendo la troupe a sospendere temporaneamente le riprese per riparare il mezzo da milioni di dollari.', 'Intervista ufficiale a Christian Bale per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:17.022771+00:00'),
('c17385c7-fec1-42c9-9ec9-aa5dba101b55', 158, 'Segreti di produzione', 'Il divieto di usare la CGI per i pipistrelli', 'Nello sforzo di mantenere il film il più radicato possibile nel realismo, Christopher Nolan e il supervisore agli effetti speciali Nick Davis rifiutarono di creare i pipistrelli della caverna interamente in computer grafica. Vennero utilizzate riprese reali di pipistrelli combinate con modelli meccanici e marionette manovrate dal vivo sul set.', 'Note di produzione ufficiali della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:17.022771+00:00'),
('6e5d1dc4-eb30-484f-af09-7987f0388442', 158, 'Casting & Scelte', 'La scelta di Katie Holmes e l''influenza di Memento', 'Per il ruolo di Rachel Dawes, la produzione prese in considerazione diverse attrici di primo piano, tra cui Claire Danes, Reese Witherspoon, Sarah Michelle Gellar e Rachel McAdams. La scelta ricadde infine su Katie Holmes dopo che Christopher Nolan rimase colpito dalla sua interpretazione nel film ''Schegge di aprile'' (2003).', 'Archivi di casting della Warner Bros. e interviste al casting director John Papsidera', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:17.022771+00:00'),
('89836047-a20b-48b0-9b48-0ed0be57c378', 158, 'Casting & Scelte', 'Il cameo vocale di Andrew Howard nel prologo', 'L''attore gallese Andrew Howard, noto per i suoi ruoli da duro, interpreta il prigioniero che litiga con Bruce Wayne nella prigione in Bhutan all''inizio del film. La sua intensa sequenza iniziale fu girata in condizioni climatiche particolarmente rigide in Islanda.', 'Credits ufficiali del film e bollettini di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:17.022771+00:00'),
('5f37c695-0f7f-456b-80cc-4c9608827e0e', 158, 'Effetti speciali & Trucco', 'I modellini in scala per il Tempio di Ra''s al Ghul', 'Invece di costruire l''intero monastero himalayano a grandezza naturale o di affidarsi totalmente alla grafica digitale, lo scenografo Nathan Crowley fece realizzare enormi e dettagliati modellini in scala dell''edificio. Questi furono combinati con riprese dal vivo girate sui ghiacciai islandesi.', 'Libro ''The Art and Making of Batman Begins'' di Jody Duncan', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:17.022771+00:00'),
('a25f2425-56da-4fb8-84c5-e363498f1e6d', 158, 'Citazioni & Easter Egg', 'Il riferimento nascosto a Thomas Wayne e Joe Chill', 'Il giudice che presiede l''udienza per la scarcerazione anticipata di Joe Chill (l''assassino dei genitori di Bruce Wayne) si chiama Falsworth, un chiaro omaggio a Lord Falsworth, storico alleato dei fumetti DC/Marvel e personaggio della Golden Age dei fumetti creato da Bill Finger.', 'Analisi di continuity e Easter Egg della sceneggiatura di David S. Goyer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:17.022771+00:00'),
('41afb60d-98ac-4ad4-8931-2068c0e12bb8', 184, 'Citazioni & Easter Egg', 'Il cameo dei registi Peter Jackson e boyd', 'Peter Jackson fa un rapido cameo non accreditato nelle vesti di uno dei cittadini di Pontelagolungo in fuga dall''attacco di Smaug, riprendendo la tradizione dei suoi brevi camei in stile Alfred Hitchcock presenti in tutta la saga. Anche il co-sceneggiatore Philippa Boyens e il produttore Fran Walsh appaiono brevemente come profughi nella stessa sequenza.', 'The Hobbit: The Battle of the Five Armies - Extended Edition Appendices', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:38.556572+00:00'),
('bfb1b28b-134a-4e94-80d8-4c89adfeab6b', 184, 'Aneddoti dal set', 'L''addio di Sir Ian McKellen al green screen', 'Sir Ian McKellen ha manifestato più volte in pubblico la propria frustrazione durante le riprese a causa dell''uso massiccio di palcoscenici completamente verdi e set digitali, arrivando a piangere di frustrazione nel dover recitare da solo davanti a marcatori di posizione anziché con altri attori reali.', 'Intervista rilasciata da Ian McKellen al programma televisivo The Graham Norton Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:38.556572+00:00'),
('592f6e81-3972-4825-9273-d90c4bc29a1f', 184, 'Citazioni & Easter Egg', 'Il cameo dei figli di Peter Jackson', 'I tre figli di Peter Jackson – Katie, Billy e Ted – compiono tutti brevi apparizioni all''interno della trilogia; in questo capitolo finale compaiono rispettivamente come una ragazza di Pontelagolungo, un giovane abitante e un soldato di Dale pronto alla difesa.', 'Crediti del film e documentari del backstage ''New Zealand: Home of Middle-earth''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:38.556572+00:00'),
('7fbe3afd-0c95-4070-9f5b-b6ed9c5f759f', 184, 'Effetti speciali & Trucco', 'La progettazione digitale dell''esercito dei Goblin', 'La Weta Digital ha impiegato algoritmi avanzati del software Massive per gestire le complesse coreografie di massa durante la battaglia finale, permettendo a migliaia di orchi, elfi e nani digitali di combattere con intelligenza artificiale autonoma anziché attraverso animazioni predefinite.', 'Weta Digital Production Notes e Cinefex Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:38.556572+00:00'),
('7d1adadf-7c04-4b1a-bca8-ce6c6c75a723', 184, 'Curiosità & Retroscena', 'Il tributo musicale ai film di Ralph Bakshi', 'Howard Shore ha inserito alcuni sottili richiami melodici alla storica colonna sonora composta da Leonard Rosenman per il film d''animazione ''Il Signore degli Anelli'' del 1978 diretto da Ralph Bakshi, come omaggio ai pionieri dell''adattamento tolkeniano sul grande schermo.', 'Note di copertina dell''album della colonna sonora ufficiale e interviste a Howard Shore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:38.556572+00:00'),
('e51b3a0c-9095-4c68-ac2e-046a4287a88f', 262, 'Casting & Scelte', 'Ryan Gosling e il coinvolgimento precoce', 'Ryan Gosling non è solo il protagonista nei panni di Ryland Grace, ma ha anche svolto un ruolo chiave come produttore del film attraverso la sua casa di produzione General Admission, legandosi al progetto già nel marzo 2020, ancor prima che il romanzo di Andy Weir fosse pubblicato.', 'Annunci ufficiali di produzione e interviste ad Andy Weir su Deadline', TRUE, 'IA (Admin)', 'IA Verificata', 5, 1, '2026-11-02T17:18:47.147662+00:00'),
('79d70cd9-23d1-4a74-aaf7-3954fdde1c40', 262, 'Curiosità & Retroscena', 'Adattamento cinematografico preventivo', 'I diritti cinematografici del romanzo di Andy Weir ''Project Hail Mary'' sono stati acquistati dalla Metro-Goldwyn-Mayer (MGM) per ben 3 milioni di dollari nel 2020, quando il libro era ancora un semplice manoscritto non ancora dato alle stampe.', 'Report di Deadline e registri di acquisizione diritti della MGM', TRUE, 'IA (Admin)', 'IA Verificata', 2, 2, '2026-11-02T17:18:47.147662+00:00'),
('413da5cc-5b6e-4ac8-82b1-320bec854e2e', 262, 'Segreti di produzione', 'La scelta della regia dei registi di Spider-Verse', 'La regia del film è stata affidata al duo Phil Lord e Christopher Miller, celebri per il loro stile visivo innovativo in ''Spider-Man: Un nuovo universo'' e ''The LEGO Movie'', scelti per gestire la complessa commistione di rigore scientifico e toni umoristici tipica della scrittura di Andy Weir.', 'Comunicato stampa ufficiale MGM e note di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 4, 3, '2026-11-02T17:18:47.147662+00:00'),
('92da0e11-8052-4b2c-abbd-4580cc1365f2', 262, 'Casting & Scelte', 'L''ingresso nel cast di Sandra Hüller', 'L''attrice tedesca Sandra Hüller, reduce dal successo internazionale e dalla candidatura all''Oscar per ''Anatomia di una caduta'' e ''La zona d''interesse'', è stata ingaggiata per un ruolo di primo piano all''interno del cast principale al fianco di Ryan Gosling.', 'The Hollywood Reporter, annunci di casting ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 3, 4, '2026-11-02T17:18:47.147662+00:00'),
('3d194110-a697-470a-aa4a-30045c0d8df2', 262, 'Curiosità & Retroscena', 'La continuità con The Martian', 'Come già avvenuto per l''adattamento cinematografico di ''The Martian'' (Sopravvissuto) diretto da Ridley Scott, anche ''Project Hail Mary'' mantiene la caratteristica firma di Andy Weir basata su rigorose basi scientifiche, problem-solving ingegneristico e un protagonista ironico e isolato nello spazio profondo.', 'Recensioni letterarie e analisi di pre-produzione', TRUE, 'IA (Admin)', 'IA Verificata', 4, 5, '2026-11-02T17:18:47.147662+00:00'),
('f0e2fc76-147e-48d2-8fa6-7879b2556903', 262, 'Casting & Scelte', 'Completamento del cast di supporto', 'Il cast di supporto vede la partecipazione di attori affermati come Ken Leung (noto per ''Lost'' e ''Star Wars: Il risveglio della Forza''), Milana Vayntrub, Lionel Boyce e Priya Kansara, selezionati per interpretare i vari ruoli chiave della missione scientifica internazionale.', 'Database di produzione IMDbPro e comunicati stampa ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 5, 6, '2026-11-02T17:18:47.147662+00:00'),
('5c6f7b36-70a7-490b-a1d4-54c08e9fb755', 262, 'Segreti di produzione', 'Sceneggiatura affidata a Drew Goddard', 'La sceneggiatura del film è stata scritta da Drew Goddard, già candidato all''Oscar proprio per l''adattamento di ''The Martian'' di Andy Weir, garantendo così una continuità stilistica e narrativa nell''adattare i complessi romanzi scientifici dell''autore per il grande schermo.', 'Crediti ufficiali della produzione e note della Writers Guild of America', TRUE, 'IA (Admin)', 'IA Verificata', 4, 7, '2026-11-02T17:18:47.147662+00:00'),
('df8d1e5c-5c99-4c03-b78c-a71d7f32c777', 368, 'Casting & Scelte', 'Il casting di Elle Fanning come protagonista', 'Elle Fanning è stata scelta per interpretare il ruolo principale di Thia in Predator: Badlands, segnando la sua prima collaborazione con il franchise sci-fi diretto da Dan Trachtenberg.', 'Annunci di casting ufficiali della produzione e interviste a Dan Trachtenberg', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:36:52.395544+00:00'),
('4ed0d76e-58ab-4a35-9c0f-be504ebe3ca1', 368, 'Curiosità & Retroscena', 'La continuità nel franchise dopo Preiz', 'Il film rappresenta il ritorno alla regia di Dan Trachtenberg nell''universo di Predator dopo il grande successo acclamato dalla critica di Preiz (2022), puntando a espandere la mitologia della saga in direzioni inedite e temporali differenti.', 'Note di produzione ufficiali 20th Century Studios', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:36:52.395544+00:00'),
('4343b7ee-64e0-43e5-95a9-61581c98a92d', 368, 'Segreti di produzione', 'Un''ambientazione futuristica su un pianeta remoto', 'A differenza dei capitoli precedenti ambientati storicamente sulla Terra o nei giorni nostri, la trama di Predator: Badlands sposta ufficialmente l''azione in un contesto futuristico su un pianeta alieno mai visto prima.', 'Sinossi ufficiale e comunicati stampa della produzione', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:36:52.395544+00:00'),
('ecc5f270-e47b-468a-ac04-30cb52611720', 368, 'Casting & Scelte', 'Il coinvolgimento di Dimitrius Schuster-Koloamatangi', 'L''attore Dimitrius Schuster-Koloamatangi è stato inserito nel cast principale del film, affiancando Elle Fanning in questo progetto fantascientifico ad alto budget.', 'Database ufficiale dei crediti e casting di produzione', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:36:52.395544+00:00'),
('8e46cc1e-329b-49db-8ad1-ae5c21b1e0c7', 159, 'Segreti di produzione', 'L''esplosione reale dell''ospedale', 'La spettacolare sequenza in cui il Joker fa esplodere l''ospedale di Gotham non è stata realizzata in CGI, ma demolendo realmente l''ex Brach''s Candy Factory a Chicago. Christopher Nolan ottenne il permesso di abbattere l''edificio tramite una singola e complessa detonazione controllata.', 'Documentario dietro le quinte ''Gotham Uncovered'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:22.378796+00:00'),
('14db3a97-8340-4a83-9097-481ee5896725', 264, 'Casting & Scelte', 'Ingaggio di Emily Blunt come protagonista', 'Emily Blunt è stata la prima scelta di Steven Spielberg per guidare il cast principale di Disclosure Day, consolidando una collaborazione fortemente desiderata dal regista dopo i contatti avuti per altri progetti negli anni precedenti.', 'Comunicati stampa di produzione Amblin Entertainment', TRUE, 'IA (Admin)', 'IA Verificata', 5, 1, '2026-11-02T17:19:02.173727+00:00'),
('d90d0b7c-c1ba-4087-a6a0-7f2c078cfc4d', 264, 'Casting & Scelte', 'La scelta di Josh O''Connor al fianco della Blunt', 'Josh O''Connor è stato selezionato per affiancare Emily Blunt in un ruolo chiave incentrato sul tema del contatto, grazie al plauso internazionale ricevuto per le sue interpretazioni drammatiche in produzioni cinematografiche e televisive.', 'Report di casting ufficiali Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 2, 2, '2026-11-02T17:19:02.173727+00:00'),
('c1a98ba8-1d1b-409f-87e8-881578092b44', 264, 'Casting & Scelte', 'Il coinvolgimento di Colin Firth nel cast corale', 'Il Premio Oscar Colin Firth è entrato a far parte del cast principale del film, interpretando una figura istituzionale di rilievo all''interno della complessa struttura narrativa incentrata sulla rivelazione.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Admin)', 'IA Verificata', 3, 3, '2026-11-02T17:19:02.173727+00:00'),
('16e4a7e6-df00-43b8-8a5a-980486e1f8fb', 264, 'Curiosità & Retroscena', 'Il ritorno di Steven Spielberg al genere fantascientifico', 'Con Disclosure Day, Steven Spielberg è tornato a dirigere un lungometraggio interamente incentrato sul tema del contatto alieno e della rivelazione globale, un territorio narrativo che non affrontava in veste di regista principale dai tempi di La guerra dei mondi (2005) e Incontri ravvicinati del terzo tipo (1977).', 'Dichiarazioni ufficiali del regista per la stampa specializzata', TRUE, 'IA (Admin)', 'IA Verificata', 5, 4, '2026-11-02T17:19:02.173727+00:00'),
('00db3da7-46e9-4605-a185-f8017fb3f5e7', 264, 'Segreti di produzione', 'La sceneggiatura originale basata su un soggetto di Spielberg', 'Il progetto è basato su un soggetto originale ideato dallo stesso Steven Spielberg, con la sceneggiatura affidata a David Koepp, storico collaboratore del regista con cui aveva già lavorato a Jurassic Park, La guerra dei mondi e Indiana Jones e il regno del teschio di cristallo.', 'Archivio WGA e note di pre-produzione', TRUE, 'IA (Admin)', 'IA Verificata', 4, 5, '2026-11-02T17:19:02.173727+00:00'),
('588b1116-ff93-4dbd-9da9-f15cc4d88dbf', 264, 'Segreti di produzione', 'Accordo di distribuzione globale con Universal Pictures', 'Il film è stato sviluppato e prodotto attraverso la Amblin Entertainment di Spielberg in partnership strategica con Universal Pictures, confermando il sodalizio storico che lega il regista allo Studio di Hollywood.', 'Deadline Hollywood - Announcement di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 2, 6, '2026-11-02T17:19:02.173727+00:00'),
('a5c7dcd1-00a7-412a-bb4a-c6418ae6d68a', 264, 'Curiosità & Retroscena', 'Un cast corale di alto profilo internazionale', 'Il film vanta un ensemble di prim''ordine che comprende, oltre ai protagonisti, attori del calibro di Eve Hewson, Colman Domingo, Wyatt Russell e Henry Lloyd-Hughes, scelti per dare spessore ai diversi punti di vista di fronte all''evento straordinario.', 'Variety Casting Report', TRUE, 'IA (Admin)', 'IA Verificata', 5, 7, '2026-11-02T17:19:02.173727+00:00'),
('90c08e74-29df-44da-9544-64ed72067c5f', 264, 'Segreti di produzione', 'La gestione del massimo riserbo sulla trama', 'Come da consuetudine per le produzioni di Steven Spielberg, la fase di lavorazione si è svolta sotto strettissima sorveglianza e con rigidi accordi di riservatezza (NDA) imposti a cast e troupe per preservare il fattore sorpresa legato alla sinossi.', 'Report di set e testimonianze della troupe', TRUE, 'IA (Admin)', 'IA Verificata', 2, 8, '2026-11-02T17:19:02.173727+00:00'),
('2143dc17-f61e-4791-8e62-1c64aae6058c', 369, 'Curiosità & Retroscena', 'Adattamento di un drammatico documentario reale', 'Il film è la trasposizione drammatica dell''omonimo documentario del 2019 diretto dagli stessi registi Alex Parkinson e Richard da Costa, che raccontava il tragico incidente subito dal sommozzatore Chris Lemons nel 2012 nel Mare del Nord.', 'Note di produzione ufficiali e pressbook del film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:42:56.149599+00:00'),
('00bfa038-c35b-4829-ad9a-49545045b3f5', 369, 'Casting & Scelte', 'Il coinvolgimento di Simu Liu e Woody Harrelson', 'Simu Liu e Woody Harrelson sono stati ingaggiati per i ruoli principali rispettivamente nei panni di un sommozzatore e del veterano a bordo della nave di supporto, portando un forte profilo internazionale alla produzione drammatica.', 'Annunci di casting ufficiali di Deadline e Hollywood Reporter', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:42:56.149599+00:00'),
('d51ee3dd-8a60-43a6-982e-73f673f7ff08', 369, 'Segreti di produzione', 'Le riprese in ambienti subacquei complessi', 'Per ricreare la drammaticità e la claustrofobia dell''incidente a 100 metri di profondità, la produzione ha combinato set in studio con grandi vasche d''acqua e sequenze girate in condizioni marine reali per massimizzare il realismo tecnico.', 'Intervista al regista Alex Parkinson e resoconti della troupe', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:42:56.149599+00:00'),
('634f27b5-819d-4718-9ebd-34ba468f0e06', 369, 'Aneddoti dal set', 'La consulenza dei veri sommozzatori professionisti', 'Gli attori principali e la troupe tecnica hanno lavorato a stretto contatto con sommozzatori commerciali esperti e con i veri protagonisti della vicenda reale per apprendere i protocolli di sicurezza e l''uso corretto delle attrezzature pesanti.', 'Backstage ufficiale e interviste al cast', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:42:56.149599+00:00'),
('76ae534d-848f-4c26-9863-d145d9f41b40', 257, 'Casting & Scelte', 'La riunione del cast stellare con Nolan', 'Christopher Nolan ha assemblato un cast di prim''ordine includendo collaboratori storici come Matt Damon, Anne Hathaway e Robert Pattinson, affiancandoli per la prima volta a Tom Holland e Charlize Theron in un progetto epico.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Admin)', 'IA Verificata', 4, 1, '2026-11-02T17:20:01.120527+00:00'),
('ec2b929c-6426-4902-9aed-ef2603b757b5', 257, 'Segreti di produzione', 'L''utilizzo massiccio di pellicola IMAX e 70mm', 'Fedele alla sua estetica cinematografica analogica, Nolan e il direttore della fotografia Hoyte van Hoytema hanno girato gran parte delle sequenze marittime e mitologiche utilizzando cineprese IMAX a 65mm, riducendo al minimo l''uso del digitale.', 'American Cinematographer Magazine', TRUE, 'IA (Admin)', 'IA Verificata', 2, 2, '2026-11-02T17:20:01.120527+00:00'),
('96c4ef26-72e5-4840-9325-283ae7b00628', 257, 'Curiosità & Retroscena', 'Un adattamento epico della mitologia classica', 'Il progetto rappresenta la prima incursione diretta di Christopher Nolan nel genere epico-mitologico, adattando le avventure di Ulisse dall''Odissea di Omero con un approccio realistico e psicologico.', 'Intervista ufficiale di Christopher Nolan', TRUE, 'IA (Admin)', 'IA Verificata', 5, 3, '2026-11-02T17:20:01.120527+00:00'),
('fada58e1-1d5b-4f8a-b01d-eea2d9fd0dd5', 257, 'Aneddoti dal set', 'Condizioni estreme per le sequenze in mare', 'Le riprese delle scene di navigazione hanno richiesto settimane di lavoro in vasche d''acqua controllate e in open water, con attori come Matt Damon e Tom Holland sottoposti a condizioni climatiche e fisiche particolarmente impegnative.', 'Making-of ufficiale dal set', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T17:20:01.120527+00:00'),
('387a987d-379b-4e4a-b390-6cbd4c2eb76e', 257, 'Effetti speciali & Trucco', 'Preferenza per gli effetti pratici di scena', 'In linea con la filosofia di regia di Nolan, la produzione ha evitato l''abuso di CGI verde privilegiando effetti pratici, modellini in scala e scenografie reali per ricreare le tempeste e le isole fantastiche dell''epopea.', 'Reportage tecnico di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 1, 5, '2026-11-02T17:20:01.120527+00:00'),
('f4c0d8d2-29f2-4a6e-9f15-9cc1735e1d68', 257, 'Casting & Scelte', 'Il coinvolgimento di Tom Holland fuori dai franchise', 'La scelta di Tom Holland per un ruolo chiave nel film ha segnato una mossa strategica importante per l''attore, impegnato a consolidare la sua versatilità drammatica al di fuori dell''universo Marvel.', 'The Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 2, 6, '2026-11-02T17:20:01.120527+00:00'),
('a2d7fea2-4cf3-414e-9018-9e010a8b72f4', 257, 'Curiosità & Retroscena', 'La collaborazione ricorrente con Ludwig Göransson', 'Il compositore premio Oscar Ludwig Göransson ha curato la colonna sonora del film, segnando la sua terza collaborazione consecutiva con Christopher Nolan dopo Tenet e Oppenheimer.', 'Comunicato stampa ufficiale della colonna sonora', TRUE, 'IA (Admin)', 'IA Verificata', 5, 7, '2026-11-02T17:20:01.120527+00:00'),
('da1fe381-1acb-4b45-aa3e-f13cfabe8549', 257, 'Segreti di produzione', 'La segretezza blindata tipica delle produzioni Nolan', 'Come da tradizione per i film di Christopher Nolan, la sceneggiatura di Odissea è stata custodita con livelli di sicurezza estremi, costringendo gli attori a leggerla in stanze blindate senza poter portare copie cartacee o digitali con sé.', 'Interviste promozionali al cast', TRUE, 'IA (Admin)', 'IA Verificata', 4, 8, '2026-11-02T17:20:01.120527+00:00'),
('9b718fb5-ccc2-40bf-96a4-4eea73731d4b', 309, 'Casting & Scelte', 'David Thewlis e la trattativa per un ruolo chiave', 'L''attore britannico David Thewlis ha confermato in varie interviste di essere stato ingaggiato per interpretare un personaggio Na''vi non specificato nei vari sequel di Avatar, le cui apparizioni sono previste nei capitoli successivi al terzo o all''interno della saga stessa in evoluzione.', 'Intervista ufficiale a Total Film', TRUE, 'IA (Admin)', 'IA Verificata', 5, 8, '2026-11-02T17:21:46.447091+00:00'),
('e6e586b0-e059-4254-9332-e4a91a79e67e', 309, 'Segreti di produzione', 'La struttura produttiva del blocco triplo di riprese', 'James Cameron ha girato gran parte delle sequenze di ''Avatar: Fuoco e cenere'' in contemporanea non solo con ''La via dell''acqua'' (2022), ma anche con porzioni del quarto capitolo, per ovviare al naturale invecchiamento dei giovani attori della troupe.', 'Note di produzione ufficiali della Lightstorm Entertainment', TRUE, 'IA (Admin)', 'IA Verificata', 4, 9, '2026-11-02T17:21:46.447091+00:00'),
('799045e8-df58-4578-af8c-773d6fbcb488', 309, 'Aneddoti dal set', 'Il superamento dei limiti subacquei per la performance capture', 'Per girare le complesse scene acquatiche, la troupe ha dovuto sviluppare un nuovo sistema di comunicazione subacquea che permettesse a James Cameron di dirigere gli attori mentre trattenevano il respiro in enormi vasche da un milione e mezzo di galloni.', 'Featurette di making-of e documentario tecnico Wētá FX', TRUE, 'IA (Admin)', 'IA Verificata', 1, 10, '2026-11-02T17:21:46.447091+00:00'),
('cd99db4c-fd39-477f-8382-06492808f394', 309, 'Effetti speciali & Trucco', 'L''evoluzione del software di simulazione della cenere e della lava', 'La Wētá FX ha dovuto scrivere codici di simulazione completamente inediti per gestire l''interazione tra i corpi dei Na''vi e gli elementi vulcanici del Popolo della Cenere, in particolare per tracciare la cenere calda e le particelle di carbone sulla pelle digitale.', 'Articolo tecnico di Cinefex / Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 5, 11, '2026-11-02T17:21:46.447091+00:00'),
('b1f3b4f2-bbee-46a8-99d6-f935971e7b9c', 309, 'Curiosità & Retroscena', 'La riduzione della durata iniziale nel montaggio di Cameron', 'Come rivelato da James Cameron in diverse occasioni, il primo assemblaggio grezzo di questo terzo capitolo superava le nove ore di materiale, costringendo il montatore Stephen Rivkin e il regista a un lavoro di sintesi rigoroso prima di passare alla finalizzazione degli effetti visivi.', 'Intervista a Empire Magazine', TRUE, 'IA (Admin)', 'IA Verificata', 4, 12, '2026-11-02T17:21:46.447091+00:00'),
('bd2d9ec1-b021-4b9f-8210-9f528c66e63e', 370, 'Casting & Scelte', 'La collaborazione tra Bill Skarsgård e Anthony Hopkins', 'Il film vede la partecipazione straordinaria del veterano premio Oscar Anthony Hopkins al fianco del protagonista Bill Skarsgård, noto per aver interpretato Pennywise in IT. La dinamica tra i due attori costituisce il fulcro psicologico ed emotivo attorno a cui ruota l''intero thriller confinato all''interno dell''abitacolo del SUV.', 'Note di produzione ufficiali e comunicati stampa', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:43:34.01361+00:00'),
('7ff3b4aa-12cf-4140-a87b-e8805af09f78', 370, 'Curiosità & Retroscena', 'Remake del thriller argentino 4x4', 'La pellicola diretta da David Yarovesky è il remake ufficiale del celebre thriller argentino del 2019 intitolato 4x4, diretto da Mariano Cohn. Il film originale ha già generato diversi adattamenti internazionali grazie alla forza del suo concept claustrofobico basato su un veicolo apparentemente inespugnabile.', 'Database cinematografici ufficiali e registri di produzione', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:43:34.01361+00:00'),
('5f1d6a58-2976-4b3b-8a69-100007ae38b6', 370, 'Segreti di produzione', 'Unità di ripresa e ambientazione claustrofobica', 'Gran parte delle riprese si è svolta all''interno di spazi ristretti per ricreare la tensione e l''ansia del protagonista intrappolato. La troupe ha dovuto impiegare soluzioni tecniche particolari di cinepresa per muoversi agevolmente dentro e intorno all''abitacolo del veicolo di lusso.', 'Interviste alla troupe e report dal set', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:43:34.01361+00:00'),
('250aa4b2-a4d8-47c7-af23-719a97f1ee23', 370, 'Casting & Scelte', 'La direzione di David Yarovesky', 'Il regista David Yarovesky, già noto per aver diretto il thriller horror a tinte supereroistiche Brightburn - Figlio del male (2019), è stato scelto per dirigere il progetto grazie alla sua comprovata abilità nel gestire atmosfere tese e ad alta carica di adrenalina.', 'Annunci di casting e stampa specializzata', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:43:34.01361+00:00'),
('c0be12a3-2be6-464e-94b7-4685e530b134', 270, 'Casting & Scelte', 'La genesi teatrale dei personaggi e la transizione sul grande schermo', 'I tre personaggi di Al, John e Jack nacquero originariamente all''interno degli sketch teatrali del trio portati in tour negli anni precedenti, subendo una profonda riscrittura cinematografica per adattarli alla struttura narrativa di un lungometraggio di genere.', 'Interviste promozionali ufficiali e retroscena di sceneggiatura', TRUE, 'IA (Admin)', 'IA Verificata', 4, 6, '2026-11-02T17:20:15.905864+00:00'),
('b9824953-86d2-4943-a286-9070eb29884e', 270, 'Aneddoti dal set', 'Le difficoltà linguistiche e i dialetti sul set milanese', 'Durante le riprese, gli attori dovettero lavorare intensamente sulla dizione e sul tono della voce per conferire ai loro personaggi mafiosi quell''accento italo-americano stereotipato, alternando momenti di seria recitazione a frequenti pause di ilarità collettiva dovute alle gag improvvisate da Giovanni Storti.', 'Making-of ufficiale e contenuti extra del DVD Medusa', TRUE, 'IA (Admin)', 'IA Verificata', 2, 7, '2026-11-02T17:20:15.905864+00:00'),
('f84f286e-9b6a-42c9-9d5d-a83f099a3b9b', 270, 'Segreti di produzione', 'La ricostruzione degli interni tra Cinecittà e studi dedicati', 'Per riprodurre fedelmente i locali, gli uffici e le strade della New York di fine anni cinquanta, la produzione si affidò a imponenti set di Cinecittà, coordinati dallo scenografo che dovette studiare repertori fotografici d''epoca per garantire il massimo rigore visivo.', 'Note di produzione e reparti artistici del film', TRUE, 'IA (Admin)', 'IA Verificata', 2, 8, '2026-11-02T17:20:15.905864+00:00'),
('9456c9d0-20b2-4af0-9caa-43d1a060fc8c', 270, 'Citazioni & Easter Egg', 'I riferimenti espliciti a ''A qualcuno piace caldo''', 'Molte delle dinamiche e delle gag visive del film, in particolare quelle legate agli scambi di persona e ai travestimenti goffi dei protagonisti, sono un chiaro omaggio strutturale alle commedie slapstick americane degli anni cinquanta, con citazioni dirette al cinema di Billy Wilder.', 'Analisi critiche e commento audio del regista Massimo Venier', TRUE, 'IA (Admin)', 'IA Verificata', 4, 9, '2026-11-02T17:20:15.905864+00:00'),
('014ad1c3-8707-4281-b730-b70e8a69e58b', 371, 'Casting & Scelte', 'Il primo sodalizio tra Wes Anderson e Benicio Del Toro', 'Benicio Del Toro è stato scelto per interpretare il magnate internazionale Zsa-zsa Korda, segnando la prima collaborazione in assoluto tra l''attore premio Oscar e il regista Wes Anderson.', 'Annunci ufficiali di casting della produzione e comunicati stampa della 20th Century Studios', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:44:24.781983+00:00'),
('f3ea8929-cdb8-4ca7-9e03-3fd40a0f18bc', 371, 'Curiosità & Retroscena', 'La compresenza di Mia Threapleton nel cast corale', 'Nel cast figura anche Mia Threapleton, attrice e figlia di Kate Winslet, chiamata a interpretare ruoli di rilievo a fianco di veterani del cinema come Tom Hanks e Bill Murray.', 'Note di produzione ufficiali e database IMDb Pro', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:44:24.781983+00:00'),
('3f302b9a-f1af-43c0-939b-f5d7c3c15a09', 371, 'Casting & Scelte', 'Il ritorno di collaboratori storici di Anderson', 'Il film vede la partecipazione di attori storicamente legati all''estetica di Wes Anderson, tra cui Bill Murray, Bryan Cranston, Mathieu Amalric e Adrien Brody, confermando la consueta compagnia di giro del regista.', 'Press kit ufficiale del film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:44:24.781983+00:00'),
('49e9166a-1217-42e1-874b-387c087a7ed3', 371, 'Segreti di produzione', 'La genesi della sceneggiatura scritta con Roman Coppola', 'La sceneggiatura originale di ''La trama fenicia'' è stata scritta da Wes Anderson a quattro mani insieme a Roman Coppola, proseguendo una fortunata e duratura collaborazione di scrittura iniziata con ''Il treno per il Darjeeling'' e ''Moonrise Kingdom''.', 'Crediti ufficiali della sceneggiatura e registrazioni WGA', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:44:24.781983+00:00'),
('051e973f-a25e-4585-ae14-e27ed514b55e', 371, 'Curiosità & Retroscena', 'Il focus narrativo sul rapporto padre-figlia', 'La trama centrale ruota attorno al magnate Zsa-zsa Korda che, sopravvissuto a un incidente aereo per la sesta volta, cerca di riconciliarsi con la figlia Liesl, votata alla vita monastica.', 'Sinossi ufficiale rilasciata dalla produzione', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T17:44:24.781983+00:00'),
('2c8fde20-cf0f-4212-92ae-ca99d728d3b0', 276, 'Casting & Scelte', 'Il coinvolgimento di Maria Di Biase', 'L''attrice e comica Maria Di Biase è stata fortemente voluta dal regista Ivan Silvestrini per interpretare uno dei docenti più stravaganti del corpo insegnanti, portando sul set la sua collaudata esperienza nel genere comico e nella caratterizzazione surreale.', 'Note di produzione ufficiali Wildside', TRUE, 'IA (Admin)', 'IA Verificata', 1, 11, '2026-11-02T17:20:40.312256+00:00'),
('7e88a749-32fa-4569-8ef7-5449c2955b95', 276, 'Aneddoti dal set', 'Le riprese nei veri istituti scolastici romani', 'Le riprese del film si sono svolte principalmente all''interno di complessi scolastici realmente esistenti a Roma e provincia, costringendo la troupe a coordinare il fitto piano di lavorazione con i calendari effettivi delle attività didattiche.', 'Reportage dal set e comunicato stampa di distribuzione 01 Distribution', TRUE, 'IA (Admin)', 'IA Verificata', 4, 12, '2026-11-02T17:20:40.312256+00:00'),
('01f4df17-0a7e-47bd-8ca8-1b0b0820544d', 159, 'Effetti speciali & Trucco', 'La ripresa IMAX con la cinepresa distrutta', 'Christopher Nolan e il direttore della fotografia Wally Pfister furono tra i primi a girare sequenze cinematografiche di massa con cineprese IMAX 65mm. Durante una scena d''azione, una delle rarissime e costosissime macchine da presa IMAX è andata distrutta a causa di una collisione con la Batmobile.', 'Intervista tecnica a Wally Pfister su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:22.378796+00:00'),
('62c37a9e-ecbb-4197-9eba-90460a5496d2', 276, 'Effetti speciali & Trucco', 'La caratterizzazione visiva dei professori', 'Il reparto trucco e acconciature ha lavorato a stretto contatto con Ivan Silvestrini per accentuare i tratti caricaturali dei docenti protagonisti, differenziandoli nettamente attraverso look bizzarri e distintivi per enfatizzare l''origine fumettistica dei personaggi.', 'Intervista al reparto trucco nel making-of ufficiale', TRUE, 'IA (Admin)', 'IA Verificata', 4, 13, '2026-11-02T17:20:40.312256+00:00'),
('c7a5026e-0e6d-419f-a74f-33e014ae0c3c', 159, 'Aneddoti dal set', 'Heath Ledger regista del video amatoriale del Joker', 'I due video in cui il Joker minaccia i suoi ostaggi (inclusi il falso Batman e il giornalista Mike Engel) furono interamente diretti da Heath Ledger in persona. Christopher Nolan gli lasciò carta bianca per girare le clip in autonomia, ritenendo che l''attore avesse compreso perfettamente la psicologia del personaggio.', 'Commento audio del regista e featurette ufficiali del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:22.378796+00:00'),
('5a537642-5f57-40ae-b17e-219348e0ddd7', 159, 'Casting & Scelte', 'Il provino di Cillian Murphy mancato per Batman', 'Prima di ottenere la parte dello Spaventapasseri (Jonathan Crane), Cillian Murphy sostenne un provino ufficiale per il ruolo di Bruce Wayne indossando persino il costume originale di Batman del film del 1995. Nonostante la parte fosse andata a Christian Bale, Nolan rimase così colpito da volerlo comunque nel cast.', 'Special feature ''The Dark Knight: The Evolution of the Knight'' e provini di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:22.378796+00:00'),
('ec90b602-9adb-4eda-a740-2a50e4d8a766', 159, 'Effetti speciali & Trucco', 'Il trucco artigianale del Joker', 'Il celebre trucco facciale del Joker non fu realizzato da professionisti con costosi prostetici in silicone, ma ideato dallo stesso Heath Ledger insieme alla truccatrice C为空 Johnson usando economici cosmetici da farmacia acquistati in un negozio di Los Angeles, per riflettere l''indole caotica e trasandata del personaggio.', 'Intervista alla make-up artist C为空 Johnson e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:22.378796+00:00'),
('26d75803-118e-4ad4-a6ae-8bd973df71a6', 159, 'Aneddoti dal set', 'La matita fatta sparire senza CGI', 'Il celebre trucco di magia in cui il Joker fa ''sparire'' una matita conficcandola nel tavolo durante la riunione dei boss della malavita fu eseguito interamente dal vivo senza l''ausilio di effetti digitali. La matita fu semplicemente ritirata rapidamente nel tavolo grazie a un piccolo foro preventivamente preparato dagli stuntman.', 'Dietro le quinte e breakdown degli stunt ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:22.378796+00:00'),
('4274e39c-6ea1-40fd-9c54-1009df856aad', 159, 'Casting & Scelte', 'Robin Williams e l''interesse per l''Enigmista', 'Robin Williams espresse pubblicamente e ripetutamente il forte desiderio di interpretare un villain nella trilogia di Nolan, in particolare l''Enigmista (Riddler), candidandosi apertamente per i capitoli successivi, sebbene i produttori avessero scelto una direzione più realistica per il franchise senza quel personaggio.', 'Interviste a Robin Williams per MTV News e Los Angeles Times (2008)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:22.378796+00:00'),
('15aa5039-2df1-4d53-9b72-7ca935220cde', 159, 'Citazioni & Easter Egg', 'Il vero nome di Gotham nascosto nei titoli', 'Nelle targhe delle auto della polizia di Gotham City presenti in molte sequenze del film compare la dicitura ''State of Arkham'' o riferimenti geografici fittizi dello stato del New Jersey, omaggiando sottilmente le origini cartacee classiche ideate da Bill Finger nei fumetti della DC Comics.', 'Analisi dei prop di scena e MovieMistakes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:44:22.378796+00:00'),
('c8fc7316-0333-40c1-b810-f168c4503c19', 202, 'Effetti speciali & Trucco', 'La decolorazione dei capelli di Jennifer Lawrence', 'Per interpretare Katniss Everdeen, la naturale chioma bionda di Jennifer Lawrence è stata tinta di un castano scuro. Tuttavia, il processo di colorazione ha causato gravi danni ai suoi capelli, costringendo la produzione a farle indossare delle parrucche di alta qualità durante i ciak di ripresa nelle settimane successive.', 'Note di produzione e interviste al reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:37.217996+00:00'),
('dcbd0d2f-2fa9-4719-b7a6-1cb22901b14d', 202, 'Aneddoti dal set', 'L''incidente con il tiro con l''arco', 'Durante le settimane di addestramento intensivo con il tiro con l''arco, Jennifer Lawrence ha colpito per sbaglio un manichino di gommapiuma rimbalzando la freccia contro sé stessa, fortunatamente senza conseguenze gravi ma spaventando la troupe.', 'Dietro le quinte ufficiale del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:37.217996+00:00'),
('a6e2ace7-526e-40d7-9dc9-e45b04ca1f23', 202, 'Casting & Scelte', 'Il casting di Josh Hutcherson come Peeta', 'Josh Hutcherson ha ottenuto la parte di Peeta Mellark dopo una serie di provini in cui ha dimostrato una notevole forza fisica, riuscendo a sollevare con facilità Jennifer Lawrence durante le letture della scena del sacco di farina.', 'Audio commento del regista Gary Ross', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:37.217996+00:00'),
('9b4c5c3f-402b-45d6-a9fe-78924bd0139f', 202, 'Effetti speciali & Trucco', 'Il look stravagante di Elizabeth Banks', 'Elizabeth Banks doveva sottoporsi a sessioni di trucco quotidiane della durata di oltre due ore per trasformarsi in Effie Trinket, indossando unghie acriliche così lunghe e scomode da richiederle assistenza anche per compiere semplici gesti sul set.', 'Intervista a Elizabeth Banks per Vanity Fair', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:37.217996+00:00'),
('deb7510e-8b1c-49b5-9174-7fbacc35d5e7', 202, 'Aneddoti dal set', 'L''improvvisazione di Woody Harrelson su Haymitch', 'Woody Harrelson ha improvvisato la scena in cui Haymitch fa cadere il bicchiere di liquore durante la cena sul treno diretto a Capitol City, definendo immediatamente il carattere cinico e dipendente dall''alcol del mentore del Distretto 12.', 'Making-of ufficiale e note della sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:37.217996+00:00'),
('f0bec533-afee-4676-8fe8-8ac98653c20c', 276, 'Citazioni & Easter Egg', 'I riferimenti alla tradizione della commedia scolastica', 'All''interno del film sono disseminati diversi omaggi visivi e testuali ai classici italiani del cinema ambientato tra i banchi di scuola, pensati per strizzare l''occhio agli spettatori più cinefili e creare un ponte generazionale tra la vecchia scuola e il nuovo millennio.', 'Analisi della critica cinematografica e recensioni ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 1, 14, '2026-11-02T17:20:40.312256+00:00'),
('05039810-491e-4082-9e97-7a33280c9046', 160, 'Casting & Scelte', 'La scelta di Joseph Gordon-Levitt', 'Christopher Nolan ha voluto fortemente Joseph Gordon-Levitt per il ruolo del poliziotto John Blake dopo essere rimasto folgorato dalla sua interpretazione in Inception, girato poco prima.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:26.760884+00:00'),
('9a3e2063-241a-4a78-aa19-f5300eed790e', 160, 'Aneddoti dal set', 'La voce incomprensibile di Bane', 'Durante le prime proiezioni del montaggio preliminare, la voce filtrata di Tom Hardy nei panni di Bane risultava quasi incomprensibile a causa della maschera, costringendo Nolan a ridoppiare parzialmente l''attore in post-produzione.', 'Intervista a Christopher Nolan su Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:26.760884+00:00'),
('0d244e7d-3e06-4e50-9df9-f8d156d008ff', 160, 'Segreti di produzione', 'Il record di IMAX', 'Il direttore della fotografia Wally Pfister ha utilizzato ampiamente cineprese IMAX a pellicola 65mm, girando oltre 72 minuti del film in questo formato per garantire un''immersione visiva senza precedenti nelle sale.', 'American Cinematographer Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:26.760884+00:00'),
('c215359c-12b4-4182-aa1d-becdc837558b', 160, 'Curiosità & Retroscena', 'L''ispirazione da Una storia di due città', 'Il romanzo di Charles Dickens ''Una storia di due città'' ha fornito la struttura tematica di fondo per la rivoluzione proletaria guidata da Bane contro i ricchi di Gotham City.', 'Commento audio del regista e sceneggiatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:26.760884+00:00'),
('8707ad27-f988-4718-83aa-05a54d98f6c1', 160, 'Casting & Scelte', 'Il cameo di Liam Neeson', 'Liam Neeson ha ripreso brevemente il ruolo di Ra''s al Ghul in una sequenza onirica, riuscendo a mantenere segreta la sua partecipazione sul set grazie a riprese effettuate in gran Bretagna in un solo giorno.', 'Collider / Interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:26.760884+00:00'),
('1acb6920-0b82-4440-a6da-c0521d9cce2f', 160, 'Aneddoti dal set', 'La trasformazione fisica di Christian Bale', 'Christian Bale ha dovuto faticare enormemente per recuperare la massa muscolare necessaria dopo il drastico dimagrimento subito per The Fighter, riprendendo l''allenamento intensivo mesi prima delle riprese.', 'Interviste promozionali di Christian Bale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:26.760884+00:00'),
('b61e881a-04c8-4dcd-af3c-755ac6bbec94', 160, 'Effetti speciali & Trucco', 'La distruzione della finta palla da football', 'La celebre scena in cui il campo da football americano esplode durante la partita è stata realizzata combinando veri effetti pirotecnici sul campo di Pittsburgh con immagini generate al computer per far sprofondare il terreno.', 'Making-of ufficiale nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:26.760884+00:00'),
('494267e4-789f-400a-9c14-9917aa232250', 160, 'Citazioni & Easter Egg', 'L''omaggio a Robin', 'Il vero nome di battesimo rivelato alla fine per il personaggio di John Blake interpretato da Joseph Gordon-Levitt è Robin, un omaggio esplicito alla spalla classica di Batman nei fumetti.', 'Analisi del film e sceneggiatura ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:44:26.760884+00:00'),
('199aaed1-f7b5-485f-b2ef-6140d147fc2c', 201, 'Casting & Scelte', 'Il rifiuto di Dustin Hoffman e le pressioni sugli attori', 'Dustin Hoffman rifiutò inizialmente la parte del soldato Cresta, ruolo che andò poi a Peter Strauss. Ralph Nelson scelse Strauss per la sua aria pulita e ingenuamente idealista, contrapposta alla cinica disillusione del personaggio interpretato da Candice Bergen.', 'Note di produzione e biografia di Ralph Nelson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:31.832811+00:00'),
('b4edc590-4b93-4f53-8a6d-da20e5bdd19a', 201, 'Aneddoti dal set', 'Le riprese in Messico e i disagi climatici', 'Il film fu interamente girato nelle zone desertiche dello stato di Durango, in Messico, location storica per molti spaghetti western e produzioni hollywoodiane. La troupe dovette affrontare temperature torride superiori ai 40 gradi e frequenti tempeste di sabbia che danneggiarono le attrezzature cinematografiche.', 'Reportage d''epoca sul set di Soldier Blue', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:31.832811+00:00'),
('a0b194af-873d-491f-af37-94ae26e00460', 201, 'Segreti di produzione', 'La censura internazionale e i tagli drastici', 'A causa dell''estrema violenza della sequenza finale, il film subì forti censure e divieti in molti paesi europei e asiatici. In Spagna e in altri mercati la censura impose tagli netti per rimuovere i dettagli più truculenti del massacro per evitare sommosse nelle sale.', 'Archivi della censura cinematografica internazionale del 1970-1971', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:31.832811+00:00'),
('f7650f25-5fbb-4cec-a3af-551cb69f56a6', 201, 'Citazioni & Easter Egg', 'L''ispirazione visiva ai cinegiornali sul Vietnam', 'Ralph Nelson diresse la sequenza del massacro finale ispirandosi direttamente alle fotografie e ai reportage televisivi sui crimini di guerra americani in Vietnam, in particolare al famigerato massacro di My Lai avvenuto nel 1968.', 'Intervista retrospettiva a Ralph Nelson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:31.832811+00:00'),
('fb0b6c2c-3205-45ad-a098-dd3d6c843800', 201, 'Effetti speciali & Trucco', 'L''uso di stuntman professionisti nativi americani', 'Per le scene più pericolose dell''attacco della cavalleria e le rocambolesche cadute da cavallo, la produzione ingaggiò stuntman professionisti, molti dei quali di origini native americane, coordinati dal leggendario stunt coordinator Yakima Canutt.', 'Credits di produzione e documentario sugli stunt di Hollywood', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:31.832811+00:00'),
('7b6863a8-e5e1-4ec1-96b3-909695f4eede', 206, 'Curiosità & Retroscena', 'La consulenza di Suzanne Collins sulla sceneggiatura', 'L''autrice Suzanne Collins è stata strettamente coinvolta nello sviluppo del film fin dalle prime fasi di stesura della sceneggiatura, lavorando a stretto contatto con lo sceneggiatore Michael Arndt per mantenere intatte le tematiche filosofiche e politiche del romanzo originale del 2020.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:50.890668+00:00'),
('45d72b16-06bc-4190-9027-e68a222579df', 276, 'Segreti di produzione', 'La collaborazione tra Wildside e Universal', 'La produzione della pellicola è stata affidata a Wildside in collaborazione con Universal Pictures International Italy, un accordo strategico che ha garantito una solida campagna di lancio e una distribuzione capillare nelle sale cinematografiche italiane.', 'Comunicati finanziari e di produzione cinematografica 2018', TRUE, 'IA (Admin)', 'IA Verificata', 2, 15, '2026-11-02T17:20:40.312256+00:00'),
('32538cc6-1701-4f15-92c2-b6e23b231be2', 276, 'Casting & Scelte', 'La scelta di Pietro Ragusa nel corpo docente', 'Pietro Ragusa è stato ingaggiato per completare il quadro dei professori disadattati, attingendo al suo curriculum di attore versatile tra cinema, televisione e teatro per dare spessore a una figura di docente rigida ma grottesca.', 'Crediti ufficiali e cartella stampa del film', TRUE, 'IA (Admin)', 'IA Verificata', 4, 16, '2026-11-02T17:20:40.312256+00:00'),
('20f22cab-fe72-47ab-9592-500110882e39', 276, 'Aneddoti dal set', 'La gestione delle scene di massa con le giovani leve', 'Per gestire le caotiche sequenze in aula con le decine di giovani comparse, la troupe ha dovuto ricorrere a frequenti prove tecniche di posizionamento, così da mantenere il ritmo comico serrato imposto dalla regia durante i dialoghi principali.', 'Backstage ufficiale distribuito per l''home video', TRUE, 'IA (Admin)', 'IA Verificata', 1, 17, '2026-11-02T17:20:40.312256+00:00'),
('f8fa13ed-c8c3-4d5e-80a6-507a4bd6c0b9', 276, 'Citazioni & Easter Egg', 'Il tributo implicito al liceo di periferia', 'La scelta del nome ''Liceo Alessandro Manzoni'' per il peggior istituto d''Italia rappresenta un ironico e dissacrante rovesciamento letterario rispetto alla tradizione dei romanzi storici scolastici italiani.', 'Note di sceneggiatura e sinossi ufficiale', TRUE, 'IA (Admin)', 'IA Verificata', 1, 18, '2026-11-02T17:20:40.312256+00:00'),
('8e12624b-a531-4c41-833f-327b0403023f', 161, 'Curiosità & Retroscena', 'La vera gestazione del progetto durata un decennio', 'Luc Besson ha iniziato a scrivere la sceneggiatura di ''Lucy'' dieci anni prima dell''effettiva uscita nelle sale cinematografiche, nel 2004. Il regista ha dichiarato di aver atteso i progressi tecnologici necessari nel campo degli effetti visivi per poter rappresentare visivamente la progressiva espansione delle capacità cerebrali della protagonista senza scadere nel kitsch.', 'Note di produzione ufficiali EuropaCorp e interviste alla stampa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:31.45999+00:00'),
('cdcf48f9-21f6-478a-a391-f78cb256c4fa', 161, 'Aneddoti dal set', 'La preparazione fisica estrema di Scarlett Johansson', 'Per prepararsi al ruolo della spietata combattente potenziata dal CPH4, Scarlett Johansson si è sottoposta a mesi di allenamento intensivo quotidiano con la leggendaria stuntwoman Nadine Lucidi e il coordinatore degli stunt Simon Rhee. L''attrice ha eseguito personalmente la maggior parte dei combattimenti corpo a corpo, inclusa la complessa sequenza nell''ospedale di Taipei.', 'Featurette di making-of ''The Evolution of Lucy'' nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:31.45999+00:00'),
('64d867c6-56ca-412c-94d7-ab47e24d7058', 161, 'Aneddoti dal set', 'La barriera linguistica sul set di Taipei', 'Durante le riprese effettuate a Taipei, la troupe ha dovuto affrontare notevoli difficoltà di comunicazione tra la troupe tecnica francese/statunitense e gli operatori locali taiwanesi. L''attore Choi Min-sik, celebre stella del cinema sudcoreano che interpreta il villain Mr. Jang, recitava unicamente in coreano, costringendo Scarlett Johansson e il resto del cast a basarsi interamente sul linguaggio del corpo e sulla tempistica delle battute.', 'Intervista al regista Luc Besson e al cast nel backstage ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:31.45999+00:00'),
('1874604c-d8a8-4812-8bdd-5c69b17bbca3', 161, 'Segreti di produzione', 'L''uso reale degli spazi della National Taiwan University', 'La celebre sequenza in cui Lucy si reca all''università per incontrare il professor Samuel Norman (interpretata da Morgan Freeman) è stata girata all''interno del campus reale della National Taiwan University. La troupe ha ottenuto permessi di accesso straordinari per girare nei laboratori storici, integrando studenti e strutture reali nelle inquadrature di sfondo.', 'Diario di produzione e location report di Taiwan Film Commission', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:31.45999+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('32f3db7a-bc07-4eb5-bd32-b11db766ae8c', 161, 'Segreti di produzione', 'La collaborazione con il neuroscienziato Yannick Jacquet', 'Luc Besson si è consultato a lungo con il neuroscienziato francese Yannick Jacquet e altri esperti accademici prima di strutturare il film. Sebbene il mito del 10% del cervello umano sia scientificamente errato e smentito dalla comunità medica, il regista ha voluto mantenere un fondamento visivo rigoroso nella rappresentazione delle sinapsi e del flusso di informazioni nel sistema nervoso.', 'Intervista scientifica rilasciata da Luc Besson per la promozione del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:31.45999+00:00'),
('800039dc-f763-4d0c-bfdd-21909480b301', 161, 'Citazioni & Easter Egg', 'I camei e la troupe nei ruoli secondari', 'Molti dei membri della troupe tecnica francese di EuropaCorp, inclusi assistenti alla regia e operatori di macchina, compaiono in brevi ruoli di contorno all''interno delle sequenze ambientate a Parigi, in particolare durante la scena dello scontro a fuoco nell''hotel e nei corridoi dell''aeroporto Charles de Gaulle.', 'Crediti estesi e commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:31.45999+00:00'),
('5292d928-92d9-414c-b614-7116c8c447d0', 182, 'Effetti speciali & Trucco', 'La riproduzione in scala dei piedi pelosi di Bilbo', 'Per le inquadratura ravvicinate dei piedi pelosi di Bilbo Baggins, il reparto costumi ha realizzato protesi in silicone così dettagliate che ogni singolo pelo veniva inserito a mano. Martin Freeman doveva indossarli ogni giorno con un processo di applicazione che richiedeva oltre un''ora.', 'Documentario di produzione ufficiale ''The Appendices''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:27.480133+00:00'),
('842aab48-6d48-454d-b70d-f420234b85d1', 182, 'Casting & Scelte', 'Il rifiuto iniziale di Martin Freeman', 'Martin Freeman aveva inizialmente rifiutato il ruolo di Bilbo Baggins a causa di conflitti di programmazione con la serie televisiva ''Sherlock''. Peter Jackson decise di riorganizzare l''intero calendario di produzione pur di averlo, ritenendolo l''unico attore possibile per la parte.', 'Intervista ufficiale di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:27.480133+00:00'),
('2adca4d9-177c-4981-800a-432fe71b3625', 182, 'Segreti di produzione', 'L''uso pionieristico del 3D a 48 fotogrammi al secondo', 'Peter Jackson è stato uno dei primi registi a girare un lungometraggio epico a 48 fotogrammi al secondo (HFR) in 3D stereoscopico, una scelta tecnica che divise la critica e il pubblico per la sua estrema nitidezza visiva ma che ridusse drasticamente il fenomeno del motion blur.', 'Note tecniche di produzione della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:27.480133+00:00'),
('a3512f3c-0dc4-4099-b675-3e68527c8f6d', 182, 'Segreti di produzione', 'La spada Sting e i LED nascosti', 'La spada di Bilbo, Pungolo (Sting), è stata modificata rispetto alla trilogia de ''Il Signore degli Anelli'' inserendo minuscole luci LED interne controllate a distanza. Questo permetteva alla lama di illuminarsi di blu quando gli Orchi si avvicinavano, senza dover ricorrere esclusivamente agli effetti digitali in post-produzione.', 'Approfondimento sugli oggetti di scena con Weta Workshop', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:27.480133+00:00'),
('218e1fb3-5364-4568-914b-e513357e858a', 182, 'Citazioni & Easter Egg', 'Il cameo dei figli di Peter Jackson', 'I figli del regista Peter Jackson, ovvero Katie, Billy e Ted Jackson, compiono tutti dei brevi camei all''interno del film. Appaiono rispettivamente come rifugiati di Dale nella sequenza iniziale ambientata a Erebor e come abitanti di Brea nella scena alla locanda.', 'Commento audio del regista nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:27.480133+00:00'),
('97d88ba9-9683-4d15-ad85-d299ec416255', 182, 'Aneddoti dal set', 'Il costume di Thorin e i problemi di peso', 'Richard Armitage ha dovuto indossare costumi pesantissimi e multistrato per interpretare Thorin Scudodiquercia, inclusi pesanti parastinchi in metallo e pellicce. Durante le scene di combattimento più intense nel fango, l''attore ha rischiato più volte il colpo di calore a causa del clima umido degli studi in Nuova Zelanda.', 'Intervista a Richard Armitage nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:27.480133+00:00'),
('4f3086a7-2d18-435f-b697-ae0d50a5bce9', 182, 'Citazioni & Easter Egg', 'L''omaggio a Peter Jackson nel mercato di Brea', 'Nella sequenza in cui i nani arrivano a Brea, si intravede chiaramente un uomo che fuma una pipa e mangia una carota: quell''uomo è proprio il regista Peter Jackson, che ripete il cameo rapido e senza battute già fatto nei precedenti film della Terra di Mezzo.', 'Guida ufficiale agli Easter Egg di Middle-earth', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:27.480133+00:00'),
('a05440d6-6034-4a3b-972c-9d18d8f21318', 182, 'Effetti speciali & Trucco', 'La creazione digitale del goblin King', 'Il Grande Goblin, doppiato e interpretato tramite motion capture da Barry Humphries, è stato progettato con enormi gozzi pendenti e una corporatura grottesca. Gli animatori della Weta Digital hanno impiegato mesi solo per simulare realisticamente il movimento della pelle flaccida durante i suoi dialoghi.', 'Diario di produzione di Weta Digital', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:45:27.480133+00:00'),
('a35adfcc-97db-4df6-b414-70ad51ab5525', 162, 'Casting & Scelte', 'La svolta drammatica per Jim Carrey', 'Prima di ottenere la parte di Truman Burbank, Jim Carrey era celebre quasi esclusivamente per ruoli comici sopra le righe come in ''Ace Ventura'' e ''The Mask''. Il produttore Scott Rudin e il regista Peter Weir videro in lui la combinazione perfetta di vulnerabilità e istrionismo necessaria per dare spessore emotivo a un personaggio ignaro di vivere in una finzione.', 'Commento audio del regista Peter Weir nell''edizione speciale DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:36.242925+00:00'),
('43756eeb-8214-4f32-a0e6-517b557be4a3', 162, 'Casting & Scelte', 'Il casting originario di Ed Harris', 'Il ruolo del demiurgo Christof fu inizialmente assegnato a Dennis Hopper, ma l''attore lasciò il set dopo pochi giorni di riprese a causa di divergenze creative. Ed Harris fu chiamato d''urgenza per sostituirlo, ottenendo successivamente una candidatura al premio Oscar come miglior attore non protagonista.', 'Note di produzione ufficiali Paramount Pictures e registri di casting', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:36.242925+00:00'),
('695937a6-d487-4c72-a91b-2d8b1b06966b', 162, 'Aneddoti dal set', 'L''improvvisazione della telecamera nel box della doccia', 'Durante la sequenza in cui Truman finge di parlare con se stesso davanti allo specchio del bagno per depistare le telecamere, Jim Carrey inventò sul momento la gag in cui finge di usare una piccola telecamera nascosta dietro un adesivo, cogliendo di sorpresa la troupe e lo stesso regista.', 'Documentario making-of ''How''s the World Watching?''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:36.242925+00:00'),
('0e9b013f-d706-417f-bb26-71618e46c8d2', 162, 'Segreti di produzione', 'La costruzione della cittadina ideale di Seahaven', 'Le riprese della cittadina di Seahaven non si sono svolte in un set in studio, ma nella vera comunità pianificata di Seaside, in Florida. Peter Weir scelse questa location per la sua architettura in stile New Urbanism, perfettamente ordinata e artificiale al punto da sembrare finta.', 'Archivio storico di American Cinematographer, giugno 1998', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:36.242925+00:00'),
('d70f432b-ddd2-403f-b942-5aca4ce72136', 162, 'Effetti speciali & Trucco', 'L''assenza di effetti digitali nella cupola finale', 'Il celebre finale in cui la barca di Truman collide contro il cielo dipinto della cupola non fece quasi uso di CGI. La parete dipinta sul fondale dell''oceano fu realizzata materialmente da enormi scenografie fisiche dipinte a mano, illuminate appositamente per simulare l''orizzonte marino.', 'Special report sugli effetti visivi di Cinefex n. 74', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:36.242925+00:00'),
('b3758989-a51e-4f0a-8069-f993f62240f0', 162, 'Citazioni & Easter Egg', 'Il tributo a Charlie Chaplin', 'La sequenza in cui Truman cammina lungo i binari del treno ed evita abilmente un convoglio con una piroetta acrobatica è un esplicito omaggio visivo al cinema muto di Buster Keaton e Charlie Chaplin, voluto da Peter Weir per rimarcare la natura slapstick e controllata della vita del protagonista.', 'Analisi critica e intervista a Peter Weir per Film Comment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:36.242925+00:00'),
('66ac1201-eb8c-47fc-b22b-164e70c3bc4c', 162, 'Aneddoti dal set', 'La scelta del nome del cane e le riprese con gli animali', 'Il cane di scena che interagisce con Truman e Laura Linney era un esemplare addestrato che sul set creò non pochi problemi di continuità. A causa dei rigidi orari di lavoro imposti dalle normative sugli animali sul set, la troupe doveva girare rapidamente ogni interazione ravvicinata.', 'Diario di produzione dal set di Seaside, Florida (1997)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:36.242925+00:00'),
('51c4ad37-59d5-47d2-aebe-9b11150d9a08', 183, 'Casting & Scelte', 'La commozione di Evangeline Lilly per Tauriel', 'L''attrice Evangeline Lilly ha confessato di aver inizialmente esitato ad accettare il ruolo di Tauriel, un personaggio non presente nei libri originali di J.R.R. Tolkien, temendo le reazioni negative dei puristi della Terra di Mezzo. Ha accettato la parte solo dopo aver scoperto di essere stata una grande fan dei libri sin dalla sua giovinezza e aver ricevuto rassicurazioni sullo spessore del personaggio.', 'Interviste promozionali ufficiali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:32.037748+00:00'),
('1d4d9f44-89bd-4829-8e90-1381b06c96c7', 183, 'Effetti speciali & Trucco', 'Le ore di preparazione per Azog il Dissacratore', 'Sebbene il personaggio di Azog fosse interamente realizzato in CGI tramite performance capture interpretato da Manu Bennett, nelle prime fasi di pre-produzione si era pensato di realizzarlo con il make-up prostetico tradizionale. L''attore Conan Stevens era stato originariamente scelto e truccato per la parte prima che la produzione optasse per la versione digitale.', 'Appendici del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:32.037748+00:00'),
('edddf566-21ba-4841-9560-defb900eb2e5', 183, 'Citazioni & Easter Egg', 'Il cameo di Peter Jackson nei panni del mercante', 'Il regista Peter Jackson fa la sua consueta apparizione in un cameo all''inizio del film: è il personaggio che morde una carota e rutta fuori dalla locanda Prancey Pony a Bree, nella scena iniziale che si collega temporalmente con ''La Compagnia dell''Anello''.', 'Making-of e credit non accreditati', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:32.037748+00:00'),
('13318c69-b817-4cd7-bdd7-631515a8f813', 183, 'Segreti di produzione', 'Le coreografie di combattimento di Orlando Bloom', 'Orlando Bloom, riprendendo il ruolo di Legolas a distanza di dieci anni dalla trilogia de ''Il Signore degli Anelli'', ha dovuto sottoporsi a mesi di allenamento fisico intensivo. Poiché le sue acrobazie erano ora potenziate dalla grafica computerizzata, l''attore ha lavorato duramente con i cascatneurs per mantenere lo stile di lotta unico ed elfico già stabilito nel 2001.', 'Documentario di produzione ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:32.037748+00:00'),
('9b12e6c8-2159-4808-8ee9-625b8c489d41', 186, 'Casting & Scelte', 'L''ultima apparizione cinematografica di Audrey Hepburn', 'Il ruolo dell''angelo Hap nel film segna l''ultima apparizione sul grande schermo di Audrey Hepburn prima della sua scomparsa nel 1993. Steven Spielberg la convinse a tornare al cinema offrendole un ruolo che rispecchiava la sua reale dedizione umanitaria e donando l''intero suo compenso all''Unicef.', 'Note di produzione ufficiali di Steven Spielberg e biografie autorizzate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:45.87752+00:00'),
('4f086795-1419-4541-9fe3-271dfad05696', 186, 'Curiosità & Retroscena', 'Il remake di un classico di Victor Fleming', 'Always è il remake ufficiale del film del 1943 ''Joe il pilota'' (A Guy Named Joe), diretto da Victor Fleming e interpretato da Spencer Tracy, che Spielberg ha dichiarato essere uno dei suoi film preferiti d''infanzia e una profonda fonte di ispirazione.', 'Interviste promozionali d''archivio e pressbook originale Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:45.87752+00:00'),
('da5f7cbc-bb95-43b1-8e8d-ff01308d73d4', 186, 'Aneddoti dal set', 'L''improvvisazione di Richard Dreyfuss e John Goodman', 'Molti dei dialoghi e delle battute ironiche tra il personaggio di Richard Dreyfuss (Pete) e l''amico Al (John Goodman) durante le scene nei bar e sulla pista d''atterraggio sono frutto di una spontanea improvvisazione sul set tra i due attori.', 'Note del backstage e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:45.87752+00:00'),
('b2997e63-b2c9-4534-bffb-eebe87f73059', 168, 'Effetti speciali & Trucco', 'La parrucca storica di Anton Chigurh', 'Il celebre e insolito taglio di capelli di Javier Bardem nel ruolo di Anton Chigurh è stato ideato dai fratelli Coen insieme alla truccatrice Paulie Webb, ispirandosi alle foto d''epoca di frequentatori di bordelli texani degli anni ''60 ritrovate in un libro di ritratti storici.', 'Commento audio del cast e troupe e interviste ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:49.733573+00:00'),
('c1acaf4a-540a-4d87-8a8b-42870fdff77c', 168, 'Aneddoti dal set', 'La difficoltà di Javier Bardem con la guida', 'Javier Bardem non aveva la patente di guida e non sapeva guidare prima delle riprese del film. Ha dovuto imparare rapidamente a guidare la Ford Galaxie d''epoca del suo personaggio durante la produzione, arrivando persino a superare l''esame di guida in Texas nel bel mezzo delle riprese.', 'Intervista promozionale di Javier Bardem per il Late Show con David Letterman', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:49.733573+00:00'),
('f7b03ef0-9040-4d17-9cf0-20db82dd0449', 168, 'Segreti di produzione', 'La moneta iconica del lancio della sorte', 'La moneta da venticinque centesimi (quarter) del 1958 usata da Anton Chigurh per decidere la vita delle sue vittime fu scelta dopo un''accurata ricerca storica sulla disponibilità monetaria del periodo in cui è ambientato il film.', 'Note di produzione ufficiali della Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:49.733573+00:00'),
('8c8585fc-d735-47cb-81ac-65955af74415', 168, 'Casting & Scelte', 'Il rifiuto iniziale di Javier Bardem', 'Quando i fratelli Coen proposero il ruolo a Javier Bardem, l''attore inizialmente rifiutò spiegando che non sapeva parlare inglese, non sapeva guidare e odiava la violenza nei film; i registi risposero semplicemente dicendogli di accettare la parte.', 'Intervista retrospettiva a Javier Bardem per Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:49.733573+00:00'),
('f4ad17d5-5ad1-4fb3-addf-e4a7d40485ca', 168, 'Aneddoti dal set', 'L''infortunio sul set di Josh Brolin', 'Josh Brolin si ruppe la clavicola saltando da un pick-up durante una scena d''azione nei primi giorni di riprese, rischiando di far saltare la sua partecipazione al film prima che la produzione riorganizzasse il calendario per permettergli di guarire parzialmente.', 'Intervista a Josh Brolin nel making-of del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:49.733573+00:00'),
('c2363217-445f-4cb8-be82-0e322af05266', 168, 'Curiosità & Retroscena', 'L''assenza quasi totale di musica orchestrale', 'Il compositore Carter Burwell creò una colonna sonora estremamente minimale, composta quasi interamente da suoni metallici a bassa frequenza e ronzii impercettibili, per mantenere la tensione costante senza coprire i suoni realistici degli ambienti texani.', 'Note di produzione sulla colonna sonora originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:49.733573+00:00'),
('028cf1c9-4139-465e-a333-d5eedd45f1f0', 178, 'Casting & Scelte', 'La prova costume e la parrucca bionda', 'Prima di assegnare la parte di Ann Darrow a Fay Wray, la RKO valutò altre attrici e impose alla Wray di indossare una parrucca bionda per volere di Merian C. Cooper, il quale desiderava una forte contrapposizione cromatica tra la fragilità della donna e la scura pelliccia del gorilla.', 'Autobiografia di Fay Wray ''On the Other Hand''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:14.181975+00:00'),
('0421e30d-31e0-4a03-a034-37c70982b22a', 178, 'Effetti speciali & Trucco', 'Il ruggito combinato di leoni e tigri', 'Il celebre ruggito di King Kong fu realizzato dal tecnico del suono Murray Spivack mescolando i ruggiti di leoni e tigri registrati allo zoo di San Diego, rallentati magneticamente e combinati con la voce dello stesso Spivack che gridava attraverso un tubo di gomma dentro una cassa armonica.', 'Documentario ''The Making of King Kong'' (2005)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:14.181975+00:00'),
('f4753036-01ca-4e2a-9882-a6333fc21006', 178, 'Segreti di produzione', 'L''uso pionieristico della proiezione posteriore', 'Per fare interagire gli attori in carne ed ossa con le miniature e le animazioni in stop-motion, la produzione perfezionò la tecnica della proiezione posteriore (rear projection) e il sistema della ''Dunning process'', che permetteva di combinare la pellicola dal vivo con l''animazione fotogramma per fotogramma.', 'Archivi storici della RKO Radio Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:14.181975+00:00'),
('5f722ca6-8943-468f-aa69-71edb6f00ca3', 178, 'Curiosità & Retroscena', 'Il costo e la salvezza finanziaria della RKO', 'Con un budget stimato di circa 672.000 dollari dell''epoca, una cifra considerevole per i primi anni trenta, il film ottenne un successo di botteghino talmente clamoroso da salvare letteralmente la RKO Radio Pictures dalla bancarotta durante la Grande Depressione.', 'Registri finanziari storici della RKO e box-office report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:14.181975+00:00'),
('03bac143-0540-49f6-a252-4aab0445b596', 178, 'Effetti speciali & Trucco', 'La marionetta principale di alluminio e gommapiuma', 'Willis O''Brien e il suo assistente Marcel Delgado realizzarono i modelli di Kong alti circa 45 e 18 centimetri, costruiti attorno a un''armatura scheletrica in acciaio e piombo, ricoperti di gomma, lattice e vera pelle di coniglio tagliata e incollata pelo per pelo.', 'Libro ''The Making of King Kong'' di Orville Goldner e George E. Turner', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:14.181975+00:00'),
('0bf2b165-67b3-42dd-bc44-a6f0aabbb6f6', 178, 'Citazioni & Easter Egg', 'Il cameo dei registi come mitraglieri', 'Nelle battute finali del film, quando i biplani attaccano Kong sull''Empire State Building, i due registi Merian C. Cooper e Ernest B. Schoedsack decisero di apparire cammeo nei panni del pilota e del mitraglieri che sparano il colpo di grazia al primate.', 'Commento audio storico del DVD Warner Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:14.181975+00:00'),
('bc333548-7ef0-4955-a0cd-034e0a176cfd', 194, 'Casting & Scelte', 'Il compenso posticipato di Al Pacino', 'Al Pacino rifiutò il ruolo di John Milton per ben tre volte prima di accettare, principalmente perché la produzione non riusciva a trovare il budget necessario per coprire le sue richieste economiche. Il progetto si sbloccò quando lo stesso Pacino accettò di tagliare il proprio cachet e di legarlo agli incassi futuri del botteghino pur di interpretare il personaggio.', 'Audio commento del regista Taylor Hackford nell''edizione DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:58.407087+00:00'),
('8d04bcb7-f653-4cba-a453-b215bb09c7ff', 194, 'Aneddoti dal set', 'La preparazione legale di Keanu Reeves', 'Per prepararsi al ruolo dell''avvocato difensore Kevin Lomax, Keanu Reeves trascorse diverse settimane a New York frequentando veri tribunali e studi legali. L''attore osservò il comportamento, la gestualità e le tecniche oratorie di avvocati penalisti di successo per rendere credibili le sue arringhe in aula.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:58.407087+00:00'),
('cd0cc3ba-bbc8-4e97-a3d0-ed6e3651b500', 194, 'Casting & Scelte', 'La rinuncia di Brad Pitt e Edward Norton', 'Prima che Keanu Reeves venisse ufficialmente scritturato per la parte di Kevin Lomax, i dirigenti della Warner Bros. considerarono a lungo Brad Pitt ed Edward Norton per il ruolo da protagonista. Entrambi gli attori rifiutarono l''offerta a causa di conflitti di programmazione con altri progetti cinematografici.', 'Archivi storici di casting di Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:58.407087+00:00'),
('f5deaf51-d20b-4fe9-8a8a-f50c7c9b1ea5', 354, 'Curiosità & Retroscena', 'Il cambio del titolo italiano e internazionale', 'Il film diretto da Taylor Hackford è uscito nelle sale cinematografiche americane con il titolo originale ''Proof of Life'', mentre in Italia è stato distribuito con il titolo ''Rapimento e riscatto''. Questa scelta di localizzazione mirava a esplicitare immediatamente la dinamica centrale della trama incentrata sul negoziatore Terry Thorne.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Admin)', 'IA Verificata', 3, 6, '2026-11-02T17:20:58.654991+00:00'),
('055ac0bd-d217-49e6-8a0d-a65178ad9047', 169, 'Casting & Scelte', 'La scelta iniziale di Anthony Michael Hall', 'Prima che Matthew Modine ottenesse la parte del protagonista Joker, l''attore Anthony Michael Hall era stato fortemente considerato e aveva trattato con Stanley Kubrick per nove mesi. Alla fine le trattative fallirono per disaccordi sulla durata e sui termini del contratto.', 'Interviste retrospettive di Anthony Michael Hall e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:44:55.307077+00:00'),
('c26f3007-273b-495d-aa77-8ad1f5fa83be', 169, 'Segreti di produzione', 'Le palme britanniche e la ricostruzione del Vietnam', 'Poiché Stanley Kubrick non amava viaggiare in aereo, l''intero film fu girato in Inghilterra. Per simulare la vegetazione asiatica, la produzione fece importare centinaia di palme dalla Spagna e le piantò vicino agli studi di Beckton, combinandole con oltre duecento piante di plastica realizzate appositamente.', 'Documentario ''Stanley Kubrick: A Life in Pictures'' e making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:44:55.307077+00:00'),
('47ba5d59-9d7e-4a1d-8f01-92202b4d573e', 169, 'Segreti di produzione', 'La demolizione autorizzata dal governo inglese', 'Le sequenze della città distrutta di Huế furono girate in una vasta area industriale dismessa a Beckton, nei pressi di Londra, destinata alla demolizione. Kubrick ottenne il permesso di far esplodere e distruggere realmente gli edifici preesistenti per ottenere un realismo urbano ineguagliabile.', 'Note di produzione e interviste allo scenografo Anton Furst', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:44:55.307077+00:00'),
('19c72a22-98cd-4454-8ac3-32c37622ffdb', 169, 'Aneddoti dal set', 'L''infortunio di Matthew Modine sul set', 'Durante le riprese, Matthew Modine si ruppe una mano in un incidente non correlato al set, costringendo la produzione a riorganizzare temporaneamente il piano di lavorazione. Inoltre, l''attore rischiò seriamente di ferirsi durante le scene con i blindati M113 a causa della fitta polvere e della scarsa visibilità.', 'Diario di bordo e interviste di Matthew Modine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:44:55.307077+00:00'),
('3362b699-08c2-4c5b-b594-040c0b2cc09a', 169, 'Curiosità & Retroscena', 'Il fucile M14 come estensione del corpo', 'Per garantire la massima autenticità nei movimenti militari, gli attori che interpretavano le reclute passarono settimane a esercitarsi con i fucili M14 sotto la supervisione di consulenti militari. Kubrick pretese che brandissero le armi con assoluta naturalezza, trattandole esattamente come facevano i veri Marines.', 'Commenti audio e contenuti speciali del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:44:55.307077+00:00'),
('bf86d094-1411-43ea-bd18-c135759e9f29', 169, 'Segreti di produzione', 'L''uso dei veri elmetti della guerra del Vietnam', 'La produzione reperì e utilizzò veri elmetti M1 risalenti all''epoca della guerra del Vietnam, acquistati in grandi quantità da surplus militari. Molti dei graffiti, dei simboli di pace e delle scritte ''Born to Kill'' dipinte sopra furono applicati seguendo rigorose fotografie d''archivio del conflitto.', 'Archivio storico dei costumi e interviste ai reparti artistici', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:44:55.307077+00:00'),
('0f097786-d4a4-4e39-b52c-bdd4ff635147', 169, 'Casting & Scelte', 'Il provino di R. Lee Ermey registrato in VHS', 'R. Lee Ermey non fu inizialmente scelto come attore, ma assunto come consulente tecnico. Per dimostrare le sue capacità, realizzò un provino in VHS in cui lanciava insulti per quindici minuti senza mai ripetersi e senza battere ciglio mentre gli venivano tirate arance e racchette da tennis, convincendo immediatamente Kubrick.', 'Making-of ufficiale ''Full Metal Jacket: Between Good and Evil''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:44:55.307077+00:00'),
('67948490-a1dd-473b-8fbe-9a5025d22044', 169, 'Effetti speciali & Trucco', 'La precisione maniacale nell''illuminazione notturna', 'Per la sequenza della battaglia notturna a Huế, Kubrick pretese che l''illuminazione simulasse accuratamente i razzi di segnalazione militari. La troupe impiegò complessi sistemi di cavi e potenti riflettori nascosti per ricreare l''effetto spettrale e tremolante dei flare in cielo.', 'Interviste al direttore della fotografia Douglas Milsome', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:44:55.307077+00:00'),
('8fa787ce-f3ae-4594-b0b0-fc6d7ed111b5', 179, 'Casting & Scelte', 'Il debutto cinematografico di Jessica Lange', 'Jessica Lange fu scelta da Dino De Laurentiis tra centinaia di modelle e attrici emergenti per il ruolo di Dwan, segnando il suo primissimo film in assoluto prima di vincere il Golden Globe come miglior attrice debuttante.', 'Note di produzione ufficiali Paramount / Autobiografia di Dino De Laurentiis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:18.167992+00:00'),
('150bd940-7d0e-4581-8d80-ec80e13ac56c', 179, 'Aneddoti dal set', 'La tensione sul set tra Charles Grodin e il cast', 'Charles Grodin, che interpretava lo spietato dirigente petrolifero Fred Wilson, manteneva spesso un atteggiamento distaccato e polemico anche fuori dalle riprese per rimanere nel personaggio, creando qualche attrito con i colleghi Jeff Bridges e Jessica Lange.', 'Intervista retrospettiva a Jeff Bridges', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:18.167992+00:00'),
('b42d464d-8022-4008-bcbe-3cf8007a76de', 179, 'Segreti di produzione', 'Il gigantesco braccio meccanico di Carlo Rambaldi', 'Per interagire fisicamente con Jessica Lange, Carlo Rambaldi costruì un braccio meccanico idraulico a grandezza naturale del peso di oltre sei tonnellate, manovrato da una complessa squadra di tecnici nascosti fuori campo.', 'Documentario ''The Making of King Kong'' (1976)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:18.167992+00:00'),
('36bbc386-9379-412e-bf34-45ceb1d5d5e3', 179, 'Aneddoti dal set', 'Le difficoltà climatiche a Los Angeles e New York', 'Le riprese delle sequenze finali ambientate a New York furono effettuate in realtà a Los Angeles e in parte a Manhattan durante un''ondata di calore anomala, costringendo la troupe a lavorare con enormi difficoltà logistiche e con Jeff Bridges e Jessica Lange oppressi dai pesanti abiti invernali.', 'Diario di produzione di John Guillermin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:18.167992+00:00'),
('3ad25342-688e-4c38-8c32-eefb831029cf', 179, 'Casting & Scelte', 'La scelta iniziale di Meryl Streep scartata', 'Prima che Jessica Lange ottenesse la parte, Meryl Streep fu valutata per il ruolo di Dwan, ma Dino De Laurentiis la scartò esplicitamente parlando in italiano al figlio, dicendo che era ''troppo brutta'' per interpretare l''oggetto del desiderio del gorilla.', 'Intervista televisiva a Meryl Streep al ''The Graham Norton Show''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:18.167992+00:00'),
('a17ecbf3-4bf7-4553-a89e-55740cfb7070', 179, 'Segreti di produzione', 'I movimenti coreografici di Jessica Lange', 'Poiché gran parte delle scene con il gigantesco gorilla venivano girate con l''attrice che recitava di fronte a uno schermo blu o a un operatore che reggeva un bastone con una croce, Jessica Lange dovette affidarsi al suo passato di ballerina e mimo per rendere credibile il terrore e lo stupore.', 'Commento audio del regista John Guillermin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:18.167992+00:00'),
('379e21c1-d61d-4ae5-8d63-5c2c53c2c8e9', 185, 'Curiosità & Retroscena', 'La genesi del racconto di Lord Dunsany', 'Il soggetto originale del film si basa su un racconto breve e su un''opera teatrale inedita dell''autore anglo-irlandese Lord Dunsany, intitolata ''The Jest of Hahalaba''. René Clair acquistò i diritti e rielaborò la premessa fantastica per adattarla alle dinamiche della commedia brillante hollywoodiana.', 'Note di produzione e archivi storici della United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:41.851178+00:00'),
('4dc071ec-a66c-4e50-a5d2-019d9e9c41fe', 170, 'Casting & Scelte', 'Il rifiuto del ruolo di David Levinson da parte di Matthew Broderick', 'Prima che la parte venisse assegnata a Jeff Goldblum, la produzione offrì il ruolo del tecnico informatico David Levinson a Matthew Broderick. L''attore rifiutò l''offerta, permettendo così a Goldblum di assicurarsi una delle interpretazioni più iconiche della sua carriera.', 'Note di produzione ufficiali e documentario d''archivio della 20th Century Fox', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:01.84296+00:00'),
('87ee987d-804f-46a1-b043-47de93d14d23', 170, 'Casting & Scelte', 'La scelta iniziale di James Spader per il co-protagonista', 'Prima di virare su Jeff Goldblum e Matthew Broderick, i produttori valutarono seriamente James Spader per il ruolo di David Levinson. Spader aveva già lavorato con il co-sceneggiatore e produttore Dean Devlin in ''Stargate'' (1994).', 'Intervista retrospettiva al co-sceneggiatore Dean Devlin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:01.84296+00:00'),
('1e23b12c-907a-465c-a637-7215d72efc78', 170, 'Casting & Scelte', 'Il ritardo nella scelta di Will Smith per motivi di budget', 'I dirigenti della 20th Century Fox inizialmente erano scettici sull''ingaggiare Will Smith come protagonista, temendo che un attore non ancora pienamente testato come primattore in un kolossal d''azione internazionale potesse compromettere il botteghino estero. Roland Emmerich e Dean Devlin lottarono strenuamente per averlo, minacciando di portare il progetto altrove.', 'Audio-commento del regista Roland Emmerich e del produttore Dean Devlin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:01.84296+00:00'),
('34f93f00-836c-43ca-a268-e0ee0c0ba678', 170, 'Segreti di produzione', 'L''uso della vera Area 51 nel film', 'Durante le riprese nel deserto del Nevada, la produzione ottenne il permesso limitato di girare nei pressi di zone di addestramento militare adiacenti alla vera Area 51. L''aeronautica militare statunitense, tuttavia, negò ogni collaborazione formale dopo aver letto la sceneggiatura, rifiutandosi di prestare velivoli o supporto logistico a causa della segretezza legata alla base.', 'Special making-of ''Creating Independence Day'' inserito nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:01.84296+00:00'),
('6198feb7-f182-44ee-a1e0-8961ed54c666', 170, 'Citazioni & Easter Egg', 'Il computer Apple Macintosh e il virus informatico', 'Il piano per sconfiggere gli alieni prevede l''uso di un computer Apple Macintosh del 1996 (precisamente un PowerBook 5300c) per caricare un virus nei sistemi della nave madre. Apple pagò circa un milione di dollari per il product placement, trasformando il computer nella chiave di volta tecnologica dell''intera salvezza terrestre.', 'Archivio storico del marketing cinematografico e rivista Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:01.84296+00:00'),
('f3526508-da88-4d1c-9f0f-608cb4fc1589', 170, 'Citazioni & Easter Egg', 'La vera targa dell''auto del Presidente Whitmore', 'La limousine presidenziale guidata dal personaggio di Bill Pullman mostra una targa specifica con il codice ''ID4'', un evidente e autoironico riferimento al titolo di lavorazione e all''abbreviazione popolare del film.', 'MovieMistakes e analisi visiva dell''edizione speciale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:01.84296+00:00'),
('fd1e4e2b-fdc4-4005-88f5-9b9845e2f450', 170, 'Effetti speciali & Trucco', 'La distruzione della Casa Bianca fatta esplodere in scala', 'La celebre sequenza in cui la Casa Bianca viene disintegrata dal raggio alieno fu realizzata utilizzando un modello in scala dettagliato lungo circa 5 metri. Ci vollero settimane per costruire l''edificio in gesso e legno e la detonazione richiese decine di cariche esplosive piazzate millimetricamente per ottenere l''impatto visivo desiderato in una sola ripresa.', 'Documentario sugli effetti speciali VFX supervisionati da Volker Engel', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:01.84296+00:00'),
('8ac36a36-7a88-41b2-bd40-20846180dfac', 170, 'Citazioni & Easter Egg', 'L''omaggio al film ''La guerra dei mondi'' nel discorso di Bill Pullman', 'Il famosissimo discorso patriottico pronunciato dal presidente Thomas J. Whitmore prima della battaglia finale contiene diverse strutture retoriche che omaggiano la tradizione dei discorsi di guerra cinematografici, in particolare richiamando l''immaginario bellico classico della fantascienza anni ''50 come ''La guerra dei mondi''.', 'Note di sceneggiatura di Roland Emmerich e David Arnold', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:45:01.84296+00:00'),
('b2f23219-fb63-4f74-b05f-85b04751e0b1', 170, 'Casting & Scelte', 'Il cameo vocale di Frank Welker per i versi alieni', 'Il leggendario doppiatore e attore Frank Welker, celebre per aver prestato la voce a innumerevoli mostri e creature cinematografiche (incluso Megatron in Transformers), fu ingaggiato per creare gran parte dei vocalizzi e dei versi emessi dagli alieni durante il film.', 'Crediti di post-produzione e intervista al sound designer Paul Apedkin', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:45:01.84296+00:00'),
('8d0acbb7-3a3a-40cb-841c-a9330c3a5a3f', 170, 'Aneddoti dal set', 'I problemi di calore sul set durante la scena del fuoco nel tunnel', 'Durante le riprese della scena in cui i protagonisti fuggono dall''onda d''urto dell''esplosione nucleare rifugiandosi in un tunnel di manutenzione, le fiamme reali generate dagli stuntmen produssero temperature così elevate da fondere parzialmente le telecamere e causare lievi ustioni da calore ad alcuni membri della troupe tecnica.', 'Diario di bordo della troupe pubblicato nel libro ''The Making of Independence Day''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T15:45:01.84296+00:00'),
('2beaa88e-861d-4b4e-ae2a-9f16a2041302', 180, 'Casting & Scelte', 'Il provino improvvisato di Naomi Watts', 'Naomi Watts non dovette sostenere un provino tradizionale in studio, ma fu convocata da Peter Jackson direttamente sul set di un altro film che stava girando in Australia, dove le chiese di improvvisare una scena drammatica su un terrazzo per valutare la sua chimica e la sua espressività.', 'Documentario ufficiale ''The Making of King Kong'' / Extra DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:22.182733+00:00'),
('eaaf1bc9-6200-4563-9bda-0b009e648ac8', 180, 'Effetti speciali & Trucco', 'La voce originale di Kong fornita da Andy Serkis', 'Per trovare il verso giusto del gorilla, Andy Serkis ha studiato per mesi i comportamenti dei gorilla di montagna nel loro habitat naturale in Ruanda, combinando vocalizzi reali di gorilla con suoni di leoni e tigri rallentati ed elaborati digitalmente.', 'Note di produzione Weta Digital e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:22.182733+00:00'),
('901a09a9-f5f8-407d-9520-83bb0eddd9de', 180, 'Casting & Scelte', 'Il rifiuto originale di George Clooney', 'Prima che Adrien Brody ottenesse la parte dello scrittore Jack Driscoll, la produzione aveva offerto il ruolo principale maschile a George Clooney, il quale declinò l''offerta perché non era convinto della sceneggiatura preliminare dell''epoca.', 'Report di Variety e interviste di casting di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:22.182733+00:00'),
('8b0e6956-9d72-4bfb-9464-a5b31d1cb359', 180, 'Curiosità & Retroscena', 'La rielaborazione del progetto del 1996', 'Peter Jackson aveva iniziato a sviluppare una versione di King Kong per la Universal Pictures già nel 1996, ma il progetto fu accantonato all''ultimo minuto dallo studio per via dell''uscita imminente di film a tema ''dinosauro'' concorrenti come ''Il mondo perduto - Jurassic Park''.', 'Archivio storico di produzione Universal e libri sul cinema di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:22.182733+00:00'),
('0b2067ad-80db-4e66-b2b2-64dc2d09fb2f', 180, 'Citazioni & Easter Egg', 'Il cameo dei figli del regista', 'I figli di Peter Jackson, Billy e Katie Jackson, compaiono in un breve cameo verso l''inizio del film nei panni di due bambini che comprano un giornale per le strade di New York nel 1933.', 'Crediti del film e sezioni extra del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:22.182733+00:00'),
('6574caf3-46f7-4e64-af3d-104cf55207d9', 174, 'Citazioni & Easter Egg', 'L''ispirazione visiva ai classici del muto e del realismo', 'Matteo Rovere ha dichiarato di essersi ispirato non solo ai kolossal storici tradizionali, ma anche alla crudezza visiva di film come ''Apocalypto'' e al cinema neorealista per la messa in scena della lotta per la sopravvivenza.', 'Conferenza stampa di presentazione alla Festa del Cinema di Roma', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:05.349149+00:00'),
('537222fe-f01e-4be1-9716-e26ec4cb5f6c', 189, 'Curiosità & Retroscena', 'L''ispirazione autobiografica di Rob Reiner', 'Il regista Rob Reiner ha ammesso che il film rifletteva il suo stato d''animo e le sue difficoltà sentimentali dell''epoca: reduce da un divorzio e single da dieci anni, era immerso nel mondo degli appuntamenti al buio a Los Angeles.', 'Commento audio del regista nel DVD celebrativo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:50.049218+00:00'),
('185fd15c-2b1e-4e23-8a5f-344ef9a7f457', 189, 'Aneddoti dal set', 'La genesi del celebre orgasmo simulato', 'La celebre scena dell''orgasmo simulato al Katz''s Delicatessen fu un''idea di Meg Ryan e Billy Crystal, suggerita a Nora Ephron per aggiungere un dettaglio divertente e realistico sulla conoscenza intima tra i sessi.', 'Documentario retrospettivo ''How Harry Met Sally...''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:50.049218+00:00'),
('98500d23-0ac1-4d77-8d10-550f7ce07fa7', 189, 'Aneddoti dal set', 'Il ruolo della madre di Rob Reiner', 'La celebre battuta finale della cliente del ristorante (''Quello che prende quello che ha preso lei'') fu pronunciata da Estelle Reiner, madre del regista, presente sul set per un piccolo cameo.', 'Note di produzione ufficiali della Castle Rock Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:50.049218+00:00'),
('589a8508-a511-494a-9f30-f1b5f27a7a5e', 189, 'Casting & Scelte', 'Il rifiuto iniziale di Albert Brooks', 'Prima che Billy Crystal ottenesse la parte, il ruolo di Harry Burns fu offerto ad Albert Brooks, il quale rifiutò il progetto perché riteneva che il personaggio fosse troppo simile a Woody Allen e temeva che il film somigliasse a ''Io e Annie''.', 'Intervista retrospettiva ad Albert Brooks', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:50.049218+00:00'),
('bf2d0e3a-b1a6-4639-8f9f-fd321acb42ec', 189, 'Casting & Scelte', 'Le attrici considerate per il ruolo di Sally', 'Prima che Meg Ryan firmasse per il ruolo di Sally Albright, la produzione prese in considerazione diverse attrici di grande fama tra cui Molly Ringwald, Susan Sarandon, Elizabeth McGovern e Jodie Foster.', 'Archivi di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:50.049218+00:00'),
('3d038433-5e19-468d-9f34-981cec8bbc63', 189, 'Curiosità & Retroscena', 'La scelta del titolo originale', 'Durante le fasi di lavorazione, la produzione prese in considerazione numerosi titoli alternativi, tra cui ''Boy Meets Girl'', ''How They Met'' e ''Chronicles of Harry & Sally'', prima di optare per la struttura della domanda con ''When Harry Met Sally...''.', 'The making of When Harry Met Sally... - featurette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:50.049218+00:00'),
('a5b7fa6e-5b7a-486f-925e-81984c272d7b', 189, 'Aneddoti dal set', 'L''improvvisazione del carrello della spesa', 'Durante la scena in cui Harry e Sally fanno la spesa al supermercato, Billy Crystal improvvisò la battuta in cui usa un carrello come se fosse un''automobile sportiva, cogliendo di sorpresa la troupe.', 'Libro ''I''ll Have What She''s Having: How Nora Ephron''s Three Iconic Films Saved the Romantic Comedy''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:50.049218+00:00'),
('1ab71dda-0476-460f-82fb-5e8937eab891', 204, 'Aneddoti dal set', 'La paura del fuoco di Jennifer Lawrence', 'Durante le riprese delle sequenze in cui Katniss deve muoversi tra edifici in fiamme, Jennifer Lawrence ha dovuto affrontare la sua forte fobia per il fuoco e i fumogeni. Nonostante l''ansia, l''attrice ha insistito per girare la maggior parte delle scene d''azione senza ricorrere a una controfigura.', 'Audio commento del regista Francis Lawrence e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:44.407399+00:00'),
('fa0f22f3-7d75-4b76-b305-d909a3a626ac', 209, 'Segreti di produzione', 'La lingua incomprensibile dei Minions', 'Il cosiddetto ''Minionese'' parlato dai personaggi non è un linguaggio casuale, ma è stato inventato personalmente dai co-registi Pierre Coffin e Chris Renaud, i quali hanno inserito termini presi in prestito da molteplici lingue reali tra cui l''inglese, lo spagnolo, il francese, l''italiano, il filippino e il russo.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:47:02.339766+00:00'),
('f86d720d-9510-4f18-9c86-c09f9280013d', 209, 'Casting & Scelte', 'Il doppiaggio originale di tutti i Minions', 'Nonostante il cast vocale vanti grandi star di Hollywood, il co-regista Pierre Coffin ha doppiato personalmente tutti e ottocento i Minions presenti nel film, modulando la frequenza e la tonalità della propria voce per differenziarli.', 'Commento audio del Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:47:02.339766+00:00'),
('4bc19b73-5522-4474-85d3-eb2bc3eb221f', 209, 'Citazioni & Easter Egg', 'Il riferimento alla regina Elisabetta II', 'La sequenza in cui la regina Elisabetta II viene incoronata dai Minions contiene un omaggio nascosto: la corona rubata dai piccoli protagonisti riprende fedelmente i dettagli e le pietre preziose della vera Corona Imperiale di Stato conservata nella Torre di Londra.', 'Articolo di approfondimento di Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:47:02.339766+00:00'),
('ee7d00fa-ea39-47a3-9684-25ca1eb91ec7', 209, 'Curiosità & Retroscena', 'L''ambientazione temporale del 1968', 'Gli sceneggiatori hanno scelto l''anno 1968 come ambientazione principale per sfruttare l''iconica estetica della Swinging London, della musica rock dell''epoca e dei movimenti culturali che facevano da sfondo alle vicende dei protagonisti.', 'Intervista agli sceneggiatori su Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:47:02.339766+00:00'),
('0433b5fc-779b-437c-b8e6-efd0c7ef11e5', 209, 'Segreti di produzione', 'La musica rock degli anni Sessanta', 'La colonna sonora del film include brani celebri originali del 1968 e degli anni immediatamente precedenti, tra cui canzoni dei The Doors, The Who, The Kinks e Jimi Hendrix, per immergere lo spettatore nell''atmosfera dell''epoca.', 'Credits ufficiali della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:47:02.339766+00:00'),
('9d146500-0f73-4b32-8a77-1be0b2e80c06', 354, 'Segreti di produzione', 'Le reali location tra Europa e Sud America', 'Nonostante l''ambientazione principale della sceneggiatura sia la Colombia, la troupe ha girato gran parte delle sequenze in Ecuador e in diverse location della Repubblica Dominicana, oltre che nei teatri di posa di Los Angeles per le scene in interni.', 'Dichiarazioni del regista Taylor Hackford nel making-of del DVD', TRUE, 'IA (Admin)', 'IA Verificata', 1, 7, '2026-11-02T17:20:58.654991+00:00'),
('085b3d3e-9455-45d9-9f5e-3cc1e618d38a', 354, 'Aneddoti dal set', 'La collaborazione con il consulente di sicurezza', 'Per mantenere il massimo rigore nella rappresentazione delle tecniche di negoziazione e liberazione degli ostaggi, la produzione ha ingaggiato come consulente tecnico Phil Baumann, un ex negoziatore professionista che ha affiancato costantemente Russell Crowe sul set.', 'Intervista a Russell Crowe nelle note stampa del film', TRUE, 'IA (Admin)', 'IA Verificata', 1, 8, '2026-11-02T17:20:58.654991+00:00'),
('1e2ea429-ab24-48b0-a1f2-ff51489961a4', 354, 'Effetti speciali & Trucco', 'La ricostruzione della giungla ecuadoriana', 'Le sequenze ambientate nell''accampamento dei guerriglieri hanno richiesto la costruzione di set complessi in zone remote della foresta ecuadoriana, dove la troupe ha dovuto fronteggiare condizioni climatiche estreme, piogge torrenziali e problemi logistici per il trasporto delle attrezzature cinematografiche.', 'Reportage di produzione della rivista American Cinematographer', TRUE, 'IA (Admin)', 'IA Verificata', 4, 9, '2026-11-02T17:20:58.654991+00:00'),
('6404b24e-9078-4d09-a681-a527379ae3e4', 176, 'Casting & Scelte', 'La trasformazione fisica di Andy Garcia', 'Andy Garcia, scelto per il ruolo dell''agente George Stone (originariamente chiamato Giuseppe Petri), studiò per mesi l''uso delle armi da fuoco e il dialetto italo-americano per risultare credibile accanto a mostri sacri come Connery e De Niro.', 'Note di produzione e interviste promozionali del 1987', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:45:10.145088+00:00'),
('131fdcdb-6495-4e95-8c0b-a66fe80d6684', 176, 'Segreti di produzione', 'I costumi d''epoca firmati da Giorgio Armani', 'Tutti i raffinati abiti indossati da Kevin Costner e dal resto del cast maschile furono disegnati e realizzati appositamente dalla maison di Giorgio Armani, che ricreò fedelmente la moda sartoriale maschile degli anni Trenta.', 'Archivio storico Giorgio Armani e crediti di costume del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:45:10.145088+00:00'),
('bfe8fb73-a7a8-4f04-b71e-fb0da40c4c0c', 176, 'Curiosità & Retroscena', 'La censura della scena dell''orecchio mozzato', 'La primissima versione della scena in cui Al Capone interroga un gangster sul tetto prevedeva una violenza ancora più esplicita con il taglio di un orecchio, che fu ridotta nel montaggio finale per evitare il divieto severo della censura americana.', 'Note di montaggio e registri della MPAA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T15:45:10.145088+00:00'),
('04526a4a-2c07-4ead-a170-710deef21125', 190, 'Casting & Scelte', 'Il provino casuale di Sophie Marceau', 'Sophie Marceau fu notata per caso da un''agenzia di modelle che cercava nuovi volti per la Gaumont; la giovane si presentò ai provini quasi per gioco senza alcuna esperienza di recitazione precedente, sbaragliando la concorrenza di centinaia di ragazze.', 'Documentario retrospettivo Gaumont', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:45:54.145242+00:00'),
('a953e46a-cae1-4a57-be89-cbea9136f825', 190, 'Casting & Scelte', 'La scelta del nome d''arte', 'Nata come Sophie Maupu, l''attrice decise di adottare il cognome d''arte Marceau prendendo spunto da Avenue Marceau, la strada parigina in cui aveva sede l''agenzia che l''aveva scoperta.', 'Autobiografia di Sophie Marceau e interviste storiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:54.145242+00:00'),
('b177e4f7-c07d-4eae-9bb6-9a9cf38eed45', 190, 'Aneddoti dal set', 'La celebre scena delle cuffie', 'La celebre sequenza in cui il personaggio di Mathieu infila le cuffie con la canzone ''Reality'' di Richard Sanderson nelle orecchie di Vic fu girata durante una vera festa scolastica organizzata dalla produzione, per catturare reazioni quanto più naturali possibili tra i giovani comparse.', 'Note di produzione e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:54.145242+00:00'),
('186befce-305a-4da6-b077-909f0da82396', 190, 'Casting & Scelte', 'Il rifiuto iniziale di Claude Brasseur', 'Claude Brasseur, che interpreta il padre di Vic, inizialmente aveva esitato ad accettare la parte temendo di rimanere etichettato in ruoli troppo leggeri, ma cambiò idea dopo aver letto la sceneggiatura che bilanciava bene commedia e dramma familiare.', 'Intervista a Claude Brasseur per Ciné Revue', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:54.145242+00:00'),
('fb6e6b96-0c53-4843-b71a-a035fea09221', 190, 'Curiosità & Retroscena', 'L''ispirazione autobiografica della sceneggiatrice', 'La co-sceneggiatrice Daniela Laurent ha basato molte delle dinamiche giovanili, dei dialoghi e delle ansie adolescenziali del film sulle sue vere esperienze vissute nei licei parigini della fine degli anni ''70.', 'Pressbook ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:54.145242+00:00'),
('66d69705-c102-408f-a74c-e46e05755b3c', 190, 'Curiosità & Retroscena', 'Il successo inaspettato in Europa', 'Il film fu un modesto successo iniziale in Francia, ma esplose clamorosamente in Italia, Germania e Unione Sovietica, dove incassò cifre record e rese Sophie Marceau una delle attrici adolescenti più famose d''Europa.', 'Archivio Box Office C.N.C. Francia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:54.145242+00:00'),
('7582422b-428a-4001-a43d-1679aa53d8fc', 354, 'Casting & Scelte', 'Il ruolo di David Morse come ingegnere civile', 'L''attore David Morse è stato scelto personalmente dal regista Taylor Hackford per interpretare Peter Bowman, l''ingegnere civile rapito, grazie alla sua capacità di trasmettere vulnerabilità e determinazione in ruoli drammatici ad alta tensione.', 'Note di casting ufficiali del film', TRUE, 'IA (Admin)', 'IA Verificata', 2, 10, '2026-11-02T17:20:58.654991+00:00'),
('183a2cbb-dbf0-42e5-810e-b5ee4800317a', 354, 'Casting & Scelte', 'La partecipazione di David Caruso nel cast di supporto', 'David Caruso, noto al grande pubblico per la serie televisiva ''NYPD Blue'' e successivamente per ''CSI: Miami'', ha interpretato il ruolo di Dino nel film, segnando una delle sue importanti apparizioni cinematografiche in produzioni ad alto budget dei primi anni duemila.', 'Crediti ufficiali della pellicola', TRUE, 'IA (Admin)', 'IA Verificata', 3, 11, '2026-11-02T17:20:58.654991+00:00'),
('7fa331ba-bba9-4b1a-864b-cc6c35b5fde0', 372, 'Casting & Scelte', 'Il coinvolgimento di Liam Neeson come Frank Drebin Jr.', 'Seth MacFarlane, produttore del film, ha dichiarato in diverse interviste che Liam Neeson è stata la sua prima e unica scelta per il ruolo di Frank Drebin Jr., citando la capacità dell''attore di mantenere un''espressione seria e impassibile mentre recita battute assurde, una caratteristica fondamentale per lo stile comico di Leslie Nielsen.', 'Intervista ufficiale di Seth MacFarlane per The Hollywood Reporter', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:45:39.43012+00:00'),
('f80b667f-fb11-49c2-affa-5c539868cc92', 372, 'Casting & Scelte', 'Il ritorno di Pamela Anderson nel franchise', 'Pamela Anderson è stata scritturata per il ruolo di Jane Spencer, omaggiando il suo passato nella serie televisiva originale ''Police Squad!'' (Quelli della pallottola spuntata), dove apparve in un episodio del 1982, segnando uno dei suoi primi ruoli accreditati in carriera.', 'Note di produzione Paramount Pictures', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:45:39.43012+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('a59a7506-6714-4ec3-8305-f38dee18352a', 372, 'Curiosità & Retroscena', 'Sviluppo del progetto dopo anni di stallo', 'Il progetto di un reboot di ''The Naked Gun'' è rimasto in fase di sviluppo presso la Paramount per oltre un decennio, con Ed Helms inizialmente associato al ruolo principale nel 2013 prima che il progetto venisse completamente rielaborato da Akiva Schaffer e dal team di sceneggiatori di ''Chip ''n Dale: Rescue Rangers''.', 'Archivio storico Variety e Deadline Hollywood', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:45:39.43012+00:00'),
('703d9511-b65a-4ba7-be09-3f8be5a0a9c7', 372, 'Segreti di produzione', 'La regia di Akiva Schaffer e lo stile visivo', 'Il regista Akiva Schaffer ha scelto di mantenere un approccio visivo fedele ai film originali di Zucker-Abrahams-Zucker, utilizzando inquadrature statiche e una fotografia volutamente piatta per far risaltare le gag visive di sfondo, evitando l''uso eccessivo di movimenti di macchina moderni.', 'Making-of ufficiale: ''The Legacy of Frank Drebin''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:45:39.43012+00:00'),
('437ac48a-1c5f-472d-b829-36f6562393a8', 372, 'Citazioni & Easter Egg', 'Omaggio alla sigla di Police Squad!', 'Il film include una sequenza di apertura che replica fedelmente l''iconica introduzione della serie televisiva del 1982, con il logo della polizia che attraversa lo schermo e i titoli di testa che presentano gag visive assurde, mantenendo intatto il DNA comico del materiale originale.', 'Analisi tecnica della sequenza di apertura (Paramount Home Entertainment)', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-03T17:45:39.43012+00:00'),
('89c43054-1fb1-4f00-9658-f020bb872942', 180, 'Aneddoti dal set', 'La perdita di peso lampo di Adrien Brody', 'Per interpretare al meglio lo sceneggiatore Jack Driscoll visibilmente provato dal viaggio e dalla prigionia sull''isola, Adrien Brody seguì una dieta rigidissima perdendo oltre 10 chili in poche settimane prima dell''inizio delle riprese principali.', 'Interviste promozionali di Adrien Brody per il tour stampa del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:22.182733+00:00'),
('6a9ada45-821f-465d-8fbe-dfc41eb63055', 180, 'Citazioni & Easter Egg', 'Il tributo a Fay Wray nei titoli di coda', 'L''attrice originale Fay Wray, che interpretò Ann Darrow nel film del 1933, fu la prima scelta di Peter Jackson per pronunciare la battuta finale del film del 2005, ma purtroppo l''attrice morì nel 2004 all''età di 96 anni prima che le riprese potessero includere la sua partecipazione.', 'Dichiarazioni ufficiali di Peter Jackson rilasciate alla stampa alla morte dell''attrice', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:22.182733+00:00'),
('9e9cc98a-7949-4722-94ac-a3db2ec50ad4', 196, 'Aneddoti dal set', 'L''incidente di Vernon Wells con il boomerang', 'Durante le riprese, l''attore Emil Minty (che interpretava il Ragazzo Selvaggio) stava imparando a lanciare il vero boomerang affilato di metallo usato nel film; a causa di un errore di calcolo, l''attrezzo sfiorò pericolosamente la testa di Vernon Wells (Wez), rischiando di decapitarlo.', 'Commento audio del regista George Miller e interviste al cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:09.357384+00:00'),
('7e237c2d-df2f-4ae7-b0d5-c213dff9ab7b', 196, 'Casting & Scelte', 'La cicatrice reale di Mel Gibson', 'La vistosa cicatrice che Max ha sulla guancia all''inizio del film non è frutto del trucco di scena, ma il risultato di una rissa da bar realmente avvenuta a Sydney la notte prima che Mel Gibson sostenesse il provino per il primo Mad Max nel 1978.', 'Biografie ufficiali e note di produzione della saga', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:09.357384+00:00'),
('b34ed396-1b29-46e8-97ac-caae8798eb75', 196, 'Segreti di produzione', 'Il budget ridotto e la riutilizzazione dei costumi', 'A causa del budget limitato, la costumista Norma Moriceau dovette recuperare gran parte del materiale per i costumi dei predoni nei negozi di rigattiere locali e nei sex shop di Sydney, utilizzando pelle di canguro e cuoio riciclato per dare l''aspetto sadomaso post-apocalittico.', 'Documentario ''The Road Warrior: Making of Mad Max 2''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:09.357384+00:00'),
('dcb9d431-7726-4971-bc52-3bd18fc93ad3', 196, 'Casting & Scelte', 'La vera identità del cane e il rischio canile', 'Il celebre cane ''Dog'' fu trovato dal dipartimento di casting in un canile di Sydney appena tre giorni prima dell''inizio delle riprese; l''animale era quasi destinato alla soppressione e fu addestrato rapidamente a non spaventarsi per i rumori degli spari e dei motori ruggenti.', 'Archivi di produzione Warner Bros e note del regista George Miller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:09.357384+00:00'),
('8d69867f-d397-4015-988e-0b5809c22d91', 196, 'Aneddoti dal set', 'Le costole rotte dello stuntman', 'Durante la spettacolare sequenza dell''assalto alla cisterna in movimento, lo stuntman Guy Norris subì una violenta caduta dal camion in corsa dopo essere stato colpito da una finta freccia, rimediando la frattura di diverse costole ma insistendo per rimanere sul set.', 'Documentario ''Assembling the Wasteland'' e registri della troupe di stunt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:09.357384+00:00'),
('65dc7b08-9213-47b5-b1db-6dd0f3e1bf20', 196, 'Citazioni & Easter Egg', 'Il cameo del regista George Miller alla guida', 'Il regista George Miller, che possiede la licenza per guidare ambulanze, appare brevemente in una delle sequenze iniziali alla guida di uno dei veicoli dei predoni in corsa prima di essere coinvolto in uno schianto simulato.', 'Curiosità ufficiali certificate da IMDb e commento del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:09.357384+00:00'),
('2ee4395f-8857-4924-ac56-076803d3c1ce', 196, 'Effetti speciali & Trucco', 'L''uso innovativo della cinepresa Panavision', 'Per girare le frenetiche scene d''inseguimento nel deserto australiano, il direttore della fotografia Dean Semler montò una speciale cinepresa Panavision su un braccio meccanico fissato a un fuoristrada stabilizzato, inventando nuove tecniche di ripresa in movimento poi emulate in tutto il cinema d''azione.', 'American Cinematographer, retrospettiva su Mad Max 2', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:09.357384+00:00'),
('be5b4df3-7099-40d5-a209-35a4cd99cdf3', 203, 'Casting & Scelte', 'La commozione di Philip Seymour Hoffman', 'Philip Seymour Hoffman accettò il ruolo di Plutarch Heavensbee senza nemmeno leggere la sceneggiatura, spinto esclusivamente dalla sua ammirazione per il primo film e dalla stima artistica verso il premio Oscar Jennifer Lawrence.', 'Intervista ufficiale al junket stampa del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:41.333341+00:00'),
('c7f0cb95-9024-4d90-add9-3e173be45974', 203, 'Segreti di produzione', 'Il primo film IMAX parziale della storia', 'Il regista Francis Lawrence ha girato l''intera sequenza dell''ingresso di Katniss nell''arena utilizzando cineprese IMAX native, segnando la prima volta in cui un lungometraggio a soggetti ha sfruttato questo formato cinematografico gigante esclusivamente per una specifica sezione centrale della narrazione.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:41.333341+00:00'),
('768092bc-2b84-45aa-9322-af03b1408359', 203, 'Aneddoti dal set', 'Il salto della corda sul set tra le riprese', 'Per ingannare la noia e la tensione durante le lunghe ore di attesa nelle pause delle riprese nella giungla hawaiana, Jennifer Lawrence e Josh Hutcherson organizzavano spesso competizioni di salto della corda in costume di scena.', 'Commento audio del regista e del produttore nel Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:41.333341+00:00'),
('0ce34007-a4f3-491a-821f-dcd9f4f827aa', 203, 'Aneddoti dal set', 'L''orecchio ferito di Jennifer Lawrence', 'Durante le riprese delle scene sott''acqua nell''arena tropicale, Jennifer Lawrence si ruppe inavvertitamente il timpano a causa della pressione dell''acqua, costringendo la troupe a interrompere temporaneamente i ciak per consentire cure mediche immediate.', 'Intervista televisiva al David Letterman Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:41.333341+00:00'),
('63ce3f42-6f8f-4109-8cba-c571d454c505', 203, 'Effetti speciali & Trucco', 'Il vero abito da sposa di Sposa Katniss', 'L''abito da sposa indossato da Katniss durante l''intervista televisiva con Caesar Flickerman è stato disegnato dall''indonesiano Tex Saverio ed era interamente tempestato di cristalli Swarovski cuciti a mano, pesando quasi quindici chili.', 'Featurette ufficiale sui costumi del making-of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:41.333341+00:00'),
('361313a7-65f7-445a-b1a3-97b7fb4a8f87', 203, 'Aneddoti dal set', 'La cicatrice di Jennifer Lawrence sul set', 'Mentre girava la scena in cui Katniss colpisce violentemente Gloss sul campo di forza dell''arena, Jennifer Lawrence colpì per errore l''attore Alan Ritchson in faccia con una lanterna di plastica, procurandogli un piccolo taglio e guadagnandosi un momento di grande imbarazzo generale.', 'Intervista di Alan Ritchson per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:41.333341+00:00'),
('1964e344-0f3b-4672-8bd1-68cb4469a590', 203, 'Curiosità & Retroscena', 'La scena tagliata del treno con Stephanie Leigh Schlund', 'Nel montaggio originale era presente un''estesa sequenza a bordo del treno in cui Cashmere e Gloss discutevano delle loro precedenti vittorie ai giochi con i Distretti, scena successivamente tagliata per mantenere il ritmo serrato del primo atto.', 'Scene eliminate presenti nei contenuti speciali dell''edizione Home Video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:41.333341+00:00'),
('10bc2018-87dd-4634-befa-6a6f6692584b', 184, 'Segreti di produzione', 'La realizzazione fisica dell''elmo di Dáin Piediferro', 'L''armatura e l''elmo imponenti indossati da Billy Connolly nel ruolo di Dáin Piediferro sono stati inizialmente scolpiti digitalmente e poi stampati in 3D con resine ultraleggere, per permettere all''attore di muoversi agilmente nonostante i problemi di salute e l''età avanzata.', 'Weta Workshop Chronicles: Art & Design of The Hobbit', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:45:38.556572+00:00'),
('2ac1105a-0ea1-404a-bd7d-0a7766375d44', 184, 'Aneddoti dal set', 'Billy Connolly e la doppia personalità del maiale da guerra', 'Nelle scene in cui Dáin cavalca il grosso cinghiale da battaglia, Billy Connolly non era in sella a un animale reale né meccanico, ma a uno sgabello idraulico rivestito di green screen, costringendo l''attore a mimare i sobbalzi con grande ironia tra una ripresa e l''altra per far ridere la troupe.', 'Commento audio del cast e troupe nell''edizione Blu-ray estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:45:38.556572+00:00'),
('307bbd6c-92b8-41fa-b635-1e0526f231ff', 184, 'Casting & Scelte', 'Il ritorno di Christopher Lee e la sua registrazione a distanza', 'Data l''avanzata età e le difficoltà di viaggio nel 2013, Sir Christopher Lee (Saruman) ha registrato tutte le sue battute e sequenze in un teatro di posa appositamente allestito a Londra, lontano dalla troupe principale in Nuova Zelanda, e successivamente integrato digitalmente nelle scene di Dol Guldur.', 'Note di produzione ufficiali della Warner Bros. Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:45:38.556572+00:00'),
('7747d877-9a88-4eb6-bfbc-b60853f316d9', 199, 'Segreti di produzione', 'La ripresa del montaggio parallelo durante la pandemia', 'George Miller ha supervisionato gran parte della pre-produzione e del montaggio preliminare di Furiosa da remoto e in parallelo con la post-produzione di Three Thousand Years of Longing, sfruttando i ritardi imposti dalle restrizioni sanitarie globali per perfezionare gli storyboard animati.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:24.051804+00:00'),
('497a897e-fc39-44eb-b45b-027cab1d11c3', 199, 'Effetti speciali & Trucco', 'La cicatrice facciale meccanica di Dementus', 'Il truccatore prostetico Leslie Vanderwalt ha ideato per Chris Hemsworth una complessa cicatrice sul labbro e sul mento di Dementus, realizzata con materiali siliconici avanzati che resistevano alle tempeste di sabbia e al sudore durante le riprese nel deserto del New South Wales.', 'Featurette sul make-up ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:24.051804+00:00'),
('90b0ab1a-944a-45c2-900c-eb8675edebb2', 199, 'Citazioni & Easter Egg', 'L''ispirazione storica per il carro armato a pale', 'Il gigantesco veicolo da guerra corazzato guidato da Dementus, noto come la ''Chariot'', è stato ispirato sia dai progetti dei carri armati della Prima guerra mondiale sia dai trattori cingolati modificati utilizzati nei cantieri minerari australiani degli anni ''20.', 'Artbook ufficiale ''The Art of Furiosa''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:24.051804+00:00'),
('9f0a4f11-5d86-4384-92eb-d461edbc6869', 199, 'Casting & Scelte', 'Il ruolo di Alyla Browne e la somiglianza con Anya Taylor-Joy', 'Per trovare la giovane Furiosa, George Miller ha visionato decine di giovani attrici prima di scegliere Alyla Browne, imponendo che la somiglianza fisica non fosse solo sommaria ma che la giovane attrice replicasse esattamente i movimenti oculari e la postura di Anya Taylor-Joy.', 'Intervista al regista su Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:24.051804+00:00'),
('a270fe54-bfd2-4aaf-8526-2302808eabe7', 199, 'Citazioni & Easter Egg', 'Il tributo sonoro ai motori originali del 1979', 'Il supervisore al montaggio sonoro Mark Mangini ha inserito nel mix audio di alcune sequenze di inseguimento dei campioni audio originali registrati per il film capostipite Mad Max del 1979, rimasterizzati digitalmente per rendere omaggio alla pellicola d''esordio di George Miller.', 'SoundWorks Collection Featurette', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:24.051804+00:00'),
('48623024-19d4-47a0-b3ce-b15458f31720', 263, 'Casting & Scelte', 'La scelta di Michael Sarnoski alla regia', 'Dopo il successo di critica ottenuto con ''Pig'' (2021) e la direzione del kolossal ''A Quiet Place: Day One'' (2024), il regista Michael Sarnoski è stato ingaggiato per dirigere questa nuova e cupa rilettura del mito di Robin Hood, incentrata su toni realistici e crudi.', 'Comunicati di produzione ufficiali Deadline e Variety', TRUE, 'IA (Admin)', 'IA Verificata', 3, 1, '2026-11-02T17:21:17.999641+00:00'),
('96ef74c0-399d-4a8c-ab4d-00492276b69e', 263, 'Casting & Scelte', 'Hugh Jackman e Jodie Comer nei ruoli principali', 'Il progetto si distingue per la prestigiosa accoppiata artistica formata da Hugh Jackman, scelto per interpretare una versione inedita e disillusa del celebre fuorilegge, e Jodie Comer, confermata nel ruolo della co-protagonista.', 'Annunci di casting ufficiali Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 1, 2, '2026-11-02T17:21:17.999641+00:00'),
('f0edcc29-97c0-4a4a-9aa5-18182a137cba', 263, 'Casting & Scelte', 'Un cast di supporto internazionale di alto profilo', 'Il cast si avvolge della partecipazione di attori affermati come Bill Skarsgård e Murray Bartlett, affiancati da giovani promesse come Noah Jupe, Jade Croot e Faith Delaney per dare spessore al dramma corale.', 'Note di produzione ufficiali del film', TRUE, 'IA (Admin)', 'IA Verificata', 2, 3, '2026-11-02T17:21:17.999641+00:00'),
('2030b072-20e9-4925-b404-fd64921eba1c', 263, 'Segreti di produzione', 'Una riscrittura radicale del mito classico', 'A differenza delle trasposizioni cinematografiche tradizionali che dipingono Robin Hood come un nobile paladino della giustizia, la sceneggiatura di questo film adotta un approccio revisionista, descrivendolo come un feroce bandito coinvolto in sanguinarie scorribande.', 'Sinossi ufficiale e note di regia di Michael Sarnoski', TRUE, 'IA (Admin)', 'IA Verificata', 4, 4, '2026-11-02T17:21:17.999641+00:00'),
('32e229e3-c83c-43ad-b280-2758a23f0de7', 373, 'Casting & Scelte', 'La genesi del progetto con A24', 'Il film è stato prodotto e finanziato da A24, che ha scelto di puntare sull''esordio alla regia di lungometraggio di Alex Scharfman, il quale ha anche firmato la sceneggiatura originale basata su un concept surreale e satirico.', 'Annuncio ufficiale di produzione Deadline / A24', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-03T17:46:20.90907+00:00'),
('4959fe66-9999-4ee2-a69a-900641599813', 373, 'Segreti di produzione', 'Il coinvolgimento di Ari Aster alla produzione', 'Il regista Ari Aster e Lars Knudsen hanno partecipato in qualità di produttori attraverso la loro casa di produzione Square Peg, confermando la linea autoriale vicina a un horror-commedia grottesco e tagliente.', 'Note di produzione ufficiali A24', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-03T17:46:20.90907+00:00'),
('ca417dad-44ea-4d5e-b52a-c4d1479f33f2', 373, 'Casting & Scelte', 'La co-protagonista Jenna Ortega accanto a Paul Rudd', 'Jenna Ortega è stata ingaggiata per interpretare Ridley, la figlia del personaggio di Paul Rudd, consolidando la sua presenza nel cinema di genere tra horror e dark comedy dopo il successo di Wednesday e Scream.', 'Comunicato casting Hollywood Reporter', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-03T17:46:20.90907+00:00'),
('c7c59012-bb0c-41fd-b7b2-7a630c834454', 373, 'Curiosità & Retroscena', 'Location delle riprese in Ungheria', 'Le riprese principali del film si sono svolte in Ungheria, sfruttando le agevolazioni fiscali locali e le maestranze tecniche della zona per ricreare la sfarzosa tenuta isolata della famiglia Leopold.', 'Report di produzione e schede tecniche ungheresi', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-03T17:46:20.90907+00:00'),
('eafc8cb2-5db5-4b44-80a8-eb028cae13a4', 185, 'Segreti di produzione', 'La produzione indipendente di Arnold Pressburger', 'Il film fu prodotto da Arnold Pressburger per la sua omonima casa di produzione indipendente, distribuito poi dalla United Artists. Questa struttura permise a René Clair di mantenere un elevato controllo creativo sulla sceneggiatura, scritta dallo stesso regista insieme a Dudley Nichols.', 'Dossier storiografici sulla United Artists negli anni ''40', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:45:41.851178+00:00'),
('3f660ccd-9e9b-4f2d-98f9-1109b5278e39', 185, 'Casting & Scelte', 'La transizione di Dick Powell dal musical al noir/commedia', 'Prima di interpretare il giornalista Larry Stevens in questo film e l''anno successivo in ''Murder, My Sweet'' (La chiave di vetro), Dick Powell era noto quasi esclusivamente come attore di gradevoli musical Warner Bros. Questo ruolo rappresentò un passaggio cruciale per dimostrare la sua versatilità drammatica e brillante.', 'Biografia ufficiale di Dick Powell e retrospettive storiografiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:45:41.851178+00:00'),
('23ef1a71-513b-4e71-ab11-1b3a874b1d52', 185, 'Aneddoti dal set', 'La chimica sul set tra Powell e Linda Darnell', 'Dick Powell e Linda Darnell instaurarono un''eccellente sintonia professionale durante le riprese, facilitando le scene corali e i momenti di comicità romantica. La Darnell, all''epoca ventenne e sotto contratto con la 20th Century Fox, fu concessa in prestito alla produzione indipendente di Pressburger.', 'Cronache dei set cinematografici di Hollywood del 1943', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:41.851178+00:00'),
('59f11250-2773-4876-bba1-09932d1e0d47', 195, 'Casting & Scelte', 'Il casting casuale di Mel Gibson', 'Mel Gibson non aveva intenzione di fare un provino per la parte principale; aveva accompagnato al casting l''amico e collega attore Steve Bisley. Avendo subito una rissa la sera prima ed essendo pieno di lividi e graffi, i realizzatori lo trovarono perfetto per il ruolo del ''guerriero della strada'' e lo convocarono per le prove il lunedì successivo.', 'Documentario ufficiale ''Birth of a Hero'' e interviste d''archivio a George Miller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:04.371051+00:00'),
('28aef978-ee51-440d-960e-7fd94b597a49', 195, 'Aneddoti dal set', 'Il braccio gessato di Mel Gibson', 'Poco prima dell''inizio delle riprese, Mel Gibson fu coinvolto in una rissa da bar a Melbourne per difendere un uomo, riportando gravi fratture al volto e al braccio. Poiché le riprese non potevano essere rimandate, la produzione organizzò il piano di lavoro girando prima le scene non d''azione e mascherando il gesso con costumi strategici e inquadrature angolate.', 'Note di produzione e commento audio del regista George Miller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:04.371051+00:00'),
('97a3faea-4b5b-49bc-a8fe-cd73a9899ef9', 195, 'Casting & Scelte', 'La vera professione di Hugh Keays-Byrne', 'L''attore Hugh Keays-Byrne, che interpreta il memorabile cattivo Toecutter, sul set era così immerso nel personaggio e nella follia della banda di motociclisti da spaventare la troupe. Curiosamente, nella vita reale era un rispettato attore teatrale shakespeariano membro della Royal Shakespeare Company.', 'Backstage ufficiale e interviste al cast nel cofanetto DVD antologico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:04.371051+00:00'),
('0d29bee2-905b-4772-9660-1bb1413715e1', 195, 'Aneddoti dal set', 'Il vero motoclub australiano sul set', 'Gran parte della banda di motociclisti nel film non era composta da attori professionisti, ma da membri del famigerato motoclub australiano Vigilantes. Durante le riprese vivevano insieme alla troupe in campeggi di fortuna, arrivando sul set ogni mattina direttamente in moto con i loro costumi di scena.', 'Making-of documentario ''Mad Max: The Filmumentary''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:04.371051+00:00'),
('f69965a2-b1b9-439f-b44d-8aa1284a7abf', 195, 'Segreti di produzione', 'L''uso estensivo delle lenti grandangolari', 'Il direttore della fotografia David Eggby e George Miller decisero di girare gran lunga parte del film utilizzando lenti grandangolari, in particolare la focale da 35mm e talvolta da 28mm. Questa scelta tecnica accentuava la distorsione prospettica e dava un senso costante di velocità e instabilità visiva durante le sequenze di guida.', 'American Cinematographer, articolo tecnico d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:04.371051+00:00'),
('985b1686-f812-49f1-a46d-e15b290d972b', 195, 'Aneddoti dal set', 'La finta troupe cinematografica', 'Non avendo i permessi ufficiali per girare su molte autostrade pubbliche dello Stato del Victoria, la troupe adottava tattiche di guerriglia cinematografica. Agivano rapidamente bloccando il traffico con la scusa di essere una troupe televisiva locale o una finta troupe documentaristica prima che arrivasse la polizia vera.', 'Libro biografico ''George Miller: The Filmmaker''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:04.371051+00:00'),
('c2ef5192-b984-416e-93e3-5e00ad5d5f3e', 195, 'Segreti di produzione', 'Il montaggio in una camera da letto', 'Poiché il budget iniziale era estremamente risicato, il montaggio del film non avvenne in uno studio professionale ma fu eseguito da George Miller e dal montatore Cliff Hayes direttamente nella camera da letto della casa della madre di Miller a Melbourne, utilizzando una moviola autocostruita.', 'Intervista retrospettiva a Cliff Hayes e note storiche del NFSA (National Film and Sound Archive australiano)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:04.371051+00:00'),
('b9469f37-f7f7-417d-83f4-9268b7f2dbde', 195, 'Segreti di produzione', 'Il doppiaggio quasi totale in post-produzione', 'A causa del rumore assordante dei motori, del vento e dei macchinari sul set, l''audio in presa diretta era quasi inutilizzabile. Circa il 90% dei dialoghi presenti nella versione cinematografica finale è stato interamente ridoppiato in studio dagli attori durante la fase di post-produzione.', 'Note di montaggio del suono e documentario d''archivio sul mix audio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:46:04.371051+00:00'),
('5d3834b3-c1e3-447e-9075-e742c9308234', 195, 'Citazioni & Easter Egg', 'Il cameo del regista come stuntman non accreditato', 'Il co-sceneggiatore e regista George Miller appare brevemente in una sequenza del film come stuntman di supporto e comparsa, guidando uno dei veicoli di minor importanza coinvolti negli inseguimenti per sopperire alla carenza di stuntmen professionisti disponibili.', 'Trivia ufficiale IMDb verificato dal team di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:46:04.371051+00:00'),
('9c50b8c1-341a-4477-8ac6-8c1f5b79094f', 200, 'Curiosità & Retroscena', 'La genesi dell''articolo di rivista', 'Il film è tratto da un articolo del 1972 apparso su ''Life'' intitolato ''The Boys in the Bank'', scritto da P.F. Kluge e Thomas Moore, che raccontava la vera rapina compiuta da John Wojtowicz e Salvatore Naturile nella filiale della Chase Manhattan Bank a Brooklyn.', 'Note di produzione e archivio della rivista Life', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:28.1212+00:00'),
('6853a336-d939-41bf-8652-e0e4f145f658', 200, 'Aneddoti dal set', 'L''ispirazione per il coro ''Attica!''', 'Il celebre grido ''Attica!'' urlato da Al Pacino per provocare la polizia fu un''improvvisazione basata su un suggerimento dello sceneggiatore Frank Pierson, in riferimento alla sanguinosa rivolta del carcere di Attica avvenuta nel 1971.', 'Commento audio del regista Sidney Lumet', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:28.1212+00:00'),
('b46dfd57-b89f-432b-a181-8158d4340996', 200, 'Segreti di produzione', 'L''assenza di colonne sonore tradizionali', 'Sidney Lumet decise di non utilizzare alcuna colonna sonora extradiegetica per accentuare il realismo documentaristico della vicenda, ad eccezione del brano ''A Suitable Boy'' trasmesso dalla radio all''inizio della pellicola.', 'Note di regia ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:28.1212+00:00'),
('5409512e-a391-462a-8c93-0fd61a097880', 186, 'Segreti di produzione', 'L''addestramento dei piloti acrobatici', 'Per girare le spettacolari e pericolose manovre di sgancio dell''acqua sulle fiamme, la produzione ha ingaggiato i migliori piloti acrobatici del mondo, operando sotto la stretta supervisione della Federal Aviation Administration (FAA) per evitare incidenti.', 'Report tecnico di produzione e riviste di settore aeronautico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:45.87752+00:00'),
('618edacc-9f30-4eb5-980a-7de7d238c2d2', 186, 'Aneddoti dal set', 'La gestione degli incendi boschivi controllati', 'Le sequenze degli incendi in foresta non sono state realizzate interamente in CGI; la troupe ha dovuto coordinarsi con i servizi forestali statali per gestire veri fuochi controllati in aree sicure del Montana, affrontando temperature elevate e fumo denso.', 'Diario di lavorazione della troupe e documentari sul set', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:45.87752+00:00'),
('3b1ae9b9-0cc2-4a7d-b6d0-51a649979888', 198, 'Aneddoti dal set', 'La tensione reale tra Tom Hardy e Charlize Theron', 'Durante le difficili riprese nel deserto della Namibia, le estreme condizioni di lavoro e lo stress generale causarono forti attriti tra i due protagonisti Tom Hardy e Charlize Theron. La stessa Theron ha ammesso in seguito che la loro reciproca tensione sul set rispecchiava perfettamente l''iniziale ostilità tra i loro personaggi, Max e Furiosa.', 'Intervista ufficiale di Charlize Theron per il New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:20.073552+00:00'),
('df2a2f38-c283-4612-81ca-a512c57261e9', 198, 'Casting & Scelte', 'L''assenza quasi totale di una sceneggiatura tradizionale', 'George Miller ha diretto il film senza una sceneggiatura classica basata sui dialoghi, affidandosi invece a un immane storyboard composto da circa 3.500 pannelli illustrati realizzati dall''artista Comic Book Brendan McCarthy e Peter Pound, concependo l''opera come un inseguimento ininterrotto lungo 120 minuti.', 'Note di produzione ufficiali Warner Bros. e commento audio del regista', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:20.073552+00:00'),
('847c5a8b-96a8-4e2b-ac6a-90b0ff39fb6c', 198, 'Casting & Scelte', 'Il ritorno di Hugh Keays-Byrne nel franchise', 'L''attore Hugh Keays-Byrne, che veste i panni del principale antagonista Immortan Joe, aveva già interpretato un iconico cattivo nel primissimo film della saga ''Interceptor'' (Mad Max) del 1979, dove interpretava il malvagio Toecutter.', 'Credits ufficiali e press kit del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:20.073552+00:00'),
('126fdebe-d05f-4b55-a7ee-662a7e662112', 198, 'Curiosità & Retroscena', 'La consulenza d''autore di Eve Ensler', 'Per trattare con estremo realismo e rispetto il tema dello sfruttamento delle donne nel mondo post-apocalittico, George Miller ha assunto come consulente Eve Ensler, celebre drammaturga e attivista fondatrice di V-Day e autrice de ''I monologhi della vagina''.', 'Intervista a George Miller e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:20.073552+00:00'),
('55c90b46-efb7-440b-bdc5-47f0ee2b81d5', 198, 'Effetti speciali & Trucco', 'L''uso massiccio di effetti visivi digitali nascosti', 'Nonostante la forte impronta artigianale e l''uso di veri stunt, il film contiene oltre 2.000 inquadrature con effetti digitali curati dallo studio di post-produzione Iloura. La maggior parte dei VFX è stata utilizzata per rimuovere i cavi di sicurezza degli stuntmen, inserire il paesaggio desertico della Namibia e ricreare digitalmente il cielo o la tempesta di sabbia.', 'Articolo di approfondimento tecnico su Cinefex', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:20.073552+00:00'),
('af5bf331-5699-49be-a104-b38c9167861b', 198, 'Segreti di produzione', 'Il chitarrista cieco con la chitarra lanciafiamme', 'Il musicista mascherato che suona la chitarra elettrica sputafuoco sul ''Doof Wagon'' (interpretato dal musicista e attore australiano iOTA) suonava realmente uno strumento funzionante collegato a bombole di gas propano, e il peso della sola chitarra pesava circa 60 chilogrammi.', 'Making-of ufficiale ''The Fury Road: Crash and Burn''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:20.073552+00:00'),
('4a814c6a-922f-48b1-b2d4-898efca25f4d', 198, 'Casting & Scelte', 'La scelta iniziale di Heath Ledger', 'Nei primi anni di sviluppo del film, intorno al 2007, George Miller aveva seriamente considerato e incontrato Heath Ledger per il ruolo principale di Max Rockatansky, prima della tragica scomparsa dell''attore avvenuta nel gennaio del 2008.', 'Dichiarazioni di George Miller a Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:20.073552+00:00'),
('998f3f42-f862-45e8-9710-7fa98c7b00c7', 198, 'Aneddoti dal set', 'Il regalo d''addio di Tom Hardy a Charlize Theron', 'Alla fine delle estenuanti riprese in Namibia, superati i dissapori iniziali, Tom Hardy ha regalato a Charlize Theron un''autocisterna giocattolo in miniatura sulla quale aveva inciso personalmente la scritta: ''You are an absolute nightmare, but you are also fucking awesome. Love, Tom''.', 'Intervista di Charlize Theron a Esquire', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:46:20.073552+00:00'),
('86af3e8f-5c61-4814-b4aa-e8021fd0455b', 198, 'Effetti speciali & Trucco', 'La genesi del make-up dei War Boys', 'Il caratteristico trucco bianco gesso dei War Boys fu ideato dalla capo truccatrice Lesley Vanderwalt utilizzando una speciale vernice minerale opaca in grado di resistere sia al forte sudore provocato dal clima desertico che alle sequenze d''azione più violente.', 'Documentario dietro le quinte ''The Making of Mad Max: Fury Road''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:46:20.073552+00:00'),
('60b7f269-280f-457f-bd18-47e782335ff4', 273, 'Casting & Scelte', 'La genesi del personaggio di Claudia', 'Prima che Paola Cortellesi venisse confermata nel ruolo della protagonista eponima, la produzione valutò diverse attrici del panorama comico italiano per trovare il giusto equilibrio di forza e ironia in grado di reggere il confronto con la comicità surreale del trio.', 'Intervista al regista Massimo Venier nelle note di produzione Medusa Film', TRUE, 'IA (Admin)', 'IA Verificata', 5, 4, '2026-11-02T17:21:33.241734+00:00'),
('8234bb4c-3e03-497d-8846-3b456bb85c5d', 273, 'Aneddoti dal set', 'Le difficoltà logistiche del taxi di Aldo', 'Le sequenze in cui Aldo interpreta il tassista innamorato hanno richiesto l''utilizzo di un vero taxi milanese attrezzato con macchine da presa montate sul cofano, causando non pochi rallentamenti al traffico reale durante le riprese in esterna a Milano.', 'Making-of ufficiale incluso nel DVD Medusa Home Entertainment', TRUE, 'IA (Admin)', 'IA Verificata', 3, 5, '2026-11-02T17:21:33.241734+00:00'),
('f7b4f946-b83b-4a40-a83e-68bd49a86324', 273, 'Segreti di produzione', 'Il ritorno alla regia di Massimo Venier senza Morgan Bertacca', 'Questo film rappresenta il primo lungometraggio in cui Massimo Venier dirige il trio comico da solo, senza la co-regia di Aldo, Giovanni e Giacomo o l''apporto registico dei precedenti film, segnando una transizione nello stile visivo.', 'Dati di produzione ufficiali e schede tecniche SIAE', TRUE, 'IA (Admin)', 'IA Verificata', 5, 6, '2026-11-02T17:21:33.241734+00:00'),
('97a3388a-95d9-4d68-939a-b15bed9fb7b3', 273, 'Casting & Scelte', 'La partecipazione di Ottavia Piccolo', 'La presenza di Ottavia Piccolo, attrice di grande spessore teatrale e cinematografico drammatico, fu voluta per dare un ancoraggio di realismo e credibilità emotiva alle dinamiche di coppia e familiari che fanno da contrappunto alla commedia.', 'Note di edizione e pressbook del film', TRUE, 'IA (Admin)', 'IA Verificata', 2, 7, '2026-11-02T17:21:33.241734+00:00'),
('a69e933c-3ee5-4e89-bb24-d64a8770f0c0', 273, 'Effetti speciali & Trucco', 'La cura per gli interni borghesi', 'Gli ambienti domestici dei protagonisti, in particolare il salotto di Giovanni ossessionato da ''Passaparola'', sono stati meticolosamente arredati dalla scenografa per riflettere la mania di controllo e la ripetitività della vita del personaggio.', 'Intervista alla scenografa nel backstage ufficiale', TRUE, 'IA (Admin)', 'IA Verificata', 1, 8, '2026-11-02T17:21:33.241734+00:00'),
('3e2463b4-30e5-4fec-9749-d33b3523e0dc', 194, 'Effetti speciali & Trucco', 'Il trucco prostetico di Al Pacino per il finale', 'Nella sequenza finale in cui John Milton si trasforma e mostra la sua vera natura demoniaca, il truccatore premio Oscar Rick Baker impiegò protesi in lattice avanzate e animatronics per modificare i tratti del viso di Al Pacino. La lavorazione richiese oltre quattro ore di seduta di trucco per ogni giorno di ripresa della scena.', 'Documentario ''The Making of The Devil''s Advocate'' incluso nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:45:58.407087+00:00'),
('d301426e-e1e0-4c58-9e8d-4babd81222d5', 194, 'Segreti di produzione', 'L''ispirazione visiva per l''attico di Milton', 'L''architettura e gli interni lussuosi dell''attico di John Milton furono progettati dallo scenografo Stuart Wurtzel traendo ispirazione diretta dalle opere di M.C. Escher e dalle cattedrali gotiche. Lo scopo era trasmettere un senso di labirintica oppressione e grandiosità luciferina attraverso scale geometricamente impossibili.', 'Intervista allo scenografo Stuart Wurtzel su American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:45:58.407087+00:00'),
('5f930036-808c-4284-8d17-1b41169f5cf0', 194, 'Citazioni & Easter Egg', 'Il nome in codice dei personaggi', 'Il nome del personaggio interpretato da Al Pacino, John Milton, è un chiaro omaggio al celebre poeta inglese autore del ''Paradiso Perduto'', poema epico incentrato proprio sulla figura di Lucifero e sulla caduta degli angeli ribelli. Molti dei dialoghi di Milton contengono sottili riferimenti letterari all''opera di Milton.', 'Analisi critico-cinematografica dell''edizione speciale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:45:58.407087+00:00'),
('a8df6ff9-31f0-456d-ba9a-92bad7cbb91d', 273, 'Citazioni & Easter Egg', 'Omaggio alla televisione commerciale', 'Il programma televisivo ''Passaparola'', condotto all''epoca da Gerry Scotti, viene citato esplicitamente e inserito come tormentone narrativo per sottolineare la pigrizia mentale e la routine rassicurante del personaggio interpretato da Giovanni.', 'Analisi testuale della sceneggiatura del film', TRUE, 'IA (Admin)', 'IA Verificata', 3, 9, '2026-11-02T17:21:33.241734+00:00'),
('f9dd5c64-2f9a-4b88-8cb5-ace074a10a11', 273, 'Curiosità & Retroscena', 'Le location milanesi e la periferia', 'Gran parte delle riprese si è svolta tra Milano e l''hinterland, sfruttando scorci urbani reali non patinati per accentuare il contrasto tra le nevrosi dei tre protagonisti e la frenesia della vita cittadina.', 'Diario di bordo delle riprese e archivio della Lombardia Film Commission', TRUE, 'IA (Admin)', 'IA Verificata', 4, 10, '2026-11-02T17:21:33.241734+00:00'),
('e6e9184c-f52d-488c-94c0-826228093fb4', 374, 'Casting & Scelte', 'La genesi televisiva e il rifiuto dei network', 'Il film nasce come adattamento cinematografico della serie televisiva di breve durata ''Quelli della pallottola spuntata'' (Police Squad!, 1982) ideata da David Zucker, Jim Abrahams e Jerry Zucker. La serie fu cancellata dalla ABC dopo appena sei episodi perché, secondo i dirigenti dell''epoca, ''richiedeva troppo sforzo da parte del pubblico'' per cogliere le battute visive.', 'Documentario retrospettivo e note di produzione Paramount Pictures', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-04T17:55:13.265422+00:00'),
('ff47a393-86e2-4d62-8330-697ca1c7f00b', 374, 'Casting & Scelte', 'La scelta rischiosa di O.J. Simpson', 'Prima della sua infamia giudiziaria degli anni ''90, O.J. Simpson fu fortemente voluto dai registi per il ruolo del detective Nordberg, nonostante i produttori temessero che il pubblico non lo trovasse credibile in una veste comica. David Zucker difese strenuamente la scelta, lodando la naturale autoironia dell''ex campione di football sul set.', 'Commento audio del regista David Zucker e del co-creatore Jerry Zucker', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-04T17:55:13.265422+00:00'),
('72fff49d-8afa-47c1-8970-04acc05e97d1', 374, 'Casting & Scelte', 'Il provino decisivo di Leslie Nielsen', 'Leslie Nielsen era noto principalmente come attore drammatico in film catastrofici come ''L''aereo più pazzo del mondo'' quando fu scelto. Per dimostrare la sua idoneità al ruolo di Frank Drebin, i registi lo convocarono per testare la sua celebre abilità nel mantenere un''espressione totalmente seria pronunciando battute demenziali.', 'Intervista d''archivio a Leslie Nielsen nei contenuti speciali dell''edizione Home Video', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-04T17:55:13.265422+00:00'),
('d3285eba-1a56-4df5-9a57-ff9095560c27', 374, 'Aneddoti dal set', 'La scena della regina e il cane combinaguai', 'Durante la celebre sequenza in cui Frank Drebin finisce addosso alla Regina Elisabetta durante la partita di baseball, la troupe dovette addestrare un cane specifico per far sì che azzannasse i pantaloni dell''attore al momento giusto. La scena richiese oltre quindici riprese a causa della distrazione dell''animale causata dal pubblico dello stadio di Anaheim.', 'Making-of ufficiale incluso nel DVD celebrativo del ventesimo anniversario', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-04T17:55:13.265422+00:00'),
('fbf2e182-d5cb-4f3a-92c4-8c8c12518ee7', 374, 'Segreti di produzione', 'Le riprese nello stadio dei Dodgers e degli Angels', 'Le sequenze della partita di baseball culminanti con il salvataggio della Regina furono girate principalmente all''Anaheim Stadium durante le reali pause delle partite casalinghe dei California Angels. La produzione sfruttò la presenza di migliaia di veri tifosi sugli spalti per le inquadrature panoramiche, integrando poi gli attori con riprese mirate.', 'Note di produzione e archivi della Paramount Pictures', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-04T17:55:13.265422+00:00'),
('94e038f4-c851-41a1-aff3-fd742e1372e2', 197, 'Segreti di produzione', 'La genesi del Thunderdome ispirata al catch', 'L''idea strutturale della gabbia metallica in cui combattono Max e Blaster nel Thunderdome fu concepita da George Miller traendo ispirazione dai match di wrestling professionistico e dai vecchi spettacoli circensi dei ''Wall of Death''. La struttura fu progettata per risultare claustrofobica e pericolosa, imponendo agli stuntmen movimenti estremamente complessi e coreografati con precisione millimetrica.', 'Documentario ''The Making of Mad Max Beyond Thunderdome''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:14.204804+00:00'),
('af4fb42a-a2f3-4f87-911d-bf02958ab013', 197, 'Casting & Scelte', 'Il cameo musicale di Angry Anderson', 'Angry Anderson, carismatico frontman della rock band australiana Rose Tattoo, fu scelto per interpretare il feroce personaggio di Ironbar, il braccio destro di Aunty Entity. La sua presenza scenica imponente e la sua voce roca contribuirono a definire il look aggressivo dei guerrieri di Bartertown, consolidando il legame tra il franchise e la cultura rock.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:14.204804+00:00'),
('2cd45c57-0204-4d0a-83f2-9cac37d88af6', 197, 'Aneddoti dal set', 'La polvere di Coober Pedy e i problemi di salute', 'Durante le riprese nelle remote saline e deserti attorno a Coober Pedy, la combinazione di vento forte, sabbia finissima e calore estremo causò seri problemi respiratori a diversi membri della troupe e del cast. Molti attori dovettero indossare mascherine protettive tra un ciak e l''altro per evitare infezioni ai polmoni causate dalla polvere minerale locale.', 'Intervista al direttore della fotografia Dean Semler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:14.204804+00:00'),
('cfd1ff42-fab0-42b0-b75d-da61f2f96692', 197, 'Curiosità & Retroscena', 'L''ispirazione letteraria del Signore delle Mosche', 'La seconda metà del film, incentrata sulla tribù dei bambini sopravvissuti che attendono il ritorno del leggendario ''Capitano Walker'', fu apertamente modellata da George Miller e dal co-sceneggiatore Terry Hayes sul classico romanzo ''Il Signore delle Mosche'' di William Golding e sul mito di Peter Pan, ribaltato in chiave post-apocalittica.', 'Commento audio del regista George Miller', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:14.204804+00:00'),
('c7f9a44a-f504-4a70-8e6d-99d748a7afc0', 197, 'Effetti speciali & Trucco', 'Il trucco complesso di Master Blaster', 'Per realizzare la figura combinata di Master Blaster, l''attore nano Angelo Rossitto (Master) doveva essere imbragato saldamente sulle spalle del corpulento stuntman Paul Larsson (Blaster) per ore intere. Gli specialisti del trucco e degli effetti protesici dovettero studiare imbragature ergonomiche nascoste sotto i costumi di cuoio per evitare lesioni alla colonna vertebrale durante le riprese delle scene di lotta.', 'Archivio storico degli stuntmen australiani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:14.204804+00:00'),
('41893b96-b559-4377-a8fb-9b2184b871fd', 197, 'Segreti di produzione', 'La sequenza del treno merci nel deserto', 'L''imponente inseguimento finale che vede protagonisti il treno merci modificato e i veicoli di Bartertown richiese mesi di pianificazione logistica e il coinvolgimento delle ferrovie dell''Australia Meridionale. Il treno fu appositamente corazzato con lamiere saldate e attrezzato con rampe mobili per permettere agli stuntman di saltare da un mezzo in corsa all''altro senza protezioni digitali.', 'Special TV ''The Stunts of Mad Max''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:14.204804+00:00'),
('8ff00e13-2102-41a5-b807-8bc0352c9500', 289, 'Casting & Scelte', 'La prima scelta della MGM per il ruolo di Manuel', 'Prima di affidare la parte del pescatore portoghese a Spencer Tracy, la produzione aveva valutato seriamente Clark Gable per il ruolo principale, ma l''attore rifiutò l''offerta perché non si sentiva adatto a interpretare un marinaio straniero e a cantare.', 'Archivi storici MGM e biografie ufficiali di Spencer Tracy', TRUE, 'IA (Admin)', 'IA Verificata', 2, 11, '2026-11-02T17:22:33.591663+00:00'),
('a2d60767-edce-45ee-8caf-b449449d2603', 289, 'Aneddoti dal set', 'Il mal di mare cronico del giovane Freddie Bartholomew', 'Durante le riprese in mare aperto al largo di Gloucester, il giovanissimo protagonista Freddie Bartholomew soffrì pesantemente di mal di mare, costringendo la troupe a fare frequenti pause e a tenere costantemente a bordo un medico per le cure del caso.', 'Memorie e interviste d''archivio di Freddie Bartholomew', TRUE, 'IA (Admin)', 'IA Verificata', 3, 12, '2026-11-02T17:22:33.591663+00:00'),
('1c0e8bb9-3daa-4d54-83ea-e4e0d951a22a', 289, 'Segreti di produzione', 'L''impiego di veri pescatori professionisti nel cast', 'Per garantire la massima autenticità nelle sequenze di pesca e nella gestione delle vele, il regista Victor Fleming arruolò gran parte del vero equipaggio del peschereccio ''Mariner'' facendoli recitare nel film come membri della ciurma del ''We''re Here''.', 'Note di produzione e documentario sul making-of del film', TRUE, 'IA (Admin)', 'IA Verificata', 1, 13, '2026-11-02T17:22:33.591663+00:00'),
('adc02146-bdee-4f15-afd7-1f0bec3c4d27', 289, 'Effetti speciali & Trucco', 'L''uso innovativo della tintura per i capelli di Spencer Tracy', 'Per conferire a Spencer Tracy un aspetto più mediterraneo e aderente alle origini portoghesi del personaggio di Manuel, i truccatori della MGM dovettero scurire notevolmente i suoi capelli e applicare una tintura speciale per la pelle resistente alla salsedine.', 'Archivio del reparto trucco e parrucco degli studi MGM', TRUE, 'IA (Admin)', 'IA Verificata', 3, 14, '2026-11-02T17:22:33.591663+00:00'),
('6d17af75-e3f1-4296-9038-cb01c49c8c0d', 289, 'Curiosità & Retroscena', 'Il rapporto epistolare tra Kipling e la produzione', 'Prima della sua scomparsa avvenuta nel gennaio 1936, lo scrittore Rudyard Kipling fu consultato personalmente dai dirigenti della MGM per approvare la struttura generale dell''adattamento cinematografico del suo romanzo del 1897.', 'Corrispondenza tra gli archivi MGM e la tenuta di Rudyard Kipling', TRUE, 'IA (Admin)', 'IA Verificata', 4, 15, '2026-11-02T17:22:33.591663+00:00'),
('c3faac3a-b4e6-409f-b63e-f39ee142ed37', 289, 'Casting & Scelte', 'Il rifiuto iniziale di Lionel Barrymore', 'Lionel Barrymore fu inizialmente riluttante ad accettare la parte del Capitano Disko Troop a causa dei crescenti problemi di artrite che già lo costringevano a limitare i movimenti, ma accettò dopo che la produzione modificò parzialmente le sue scene per permettergli di recitare prevalentemente da seduto.', 'Biografie storiche e registri di produzione della MGM', TRUE, 'IA (Admin)', 'IA Verificata', 5, 17, '2026-11-02T17:22:33.591663+00:00'),
('d2e595b2-50c9-450b-80a3-e22420ac7910', 289, 'Aneddoti dal set', 'L''incidente con le attrezzature di bordo', 'Durante una complessa manovra di virata del veliero in presenza di vento forte, un pennone si spezzò improvvisamente sfiorando la troupe tecnica, fortunatamente senza causare feriti gravi ma costringendo la produzione a interrompere le riprese per due giorni.', 'Rapporti di sicurezza e di produzione sul set del 1937', TRUE, 'IA (Admin)', 'IA Verificata', 2, 18, '2026-11-02T17:22:33.591663+00:00'),
('dd5d97ca-105e-4e8e-b10f-8a2a323ebe48', 375, 'Casting & Scelte', 'Il rifiuto iniziale di Diego Abatantuono', 'Diego Abatantuono rifiutò inizialmente la parte del sergente Lorusso perché non voleva allontanarsi dall''Italia per un intero periodo di riprese estive. Fu Gabriele Salvatores a insistere e a convincerlo dopo aver modificato alcuni aspetti caratteriali del personaggio per renderlo più affine alla sua sensibilità artistica.', 'Intervista ufficiale a Gabriele Salvatores nel documentario di retroscena dell''edizione home video', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-04T19:51:21.091893+00:00'),
('5a6b306c-3e9a-48dd-8834-f7a6f5cb5229', 375, 'Curiosità & Retroscena', 'La scelta dell''isola di Kastellorizo', 'Le riprese si svolsero quasi interamente sull''isola greca di Kastellorizo, scelta dalla produzione dopo che l''isola di Mykonos era stata ritenuta troppo cementificata e turistica per rappresentare la Grecia rurale e isolata del 1941.', 'Note di produzione ufficiali della Ciga Film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-04T19:51:21.091893+00:00'),
('7ee96ce6-05c4-4f47-bd0a-3ba0a5301f06', 200, 'Segreti di produzione', 'La ricostruzione della strada in studio', 'Poiché non fu permesso di girare all''interno di una vera banca durante l''orario di lavoro o di bloccare indefinitamente una strada di Brooklyn, la produzione ricostruì l''esterno della banca e parte della strada in un set appositamente allestito a세대 Brooklyn (Prospect Park West) e in un teatro di posa.', 'Making-of documentario ''The Making of Dog Day Afternoon''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:28.1212+00:00'),
('67dced0b-c63f-4ac9-b18a-557dcba134e9', 200, 'Curiosità & Retroscena', 'Il compenso devoluto dal vero Wojtowicz', 'John Wojtowicz ricevette circa 7.500 dollari più una percentuale sui profitti per i diritti della sua storia, denaro che usò in parte per pagare l''operazione di cambio sesso della moglie Elizabeth Debbie Eden.', 'Articoli biografici e interviste storiche a John Wojtowicz', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:28.1212+00:00'),
('0d662b63-f77c-43e5-8214-960ec283010d', 200, 'Casting & Scelte', 'Dustin Hoffman rifiutato o non disponibile', 'Prima che il ruolo di Sonny Wortzik venisse affidato ad Al Pacino, la produzione aveva valutato altri attori di primissimo piano, tra cui Dustin Hoffman, che tuttavia declinò l''offerta.', 'Archivi di casting della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:28.1212+00:00'),
('37a8e5a1-5692-4a29-801c-d2d8bbb9d8e0', 200, 'Aneddoti dal set', 'L''improvvisazione di Charles Durning', 'Charles Durning, che interpreta il detective Eugene Moretti, improvvisò gran parte delle sue interazioni telefoniche con Al Pacino, accentuando il tono stanco e paternalistico del negoziatore.', 'Intervista retrospettiva a Charles Durning', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:28.1212+00:00'),
('04bb511f-16b9-4b9a-8eee-1fb183865a1a', 205, 'Casting & Scelte', 'La morte improvvisa di Philip Seymour Hoffman e la riscrittura digitale', 'A seguito della tragica e improvvisa scomparsa di Philip Seymour Hoffman nel febbraio 2014, quando mancavano ancora otto giorni di riprese per il suo personaggio Plutarch Heavensbee, il regista Francis Lawrence decise di non ricastare il ruolo né di usare una controfigura digitale completa. Le poche scene cruciali rimaste senza di lui furono riscritte modificando le inquadrature, facendo pronunciare le sue battute ad altri personaggi come Haymitch o inserendo Plutarch tramite lettere lette da Katniss.', 'Dichiarazioni ufficiali del regista Francis Lawrence e note di produzione Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:48.963638+00:00'),
('56f1fff6-34a2-44ef-95e2-59e625dce2c4', 205, 'Aneddoti dal set', 'Il tributo commosso sul set per l''addio alla saga', 'Durante l''ultimo giorno di riprese in assoluto della produzione a Berlino, che corrispondeva anche alla fine del percorso per gli attori principali, Jennifer Lawrence, Josh Hutcherson e Liam Hemsworth si scambiarono un lungo e pubblico abbraccio sul set che fece commuovere l''intera troupe. Per suggellare la fine del franchise, i tre attori ricevettero in dono dalla produzione dei calchi in bronzo dei loro stessi pugni nel celebre gesto di saluto dei distretti.', 'Making-of ufficiale ''The Hunger Games: Mockingjay - Part 2'' Blu-ray bonus features', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:48.963638+00:00'),
('9c213ad9-0c28-49f0-a60c-1104f8405e0c', 205, 'Segreti di produzione', 'Le riprese reali nei luoghi storici di Berlino e dintorni', 'Per conferire a Capitol City un''architettura brutalista e monumentale autentica, la produzione evitò quasi del tutto i set virtuali in favore di location reali in Europa, girando estensivamente a Berlino e a Babelsberg. Tra i siti chiave ripresi figurano il complesso residenziale di Karl-Marx-Allee, l''aeroporto abbandonato di Tempelhof e la torre di raffreddamento della centrale termoelettrica di Rüdersdorf, trasformata visivamente nelle trappole mortali delle fogne.', 'Production Designer Philip Messina nelle featurette di approfondimento architettonico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:48.963638+00:00'),
('a9d3d7bb-f530-4aa2-9fea-625dca47f6f2', 205, 'Effetti speciali & Trucco', 'L''addio al trucco estremo per Elizabeth Banks nei panni di Effie Trinket', 'In questo capitolo finale, l''evoluzione del personaggio di Effie Trinket — ora spogliata del lusso sfrenato di Capitol City e vicina agli ideali della rivoluzione — richiese un drastico ridimensionamento delle parrucche elaborate e del trucco facciale pesante visti nei film precedenti. L''attrice Elizabeth Banks ha ammesso di aver accolto con grande sollievo questo cambiamento, avendo dovuto sopportare fino a quattro ore al giorno di sedia di trucco nei primi capitoli della saga.', 'Intervista a Elizabeth Banks per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:48.963638+00:00'),
('a76aa0df-61a1-44f5-bb5e-dc2c53958b5d', 205, 'Citazioni & Easter Egg', 'Il cameo della famiglia di Francis Lawrence nella scena finale', 'Nella commovente sequenza finale ambientata nel prato verde dove Katniss e Peeta giocano con i loro bambini, i neonati che appaiono in braccio ai protagonisti sono in realtà i figli di alcuni membri chiave della troupe e dello stesso regista Francis Lawrence. Questa scelta ha permesso di mantenere un''atmosfera intima e genuina durante le riprese di una delle scene più delicate e simboliche dell''intero epilogo.', 'Commento audio del regista Francis Lawrence e del produttore Nina Jacobson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:48.963638+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('60e91ea7-8989-4895-b652-934b34d0ec38', 261, 'Casting & Scelte', 'Il passaggio di consegne alla regia da Ilya Naishuller a Timo Tjahjanto', 'A causa di conflitti di programmazione con la post-produzione e altri impegni del primo capitolo, Ilya Naishuller ha ceduto la sedia da regista a Timo Tjahjanto, noto per il suo stile frenetico e viscerale in film action come The Night Comes for Us.', 'Annuncio ufficiale Deadline / Note di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 5, 1, '2026-11-02T17:22:46.583451+00:00'),
('fda26888-6018-4270-86e3-bf91fe6ba8f2', 261, 'Curiosità & Retroscena', 'L''evoluzione del passato di Becca interpretata da Connie Nielsen', 'Inizialmente concepito come un seguito incentrato unicamente sulla vendetta solitaria di Hutch Mansell, la sceneggiatura ha ampliato notevolmente il background di sua moglie Becca, interpretata nuovamente da Connie Nielsen, svelando legami inaspettati con il mondo criminale.', 'Intervista agli sceneggiatori / CinemaBlend', TRUE, 'IA (Admin)', 'IA Verificata', 4, 2, '2026-11-02T17:22:46.583451+00:00'),
('e173abee-24d6-4bbf-b21e-65323e53c9d1', 261, 'Aneddoti dal set', 'La preparazione atletica intensiva di Bob Odenkirk', 'Nonostante avesse già sorpreso pubblico e critica per la sua forma fisica nel primo film a quasi 60 anni, Bob Odenkirk ha intensificato ulteriormente gli allenamenti di arti marziali miste e stunt coordination sotto la supervisione del team 87North.', 'Featurette di backstage ufficiale', TRUE, 'IA (Admin)', 'IA Verificata', 3, 3, '2026-11-02T17:22:46.583451+00:00'),
('8116b1a5-17c0-4b9f-a5c3-993235fc1b51', 261, 'Casting & Scelte', 'L''ingresso di Sharon Stone nel cast principale', 'Tra le aggiunte più rilevanti al cast figura Sharon Stone, ingaggiata per interpretare la principale antagonista del film, portando una dinamica di classe e spietatezza contrapposta alla furia operaia del protagonista Hutch.', 'The Hollywood Reporter casting update', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T17:22:46.583451+00:00'),
('c00962ef-cecc-40e2-ac9a-02d5730b16cd', 261, 'Segreti di produzione', 'Le riprese principali nella regione di Winnipeg', 'La produzione principale del film si è svolta a Winnipeg, in Canada, sfruttando le architetture urbane e le zone periferiche per replicare le atmosfere fredde e isolate che caratterizzano la doppia vita della famiglia Mansell.', 'Production Weekly report', TRUE, 'IA (Admin)', 'IA Verificata', 5, 5, '2026-11-02T17:22:46.583451+00:00'),
('929e1e7f-f9f9-4cf3-9cf0-7f370652d0c7', 202, 'Effetti speciali & Trucco', 'La scelta del look per Caesar Flickerman', 'Il truccatore Ve Neill ha ideato per Stanley Tucci un abito interamente ricoperto di luci LED funzionanti per la parata dei tributi, un dettaglio tecnico complesso che richiedeva l''ausilio di un tecnico elettrico nascosto dietro le quinte per gestire le batterie.', 'Documentario sugli effetti di trucco e costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:37.217996+00:00'),
('64a4bf60-814a-438b-b6f6-ed67aa04e64b', 202, 'Segreti di produzione', 'La costruzione pratica della Cornucopia', 'La gigantesca struttura della Cornucopia nell''Arena non era interamente in CGI: la sezione principale è stata costruita a grandezza naturale in vetroresina e acciaio, posizionata direttamente all''interno di una cava boschiva in North Carolina.', 'Articolo di American Cinematographer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T15:46:37.217996+00:00'),
('44725a4d-112a-46ff-ab5a-b66ca0232a30', 202, 'Casting & Scelte', 'Il cameo di Jackie Emerson e il suo cane', 'Jackie Emerson, che interpreta la tributo del Distretto 5 Foxface, ha ottenuto la parte dopo una vasta ricerca di casting aperta, distinguendosi per un''espressione furba che il regista ha ritenuto perfetta per il personaggio.', 'Note di casting ufficiali della Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T15:46:37.217996+00:00'),
('f3428faa-2f3d-4e05-a8e0-a81a3a992a4e', 202, 'Segreti di produzione', 'Le riprese con la macchina a mano', 'Il direttore della fotografia Tom Stern ha girato gran parte delle sequenze del Distretto 12 e dell''Arena utilizzando quasi esclusivamente cineprese a mano con ottiche anamorfiche, per accentuare il senso di realismo documentaristico e di caos vissuto da Katniss.', 'Note tecniche della troupe di fotografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T15:46:37.217996+00:00'),
('aaf341fe-1291-4b67-9990-c6e5af8bf93d', 207, 'Segreti di produzione', 'L''invenzione del linguaggio dei Minions', 'Il cosiddetto ''Minionese'' non è un linguaggio casuale ma un vero e proprio collage fonetico inventato dai registi Pierre Coffin e Chris Renaud, i quali hanno prestato la voce alle creature inserendo parole in francese, spagnolo, inglese, italiano, russo e persino termini culinari come ''paprikà'' o ''gelato''.', 'Commento audio del Blu-ray e interviste ufficiali Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:55.101414+00:00'),
('4c6c42b8-bee8-4c97-85b0-f74b6c9eb74a', 207, 'Casting & Scelte', 'La prova di voce di Steve Carell', 'Steve Carell ha registrato le sue battute per Gru provando tre diverse tonalità di voce prima di trovare quella definitiva, ispirandosi a una combinazione tra l''accento di Bela Lugosi nei film di Dracula e un tono di voce burbero ma affettuoso.', 'Making-of ufficiale ''The World of Despicable Me''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:55.101414+00:00'),
('0a71be91-0073-4412-af68-6c0c67ccffbe', 207, 'Curiosità & Retroscena', 'Il nome in codice originale e i primi bozzetti', 'Nelle prime fasi di sviluppo presso la Illumination, il progetto era noto con il titolo di lavorazione ''Evil Me'' e i Minions non dovevano essere piccoli e gialli, bensì enormi creature simili a orchi pelosi e goffi, poi ridotte in taglia e numero per renderli più empatici.', 'Art of Despicable Me / Documentario di produzione Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:55.101414+00:00'),
('c70b97d7-1e28-4b3b-bbdb-baa8ec75660e', 207, 'Casting & Scelte', 'Il cameo vocale di Kristen Wiig', 'Prima di interpretare Lucy Wilde nel sequel del 2013, l''attrice Kristen Wiig ha partecipato al primo film doppiando Miss Hattie, la severa direttrice dell''orfanotrofio dove vivono Margo, Edith e Agnes.', 'Crediti ufficiali del film e press kit Illumination', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:55.101414+00:00'),
('c3f2f4c5-0240-40f8-8e7a-b7092af93f05', 207, 'Citazioni & Easter Egg', 'Il riferimento cinematografico a Il padrino', 'La scena in cui il direttore della Bank of Evil (interpretato da David Hyde Pierce) nega il prestito a Gru contiene una chiara citazione visiva e di messa in scena all''incontro tra Michael Corleone e Hyman Roth nel film ''Il padrino - Parte II''.', 'Analisi visiva e contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:55.101414+00:00'),
('9b8c35ab-3445-4706-946a-c02b65f2fa55', 207, 'Citazioni & Easter Egg', 'Il tributo a Willy Wonka nel laboratorio', 'La sequenza in cui Gru mostra per la prima volta il suo laboratorio segreto ai Minions e alle bambine presenta numerosi macchinari e marchingegni stravaganti che omaggiano la fabbrica di cioccolato del film ''Willy Wonka e la fabbrica di cioccolato'' del 1971.', 'Easter Egg documentati su IMDb e recensioni di settore', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T15:46:55.101414+00:00'),
('0e74ad49-f353-4ac1-9063-d822b5a1c332', 267, 'Curiosità & Retroscena', 'Genesi e accordo di distribuzione Netflix', 'Il film rappresenta il terzo capitolo della redditizia saga di Benoit Blanc, frutto dell''accordo da oltre 400 milioni di dollari siglato nel 2021 tra Netflix e il regista Rian Johnson per la produzione di due sequel di ''Knives Out''.', 'Comunicato ufficiale Netflix e Deadline Hollywood', TRUE, 'IA (Admin)', 'IA Verificata', 1, 1, '2026-11-02T17:23:01.744529+00:00'),
('3b20d1ea-5d66-499b-ba32-746313065735', 267, 'Casting & Scelte', 'L''annuncio scaglionato del cast stellare', 'Come da tradizione per il franchise, la produzione ha rivelato i membri del cast corale uno alla volta tramite brevi teaser video sui social media, confermando la presenza di Josh O''Connor, Glenn Close e Josh Brolin nelle settimane precedenti l''inizio delle riprese.', 'Account social ufficiali di Rian Johnson e Netflix', TRUE, 'IA (Admin)', 'IA Verificata', 4, 2, '2026-11-02T17:23:01.744529+00:00'),
('b0cfdbfa-e14a-4a9b-8c96-6de8e1d643c4', 267, 'Segreti di produzione', 'Spostamento delle location di ripresa', 'A differenza del secondo capitolo ''Glass Onion'' interamente girato in Grecia, le riprese principali di ''Wake Up Dead Man'' si sono svolte prevalentemente nel Regno Unito, sfruttando location storiche e teatri di posa britannici per ricostruire l''ambientazione della piccola comunità parrocchiale.', 'Production Weekly e note di produzione ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 2, 3, '2026-11-02T17:23:01.744529+00:00'),
('496650d0-e485-4c2f-84f9-36544902394b', 267, 'Curiosità & Retroscena', 'Il significato del titolo tratto dai Doors', 'Il titolo del film trae origine dall''omonima canzone tradizionale gospel reinterpretata dal gruppo rock The Doors nell''album ''Full Circle'' del 1972, un elemento musicale che riflette le tinte oscure e misteriose della trama incentrata su un crimine in una chiesa.', 'Intervista al regista Rian Johnson su Empire Magazine', TRUE, 'IA (Admin)', 'IA Verificata', 3, 4, '2026-11-02T17:23:01.744529+00:00'),
('ce1a2540-bcca-4de5-88b6-7f683f0e8220', 267, 'Casting & Scelte', 'Il ritorno di Daniel Craig nei panni di Benoit Blanc', 'Daniel Craig ha ripreso per la terza volta l''iconico ruolo del detective privato del Sud degli Stati Uniti, confermando l''accento caratteristico che aveva già perfezionato nei capitoli precedenti con l''aiuto di un vocal coach.', 'Note di produzione e conferenze stampa ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 5, 5, '2026-11-02T17:23:01.744529+00:00'),
('46cfaf40-d715-486d-bf3a-9dc0f6be3c61', 267, 'Segreti di produzione', 'Curiosità dal set', 'Rian Johnson ha rinnovato la collaborazione con il direttore della fotografia Steve Yedlin, sodalizio artistico che dura fin dai tempi del film esordio ''Brick'' del 2005 e proseguito attraverso tutti i blockbuster successivi del regista.', 'Crediti ufficiali della troupe e rivista American Cinematographer', TRUE, 'IA (Admin)', 'IA Verificata', 5, 6, '2026-11-02T17:23:01.744529+00:00'),
('d003d3be-4390-49ce-b444-3f294fff7717', 375, 'Segreti di produzione', 'L''ispirazione letteraria dal romanzo di Renzo Biasion', 'Il film è liberamente tratto dal romanzo ''Sagapo'' di Renzo Biasion, pubblicato nel 1945. Il titolo originale del libro e della sceneggiatura provvisoria faceva riferimento alla corruzione fonetica greca della frase ''ti s agapo'' (ti voglio bene).', 'Crediti iniziali del film e saggistica cinematografica sul cinema italiano degli anni Novanta', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-04T19:51:21.091893+00:00'),
('1839e312-c2ac-440b-8ef2-346a93355002', 208, 'Citazioni & Easter Egg', 'La parodia di ''Speed'' nella sequenza d''apertura', 'La sequenza in cui il misterioso veicolo magnetico ruba il siero PX-41 dall''Artico è un esplicito omaggio al thriller d''azione ''Speed'' del 1994, con richiami visivi alla celebre dinamica del dirottamento in corsa.', 'Commento audio del Blu-ray dei registi Pierre Coffin e Chris Renaud', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T15:46:58.85366+00:00'),
('3686a238-4fdf-472d-9900-0b74d3c18d6c', 208, 'Casting & Scelte', 'Il ritorno di Kristen Wiig in un nuovo ruolo principale', 'Sebbene Kristen Wiig avesse già doppiato Miss Hattie nel primo capitolo del 2010, i realizzatori rimasero così colpiti dalla sua versatilità vocale da volerla assolutamente richiamare per il ruolo inedito e di primo piano dell''agente segreto Lucy Wilde.', 'Note di produzione ufficiali della Illumination Entertainment', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T15:46:58.85366+00:00'),
('0f0b1708-5769-490b-bc47-64b04ae099f7', 208, 'Segreti di produzione', 'L''ispirazione per i Minions cattivi viola', 'I Minions trasformati dal siero PX-41 in creature selvagge e indistruttibili di colore viola traggono ispirazione cromatica e comportamentale dai classici mostri dei film horror degli anni ''50 e dai cartoni animati Looney Tunes, in particolare da Taz il diavolo della Tasmania.', 'Artbook ufficiale ''The Art of Despicable Me 2''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T15:46:58.85366+00:00'),
('c9269d89-d161-41fe-94ea-08effed18f34', 208, 'Aneddoti dal set', 'La registrazione dei dialoghi in solitaria per Steve Carell e Benjamin Bratt', 'Come da prassi per la maggior parte dei film d''animazione a grande budget, Steve Carell e Benjamin Bratt hanno registrato tutti i loro scambi di battute e i confronti verbali tra Gru ed El Macho in sessioni separate, senza mai trovarsi contemporaneamente in sala di registrazione.', 'Intervista promozionale sul cast e doppiaggio del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T15:46:58.85366+00:00'),
('c84da156-3497-46b5-ba48-0cd098a81ac3', 208, 'Citazioni & Easter Egg', 'Il cameo del cibo messicano e il nome di El Macho', 'Il nome e i tratti del cattivo principale El Macho traggono ispirazione dallo stereotipo dei lottatori di lucha libre messicana e dai ristoranti di cucina tex-mex, con diversi easter egg visivi nascosti nel suo covo sotterraneo a tema culinario.', 'Making-of e documentario sulla progettazione dei personaggi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T15:46:58.85366+00:00'),
('ed76565f-ca00-4c98-9f0b-e27aeafd090c', 362, 'Casting & Scelte', 'Il provino e l''ingresso di Olivia Wilde nel cast', 'L''attrice Olivia Wilde ha ottenuto la parte di Nicole, la madre single incontrata da John Brennan al parco giochi, dopo aver impressionato Paul Haggis con la sua capacità di conferire umanità e sfumature di compassione a un personaggio marginale ma cruciale per la disperazione morale del protagonista.', 'Note di produzione ufficiali Lionsgate', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 10, '2026-11-02T17:26:40.394388+00:00'),
('0af5d5b6-7203-459c-bfba-026360eecc34', 362, 'Curiosità & Retroscena', 'La consulenza tecnica con un ex detenuto evaso', 'Per garantire la veridicità delle tecniche di pianificazione dell''evasione messe in atto da John Brennan, Paul Haggis ha consultato un ex esperto di sicurezza carceraria e un ex detenuto condannato per reati finanziari, i quali hanno verificato la plausibilità dei metodi di studio delle telecamere a circuito chiuso.', 'Intervista promozionale al regista Paul Haggis per Collider', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 11, '2026-11-02T17:26:40.394388+00:00'),
('a7b27877-43e3-4536-b49a-2455c7347348', 362, 'Aneddoti dal set', 'Le riprese reali al Western Penitentiary', 'Alcune sequenze di transito e gli esterni carcerari sono stati girati nelle immediate vicinanze del dismesso Western Penitentiary di Pittsburgh, dove la troupe ha dovuto fronteggiare temperature rigide e condizioni atmosferiche avverse che hanno messo a dura prova le attrezzature di ripresa e gli attori.', 'Making-of incluso nell''edizione Blu-ray Home Video', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 12, '2026-11-02T17:26:40.394388+00:00'),
('6df14bda-31b5-412a-96ca-8e4952725937', 362, 'Segreti di produzione', 'La scelta delle ottiche anamorfiche per Pittsburgh', 'Il direttore della fotografia Stéphane Fontaine ha utilizzato cineprese Arricam e obiettivi anamorfici Hawk per conferire alla città di Pittsburgh una tonalità fredda, industriale e opprimente, accentuando il senso di claustrofobia e isolamento emotivo vissuto dal personaggio di Russell Crowe.', 'American Cinematographer, articolo tecnico di approfondimento', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 13, '2026-11-02T17:26:40.394388+00:00'),
('a706bd36-1e2b-41fd-93f1-444c614604ca', 375, 'Aneddoti dal set', 'Condizioni climatiche estreme durante le riprese', 'La troupe e il cast dovettero affrontare temperature elevatissime durante l''estate del 1990 sull''isola di Kastellorizo, dove non c''erano strutture alberghiere adeguate e gli attori furono costretti a dormire in case private affittate dalla produzione o su navi d''appoggio.', 'Making-of ufficiale ''Il viaggio di Mediterraneo'' incluso nel DVD speciale', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-04T19:51:21.091893+00:00'),
('787aa74c-fe16-471a-8b5f-052592977cfb', 375, 'Curiosità & Retroscena', 'La vittoria del Premio Oscar', 'Mediterraneo vinse il Premio Oscar come miglior film straniero nel marzo 1992, battendo concorrenti di alto profilo internazionale come il cinese ''Lanterne rosse'' di Zhang Yimou e il belga ''Toto il eroe''.', 'Archivio ufficiale dell''Academy of Motion Picture Arts and Sciences', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-04T19:51:21.091893+00:00'),
('842d6911-bc2d-4bcf-99b1-242e9c84eeda', 363, 'Casting & Scelte', 'Il coinvolgimento anticipato di Robert Pattinson', 'Robert Pattinson è stato il primissimo attore a essere contattato da Bong Joon-ho per il ruolo del protagonista, ancor prima che la sceneggiatura fosse completata, dopo che il regista era rimasto folgorato dalla sua performance in ''Good Time'' dei fratelli Safdie.', 'Intervista ufficiale di Bong Joon-ho a CinemaCon', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-02T17:29:23.302456+00:00'),
('6f1a8c74-d9b1-4c51-9f25-c5adc1c77099', 363, 'Curiosità & Retroscena', 'Tratto dal romanzo inedito di Edward Ashton', 'Il film è l''adattamento cinematografico del romanzo fantascientifico ''Mickey7'' di Edward Ashton. Bong Joon-ho ha ricevuto il manoscritto in anteprima ancora prima della sua pubblicazione avvenuta nel febbraio 2022, rimanendo immediatamente catturato dal concept dei cloni sacrificabili.', 'Note di produzione ufficiali Warner Bros.', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-02T17:29:23.302456+00:00'),
('6a1157a8-cb18-4281-9cd6-37cd9e0476d1', 363, 'Segreti di produzione', 'Le riprese presso i Warner Bros. Studios Leavesden', 'La produzione principale del film si è svolta tra la fine del 2022 e l''inizio del 2023 principalmente negli storici Warner Bros. Studios di Leavesden, nel Hertfordshire, dove sono stati allestiti imponenti set interni per ricreare la colonia sul pianeta ghiacciato Niflheim.', 'Report di produzione cinematografica britannica', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-02T17:29:23.302456+00:00'),
('aa80c97a-4fcf-4c88-8ccd-9acc3c2edf15', 363, 'Casting & Scelte', 'Un cast di supporto internazionale di alto livello', 'Nel corso del 2022 si sono aggiunti al cast principale attori di calibro internazionale come Naomi Ackie, Steven Yeun (già collaboratore di Bong in ''Okja''), Toni Collette e Mark Ruffalo, quest''ultimo scelto per interpretare il leader antagonista della spedizione coloniale.', 'Comunicato stampa ufficiale Deadline Hollywood', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-02T17:29:23.302456+00:00'),
('0a1827b1-f30e-40b4-9561-d33b40b65e72', 363, 'Curiosità & Retroscena', 'La scelta del titolo e la numerazione dei cloni', 'Mentre nel romanzo originale il protagonista si chiama Mickey7 (indicando che è alla sua settima iterazione), il titolo e la trama del film diretto da Bong Joon-ho alzano la sosta numerica portando il protagonista a essere Mickey17, enfatizzando ulteriormente l''accumulo di morti e rigenerazioni.', 'Confronto ufficiale tra romanzo e sceneggiatura cinematografica', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-02T17:29:23.302456+00:00'),
('b1400aa7-6a9a-4cc4-b18d-d8873e5ba010', 375, 'Aneddoti dal set', 'Il coinvolgimento della popolazione locale di Kastellorizo', 'Poiché l''isola contava pochissimi abitanti all''epoca delle riprese, la produzione dovette coinvolgere attivamente i residenti per le scene di massa, arrivando a far interpretare il ruolo della prostituta Vassilissa a Vana Barba, scelta personalmente da Salvatores per il suo volto che incarnava la bellezza mediterranea arcaica.', 'Intervista a Gabriele Salvatores, documentario ''Mediterraneo: Il making of''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 6, '2026-11-04T19:52:14.227802+00:00'),
('369a8642-b150-4d55-b4bb-4898365adf88', 375, 'Segreti di produzione', 'L''uso di una nave da guerra d''epoca', 'Per le scene in mare, la produzione ebbe enormi difficoltà a reperire un mezzo navale coerente con il 1941; fu infine utilizzato un vecchio peschereccio opportunamente camuffato e modificato con strutture in legno e cartapesta per simulare la sagoma di un piccolo naviglio militare italiano.', 'Note di produzione del film, archivio storico della Colorado Film', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 7, '2026-11-04T19:52:14.227802+00:00'),
('69291001-46c7-4e67-bf5a-9bded6727d1a', 375, 'Casting & Scelte', 'Il ruolo di Claudio Bisio come Corrado Noventa', 'Claudio Bisio fu scelto per il ruolo del tenente Montini, ma durante le prove si decise di scambiare i ruoli con Claudio Bigagli, poiché Salvatores ritenne che la fisicità di Bisio fosse più adatta a interpretare il personaggio di Corrado Noventa, il soldato che si dedica alla pittura.', 'Commento audio del DVD, edizione speciale 2002', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 8, '2026-11-04T19:52:14.227802+00:00'),
('3e97d6d7-8d6a-472b-b516-82485eac66bd', 375, 'Curiosità & Retroscena', 'La dedica finale e il significato politico', 'La dedica ''A tutti quelli che stanno scappando'' non era solo un riferimento alla trama, ma un messaggio politico preciso di Salvatores rivolto alla generazione dei trentenni italiani dell''epoca, che sentivano il bisogno di evadere da una società percepita come soffocante e priva di prospettive.', 'Intervista di Gabriele Salvatores a ''La Repubblica'', 1991', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 9, '2026-11-04T19:52:14.227802+00:00'),
('9a03d35b-9694-42c4-b61e-1faa2952492f', 375, 'Effetti speciali & Trucco', 'La gestione del colore e della luce naturale', 'Il direttore della fotografia Italo Petriccione utilizzò filtri polarizzatori specifici per esaltare il bianco accecante delle case di Kastellorizo e il blu intenso dell''Egeo, cercando di ricreare visivamente l''atmosfera sospesa e atemporale descritta nella sceneggiatura di Enzo Monteleone.', 'Analisi tecnica della fotografia, rivista ''Segnocinema''', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 10, '2026-11-04T19:52:14.227802+00:00'),
('5330ef5d-dae2-4593-910a-e19843c0a115', 188, 'Casting & Scelte', 'Rapporto reale tra i protagonisti trasposto su schermo', 'Il film si basa direttamente sulla vera fine del matrimonio tra il regista e attore Henry Jaglom e la co-protagonista Patrice Townsend. La coppia decise di elaborare il proprio divorzio girando un film insieme nel fine settimana del 4 luglio nella vera casa in cui avevano vissuto.', 'Note di produzione e interviste d''archivio di Henry Jaglom', TRUE, 'IA (Admin)', 'IA Verificata', 3, 1, '2026-11-02T17:51:33.8203+00:00'),
('df5fda5a-1606-4319-88cd-364aa3af9f06', 188, 'Curiosità & Retroscena', 'Utilizzo di veri amici e familiari nel cast', 'Molti degli attori che interpretano gli amici della coppia in crisi nel film erano legati da reali rapporti di amicizia con Jaglom e Townsend nella vita di tutti i giorni. Questa scelta di casting mirava a dissolvere il confine tra finzione e documentario emotivo.', 'Press book originale e recensioni storiche del film', TRUE, 'IA (Admin)', 'IA Verificata', 1, 2, '2026-11-02T17:51:33.8203+00:00'),
('06ef3bad-0cb6-4993-af11-4ad726d1ad65', 188, 'Segreti di produzione', 'Improvvisazione e assenza di una sceneggiatura rigida', 'Henry Jaglom ha diretto la pellicola senza una sceneggiatura tradizionale, affidandosi a un canovaccio e incoraggiando gli attori a improvvisare basandosi sulle proprie esperienze sentimentali reali. Questo metodo autoriale ha caratterizzato gran parte della filmografia indipendente di Jaglom.', 'Analisi critica della filmografia di Henry Jaglom', TRUE, 'IA (Admin)', 'IA Verificata', 5, 3, '2026-11-02T17:51:33.8203+00:00'),
('4e8289ae-c8c6-4749-a859-ea781568867a', 188, 'Aneddoti dal set', 'Riprese nella residenza privata del regista', 'L''intera produzione si è svolta all''interno della vera casa di Henry Jaglom a Malibu, riducendo al minimo la troupe tecnica per mantenere un clima intimo e non intimidatorio durante le riprese delle scene di forte tensione emotiva.', 'Intervista retrospettiva al regista e documentari sul cinema indipendente americano', TRUE, 'IA (Admin)', 'IA Verificata', 4, 4, '2026-11-02T17:51:33.8203+00:00'),
('bd17b19a-acd2-4e43-b10a-0cc1cffd068d', 376, 'Casting & Scelte', 'Bill Murray e il breve tempo di presenza sul set', 'Bill Murray, che interpreta il ruolo di M. Ivan, ha girato tutte le sue scene in soli quattro giorni a causa di impegni concomitanti. Wes Anderson ha strutturato la sua presenza in modo tale da massimizzare l''impatto comico e narrativo nonostante la brevità della permanenza sul set tedesco.', 'Intervista ufficiale al cast e note di produzione della 20th Century Fox', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 1, '2026-11-04T19:53:39.47239+00:00'),
('8ead9a07-f444-4e2e-8e50-c5c605681291', 376, 'Segreti di produzione', 'L''uso di modelli in scala ridotta per l''albergo', 'Invece di ricorrere a costose immagini generate al computer per l''esterno del Grand Budapest Hotel, la produzione ha utilizzato un modello in scala alto circa tre metri realizzato dal dipartimento artistico di Adam Stockhausen. Questo approccio artigianale riflette lo stile visivo unico e nostalgico voluto da Wes Anderson.', 'Making-of ufficiale ''The Making of Grand Budapest Hotel'' e featurette tecniche', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 2, '2026-11-04T19:53:39.47239+00:00'),
('73d84cba-9f11-4cdc-b7d7-b7d74329a9b0', 376, 'Casting & Scelte', 'Saoirse Ronan scelta senza provino tradizionale', 'L''attrice Saoirse Ronan ha ottenuto la parte della pasticcera Agatha senza dover sostenere un provino formale. Wes Anderson le ha offerto direttamente il ruolo dopo averla vista in ''Espiazione'' (Atonement) e dopo un incontro informale a Londra.', 'Intervista promozionale a Saoirse Ronan per EW e note di casting ufficiali', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 3, '2026-11-04T19:53:39.47239+00:00'),
('f7be4d2f-0da5-4407-8967-498ca3e9e686', 376, 'Effetti speciali & Trucco', 'Il dipinto rinascimentale ''Boy with Apple''', 'Il celebre dipinto ''Boy with Apple'' al centro della trama non è un''opera d''arte preesistente, ma è stato commissionato appositamente dal regista al pittore Michael Taylor. L''artista ha impiegato mesi per realizzare il quadro, combinando elementi stilistici di vari pittori fiamminghi e rinascimentali.', 'Commento audio del regista Wes Anderson nell''edizione Blu-ray Criterion', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 4, '2026-11-04T19:53:39.47239+00:00'),
('c6c83d20-cf7c-4c19-97fe-0eb4b3c4db48', 376, 'Curiosità & Retroscena', 'Ispirazione letteraria basata su Stefan Zweig', 'L''intera struttura narrativa del film e l''atmosfera decadente della Mitteleuropa sono state profondamente ispirate dai romanzi e dalle memorie dello scrittore austriaco Stefan Zweig, in particolare dalla sua autobiografia ''Il mondo di ieri''. Wes Anderson ha ammesso di aver concepito il film leggendo le opere di Zweig durante un viaggio in treno.', 'Note di regia ufficiali e intervista a Wes Anderson sul Guardian', TRUE, 'mrtrrt67@gmail.com', 'IA Verificata', 0, 5, '2026-11-04T19:53:39.47239+00:00'),
('4d5fbce2-aa3a-4fef-81af-d3e7ae38cc68', 167, 'Casting & Scelte', 'L''ingresso di Tyler, The Creator nel cast', 'Il celebre musicista e produttore Tyler, The Creator è stato ufficialmente ingaggiato per affiancare Timothée Chalamet nel cast principale, segnando una delle sue partecipazioni cinematografiche più rilevanti in un lungometraggio di finzione.', 'Comunicati di produzione e report di casting ufficiali', TRUE, 'IA (Admin)', 'IA Verificata', 2, 1, '2026-11-02T17:56:06.149445+00:00'),
('a8257fcb-f490-4173-99cf-defbd8819c98', 167, 'Curiosità & Retroscena', 'Ispirazione alla vita di Marty Reisman', 'Il progetto nasce come un adattamento liberamente ispirato alla vita e alla carriera di Marty Reisman, leggendario e iconico campione di tennistavolo noto negli Stati Uniti per il suo stile eccentrico e le sue scommesse.', 'Note di produzione e sinossi ufficiale A24', TRUE, 'IA (Admin)', 'IA Verificata', 1, 2, '2026-11-02T17:56:06.149445+00:00'),
('87f6e228-8c4b-41b7-89c8-ee54f06f4f13', 167, 'Segreti di produzione', 'La partnership produttiva con A24', 'Il film è stato sviluppato e finanziato dalla casa di produzione indipendente A24, che ha collaborato strettamente con il regista Josh Safdie per ricreare le atmosfere dell''America degli anni Cinquanta.', 'Database ufficiale A24 e annunci di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 1, 3, '2026-11-02T17:56:06.149445+00:00'),
('9d75fd66-c293-4191-b536-be22a3b0a25e', 167, 'Casting & Scelte', 'Il coinvolgimento di Gwyneth Paltrow e Penn Jillette', 'Il cast di supporto vede la partecipazione di Gwyneth Paltrow, al suo ritorno in un ruolo di primo piano sul grande schermo, e del celebre illusionista Penn Jillette, scelto per un ruolo di carattere.', 'Call sheet e annunci ufficiali di casting', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T17:56:06.149445+00:00'),
('9c0a0645-4793-4b52-a44e-b999887327d8', 167, 'Aneddoti dal set', 'Allenamenti intensivi di tennistavolo per Chalamet', 'Per interpretare in modo credibile un campione di ping pong degli anni Cinquanta, Timothée Chalamet si è sottoposto a mesi di preparazione atletica e pratica intensiva con giocatori professionisti prima di iniziare le riprese.', 'Interviste dal set e report di lavorazione', TRUE, 'IA (Admin)', 'IA Verificata', 1, 5, '2026-11-02T17:56:06.149445+00:00'),
('36dac6f0-90d6-4208-9125-e9ca66f4074e', 2, 'Casting & Scelte', 'La perdita di peso lampo di Joaquin Phoenix', 'Per interpretare il tirannico imperatore Commodo, Joaquin Phoenix dovette sottoporsi a una rapida e drastica perdita di peso. L''attore aveva infatti accumulato molti chili per il suo precedente ruolo nel film ''Quills'' (2000) e dovette snellire drasticamente la sua figura in poch settimane prima di indossare le vesti imperiali.', 'Audio commento del regista Ridley Scott nell''edizione Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T08:50:55.947094+00:00'),
('5badb6af-1cb5-4ebc-9537-73952286b8ea', 2, 'Segreti di produzione', 'La sceneggiatura riscritta durante le riprese', 'Il film iniziò le riprese a Malta nel gennaio 2000 nonostante la sceneggiatura fosse incompleta e considerata insoddisfacente da Russell Crowe. L''attore rifiutò interi passaggi di dialogo originali considerati inadatti al personaggio, costringendo gli sceneggiatori David Franzoni e John Logan a riscrivere le scene giorno per giorno sul set.', 'Intervista a Russell Crowe per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T08:50:55.947094+00:00'),
('acd79126-8e23-4c95-b82b-1137921b556a', 2, 'Effetti speciali & Trucco', 'L''armatura in cuoio al posto del metallo', 'Per garantire maggiore agilità durante i combattimenti e le scene di battaglia, la costumista Janty Yates scelse di realizzare la corazza principale di Massimo Decimo Meridio in vero cuoio bollito invece che in metallo pesante. Questa scelta permise a Russell Crowe di muoversi liberamente e di eseguire personalmente la maggior parte delle acrobazie.', 'Documentario ufficiale ''Strength and Honor: Creating the World of Gladiator''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T08:50:55.947094+00:00'),
('449dee95-f480-473c-a767-c6ded63b8143', 2, 'Aneddoti dal set', 'L''infortunio al tendine d''Achille di Russell Crowe', 'Durante la complessa sequenza della battaglia iniziale nella foresta di Germania, Russell Crowe subì un serio infortunio strappandosi il tendine d''Achille del piede destro. A causa del dolore e per non bloccare la produzione, l''attore continuò a girare nascosto dai tagli di montaggio e dovette indossare un supporto ortopedico per diverse settimane.', 'Intervista retrospettiva al settimanale Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T08:50:55.947094+00:00'),
('5e4f176d-6fe5-4a3e-be3f-2dccc41786b8', 2, 'Casting & Scelte', 'Il rifiuto iniziale di Russell Crowe', 'Inizialmente Russell Crowe mostrò forti resistenze ad accettare il ruolo di Massimo perché trovava la prima stesura del copione troppo simile al film ''La caduta dell''Impero Romano'' (1964). Fu convinto ad accettare solo quando Ridley Scott gli assicurò che avrebbe avuto totale libertà creativa per ridefinire la profondità emotiva del personaggio.', 'Libro ''Ridley Scott: The Making of Gladiator''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T08:50:55.947094+00:00'),
('670f8ecf-ada2-485c-9928-de78e5e3942c', 3, 'Curiosità & Retroscena', 'L''ispirazione giapponese di J.J. Abrams', 'L''idea per il film è venuta al produttore J.J. Abrams durante un viaggio a Tokyo nel 2006, dove si rese conto che gli Stati Uniti avevano sì King Kong, ma non avevano un loro iconico mostro nazionale paragonabile a Godzilla.', 'Intervista ufficiale a J.J. Abrams per il press junket del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:28:07.059132+00:00'),
('baa74d19-9d19-45e1-b9c5-dbaab6d5685c', 3, 'Citazioni & Easter Egg', 'Il nome della statua sulla locandina', 'Il poster promozionale originale mostrava la testa mozzata della Statua della Libertà precipitata a Manhattan; la posizione della testa e dei detriti fu accuratamente studiata per coincidere con la scala reale dei monumenti di New York.', 'Note di produzione e commento audio del regista Matt Reeves', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:28:07.059132+00:00'),
('3672813d-d864-4049-ad2a-c9532b32b6bc', 3, 'Casting & Scelte', 'Il provino basato su Lost', 'Dato il rigido embargo informativo imposto dalla Bad Robot, Lizzy Caplan e gli altri attori durante le audizioni non ricevettero alcun copione di Cloverfield, ma dovettero recitare scene tratte da un episodio della serie televisiva Lost.', 'Intervista a Lizzy Caplan per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:28:07.059132+00:00'),
('e51cc1f7-dec8-4ba5-a35d-e60bf7b78b71', 4, 'Casting & Scelte', 'Il rifiuto di Lauren Holly per il ruolo di Melissa Robinson', 'Prima che la parte di Melissa Robinson andasse a Courteney Cox, il ruolo fu offerto a Lauren Holly, che rifiutò l''offerta. Curiosamente, la stessa Holly avrebbe poi sposato Jim Carrey nel 1996, due anni dopo l''uscita del film.', 'Note di casting ufficiali e biografia di Jim Carrey', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:29:13.660293+00:00'),
('0833be92-7412-49f1-918b-eb555952da98', 4, 'Casting & Scelte', 'Il provino rifiutato da Judd Nelson', 'I produttori James G. Robinson e David C. Robinson considerarono diversi attori per la parte del protagonista prima di scommettere su Jim Carrey. Tra questi fu contattato anche Judd Nelson, che tuttavia declinò l''offerta di sostenere un provino per la parte.', 'Archivio di produzione Morgan Creek Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:29:13.660293+00:00'),
('92782ac6-ca6e-4b20-85c6-56c625143918', 4, 'Aneddoti dal set', 'Il salvataggio del cane durante le riprese', 'Durante le riprese della sequenza in cui Ace Ventura entra nell''appartamento pieno di animali, Jim Carrey dimostrò il suo amore per gli animali intervenendo personalmente per evitare che un cane sul set si ferisse a causa di un cavo elettrico scoperto.', 'Documentario dietro le quinte ''Pet Detective: The Making of Ace Ventura''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:29:13.660293+00:00'),
('73ff026e-2d5b-4799-82b3-ccd4c7c1f525', 4, 'Curiosità & Retroscena', 'La nomination ai Razzie Awards e il successivo successo commerciale', 'Nonostante sia diventato un cult e un enorme successo al botteghino con oltre 107 milioni di dollari incassati a fronte di un budget di soli 15 milioni, all''uscita nelle sale Jim Carrey ricevette una nomination ai Razzie Awards come Peggior attore esordiente.', 'Database ufficiale dei Razzie Awards e dati box office Box Office Mojo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:29:13.660293+00:00'),
('16bff3a5-a791-47c8-9f64-4368474e7d8a', 4, 'Casting & Scelte', 'Il cameo mancato di O.J. Simpson', 'Inizialmente, per il ruolo del giocatore dei Miami Dolphins caduto in disgrazia, la produzione aveva valutato l''ingaggio di O.J. Simpson prima che la parte di Ray Finkle venisse definitivamente assegnata a Sean Young (e interpretata in campo da Lyle Alzado/Nick Chinlund).', 'Intervista al regista Tom Shadyac per l''edizione anniversario in Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:29:13.660293+00:00'),
('4156f12d-33d0-4769-b451-267a4d45f951', 96, 'Segreti di produzione', 'Dalle origini virali su YouTube al lungometraggio', 'Il film nasce dall''omonima e celebre serie di cortometraggi horror creata da Kane Parsons a partire dal 2022 su YouTube quando aveva solo sedici anni, catturando l''attenzione globale per la sua estetica found footage basata su Blender e Adobe After Effects.', 'Comunicato ufficiale A24 e interviste di lancio', TRUE, 'IA (Admin)', 'IA Verificata', 4, 1, '2026-11-02T17:56:29.865565+00:00'),
('419e7012-22b2-48e4-a9fb-bea13d3b1f7b', 6, 'Segreti di produzione', 'Il divieto assoluto dei termini Mafia e Cosa Nostra', 'In seguito alle forti pressioni dell''Italian-American Civil Rights League guidata dal boss Joe Colombo, il produttore Al Ruddy firmò un accordo stringente. Nel copione finale del film i termini ''Mafia'' e ''Cosa Nostra'' vennero del tutto eliminati e sostituiti con riferimenti generici alle ''famiglie''.', 'Documentario ufficiale Paramount ''The Godfather Family: A Look Inside''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:30:34.504381+00:00'),
('595d026e-46e7-44a1-a99c-f37c920b822b', 96, 'Casting & Scelte', 'Il coinvolgimento di Ashwin De Silva', 'Accanto al giovanissimo regista Kane Parsons che compare direttamente nel progetto, il cast principale vede la partecipazione di Ashwin De Silva, confermando una produzione indipendente focalizzata su un nucleo ristretto di collaboratori.', 'Note di produzione ufficiali A24', TRUE, 'IA (Admin)', 'IA Verificata', 5, 2, '2026-11-02T17:56:29.865565+00:00'),
('5bcb4ca8-5e66-4234-9ccc-469074df662c', 6, 'Aneddoti dal set', 'I cartelli con le battute (Cue Cards) di Marlon Brando', 'Marlon Brando si rifiutò di memorizzare gran parte delle battute, sostenendo che la lettura spontanea rendesse la recitazione più naturale. La troupe fu costretta a nascondere cartelli con il testo dietro le lampade, sui cespugli e perfino appiccicati sul petto degli altri attori fuori campo.', 'Interviste di produzione e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:30:34.504381+00:00'),
('4b45883a-ea8c-493f-8f81-9915d82d7f32', 6, 'Curiosità & Retroscena', 'La squalifica agli Oscar per la colonna sonora di Nino Rota', 'La celebre colonna sonora di Nino Rota ricevette inizialmente una candidatura all''Oscar nel 1973, ma venne squalificata prima della cerimonia. L''Academy scoprì infatti che Rota aveva riutilizzato una melodia da lui già composta per il film italiano del 1958 ''Fortunella'' di Eduardo De Filippo.', 'Archivi ufficiali dell''Academy of Motion Picture Arts and Sciences', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:30:34.504381+00:00'),
('bab91464-b841-4d90-895e-9cee4672fffe', 6, 'Aneddoti dal set', 'L''ansia reale di Lenny Montana trasformata in battuta', 'Lenny Montana, ex lottatore ingaggiato per il ruolo di Luca Brasi, era talmente terrorizzato all''idea di recitare di fronte a Marlon Brando da sbagliare continuamente il suo discorso. Coppola girò così una scena in cui Brasi ripassa i ringraziamenti in giardino, trasformando la reale ansia dell''attore in una sfaccettatura del personaggio.', 'Commento audio DVD di Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:30:34.504381+00:00'),
('a25c920a-2458-4277-99dc-5669152178fb', 6, 'Aneddoti dal set', 'Le goliardiche gare di ''mooning'' sul set', 'Per allentare la forte tensione del set, Marlon Brando, Robert Duvall e James Caan diedero vita a una competizione a chi mostrasse più spesso il sedere a colleghi e troupe. La sfida culminò durante la scena del matrimonio, quando Brando mostrò il fondoschiena davanti a quasi 500 comparse sbalordite.', 'Autobiografia di Marlon Brando ''Songs My Mother Taught Me''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:30:34.504381+00:00'),
('feeeb509-7e66-412c-845d-8af98446532e', 6, 'Segreti di produzione', 'Il montaggio della guerra di mafia curato da George Lucas', 'Francis Ford Coppola chiese aiuto al suo caro amico George Lucas per realizzare la rapida sequenza di montaggio che illustra lo scoppio della guerra tra le famiglie. Lucas assemblò i ritagli di giornale e le riprese di repertorio come favore personale senza chiedere alcun accredito nei titoli di coda.', 'Making-of ufficiale ''The Godfather Supporter Pack''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T09:30:34.504381+00:00'),
('9addf27a-7846-4127-82d4-34032dfb97b9', 6, 'Curiosità & Retroscena', 'Il rifiuto del premio Oscar da parte di Marlon Brando', 'Marlon Brando vinse l''Oscar come miglior attore protagonista per il ruolo di Vito Corleone, ma boicottò la cerimonia di premiazione del 1973. Al suo posto inviò sul palco l''attivista nativa americana Sacheen Littlefeather per rifiutare la statuetta in segno di protesta contro lo stereotipato trattamento degli indigeni a Hollywood.', 'Archivi storici degli Academy Awards (45ª edizione)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T09:30:34.504381+00:00'),
('ac61dafc-b5e2-4447-946b-46093913bce8', 6, 'Aneddoti dal set', 'L''improvvisazione violenta di James Caan con il reporter', 'Durante le riprese del matrimonio, James Caan (Sonny Corleone) improvvisò completamente la scena in cui afferra la macchina fotografica di un agente dell''FBI in incognito, la distrugge a terra e poi gli lancia delle banconote per ripagarla. Lo sconcerto della comparsa fu assolutamente reale.', 'Intervista a James Caan negli archivi dell''American Film Institute', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 8, '2026-11-02T09:30:34.504381+00:00'),
('7225f7f9-0db9-47f3-aeae-12d914d8e59e', 6, 'Segreti di produzione', 'Francis Ford Coppola a un passo dal licenziamento', 'Nelle prime settimane di riprese la Paramount era estremamente insoddisfatta del girato di Coppola, considerato privo di azione e dal ritmo troppo lento. Il regista rischiò di essere sostituito da Elia Kazan, ma il sostegno categorico di Marlon Brando e il montaggio provvisorio della scena del ristorante con Sollozzo salvarono la sua regia.', 'Autobiografia produttiva di Peter Biskind ''Easy Riders, Raging Bulls''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 9, '2026-11-02T09:30:34.504381+00:00'),
('9b222654-8756-497c-ba1f-1fe51b14496c', 7, 'Segreti di produzione', 'La causa legale sul titolo originario', 'Durante le prime fasi di sviluppo e pre-produzione, la Paramount Pictures intendeva intitolare ufficialmente il film ''Mario Puzo''s The Godfather Part II''. Tuttavia, la produzione dovette affrontare dispute contrattuali e pressioni legali riguardo ai crediti e ai diritti d''autore legati al nome dello scrittore, risolte poi adottando il titolo definitivo.', 'Documenti d''archivio della Paramount Pictures e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:31:29.740457+00:00'),
('a6a3e8dc-3a15-4f0e-ad3c-08bdf4373356', 7, 'Curiosità & Retroscena', 'La riscrittura notturna del finale', 'La celebre sequenza del flashback finale in cui i fratelli Corleone si riuniscono a tavola prima dell''attacco a Pearl Harbor fu riscritta in gran parte da Francis Ford Coppola e Mario Puzo la notte prima delle riprese, poiché la scenografia e i costumi erano già pronti ma il dialogo originale non convinceva il regista sulla rottura emotiva della famiglia.', 'Audio commento ufficiale del regista Francis Ford Coppola', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:31:29.740457+00:00'),
('652b4d0c-4332-482a-91ba-c1668884cedc', 7, 'Casting & Scelte', 'Il compenso record rifiutato da Richard Castellano', 'Richard Castellano, che nel primo film interpretava il caporegime Peter Clemenza, avrebbe dovuto riprendere il suo ruolo anche nel sequel, ma rifiutò l''offerta della produzione perché pretendeva di poter controllare personalmente le battute del suo personaggio scritte da Mario Puzo.', 'Biografie ufficiali e cronache di casting della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:31:29.740457+00:00'),
('e438ae83-7bb9-4a16-bbbd-ec60b722c5b4', 7, 'Aneddoti dal set', 'L''improvvisazione di Michael V. Gazzo nella scena dell''interrogatorio', 'Durante la tesa scena dell''audizione del Senato, l''attore Michael V. Gazzo (Frankie Pentangeli) improvvisò alcuni gesti di stanchezza e battute fuori copione per aumentare il realismo del personaggio sotto pressione, spingendo le reazioni genuine di stupore negli altri attori presenti.', 'Making-of ''The Godfather: The Complete Epic''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:31:29.740457+00:00'),
('d4012029-516c-4bfa-89fa-6fb05ffe91d6', 8, 'Curiosità & Retroscena', 'L''ispirazione reale per la morte di Papa Luciani', 'La trama incentrata sulla morte improvvisa di Papa Giovanni Paolo I (rappresentato nel film come Papa Giovanni Paolo I / Lucian) e sugli scandali dello IOR e del Banco Ambrosiano fu scritta da Francis Ford Coppola e Mario Puzo traendo ispirazione diretta dalle inchieste giornalistiche dell''epoca sul misterioso decesso di Albino Luciani nel 1978.', 'Commento audio del regista nel Blu-ray ufficiale e note di sceneggiatura', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:32:22.696776+00:00'),
('2a970db9-dd9c-434f-b5c1-3ae8c5577691', 8, 'Casting & Scelte', 'Il rifiuto di Sylvester Stallone per il ruolo di Vincent Mancini', 'Prima che la parte del violento e ambizioso Vincent Mancini venisse assegnata ad Andy García (che ottenne anche una nomination all''Oscar), Sylvester Stallone espresse apertamente il proprio interesse per il ruolo, ma la produzione e Coppola scelsero di puntare su un attore non legato a franchise d''azione così ingombranti.', 'Archivi storici della Paramount Pictures e biografie del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:32:22.696776+00:00'),
('3d36cb66-2833-46c7-92d0-1349bc19cda9', 8, 'Segreti di produzione', 'La ricostruzione del set del Vaticano a Cinecittà', 'Poiché il Vaticano negò i permessi per girare all''interno dei veri palazzi apostolici e della Basilica di San Pietro a causa dei temi controversi della sceneggiatura, lo scenografo Dante Ferretti dovette ricostruire meticolosamente imponenti repliche degli interni ecclesiastici negli studi di Cinecittà a Roma.', 'Documentario ''The Godfather Family: A Look Inside'' e interviste a Dante Ferretti', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:32:22.696776+00:00'),
('c688ee67-5899-49f7-8cb5-78ce65c09bae', 8, 'Segreti di produzione', 'Il compenso record rifiutato da Al Pacino in un primo momento', 'Nei primi stadi di sviluppo del progetto, Al Pacino richiese un compenso di ben 7 milioni di dollari più una percentuale sugli incassi per tornare a vestire i panni di Michael Corleone; la Paramount rifiutò categoricamente l''offerta iniziale, costringendo Coppola e Puzo a riscrivere temporaneamente la sceneggiatura eliminando il personaggio di Michael prima di raggiungere un accordo economico al ribasso.', 'Biografie ufficiali di Francis Ford Coppola e documenti finanziari della Paramount', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:32:22.696776+00:00'),
('e425bac9-da09-4f87-a1a1-63ea3c75e873', 8, 'Aneddoti dal set', 'L''infortunio alla mano di Andy García sul set', 'Durante le riprese della sequenza della sparatoria al ristorante in cui i sicari di Joey Zasa attaccano Michael Corleone, l''attore Andy García si ferì realmente a una mano rompendo un bicchiere di vetro durante una colluttazione coreografata, ma continuò a recitare rimanendo nella parte fino allo stop del regista.', 'Giornali di bordo della produzione e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:32:22.696776+00:00'),
('7b957bc7-5084-49c7-af46-8c6e56612039', 10, 'Curiosità & Retroscena', 'Il ban nella Repubblica Popolare Cinese', 'Il film fu bandito dal governo della Repubblica Popolare Cinese a causa della rappresentazione negativa e stereotipata che veniva fatta della popolazione cinese e delle autorità locali nella sequenza iniziale ambientata a Shanghai.', 'Documenti storici di distribuzione e censura cinematografica', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:33:07.813668+00:00'),
('2e6109a7-6c0c-4db5-8fa9-3378fc6c46f4', 10, 'Curiosità & Retroscena', 'La censura della scena del cuore in India', 'Il governo indiano vietò temporaneamente la proiezione del film nel paese nel 1984, accusando la pellicola di promuovere stereotipi razzisti e offensivi nei confronti della cultura e delle tradizioni locali attraverso il culto inventato dei Thuggee.', 'Archivi storici del Ministero dell''Informazione indiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:33:07.813668+00:00'),
('a5ac7458-9ef8-43b6-bce6-57fcd01dd130', 10, 'Casting & Scelte', 'La sostituzione forzata di Victor Banerjee', 'L''attore indiano Victor Banerjee, noto per aver interpretato Passaggio in India di David Lean, era stato originariamente scelto per un ruolo di rilievo nel film, ma dovette rinunciare all''ultimo minuto a causa di conflitti di programmazione.', 'Note di produzione e casting della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:33:07.813668+00:00'),
('e9791edb-9ba9-4104-969d-f5d0a3d91d0e', 10, 'Aneddoti dal set', 'Il malore da altitudine di Harrison Ford', 'Durante le riprese delle scene montane girate nelle zone di alta quota vicino a Kandy, in Sri Lanka, parte della troupe e lo stesso Harrison Ford soffrirono di lievi malori dovuti alla rarefazione dell''aria e alla fatica fisica.', 'Diario di lavorazione della troupe di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:33:07.813668+00:00'),
('5024d2b7-679b-4506-aa49-11cb563ef01d', 10, 'Effetti speciali & Trucco', 'L''uso di carne finta e crema pasticcera nei banchetti', 'Per girare la celebre sequenza del banchetto a Pankot senza danneggiare la salute degli attori, gli specialisti degli effetti speciali guidati da Tom Smith crearono i piatti esotici combinando crema pasticcera, coloranti alimentari, pezzi di carne finta e pasta di riso colorata.', 'Making-of ufficiale ''The Making of Indiana Jones and the Temple of Doom''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:33:07.813668+00:00'),
('d73d27de-3a7c-4121-b573-2acfaa6c2fd7', 10, 'Aneddoti dal set', 'I veri serpenti sul set', 'Nonostante la presenza di molti esemplari finti, per la scena in cui la stanza di Willie Scott si riempie di serpenti furono impiegati oltre duemila serpenti veri, per la maggior parte pitoni non velenosi raccolti da allevatori locali dello Sri Lanka.', 'Intervista al reparto scenografia e coordinamento animali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:33:07.813668+00:00'),
('73ab4394-07a6-4e83-9963-47ff343a33ae', 11, 'Curiosità & Retroscena', 'Il cameo mancato di George Lucas', 'Il produttore esecutivo e co-ideatore George Lucas avrebbe dovuto fare un breve cameo nel film nei panni di uno dei turisti nella stazione ferroviaria di Berlino, ma alla fine l''idea fu scartata durante il montaggio.', 'Documentario ufficiale ''The Making of Indiana Jones and the Last Crusade''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:33:54.072247+00:00'),
('0d29cd08-ba29-4e14-a2f8-b71512d7d4c9', 11, 'Citazioni & Easter Egg', 'La scelta del vero nome di Indiana Jones', 'Il momento in cui viene rivelato che ''Indiana'' era il nome del cane di famiglia riprende esattamente l''origine del nome del cane di George Lucas, l''Alaskan Malamute che ispirò anche il personaggio di Chewbecca in Star Wars.', 'Note di produzione e interviste storiche a George Lucas', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:33:54.072247+00:00'),
('282ff112-4524-4d4d-9964-40af467054a3', 11, 'Casting & Scelte', 'La vera nazionalità del cattivo Walter Donovan', 'L''attore Julian Glover, che interpreta l''antagonista Walter Donovan, aveva precedentemente interpretato il generale Maximilian Veers in ''L''Impero colpisce ancora'' e il cattivo principale in un film di James Bond, ''Solo per i tuoi occhi''.', 'Archivio ufficiale della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:33:54.072247+00:00'),
('b2ddfb58-2f7c-49e9-9723-a080990f1125', 11, 'Effetti speciali & Trucco', 'I gabbiani telecomandati per la scena dell''aereo', 'Per girare la sequenza in cui l''aeroplano pilotato da Henry Jones Sr. colpisce uno stormo di gabbiani facendone precipitare uno, la produzione utilizzò volatili meccanici telecomandati costruiti dal reparto effetti speciali.', 'Special TV ''The Making of Indiana Jones and the Last Crusade''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:33:54.072247+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('8045f0f8-172d-434e-83b9-a1b4c2a5cd3e', 12, 'Segreti di produzione', 'La sceneggiatura rifiutata di Frank Darabont', 'Prima della stesura finale firmata da David Koepp, lo sceneggiatore Frank Darabont trascorse oltre un anno a scrivere una bozza intitolata ''Indiana Jones and the City of Gods''. Nonostante Steven Spielberg l''avesse definita la migliore sceneggiatura letta dai tempi dei ''Predatori dell''arca perduta'', George Lucas la bocciò categoricamente costringendo la produzione a ripartire da capo.', 'Intervista a Frank Darabont / Note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:34:45.364935+00:00'),
('a280a355-68a4-4e34-83b5-8f16243212d9', 12, 'Curiosità & Retroscena', 'Il furto di foto dal set e l''operazione sotto copertura', 'Nel settembre 2007, un uomo di nome Roderick Davis rubò oltre 2.000 foto di produzione, bozzetti e documenti riservati dagli uffici della produzione. L''uomo tentò di vendere il materiale ai siti di gossip per diverse migliaia di dollari, ma venne incastrato e arrestato a Los Angeles grazie a un''operazione sotto copertura organizzata dalle forze dell''ordine e da Lucasfilm.', 'Dichiarazioni ufficiali del LAPD / Los Angeles Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:34:45.364935+00:00'),
('3059422a-252e-4aee-87c3-bb51cd935f97', 64, 'Casting & Scelte', 'La sostituzione in extremis per Will Scarlet', 'Il ruolo di Will Scarlet fu originariamente affidato all''attore Patrick Knowles, ma a causa di disaccordi contrattuali iniziali con la Warner Bros. fu brevemente rimpiazzato prima di essere definitivamente confermato nel cast.', 'Archivi storici di casting della Warner Bros. Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:54:10.120391+00:00'),
('d9cd1e5f-28d5-45ab-9cd1-4169a856ddff', 12, 'Aneddoti dal set', 'L''infortunio di Shia LaBeouf durante il duello sulle Jeep', 'Durante le riprese del duello a colpi di spada mentre i personaggi bilanciano i piedi su due Jeep in corsa nella giungla, Shia LaBeouf subì uno stiramento inguinale piuttosto grave. L''infortunio rallentò la lavorazione e costrinse la produzione a riorganizzare il piano di riprese per consentire all''attore di recuperare senza abbandonare le scene d''azione.', 'Documentario ''Making the Kingdom of the Crystal Skull''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:34:45.364935+00:00'),
('98612042-3b0a-4e25-9e32-0c83a3d10430', 12, 'Curiosità & Retroscena', 'La nascita del termine pop ''Nuke the Fridge''', 'La sequenza in cui Indiana Jones sopravvive a un''esplosione nucleare all''interno di un frigorifero piombato diede origine alla celebre espressione idiomatica ''Nuke the Fridge''. Il termine è diventato un frequente neologismo della cultura pop per indicare il momento esatto in cui un franchise di successo va oltre i limiti dell''assurdo e della sospensione della incredulità.', 'Oxford Dictionary of Modern Slang / Analisi dei media', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:34:45.364935+00:00'),
('073c455f-aeb4-420d-95ff-bf978549b08f', 12, 'Segreti di produzione', 'Gli artigiani del fedora targati Adventure Bilt', 'Per ricreare fedelmente l''iconico fedora di Indiana Jones, la costumista Mary Zophres si affidò ai cappellai Steve Delk e Marc Kitter della Adventure Bilt Hat Company. La produzione ordinò circa 30 esemplari identici realizzati in feltro di castoro per resistere alle continue sollecitazioni delle riprese e degli stuntman.', 'Making-of ufficiale del reparto costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:34:45.364935+00:00'),
('f629d45d-5bb4-475e-94f4-d4bc9456a323', 13, 'Aneddoti dal set', 'La reazione di Harrison Ford durante la scena a cavallo', 'Durante le riprese della sequenza dell''inseguimento a cavallo nella metropolitana, tre stuntman si sono affrettati ad assistere l''ottantenne Harrison Ford per aiutarlo a scendere dall''animale. L''attore li ha prontamente allontanati esclamando che voleva sembrare un uomo anziano che smonta da cavallo, insistendo per completare il gesto in totale autonomia.', 'Intervista a Harrison Ford su Esquire', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:35:23.244003+00:00'),
('79c53dcf-89b7-40ef-bf85-5bb3d66c5aa9', 13, 'Casting & Scelte', 'L''ispirazione storica per l''antagonista Jürgen Voller', 'Mads Mikkelsen e il regista James Mangold hanno basato la caratterizzazione del villain su Wernher von Braun, lo scienziato nazista reclutato dagli Stati Uniti dopo la Seconda Guerra Mondiale nell''ambito dell''Operazione Paperclip. Nel film, Voller lavora proprio per la NASA alla realizzazione del programma spaziale Apollo.', 'Note di produzione ufficiali / Intervista a Mads Mikkelsen', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:35:23.244003+00:00'),
('652312af-37dc-4d18-84fe-e8c5e375e05a', 13, 'Curiosità & Retroscena', 'La Palma d''Oro d''Onore a sorpresa a Cannes', 'In occasione dell''anteprima mondiale del film al Festival di Cannes nel maggio 2023, Harrison Ford è stato insignito a sorpresa della Palma d''Oro d''Onore alla carriera. L''omaggio non era stato preannunciato nella scaletta ufficiale ed è stato consegnato direttamente dal direttore del festival Thierry Frémaux prima della proiezione.', 'Copertura stampa ufficiale Festival di Cannes 2023', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:35:23.244003+00:00'),
('a1569298-4ec2-4818-8367-01b3cd9fe743', 13, 'Casting & Scelte', 'L''ispirazione classica per la recitazione di Phoebe Waller-Bridge', 'Per definire la personalità cinica e brillante di Helena Shaw, il regista ha raccomandato a Phoebe Waller-Bridge di studiare le commedie screwball americane degli anni ''30 e ''40. L''attrice si è ispirata in particolare all''interpretazione di Barbara Stanwyck nel classico ''Lady Eva'' del 1941.', 'Intervista a Phoebe Waller-Bridge su Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:35:23.244003+00:00'),
('a7c7db59-7600-4aa0-8e12-bddb4538729c', 13, 'Segreti di produzione', 'L''imponente lavoro musicale di John Williams', 'Il novantenne John Williams ha composto oltre novanta minuti di musica inedita per la pellicola, incluso il tema dedicato al personaggio di Helena. Nonostante avesse inizialmente espresso l''intenzione di ritirarsi dal cinema dopo questo film, l''accoglienza ricevuta lo ha spinto a ritrattare l''addio definitivo alle colonne sonore.', 'Intervista a John Williams su Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:35:23.244003+00:00'),
('7a057524-43c0-45c6-ab61-67beb9cc8ddd', 13, 'Aneddoti dal set', 'Le riprese reali nel parco archeologico di Siracusa', 'Per girare le sequenze legate alla tomba di Archimede, la produzione ha ottenuto permessi speciali dalle autorità italiane per effettuare le riprese direttamente all''interno del Parco Archeologico della Neapolis a Siracusa. Tra le location reali utilizzate figurano la celebre grotta dell''Orecchio di Dionisio e il Tempio Dorico di Segesta.', 'Reportage di produzione in Sicilia / Sicilia Film Commission', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:35:23.244003+00:00'),
('bcb9075e-e983-4701-9c0b-547a558609f6', 13, 'Curiosità & Retroscena', 'Il rifiuto di Ford di nascondere la propria età anatomica', 'Per la scena nel 1969 in cui Indiana Jones si sveglia a torso nudo nel suo appartamento di New York, la troupe aveva ipotizzato di nascondere la forma fisica dell''attore con un abbigliamento diverso. Harrison Ford ha preteso di mostrare integralmente il proprio fisico ottantenne per dare realismo alle cicatrici e al passare del tempo.', 'Intervista a Harrison Ford su The Hollywood Reporter', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T09:35:23.244003+00:00'),
('b92e0582-d68b-4f4b-9346-30240a37f62b', 13, 'Curiosità & Retroscena', 'La reunion virale tra Harrison Ford e Ke Huy Quan', 'Nel settembre 2022, durante la convention D23 della Disney dove veniva presentato il trailer del film, Harrison Ford e Ke Huy Quan si sono incontrati nel backstage per la prima volta dopo 38 anni dai tempi de ''Il tempio maledetto''. Lo scatto del loro abbraccio commosso è diventato immediatamente un fenomeno virale sui social media.', 'Intervista a Ke Huy Quan su The New York Times', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T09:35:23.244003+00:00'),
('d2e2e7d1-d01f-4691-bfae-8626154b395b', 14, 'Casting & Scelte', 'L''impiego del vero commissario di polizia nel cast', 'Per interpretare il commissario di polizia che indaga sugli omicidi, Nanni Moretti non scelse un attore professionista, ma scritturò un vero funzionario di polizia, l''ispettore capo Remo Remotti, conferendo un tono di inaspettato realismo e asciuttezza alle sequenze degli interrogatori.', 'Note di produzione e dizionario del cinema italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:36:09.580213+00:00'),
('e0d082c0-9382-439c-8b76-fee517ef8ceb', 14, 'Citazioni & Easter Egg', 'Il tributo architettonico al quartiere Prati', 'Gran parte delle riprese in esterni e degli inseguimenti a piedi del professore Michele Apicella si svolgono nel quartiere Prati e lungo le rive del Tevere a Roma, luoghi realmente frequentati da Nanni Moretti nella sua giovinezza e scelti per accentuare il senso di claustrofobia urbana del protagonista.', 'Dizionario dei luoghi cinematografici romani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:36:09.580213+00:00'),
('7ad20dfd-4d70-456a-9d79-ef552d91eb27', 15, 'Curiosità & Retroscena', 'La genesi letteraria dai romanzi di Margery Sharp', 'Il film è tratto dalla serie di libri per bambini scritta dall''autrice britannica Margery Sharp, in particolare dai romanzi ''The Rescuers'' (1959) e ''Miss Bianca'' (1962). La Walt Disney Productions aveva acquistato i diritti cinematografici già a partire dagli anni Sessanta, ma il progetto fu accantonato diverse volte prima di trovare spazio nella seconda metà del decennio successivo.', 'Note di produzione ufficiali degli archivi Disney', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:37:03.365112+00:00'),
('80df2616-c061-477d-b509-13745587ff17', 15, 'Casting & Scelte', 'Il doppiaggio di Madame Medusa e i dissidi con l''attrice', 'Per il ruolo della malvagia Madame Medusa, i registi ingaggiarono l''attrice e comica Geraldine Page. La Page registrò le sue linee vocali in solitaria e, per calarsi al meglio nella isterica e avida personalità del personaggio, richiese di poter gesticolare animatamente e urlare davanti al microfono dello studio di registrazione.', 'Commento audio del Blu-ray ufficiale e making-of d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:37:03.365112+00:00'),
('cd214457-89d3-46f7-b0ba-cfec1bd8b076', 15, 'Segreti di produzione', 'Il riutilizzo di una canzone scartata da Le avventure di Peter Pan', 'La celebre canzone ''La mia terra'' (The Journey), cantata da Penny nell''orfanotrofio, era in realtà un brano composto originariamente dai cantautori Sammy Cahn e Jule Styne per il Classico Disney ''Le avventure di Peter Pan'' del 1953, dove doveva intitolarsi ''Never Smile at a Crocodile'' o brani simili, ma fu tagliata e recuperata oltre vent''anni dopo per questo film.', 'Archivi storici della musica Disney e registrazioni di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:37:03.365112+00:00'),
('c0db8c67-9bcf-4c48-859d-05339b95c463', 15, 'Citazioni & Easter Egg', 'Il nome della libellula Evinrude e il tributo ai motori fuoribordo', 'Il personaggio di Evinrude, la frenetica libellula che funge da motore per la foglia-barca di Bianca e Bernie, prende il nome da Ole Evinrude, inventore norvegese-americano del primo motore fuoribordo di successo commerciale. Il suono del suo ronzio è stato modificato in post-produzione per imitare esattamente il rumore di un piccolo fuoribordo a due tempi.', 'Intervista al supervisore degli effetti sonori e note tecniche di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:37:03.365112+00:00'),
('19a337f9-ab33-4678-8e2a-fae26dc85e26', 15, 'Curiosità & Retroscena', 'La base reale per i due alligatori Brutus e Nero', 'Gli animatori della Disney studiarono il movimento dei rettili reali per dare vita a Brutus e Nero, i due temibili alligatori domestici di Madame Medusa. Per farlo, il leggendario animatore Milt Kahl osservò attentamente il comportamento dei veri alligatori presenti nei parchi zoologici della California, concentrandosi sulla pesantezza dei passi e sulla rapidità dei morsi.', 'Documentario ''The Making of The Rescuers'' e registri degli animatori', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:37:03.365112+00:00'),
('8a83a635-8c7d-4e8e-ab1d-0a8aa5fb2fe8', 15, 'Segreti di produzione', 'La sfida tecnica nell''animare l''acqua della palude', 'La sequenza ambientata nella Baia del Diavolo richiese complesse tecniche di stratificazione dell''animazione per rendere l''effetto torbido e melmoso dell''acqua della palude. Gli artisti utilizzarono sovrapposizioni di acetati semitrasparenti e particolari giochi di ombre per simulare la vegetazione sommersa e i riflessi della luce lunare.', 'Bollettino tecnico della Society of Motion Picture and Television Engineers (SMPTE)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:37:03.365112+00:00'),
('c095ae1a-5c3b-4861-8ecb-5407ab5babca', 16, 'Curiosità & Retroscena', 'La morte di Frank Thomas e la consulenza degli animatori leggendari', 'Durante la produzione del film, i leggendari animatori dei Nine Old Men, in particolare Frank Thomas e Ollie Johnston, visitarono spesso gli studi per visionare il lavoro sul sistema CAPS e offrire consulenze informali sui personaggi, aiutando a mantenere viva la tradizione classica dell''animazione dei personaggi.', 'Documentario The Rescuers Down Under Making-Of', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:37:46.628157+00:00'),
('b448802a-d565-467d-a3b6-29954d083a7c', 16, 'Casting & Scelte', 'Il doppiaggio di Marahute senza dialoghi', 'Il personaggio della maestosa aquila Marahute non pronuncia alcuna parola nel film, ma i suoi versi e i suoi richiami realistici furono realizzati utilizzando registrazioni modificate di veri uccelli rapaci e interventi vocali curati dal sound designer Frank Eble.', 'Note di produzione ufficiali Walt Disney Feature Animation', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:37:46.628157+00:00'),
('c0f4abb5-e48b-4518-9c09-b203e476cc5b', 16, 'Citazioni & Easter Egg', 'Il riferimento visivo a Indiana Jones', 'La sequenza in cui il giovane Cody cade nella trappola sotterranea e affronta il pericolo dei teschi e dei meccanismi di blocco presenta evidenti omaggi visivi e strutturali alla celebre sequenza d''apertura de ''I predatori dell''arca perduta'' di Steven Spielberg.', 'Commento audio del regista Hendel Butoy', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:37:46.628157+00:00'),
('899aac9b-7956-44e7-8d45-206b875d4232', 18, 'Curiosità & Retroscena', 'L''intervento fondamentale di Francesco De Robertis', 'Il film fu ideato inizialmente da Francesco De Robertis, ufficiale della Regia Marina e capo del Centro Cinematografico del Ministero della Marina, che diresse le prime fasi e firmò il soggetto, prima che Rossellini subentrasse nella direzione effettiva sul campo.', 'Archivio Storico del Cinema Italiano e note di produzione originali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:39:29.771742+00:00'),
('f2fd9325-90c0-40b1-ac68-67d64ebf7f0f', 18, 'Segreti di produzione', 'Il contributo fondamentale alla sceneggiatura di Rossellini e Puccini', 'Alla stesura definitiva della sceneggiatura e dei dialoghi collaborò attivamente anche un giovane Massimo Puccini, insieme a Roberto Rossellini e allo stesso Francesco De Robertis, plasmando il materiale documentaristico in una struttura narrativa di finzione.', 'Dizionario del Cinema Italiano di G. Brunetta', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:39:29.771742+00:00'),
('58a5329e-7f38-4a43-b903-22c9c1be53ba', 18, 'Segreti di produzione', 'La collaborazione con la Lux Film di Riccardo Gualino', 'La produzione esecutiva del film fu curata dalla Lux Film di Riccardo Gualino, che scommise sul progetto di propaganda militare trasformandolo in un''opera di transizione cruciale verso il neorealismo cinematografico italiano.', 'Storia del Cinema Italiano vol. VI (Marsilio)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:39:29.771742+00:00'),
('2951005b-cc43-4a0a-9137-b34576bd405f', 18, 'Aneddoti dal set', 'L''uso innovativo della cinepresa in spazi angusti', 'Per girare le complesse scene all''interno dei corridoi stretti e delle sale operatorie della nave ospedale Arno, il direttore della fotografia Arturo Gallea dovette inventare soluzioni di ripresa innovative, usando ottiche particolari e spostando la macchina a mano in spazi ristrettissimi.', 'Memorie e saggi di tecnica cinematografica degli anni ''40', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:39:29.771742+00:00'),
('349e0276-a22a-4e63-8084-d72e8f24dcea', 21, 'Segreti di produzione', 'La genesi del progetto a Loreto', 'Le prime fasi di sviluppo e ideazione di ''Gladiatori di Roma'' sono state interamente concepite e realizzate negli studi della Rainbow CGI a Loreto, nelle Marche, consolidando il polo marchigiano come uno dei centri nevralgici dell''animazione europea.', 'Note di produzione Rainbow CGI', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:40:49.303654+00:00'),
('64cb9ceb-fbe3-4145-a9d1-2b039e3dc67d', 21, 'Casting & Scelte', 'La collaborazione internazionale con Michael Coldey', 'Per la stesura della sceneggiatura, Iginio Straffi ha lavorato a stretto contatto con lo sceneggiatore statunitense Michael Coldey, autore di diverse produzioni animate internazionali, allo scopo di calibrare l''umorismo e i tempi comici per il mercato globale.', 'Dichiarazioni stampa della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:40:49.303654+00:00'),
('7d635c75-079c-4766-8d38-1c83d4b4404f', 21, 'Aneddoti dal set', 'Il lavoro sulle espressioni facciali del cast vocale', 'Durante le sessioni di doppiaggio, la troupe ha utilizzato telecamere fisse puntate sui volti di Luca Argentero e Laura Chiatti per catturare le loro reali micro-espressioni e tradur-le poi in alcuni dettagli visivi dei personaggi animati di Timo e Lucilla.', 'Making-of ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:40:49.303654+00:00'),
('194493ab-49d2-4062-8f94-bd22b54dd860', 26, 'Segreti di produzione', 'L''esordio alla regia solista di Alfonso Brescia', 'Pellicola storica per la carriera di Alfonso Brescia, ''Il magnifico gladiatore'' segna il suo esordio ufficiale e accreditato come unico regista di un lungometraggio, giunto dopo una lunga gavetta come aiuto regista per maestri del cinema di genere e colleghi come Tanio Boccia.', 'Archivio del Cinema Italiano (ANICA) / Dizionario del Cinema Italiano', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:43:39.757695+00:00'),
('36022fb0-fc66-4296-a963-917cd90806fd', 26, 'Curiosità & Retroscena', 'Il riciclaggio televisivo americano nella serie ''Sons of Hercules''', 'Negli Stati Uniti il film fu acquistato dalla Embassy Pictures per la syndication televisiva e inserito nel celebre formato ''Sons of Hercules''. Il titolo venne adattato in ''The Magnificent Gladiator'' e il personaggio di Attalo fu associato al ciclo degli eredi di Ercole esclusivamente per motivi commerciali.', 'Archivi di distribuzione Embassy Pictures / Catalogazione TV USA', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:43:39.757695+00:00'),
('d4ebc8dd-a42e-4669-aa1c-d532328eb7bd', 26, 'Casting & Scelte', 'La doppia vita artistica di Mark Forest tra set e canto lirico', 'Durante i mesi di lavorazione del film a Roma, l''italo-americano Mark Forest (all''anagrafe Lou Degni) alternava le sessioni di ripresa e l''allenamento fisico con rigorose lezioni giornaliere di canto lirico. Questa disciplina intrapresa in Italia gli permise, terminata la stagione del peplum, di affermarsi a New York come tenore e insegnante vocale.', 'Interviste d''epoca a Mark Forest / Archivi attori del peplum', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:43:39.757695+00:00'),
('b2048a03-28af-414e-a3aa-80b97de66b1a', 28, 'Curiosità & Retroscena', 'Il successo al botteghino nell''epoca d''oro del peplum', 'Distribuito nelle sale italiane nel maggio del 1962, il film registrò un incasso totale stimato di circa 312,5 milioni di lire dell''epoca. Questo esito commerciale consolidò il valore di Gordon Scott come uno degli attori americani più redditizi per i produttori italiani di film in costume degli anni Sessanta.', 'Dizionario del Cinema Italiano: I film dal 1960 al 1969 (Poppi-Pecorari)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:44:49.141989+00:00'),
('855d626c-ab64-439b-9290-9b1124be8ea5', 28, 'Segreti di produzione', 'La distribuzione televisiva negli Stati Uniti tramite Seven Arts', 'A differenza dell''Italia, negli Stati Uniti il film non ottenne una classica distribuzione cinematografica nelle sale, ma fu acquistato dalla Seven Arts Television. La società ne curò il doppiaggio in lingua inglese e lo distribuì direttamente nei palinsesti televisivi americani a partire dal 1963 con il titolo ''Gladiator of Rome''.', 'Italian Sword and Sandal Films 1908-1990 (Roy Kinnard, Tony Crnkovich)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:44:49.141989+00:00'),
('6bff7aa4-2a66-40d2-ac1b-1179a86be90a', 31, 'Aneddoti dal set', 'L''esordio di Alfred Molina e l''incubo delle tarantole', 'Nel suo debutto cinematografico nei panni della guida Satipo, Alfred Molina dovette girare la scena del tempio con 50 tarantole vere sulla schiena. I ragni rimanevano immobili perché erano tutti maschi; l''animatore degli effetti visivi dovette aggiungere una tarantola femmina sul corpo dell''attore per scatenare il movimento dell''intero gruppo.', 'Making-of ufficiale di Indiana Jones e i predatori dell''arca perduta', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:46:34.430604+00:00'),
('68ae146e-90aa-40c3-a3ea-158d4fa0539a', 31, 'Curiosità & Retroscena', 'La nascita del personaggio sulle spiagge delle Hawaii', 'Nel maggio 1977, George Lucas e Steven Spielberg si trovavano in vacanza alle Hawaii per sfuggire allo stress dell''uscita di Guerre Stellari. Quando Spielberg espresse il desiderio di dirigere un film di James Bond, Lucas gli propose la sua idea per un film d''avventura basato sui serial degli anni ''30, allora intitolato ''Indiana Smith'', che Spielberg accettò a patto di cambiarne il cognome in Jones.', 'Intervista a Steven Spielberg e George Lucas nei contenuti speciali DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:46:34.430604+00:00'),
('da2cb359-397e-4711-a348-2c41035a5ee4', 31, 'Segreti di produzione', 'Il rumore del macigno creato con un''automobile', 'Il celebre effetto sonoro del gigantesco macigno in pietra che insegue Indiana Jones nella sequenza di apertura non proviene da una roccia. Il designer del suono Ben Burtt registrò il rumore prodotto dalle ruote di una Honda Civic guidata a motore spento lungo una collina sterrata e ghiaiosa.', 'Commento audio del sound designer Ben Burtt', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:46:34.430604+00:00'),
('1feae075-cf66-4888-8b9a-4d48ae16db69', 31, 'Effetti speciali & Trucco', 'Lo scioglimento del volto di Toht senza computer grafica', 'La sconvolgente scena in cui la testa del nazista Toht si scioglie fu realizzata interamente con effetti pratici. Il team di Chris Walas modellò un teschio ricoperto da strati di cera colorata e gelatina, che venne poi fuso posizionandovi davanti lampade a calore ed erogatori d''aria calda, riprendendo il processo a velocità ridotta con una telecamera time-lapse.', 'Archivio Industrial Light & Magic (ILM)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:46:34.430604+00:00'),
('09fec883-4a3a-4189-95ee-a1ac17dc7af3', 31, 'Effetti speciali & Trucco', 'I fantasmi dell''Arca filmati sott''acqua', 'Gli spettrali esseri celestiali che fuoriescono dall''Arca durante il climax finale furono creati immergendo piccoli manichini snodabili vestiti di veli in una vasca d''acqua dipinta di nero. Gli operatori della ILM li mossero a mano riprendendoli a testa in giù ad alta velocità per dare un effetto etereo e fluttuante.', 'Documentario ''The Light & Magic of Raiders of the Lost Ark''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:46:34.430604+00:00'),
('0eb4c035-bb4a-4a56-a199-9a343f977700', 31, 'Casting & Scelte', 'Klaus Kinski rifiutò la parte del villain Toht', 'La prima scelta della produzione per il ruolo del sadico agente della Gestapo Arnold Toht fu l''attore tedesco Klaus Kinski. Kinski rifiutò categoricamente l''offerta definendo la sceneggiatura ''una porcheria banale e priva di senso'', preferendo recitare nel film horror a basso budget ''Venom''.', 'Autobiografia di Klaus Kinski (''Kinski Uncut'')', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:46:34.430604+00:00'),
('159a1aa1-222b-4f6e-bbf3-3b0175d2bde9', 31, 'Segreti di produzione', 'Il sottomarino nazista condiviso con Das Boot', 'La sequenza dell''approdo al covo dei sottomarini nazisti venne girata a La Rochelle, in Francia, all''interno delle vere campate protettive usate dalla Kriegsmarine nella Seconda Guerra Mondiale. Per risparmiare sul budget, la produzione noleggierò il modello di U-Boot a grandezza naturale costruito per il capolavoro tedesco ''U-Boot 96'' (Das Boot).', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T09:46:34.430604+00:00'),
('f01e3d88-0754-43e5-b2ad-c1e940a9e2ef', 31, 'Segreti di produzione', 'L''invecchiamento forzato della giacca di pelle', 'Per evitare che l''iconica giacca di pelle di Indiana Jones sembrasse nuova di zecca appena uscita di fabbrica, la costumista Deborah Nadoolman la sottopose a un duro trattamento di invecchiamento artificiale, carteggiandola con una spazzola metallica e tagliuzzandola con il coltellino da tasca di Harrison Ford prima dell''inizio delle riprese.', 'Intervista alla costumista Deborah Nadoolman Landis', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T09:46:34.430604+00:00'),
('d111de8d-c608-47c1-8b01-b754794b594e', 32, 'Aneddoti dal set', 'L''infortunio sul set di un cascatore', 'Durante le riprese nel giugno 2023 nei pressi di Ouarzazate, in Marocco, un incidente durante una sequenza di stunt ha provocato ustioni non letali a diversi membri della troupe e a stuntman, richiedendo cure mediche immediate ma senza fermare la produzione.', 'Comunicato ufficiale della Paramount Pictures / Variety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:47:22.681322+00:00'),
('34e74ee8-43aa-48e2-a442-3b985a38f36a', 32, 'Curiosità & Retroscena', 'La scelta di tagliare il bacio tra Macrinus e un altro uomo', 'Denzel Washington ha rivelato in un''intervista che nel film era stata girata una scena in cui il suo personaggio, Macrinus, baciava un altro uomo sulla bocca, ma la sequenza è stata infine tagliata dal montaggio finale perché considerata non necessaria alla trama.', 'Intervista di Denzel Washington per Gayety', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:47:22.681322+00:00'),
('c013dbd7-41e2-4b74-bd28-e37feece7e4f', 32, 'Casting & Scelte', 'L''assenza di Russell Crowe nel sequel', 'Russell Crowe ha confermato pubblicamente di non essere stato contattato in alcun modo da Ridley Scott per questo secondo capitolo, dato che il suo personaggio, Massimo Decimo Meridio, era morto alla fine del film del 2000.', 'Dichiarazioni pubbliche di Russell Crowe al podcast Kyle and Jackie O', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:47:22.681322+00:00'),
('4021b64c-e6ca-4e2b-97fd-b52bd472d87e', 32, 'Citazioni & Easter Egg', 'L''omaggio nascosto alla morte di Massimo', 'In una delle prime sequenze in cui Lucio riflette sul passato, la regia inserisce brevi frammenti visivi e sonori manipolati digitalmente tratti direttamente dal duello finale tra Massimo e Commodo nel primo film.', 'Note di produzione ufficiali Paramount Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:47:22.681322+00:00'),
('6ac1a403-ce24-4181-9f95-bbb9767e3982', 33, 'Aneddoti dal set', 'La polmonite sfiorata da Noel Appleby nei panni di Barliman Butterbur', 'Durante le riprese delle scene esterne a Brea vicino a Matamata, l''attore Noel Appleby (che interpretava il locandiere Barliman Butterbur) dovette girare sotto una finta pioggia incessante creata con potenti idranti. La temperatura rigida e l''acqua gelida portarono l''attore a un passo dall''ipotermia e a una grave forma di bronchite, costringendo la troupe a una temporanea interruzione medica.', 'Documentario ufficiale ''The Appendices'' del DVD Extended Edition', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:48:01.259841+00:00'),
('ff08e5c4-3691-4121-92a7-7cf99bc1409d', 33, 'Segreti di produzione', 'La paura dei cavalli di John Rhys-Davies e la controfigura equestre', 'John Rhys-Davies soffriva di una forte avversione e disagio nel lavorare a stretto contatto con i grandi animali sul set. Sebbene il suo personaggio, Gimli, non cavalcasse regolarmente, in molte scene di gruppo in cui i membri della Compagnia dovevano muoversi a cavallo fu necessario l''impiego massiccio di una controfigura e di inquadrature studiate ad hoc per celare l''assenza dell''attore.', 'Commento audio del cast e della troupe nel DVD del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:48:01.259841+00:00'),
('e19ed32e-a5bc-4f9a-b338-61c72eaa561a', 33, 'Effetti speciali & Trucco', 'Le ore di sonno rubate da Liv Tyler per le orecchie da elfo', 'Liv Tyler doveva sottoporsi a sessioni di applicazione delle protesi auriche in lattice lunghe oltre due ore ogni singola mattina. Per evitare di rovinare la delicata colla e le punte durante le pause notturne, in alcune giornate di riprese particolarmente serrate l''attrice fu costretta a indossarle per quasi ventiquattro ore consecutive, dormendo con un cuscino speciale che impedisse di piegarle.', 'Intervista ufficiale dal libro ''The Lord of the Rings: Weapons and Warfare''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:48:01.259841+00:00'),
('21df31ac-4efb-479e-b06a-b0b607ff9b2a', 33, 'Aneddoti dal set', 'La ferita al labbro di Orlando Bloom durante il duello contro i mannari', 'Sebbene la sequenza dell''attacco dei Warg sia stata spostata nel secondo capitolo, la preparazione fisica e l''addestramento con le spade iniziarono già durante la pre-produzione del primo film. Orlando Bloom fu accidentalmente colpito al volto da una spada di gomma durante una sessione di prove di stunt, rimediando una vistosa ferita al labbro superiore che richiese l''intervento dei medici sul set.', 'Diario di produzione ufficiale di Peter Jackson', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:48:01.259841+00:00'),
('631c0b0b-5c00-4d84-9efb-1abf4828c1bb', 33, 'Citazioni & Easter Egg', 'Il cameo nascosto di Peter Jackson nel ruolo di un abitante di Brea', 'Il regista Peter Jackson fa la sua prima apparizione cinematografica nella trilogia proprio ne ''La Compagnia dell''Anello'': mentre la Compagnia entra furtivamente nella locandina del puledro impennato a Brea, Jackson appare brevemente sullo schermo mentre mastica rumorosamente una carota e guarda in camera, indossando un costume da borgo e stringendo un boccale di birra.', 'Contenuti speciali e trivia ufficiale del Blu-ray Disc', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:48:01.259841+00:00'),
('44176271-8ff2-41b0-852d-00165438d009', 34, 'Segreti di produzione', 'La colonna sonora registrata da 25.000 tifosi allo stadio', 'Per registrare l''imponente ruggito dell''armata degli Uruk-hai al Fosso di Helm, Peter Jackson sfruttò una pausa di una partita di cricket al Westpac Stadium di Wellington. Il regista guidò personalmente oltre 25.000 spettatori nel fare il tempo battendo i piedi ed intonando versi in Linguaggio Nero come ''Derum dagon kud!''.', 'Commento audio del regista nel DVD/Blu-ray Extended Edition', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:48:40.628588+00:00'),
('c9b87968-e7ad-4ce7-9f83-b368b18f0a66', 34, 'Aneddoti dal set', 'Il dente spezzato di Viggo Mortensen al Fosso di Helm', 'Durante le riprese dei combattimenti a cavallo al Fosso di Helm, Viggo Mortensen venne colpito al volto da un''arma da scena spezzandosi un dente incisivo. L''attore chiese alla troupe dell''attak per incollarlo sul momento e continuare a girare, ma Peter Jackson lo fermò mandandolo d''urgenza da un dentista locale durante la pausa pranzo.', 'Documentario ''Appendici'' dell''Edizione Estesa di Le Due Torri', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:48:40.628588+00:00'),
('b7a77124-e6d2-4469-9ac9-e002008bf0c7', 34, 'Citazioni & Easter Egg', 'La spada caduta di Karl Urban rimasta nel montaggio finale', 'Nella scena in cui Éomer regala i cavalli ad Aragorn, Legolas e Gimli, l''attore Karl Urban sale con impeto sulla sua sella, ma la spada scivola inavvertitamente dal fodero cadendo sul terreno. Poiché la recitazione complessiva e il controllo del cavallo erano perfetti, Peter Jackson decise di non ripetere la scena e lasciò l''errore nel film.', 'Commento audio del cast nei contenuti speciali DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:48:40.628588+00:00'),
('546ad7f8-1972-49d1-ab6f-b554bdd40b5c', 34, 'Casting & Scelte', 'John Rhys-Davies e la voce originale di Barbalbero', 'Oltre a interpretare il nano Gimli sul set, l''attore John Rhys-Davies ha prestato la voce originale all''Ent Barbalbero. Per ottenere il caratteristico timbro basso e cavernoso senza alterare troppo la recitazione, la sua voce venne fatta risuonare attraverso una speciale cassa acustica in legno prima di essere registrata.', 'Making-of ufficiale ''Le Due Torri - Produzione sonora''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:48:40.628588+00:00'),
('78c53423-b928-4ba3-bb48-f2c44374095a', 34, 'Segreti di produzione', 'La scena del monologo schizofrenico di Gollum diretta da Fran Walsh', 'Il celebre dibattito tra la personalità servile di Sméagol e quella malvagia di Gollum non venne girato da Peter Jackson, bensì scritto e diretto dalla co-sceneggiatrice e produttrice Fran Walsh. Walsh comprese l''importanza drammatica della scena e la realizzò lavorando con la seconda unità di ripresa.', 'Documentario ''Appendici: Dal libro al copione''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:48:40.628588+00:00'),
('f031bcda-60f4-437d-b3fa-9d3ab7badfa3', 34, 'Curiosità & Retroscena', 'L''improvvisazione toccante di Bernard Hill per la morte di Théodred', 'La battuta pronunciata da Re Théoden dopo la sepoltura di suo figlio (''Nessun genitore dovrebbe seppellire il proprio figlio'') non era presente nel testo di Tolkien né nel copione originale. Fu l''attore Bernard Hill a suggerirla a Peter Jackson, avendola sentita pronunciare nella vita reale da una madre che aveva perso un figlio.', 'Intervista a Bernard Hill nei contenuti speciali dell''Edizione Estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:48:40.628588+00:00'),
('204a62be-dd9c-47e4-9e67-8f551d9f8e2c', 35, 'Aneddoti dal set', 'La composizione improvvisata della canzone di Pippin', 'La toccante canzone ''The Edge of Night'', intonata da Pippin (Billy Boyd) mentre Denethor banchetta e Faramir carica Osgiliath, è stata ideata in appena due giorni dallo stesso attore. La sceneggiatrice Philippa Boyens, colpita dalla voce di Boyd dopo averlo sentito cantare in un karaoke bar a Wellington, gli chiese di comporre la melodia adattando i versi presi dal romanzo originale.', 'Commento audio dei filmmaker nell''edizione estesa in DVD/Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:49:26.493545+00:00'),
('f140c97c-dc49-4386-a144-4f36b8ab4542', 35, 'Casting & Scelte', 'Lawrence Makoare nel doppio ruolo di Gothmog e del Re Stregone', 'L''attore neozelandese Lawrence Makoare interpreta due dei principali antagonisti fisici del film: il malformato generale orco Gothmog e il Re Stregone di Angmar. Makoare, che nel primo capitolo aveva interpretato l''Uruk-hai Lurtz, doveva sottoporsi ogni giorno a quattro ore di trucco protesico per vestire i panni di Gothmog.', 'Documentario ''The Appendices - Part 6'' dell''edizione estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:49:26.493545+00:00'),
('d7086362-8977-4d29-b7e4-7579223dd9c3', 35, 'Citazioni & Easter Egg', 'Il cammeo di Royd Tolkien, pronipote dell''autore', 'Royd Tolkien, pronipote diretto dello scrittore J.R.R. Tolkien, fa un cammeo nel film nei panni di un ranger di Gondor. Nella scena dell''assedio di Osgiliath, appare mentre distribuisce lance ai soldati prima della ritirata; la produzione lo convinse a partecipare applicandogli protesi per le orecchie ed equipaggiamento di scena.', 'Documentario di produzione ''The Appendices'' e interviste ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:49:26.493545+00:00'),
('ef723850-eb79-4d32-838b-21e7c9123285', 35, 'Segreti di produzione', 'La ''Bigature'' gigante della cittadella di Minas Tirith', 'Per girare le inquadrature dettagliate di Minas Tirith, il reparto effetti visivi Weta Workshop ha costruito un modello in scala 1:72 denominato ''Bigature''. La struttura era alta oltre 7 metri e larga 6,5 metri, scolpita finemente a mano nei minimi dettagli architettonici per consentire riprese ravvicinate con una speciale telecamera montata su gru.', 'Documentario ''Weta Workshop: Miniatures'' dai contenuti speciali dell''edizione estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:49:26.493545+00:00'),
('fd1e0671-a8bc-46b5-a21e-fa6ff0639f47', 35, 'Effetti speciali & Trucco', 'La bava di Frodo ottenuta con compresse di Alka-Seltzer', 'Nella sequenza in cui Frodo Baggins viene avvelenato dalla ragnatela di Shelob, l''effetto della schiuma bianca che fuoriesce dalla bocca dell''attore Elijah Wood non è stato realizzato al computer. Wood ha semplicemente sciolto in bocca delle compresse effervescenti di Alka-Seltzer un attimo prima dell''inizio delle riprese.', 'Commento audio del cast al film ''Il Signore degli Anelli - Il ritorno del re''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:49:26.493545+00:00'),
('41e1da74-0435-4173-9b28-d003a8f357b3', 35, 'Citazioni & Easter Egg', 'Il cameo del regista Peter Jackson tra i Corsari di Umbar', 'Peter Jackson appare in un cammeo visibile nella versione estesa nei panni di un corsaro di Umbar a bordo delle navi pirata. Durante la sequenza, il personaggio di Jackson viene colpito e ucciso da una freccia scagliata dall''elfo Legolas su incitamento di Gimli.', 'Commento audio del regista Peter Jackson nell''edizione estesa', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:49:26.493545+00:00'),
('fe0b3b97-e7c4-4e5a-a047-f75751568f6d', 35, 'Aneddoti dal set', 'L''acquisto del cavallo di scena da parte di Viggo Mortensen', 'Durante le riprese, Viggo Mortensen sviluppò un forte legame con Uraeus, il cavallo castrone grigio che interpretava Brego. Al termine della produzione l''attore lo acquistò dal proprietario e comprò anche Kenny, il cavallo usato dalla sua controfigura, regalandolo alla stuntwoman Jane Abbott che non poteva permettersi di comprarlo.', 'Intervista di Viggo Mortensen a IGN e contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T09:49:26.493545+00:00'),
('8abb6106-f8b0-4f89-a05f-1be99a862743', 35, 'Effetti speciali & Trucco', 'L''origine sonora insolita per il barrito dei Mûmakil', 'Per creare il verso dei giganteschi Mûmakil (gli elefanti da guerra di Harad), il reparto di sound design guidato da Ethan Van der Ryn non ha utilizzato suoni di animali reali. Il verso è stato ottenuto registrando lo sfregamento di un bidone della spazzatura in plastica trascinato su un viale di ghiaia e abbassandone notevolmente la frequenza audio.', 'Documentario ''The Soundscapes of Middle-earth'' nei contenuti speciali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 7, '2026-11-02T09:49:26.493545+00:00'),
('29d07f05-1b03-42c4-918d-d484a3ddf6a1', 36, 'Curiosità & Retroscena', 'La battaglia legale con Saul Zaentz sui diritti', 'Durante la produzione, il produttore Saul Zaentz dovette affrontare complesse questioni legali per assicurarsi che l''adattamento godesse dei diritti esclusivi per il cinema d''animazione, distinguendosi dai diritti televisivi detenuti da altre parti. Questo permise a Bakshi di avere una certa autonomia creativa, sebbene vincolata a un budget rigido.', 'Documentario ''The Making of Ralph Bakshi''s The Lord of the Rings''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:49:58.521987+00:00'),
('868f6b6f-9dfc-47c4-b873-c7bd6dda74b3', 36, 'Segreti di produzione', 'La scelta iniziale di United Artists e il passaggio alla Fantasy Films', 'Il film fu originariamente finanziato e distribuito dalla United Artists. Tuttavia, a causa dei costi crescenti della lavorazione in rotoscopio e delle divergenze sulla durata dell''opera, la gestione fu presa in carico dalla neonata Fantasy Films di Saul Zaentz.', 'Archivi storici di produzione United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:49:58.521987+00:00'),
('39559426-7409-47aa-84b9-9843467a7469', 36, 'Casting & Scelte', 'L''uso di registrazioni sonore separate per gli attori', 'A differenza dei normali film d''animazione in cui il doppiaggio precede l''animazione, il cast vocale britannico registrò le proprie linee di dialogo in Inghilterra prima che le sequenze in live-action venissero girate in California, costringendo gli attori a recitare senza poter osservare le immagini definitive.', 'Note di produzione e commento audio del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:49:58.521987+00:00'),
('0462cef6-3836-4e47-8996-7978cb5b669a', 36, 'Casting & Scelte', 'Anthony Daniels e il doppiaggio di Legolas', 'Anthony Daniels, celebre per aver interpretato C-3PO in Star Wars nello stesso periodo, fu inizialmente considerato per un ruolo vocale nel film, ma impegni contrari impedirono la sua partecipazione, lasciando spazio ad altri attori britannici come Anthony Daniels non accreditato per consulenze tecniche sui costumisti.', 'Interviste d''archivio ad Anthony Daniels', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:49:58.521987+00:00'),
('faa1f9a4-c40a-462e-8c2f-66b021f0576c', 37, 'Aneddoti dal set', 'La residenza reale di Patrick Magee usata per le riprese', 'La lussuosa e moderna villa in vetro e cemento in cui i Drughi fanno irruzione per violentare la moglie dello scrittore Frank Alexander (interpretato da Patrick Magee) era in realtà la vera residenza privata dell''architetto Edward Armstrong, che l''aveva progettata per sé. La produzione affittò la casa per le riprese, e i proprietari dovettero temporaneamente trasferirsi altrove durante le devastanti scene di violenza.', 'Note di produzione e biografia ufficiale di Stanley Kubrick', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:50:33.258975+00:00'),
('52f02167-1c9b-448e-99d4-e0f1dfadf115', 37, 'Curiosità & Retroscena', 'La scelta del pezzo di Rossini per la scena della maratona', 'Stanley Kubrick scelse di utilizzare l''Ouverture de ''La gazza ladra'' di Gioachino Rossini per la sequenza della brutale rissa tra la banda di Alex e quella del rivale Dimestorp. Il brano fu riprodotto a una velocità leggermente superiore a quella standard per conferire alla violenza coreografata un tono grottesco e quasi comico, ispirandosi ai vecchi cartoni animati.', 'Commento audio e analisi della colonna sonora del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:50:33.258975+00:00'),
('a1615787-7562-49b5-88c1-d2b82b10f5ad', 37, 'Segreti di produzione', 'Il doppiaggio in russo dei termini Nadsat', 'Il gergo giovanile utilizzato dai Drughi, il Nadsat, è basato in gran parte su radici di lingua russa combinate con l''inglese cockney. ironicamente, quando il film fu distribuito in Unione Sovietica anni dopo, i dialoghi dovettero essere adattati specificamente per mantenere l''effetto di estraneità e slang giovanile che nella versione originale si otteneva proprio grazie ai termini russi.', 'Archivi storici della Warner Bros. e studi sul linguaggio Nadsat', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:50:33.258975+00:00'),
('27636336-dfbd-4831-9d6c-d91fedca724a', 37, 'Citazioni & Easter Egg', 'Il ritratto di Beethoven come omaggio e ossessione', 'Il celebre busto in gesso di Ludwig van Beethoven che appare nella stanza di Alex DeLarge e che il protagonista usa come arma fu acquistato in un normale negozio di antiquariato a Londra. Kubrick era così ossessionato dalla perfezione visiva che fece realizzare diverse copie cave del busto in materiali morbidi per evitare infortuni reali sul set durante le colluttazioni.', 'Documentario ''Stanley Kubrick: A Life in Pictures''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:50:33.258975+00:00'),
('87f9054c-c8de-4099-867f-6b31c4a4359d', 37, 'Curiosità & Retroscena', 'La censura autonoma di Kubrick in America', 'Prima che il film ricevesse la classificazione X negli Stati Uniti (che all''epoca limitava fortemente la distribuzione commerciale), Stanley Kubrick tagliò autonomamente circa trenta secondi di fotogrammi relativi alla scena della violenza domestica e al rapporto sessuale accelerato per evitare il divieto assoluto ai minori, decisione di cui si pentì parzialmente negli anni successivi.', 'Corrispondenza tra Stanley Kubrick e la Motion Picture Association of America', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:50:33.258975+00:00'),
('5409d38e-28b6-44e8-845e-eeb5f0a7803f', 44, 'Casting & Scelte', 'Il rifiuto di Noël Coward e le richieste economiche', 'I produttori Albert R. Broccoli e Harry Saltzman offrirono inizialmente il ruolo del villain Dr. No al celebre drammaturgo e attore Noël Coward. Coward rispose con un laconico telegramma ironico: ''Dr. No? No. No. No.'', rifiutando la parte e costringendo la produzione a ripiegare su Joseph Wiseman.', 'Archivi storici EON Productions e biografie ufficiali di Ian Fleming', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:05.049053+00:00'),
('75706423-a7de-4ba2-9721-04d71e024c35', 44, 'Casting & Scelte', 'La scelta iniziale per Felix Leiter', 'Prima che Jack Lord venisse ingaggiato per interpretare l''agente della CIA Felix Leiter, la produzione aveva considerato l''attore americano Richard Conte. Tuttavia, le trattative non andarono a buon fine e Jack Lord ottenne la parte, diventando il primo Leiter della storia cinematografica di 007.', 'Note di produzione originali del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:05.049053+00:00'),
('7c09765b-ae31-4b94-8ec6-67767c99f84d', 44, 'Aneddoti dal set', 'L''infortunio sfiorato dello stuntman Bob Simmons', 'Bob Simmons, lo stuntman che ha sostituito Sean Connery nella celebre sequenza della gun barrel e in vari combattimenti, rischiò seriamente la vita durante le riprese della colluttazione nel bagno turco. Un errore di tempistica con un''arma di scena creò momenti di forte tensione sul set, fortunatamente risolti senza gravi conseguenze.', 'Documentario ''Inside Dr. No'' e Making-of ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:05.049053+00:00'),
('24f5696d-9cc3-406e-86c8-c728c2f3b495', 44, 'Curiosità & Retroscena', 'Il cameo mancato di Ian Fleming', 'Il creatore di James Bond, Ian Fleming, visitò spesso il set in Giamaica durante le riprese. Il regista Terence Young valutò seriamente l''idea di fargli fare un piccolo cameo nei panni di un croupier al casinò di Kingston, ma l''idea fu poi scartata per la timidezza dello scrittore di fronte alla macchina da presa.', 'Biografie di Ian Fleming e documentari d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:05.049053+00:00'),
('74aad66d-3696-4313-a8b3-2d34cfa86d23', 44, 'Curiosità & Retroscena', 'La censura iniziale in Gran Bretagna', 'Il British Board of Film Censors (BBFC) impose diversi tagli prima di concedere al film il visto d''uscita ''A'' (accompagnato da adulti). La censura colpì in particolare la scena in cui Bond spara a freddo al Professor Dent mentre questi è disarmato, giudicata troppo brutale per gli standard cinematografici del 1962.', 'Registri ufficiali del British Board of Film Censors', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:51:05.049053+00:00'),
('27745619-0846-484d-83b4-f64b2568d806', 45, 'Effetti speciali & Trucco', 'La paura del fuoco nella scena del laser', 'Mentre Sean Connery era legato al tavolo d''oro con il vero operatore di effetti speciali che usava una sega circolare nascosta sotto il tavolo per simulare le scintille, un vero saldatore armato di cannello lavorava a pochi centimetri dai suoi piedi per bruciare il metallo. Connery visse momenti di autentico terrore durante le riprese, poiché il calore era quasi insopportabile e rischiava di ustionarlo seriamente.', 'Documentario ufficiale ''The Making of Goldfinger'' / Commento audio del regista Guy Hamilton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:30.468149+00:00'),
('041848bf-1735-479c-82e0-90e360508370', 45, 'Curiosità & Retroscena', 'La censura della sigla iniziale in Finlandia', 'La celebre sequenza dei titoli di testa, in cui i crediti del film vengono proiettati sul corpo dipinto d''oro dell''attrice Margaret Nolan, subì una censura ufficiale in Finlandia. La commissione di censura locale decise di vietare l''intero film per diverse settimane prima di autorizzarne l''uscita, ritenendo la sequenza iniziale e i materiali promozionali troppo audaci per i canoni morali dell''epoca nel paese nordico.', 'Archivi di censura cinematografica finlandese / Note di produzione Eon Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:30.468149+00:00'),
('dafdedf8-36a2-4ffd-8204-442f8592c26b', 45, 'Aneddoti dal set', 'La morte sul ring di Oddjob', 'Harold Sakata, l''attore che interpretava Oddjob, era un ex lottatore professionista noto come ''Tosh Togo''. Durante la celebre lotta finale contro James Bond all''interno di Fort Knox, Sakata rischiò davvero di ferire gravemente Sean Connery in più di un''occasione a causa della sua eccessiva forza fisica e della scarsa esperienza attoriale nel calibrare i colpi sul set.', 'Libro biografico e interviste d''archivio al cast tecnico di James Bond', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:30.468149+00:00'),
('39089043-279e-4e78-9501-16c23fd68fc0', 45, 'Casting & Scelte', 'Il contratto di Margaret Nolan per il ruolo di Dink', 'L''attrice e modella inglese Margaret Nolan, oltre ad essere la modella utilizzata per la celebre verniciatura d''oro nei titoli di testa e nei manifesti promozionali del film, ottenne anche il piccolo ruolo di Dink, la massaggiatrice di James Bond all''inizio della pellicola, grazie a un''intuizione del produttore Albert Broccoli.', 'Archivio storico Eon Productions e registri di casting del 1964', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:30.468149+00:00'),
('bf90ed82-46d9-436a-8101-652f7dd64cec', 45, 'Segreti di produzione', 'Il rifiuto iniziale di Guy Hamilton', 'Prima di affidare la regia di ''Goldfinger'' a Guy Hamilton, i produttori Harry Saltzman e Albert Broccoli avevano offerto la direzione a Terence Young, che aveva diretto i primi due film della saga (''Licenza di uccidere'' e ''A 007, dalla Russia con amore''). Young rifiutò a causa di un disaccordo sui compensi economici, spingendo la produzione a ingaggiare Hamilton che impresse un ritmo più ironico e spettacolare al franchise.', 'Documentario retrospettivo ''Inside Goldfinger'' (Edizione Blu-ray MGM)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:51:30.468149+00:00'),
('583a722f-7270-4cc4-9b79-64ad2f1d6bab', 46, 'Segreti di produzione', 'La consulenza di Frank Rosenthal sui dettagli dei casinò', 'Il vero Frank ''Lefty'' Rosenthal, a cui è ispirato il personaggio di Sam Rothstein, ha fornito una consulenza approfondita e rigorosa alla produzione durante la stesura della sceneggiatura, spiegando nel dettaglio i meccanismi interni e le truffe dei casinò di Las Vegas degli anni ''70.', 'Documentario ufficiale ''The Making of Casino''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:37.501602+00:00'),
('7279393c-3b76-4b4f-a20e-5fb7c798768b', 46, 'Casting & Scelte', 'L''ispirazione per il look e i baffi di Robert De Niro', 'Per calarsi perfettamente nei panni di Frank Rosenthal, Robert De Niro ha indossato oltre 70 differenti costumi creati su misura e ha studiato attentamente i filmati d''archivio reali di Rosenthal per replicarne la parlata, i gesti misurati e i caratteristici baffi.', 'Note di produzione ufficiali Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:37.501602+00:00'),
('8e45b826-4740-480e-a35d-ff3e1071f1a3', 46, 'Curiosità & Retroscena', 'La vera identità della voce narrante iniziale', 'Nelle prime fasi del montaggio, Martin Scorsese aveva pianificato un uso molto più limitato della voce fuori campo, ma la complessità della trama basata sul libro non-fiction di Nicholas Pileggi ha reso necessaria la doppia narrazione alternata tra Sam Rothstein e Nicky Santoro.', 'Intervista al montatore Thelma Schoonmaker', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:37.501602+00:00'),
('760bc343-c31e-442c-abb4-63063cd9e599', 46, 'Aneddoti dal set', 'Il divieto della commissione di controllo dei giochi', 'La Nevada Gaming Commission ha negato alla produzione il permesso di effettuare riprese all''interno dei veri caveau dei casinò storici ancora in attività durante gli orari di apertura, costringendo la troupe a ricostruire meticolosamente gli interni negli studi.', 'Archivio storico della produzione di Casino', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:37.501602+00:00'),
('c24d142a-21b8-48d4-86af-29c7d1848303', 46, 'Aneddoti dal set', 'La scelta del ristorante all''aperto storico', 'La celebre sequenza in cui Sam e Nicky discutono nel deserto e vicino alle insegne fu girata in location reali nel Nevada meridionale, utilizzando un vero ranch e aree desertiche periferiche per rievocare il clima di tensione mafiosa fuori dai confini cittadini.', 'Commento audio del regista Martin Scorsese', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:51:37.501602+00:00'),
('f9fd820f-385b-45dd-a603-f0d7987fe131', 48, 'Curiosità & Retroscena', 'L''origine della collaborazione letteraria', 'Béla Tarr lesse per la prima volta il romanzo d''esordio di László Krasznahorkai nel 1985, rimanendo immediatamente folgorato dalla visione apocalittica e dal linguaggio ipnotico dell''autore, che avrebbe poi firmato le sceneggiature di quasi tutti i suoi film successivi.', 'Note di produzione e interviste d''archivio di Béla Tarr', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:51.781193+00:00'),
('f4feddb6-f52b-4154-bb59-e823070edd71', 48, 'Segreti di produzione', 'Il rifiuto del sistema cinematografico ungherese', 'A causa del collasso dell''industria cinematografica statale ungherese nei primi anni novanta e della riluttanza dei produttori tradizionali a finanziare un progetto in bianco e nero della durata di 450 minuti, la produzione fu costretta a assemblare un complesso mosaico di finanziamenti internazionali provenienti da Germania, Svizzera e Ungheria.', 'Archivio di storia del cinema dell''Ungheria', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:51.781193+00:00'),
('08419759-7724-4f59-9e41-fad1f680d05b', 48, 'Segreti di produzione', 'L''uso rigoroso della pellicola 35mm e la stampa in bianco e nero', 'Il direttore della fotografia Gábor Medvigy ha girato l''intero film su pellicola 35mm, lavorando con un contrasto molto spinto per catturare le gradazioni di grigio e il fango delle lande ungheresi, sfruttando spesso la luce naturale nei momenti di transizione meteorologica.', 'Bollettino della Società Ungherese dei Direttori della Fotografia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:51.781193+00:00'),
('f963bab3-699d-4edf-a978-851294f96aa4', 48, 'Casting & Scelte', 'La scelta del cast misto e del musicista protagonista', 'Mihály Víg, oltre a comporre l''intera colonna sonora del film, fu scelto da Tarr anche per il ruolo di Kerekes, una delle figure centrali della narrazione, fondendo il suo lavoro di musicista con quello di attore non professionista all''interno della troupe.', 'Note di edizione del cofanetto DVD ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:51.781193+00:00'),
('65f037d9-94fc-4e5c-9036-c1734c46beb8', 52, 'Effetti speciali & Trucco', 'La riproduzione digitale di Michael Douglas per il 1970', 'Per la sequenza ambientata nella base militare del New Jersey nel 1970, la produzione non ha potuto utilizzare vecchi filmati di Michael Douglas. I supervisor degli effetti visivi della Marvel hanno impiegato tecniche avanzate di digital de-aging e riferimenti visivi tratti dal film del 1979 ''Sindrome cinese'' per ringiovanire l''attore.', 'Audio commento ufficiale dei registi Anthony e Joe Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:21.967498+00:00'),
('4aa120c3-ed53-4b24-bbdb-584591295fa9', 52, 'Segreti di produzione', 'Il cameo postumo di Stan Lee ringiovanito in CGI', 'L''ultima apparizione cameo cinematografica di Stan Lee nel Marvel Cinematic Universe, ambientata sempre nella sequenza del 1970 alla guida di un''auto hippy urlando ''Make love, not war'', ha richiesto un intervento digitale. La troupe ha utilizzato una combinazione di CGI e riprese d''archivio per ricreare le fattezze di Lee negli anni settanta.', 'Note di produzione ufficiali Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:21.967498+00:00'),
('1157fe6e-cdb3-4975-b561-c17aeeee9722', 52, 'Aneddoti dal set', 'La scelta della chitarra mancina per Happy Hogan', 'Durante la scena del funerale, Jon Favreau (regista e interprete di Happy Hogan) suona la chitarra con la mano sinistra. L''attore ha dovuto imparare specificamente a suonare lo strumento da mancino perché la figlia di Tony Stark nella finzione scenica doveva trovarsi sul lato destro durante la ripresa.', 'Featurette ''The Making of Avengers: Endgame'' - Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:21.967498+00:00'),
('abffd709-0632-4415-be81-7b798ee63ab0', 52, 'Aneddoti dal set', 'Il peso reale del martello Mjolnir sul set', 'Il martello utilizzato da Chris Hemsworth nelle scene in cui condivide la scena con Captain America durante la battaglia finale pesava circa 20 chili nella sua versione principale in metallo pieno, costringendo l''attore a sessioni di fisioterapia per evitare lesioni alla spalla durante le riprese delle sequenze d''azione più ripetitive.', 'Intervista di Chris Hemsworth per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:52:21.967498+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('66193fa5-d944-44ed-bbdd-c7f66128b975', 52, 'Effetti speciali & Trucco', 'I capelli veri di Scarlett Johansson per il salto temporale', 'Per mostrare il passaggio dei cinque anni nel salto temporale iniziale, il personaggio di Natasha Romanoff sfoggia capelli biondi con radici scure e acconciature differenti. L''attrice Scarlett Johansson ha realmente tinto e tagliato i propri capelli sul set, rifiutando l''uso di parrucche sintetiche per mantenere coerenza visiva con i capitoli precedenti.', 'Dichiarazione ufficiale della capo reparto trucco e parrucco Kazu Hiro e panel di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:52:21.967498+00:00'),
('b6872528-d197-42e7-8982-56cf0ba56c96', 57, 'Casting & Scelte', 'L''ispirazione per il costume e gli accessori di Jack Sparrow', 'Johnny Depp ha ideato l''aspetto visivo del suo personaggio aggiungendo dettagli bizzarri come pistole antiche, bandane, perle di legno e persino una zampa di gallina appesa alla cintura, immaginando i pirati come le rockstar del diciottesimo secolo.', 'Commento audio del regista Gore Verbinski e del produttore Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:54.47692+00:00'),
('3250493b-9dab-4176-9804-4f488eb57808', 47, 'Segreti di produzione', 'La consulenza di Alexander McQueen per il guardaroba di Vesper Lynd', 'I costumi indossati da Eva Green nel ruolo di Vesper Lynd sono stati curati con la stretta collaborazione della nota casa di moda britannica di Alexander McQueen, per riflettere l''eleganza sofisticata e l''indipendenza del personaggio.', 'Note di produzione ufficiali Sony Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:45.094883+00:00'),
('169a9cd7-0b12-433c-8df5-bd0fad246f21', 47, 'Effetti speciali & Trucco', 'Il trucco speciale per il tic all''occhio di Le Chiffre', 'Il caratteristico tic all''occhio con fuoriuscita di sangue che affligge Le Chiffre non era previsto originariamente nel romanzo di Ian Fleming; è stato ideato da Mads Mikkelsen insieme al regista Martin Campbell e realizzato tramite una combinazione di protesi e effetti di trucco cinematografico.', 'Commento audio del regista nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:45.094883+00:00'),
('fd0dca69-fe1d-4bf8-ba93-09a157306bec', 47, 'Aneddoti dal set', 'La vera ferita all''orecchio di Daniel Craig durante gli stunt', 'Oltre al dente rotto nelle prime battute, Daniel Craig subì un ulteriore infortunio durante le riprese a Praga, tagliandosi profondamente un orecchio durante una complessa sequenza di combattimento corpo a corpo.', 'Intervista ufficiale a Daniel Craig per Empire Magazine', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:45.094883+00:00'),
('79a523e5-1ca5-4b7f-9b64-7e6eed0c73af', 47, 'Curiosità & Retroscena', 'La scelta della Repubblica Ceca per sostituire il Montenegro', 'Nonostante la trama si svolga in gran parte in Montenegro, la produzione scelse di girare le sequenze ambientate nei Balcani principalmente in Repubblica Ceca, utilizzando la città termale di Karlovy Vary e gli studi cinematografici Barrandov a Praga.', 'Reportage di produzione del Making of Casino Royale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:45.094883+00:00'),
('edcb60b9-5d64-4420-ae95-852f7b109ec8', 47, 'Citazioni & Easter Egg', 'L''assenza della classica sequenza d''apertura con la pistola', 'Casino Royale è il primo film della saga di James Bond a non iniziare con la tradizionale sequenza d''apertura ''gunbarrel'' (la visuale attraverso la canna della pistola), che invece compare in modo stilizzato e inatteso solo all''inizio dei titoli di coda principali.', 'Analisi della struttura narrativa del film negli archivi ufficiali Eon Productions', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:51:45.094883+00:00'),
('136acd53-5d8a-4217-b9a3-74a42780a211', 49, 'Aneddoti dal set', 'La ripresa di riserva sul cibo di Tony Stark', 'Robert Downey Jr. aveva l''abitudine di nascondere cibo in ogni angolo del set e offriva continuamente snack ai colleghi. La famosa scena in cui offre dei mirtilli a Captain America e Bruce Banner sul Helicarrier non era sceneggiata: l''attore aveva davvero fame e stava improvvisando, ma Joss Whedon decise di tenerla nel montaggio finale.', 'Commento audio del regista Joss Whedon nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:51:58.183186+00:00'),
('6d201626-eb1c-4712-a380-13f07ddb411b', 49, 'Aneddoti dal set', 'La ferita al collo di Scarlett Johansson', 'Durante le riprese delle sequenze d''azione, Scarlett Johansson eseguiva molte delle sue acrobazie. In un''occasione si procurò una brutta contusione al collo durante uno scontro corpo a corpo con una controfigura, ma continuò a girare dopo una breve pausa.', 'Intervista ufficiale di Scarlett Johansson al David Letterman Show', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:51:58.183186+00:00'),
('6197811a-025d-44ed-ba40-2b04dec142e6', 49, 'Effetti speciali & Trucco', 'Le protesi auricolari per Occhio di Falco', 'Jeremy Renner dovette indossare speciali protesi per le orecchie durante le riprese per accentuare il profilo del suo personaggio, sebbene l''attore abbia spesso ammesso di trovarle estremamente fastidiose e di aver cercato di rimuoverle non appena le telecamere si spegnevano.', 'Note di produzione e reparti trucco Marvel Studios', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:51:58.183186+00:00'),
('75608a5e-4103-44c8-9fcf-7f9f868d90e7', 49, 'Curiosità & Retroscena', 'Il caffè notturno dopo la prima mondiale', 'La celebre scena post-credits in cui i Venditori mangiano lo shawarma in un locale di New York fu girata letteralmente la notte stessa della prima mondiale del film a Los Angeles. Joss Whedon dovette aggiungere la sequenza all''ultimo minuto, costringendo il cast a presentarsi sul set con costumi di scena di fortuna e Chris Evans a coprire la barba finta con una mano.', 'Intervista al cast e Joss Whedon nel documentario ''Assembling a Universe''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:51:58.183186+00:00'),
('198f771a-4684-4071-80b0-1bf4c49bb3ac', 50, 'Aneddoti dal set', 'L''infortunio di Jeremy Renner sul set', 'Durante le prime settimane di riprese in Italia, precisamente a Bardonecchia, l''attore Jeremy Renner si è fratturato entrambi i gomiti a causa di una scena d''azione andata storta in cui scivolava da un ponte. Questo incidente ha costretto la produzione a riorganizzare il piano di lavoro e a ricorrere pesantemente alla computer grafica e a controfigure per le sue sequenze di combattimento.', 'Intervista ufficiale di Jeremy Renner al The Tonight Show with Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:06.687111+00:00'),
('d8e91e25-ec37-4907-ba6d-56a0686145dc', 50, 'Segreti di produzione', 'La censura della parola ''mutanti''', 'A causa di una complessa disputa sui diritti cinematografici dei personaggi Marvel tra i Marvel Studios e la 20th Century Fox, Joss Whedon ha dovuto evitare rigorosamente di usare la parola ''mutanti'' o ''mutazione'' per descrivere i poteri di Wanda e Pietro Maximoff. Nel film i due fratelli vengono definiti esclusivamente come ''miracoli'' nati dagli esperimenti con la Gemma della Mente guidati dal Barone Strucker.', 'Note di produzione ufficiali Marvel e dichiarazioni di Joss Whedon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:06.687111+00:00'),
('48d791fc-2156-4d35-b1c7-8a282d2341ca', 50, 'Casting & Scelte', 'Il contratto originario di Paul Bettany', 'Prima di essere scelto per interpretare l''androide Visione nel 2015, Paul Bettany aveva prestato la voce unicamente all''intelligenza artificiale J.A.R.V.I.S. nei precedenti film del Marvel Cinematic Universe. L''attore ha rivelato di non aver mai letto i copioni dei film in cui doppiava J.A.R.V.I.S. e di aver accettato il ruolo di Visione senza un provino, firmando il contratto in una stanza d''albergo dopo una telefonata lampo di Joss Whedon.', 'Extra del Blu-ray ufficiale di Avengers: Age of Ultron e interviste promozionali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:06.687111+00:00'),
('a1ec3a18-babe-408c-9c37-2b30a9786270', 50, 'Curiosità & Retroscena', 'L''assenza di Spider-Man e Captain Marvel nella scena finale', 'La sequenza finale del film mostrava originariamente l''arrivo di una nuova formazione degli Avengers guidata da Captain America e Vedova Nera, che includeva fugaci apparizioni di eroi allora non ancora introdotti ufficialmente nel franchise, come Spider-Man e Captain Marvel. I piani della Marvel cambiarono in corso d''opera a causa dei complessi accordi con la Sony Pictures per l''Uomo Ragno, costringendo Whedon a tagliare quei cameo e a inserire invece nuovi volti come War Machine, Falcon, Visione e Scarlet Witch.', 'Commento audio del regista Joss Whedon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:52:06.687111+00:00'),
('866ad1aa-620c-414d-a0c8-5f65ca1e4f77', 50, 'Segreti di produzione', 'La sequenza della fattoria girata in totale segretezza', 'La sequenza in cui gli Avengers si rifugiano nella fattoria segreta di Occhio di Falco è stata girata a Shepperton, in Inghilterra, ma la produzione ha adottato misure di sicurezza talmente draconiane da isolare il set con enormi tende nere per impedire ai paparazzi di fotografare la famiglia segreta di Clint Barton e la presenza dell''attrice Linda Cardellini.', 'Making-of ufficiale incluso nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:52:06.687111+00:00'),
('78615497-2366-4fb8-9166-ddb1123aaac5', 51, 'Effetti speciali & Trucco', 'La parrucca da 100.000 dollari di Scarlett Johansson', 'Per interpretare Natasha Romanoff (Vedova Nera) con i capelli biondi e corti, Scarlett Johansson ha indossato una parrucca di alta qualità dal costo stimato di circa 100.000 dollari, realizzata con veri capelli umani e curata nei minimi dettagli per mantenere la continuità visiva.', 'Audio commento ufficiale dei registi Anthony e Joe Russo', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:13.877215+00:00'),
('c011d579-c771-4919-aae3-96df2c6ffdce', 51, 'Aneddoti dal set', 'Il divieto di visione per Tom Holland', 'A causa della sua nota tendenza a rivelare spoiler nelle interviste, a Tom Holland è stato permesso di leggere esclusivamente le pagine del copione che lo riguardavano direttamente e gli è stato impedito di vedere l''intero film prima della sua uscita nelle sale.', 'Intervista promozionale a Jimmy Fallon', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:13.877215+00:00'),
('a9ddc01f-fd85-477b-b5ed-367acafbc3f2', 51, 'Segreti di produzione', 'La sequenza d''apertura senza musica', 'I registi hanno deciso deliberatamente di non inserire alcuna colonna sonora o tema musicale della Marvel nei primi minuti del film, in cui Thanos attacca la nave asgardiana, per enfatizzare immediatamente il tono cupo, tragico e l''alto livello di pericolo della narrazione.', 'Dietro le quinte del Blu-Ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:13.877215+00:00'),
('decf4966-56a9-46b7-9e6b-c0cdee4edd13', 54, 'Aneddoti dal set', 'La frattura allo sterno di Sylvester Stallone', 'Durante le riprese del durissimo scontro finale contro Apollo Creed, Sylvester Stallone subì un colpo così violento da parte di Carl Weathers da riportare una frattura allo sterno. A causa dell''infortunio, le riprese dovettero essere riorganizzate temporaneamente per permettere all''attore e sceneggiatore di riprendersi.', 'Commento audio ufficiale del regista John G. Avildsen e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:33.679547+00:00'),
('b9cb7888-c340-4cf6-a903-b20c96e8a971', 54, 'Casting & Scelte', 'La scelta iniziale per il ruolo di Mickey Goldmill', 'Prima che Burgess Meredith ottenesse la parte dell''anziano allenatore Mickey (ricevendo poi una nomination all''Oscar), i produttori avevano offerto il ruolo all''attore veterano Lee J. Cobb e persino al celebre comico Groucho Marx, il quale rifiutò categoricamente.', 'Documentario ''The Making of Rocky'' e biografie ufficiali della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:33.679547+00:00'),
('8adbdbf2-0d18-425b-ae12-3b52dc14bf4a', 54, 'Curiosità & Retroscena', 'Il cameo dei familiari di Sylvester Stallone', 'Nel film compaiono diversi membri della famiglia di Stallone: suo fratello Frank Stallone Jr. interpreta il cantante di strada all''angolo della via, mentre suo padre, Frank Stallone Sr., veste i panni del giudice di gara che assegna i punteggi durante il match finale sul ring.', 'Crediti ufficiali del film e documentario d''archivio Metro-Goldwyn-Mayer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:33.679547+00:00'),
('520bd4b8-02b0-47fa-9da8-20da1f87c6e4', 54, 'Segreti di produzione', 'La vera palestra di Filadelfia e la comparsa di Frazier', 'La palestra in cui Rocky si allena all''inizio del film era la vera ''ABC Athletic Club'' di Filadelfia, gestita da Lou Lucchese. All''interno della pellicola fa una breve apparizione non accreditata anche il celebre campione del mondo dei pesi massimi Joe Frazier, che saluta Rocky per le scale della palestra.', 'Archivio storico della produzione United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:52:33.679547+00:00'),
('94ed8a22-3cb7-414f-a9e1-856ee0e01b5b', 54, 'Casting & Scelte', 'Il rifiuto dei grandi studios e la clausola sul protagonista', 'La United Artists era disposta a stanziare un budget milionario per la sceneggiatura, arrivando a offrire centinaia di migliaia di dollari, a patto però di affidare la parte del protagonista a una star affermata come Robert Redford, Ryan O''Neal o James Caan. Stallone rifiutò categoricamente per poter recitare in prima persona.', 'Interviste storiche a Irwin Winkler e Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:52:33.679547+00:00'),
('2ec5df23-aa78-40a4-95b3-50a7427790ef', 55, 'Aneddoti dal set', 'La polmonite fulminante di Stallone', 'A seguito del duro colpo al petto sferrato da Dolph Lundgren che costrinse Stallone al ricovero in terapia intensiva per quattro giorni, le riprese dovettero interrompersi bruscamente. Ironia della sorte, l''attore e regista si presentò sul set con una grave polmonite già in corso, aggravata ulteriormente dalla potenza dei colpi ricevuti sul ring.', 'Intervista ufficiale di Sylvester Stallone per il trentesimo anniversario del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:41.351759+00:00'),
('6a142a3f-f6cf-4048-8914-e4f0005a027f', 55, 'Casting & Scelte', 'La scelta del vero pugile Tony Burton', 'Tony Burton, che interpreta lo storico allenatore di Apollo Creed, Duke, aveva un vero passato da pugile professionista prima di intraprendere la carriera d''attore. La sua esperienza sul ring fu fondamentale per coordinare i movimenti realistici delle sequenze di pugilato e per consigliare Stallone sulla gestione della tensione drammatica durante gli incontri.', 'Note di produzione e documentario sul casting della saga', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:41.351759+00:00'),
('e88e366c-6a13-4c2a-81b9-a59f05af4ec1', 55, 'Segreti di produzione', 'Le riprese dell''incontro a Vancouver', 'L''arena in cui si disputa il match decisivo tra Rocky e Ivan Drago a Mosca fu in realtà ricostruita all''interno del Pacific Coliseum di Vancouver, in Canada. La produzione dovette impiegare oltre tremila comparse locali, istruite appositamente per indossare cappotti invernali grigi e mantenere un''espressione severa e impassibile per simulare il pubblico sovietico.', 'Archivio di produzione della MGM e diario di troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:41.351759+00:00'),
('1f43756f-2ca1-4419-a12c-6781fc23a60e', 55, 'Curiosità & Retroscena', 'L''assenza di Rocky Balboa Jr. nella trama', 'Il personaggio di Rocky Jr., interpretato in Rocky III da Ian Fried, fu quasi totalmente escluso dalle dinamiche narrative di questo capitolo per concentrare la narrazione unicamente sul lutto, sulla vendetta e sulla Guerra Fredda. Il giovane attore fu sostituito da Sage Stallone nei film successivi, ma in Rocky IV la sua presenza è ridotta a pochissime inquadrature marginali.', 'Sceneggiatura originale e note di montaggio di Sylvester Stallone', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:52:41.351759+00:00'),
('18cfb40d-f207-4e53-a824-ea1e32709926', 55, 'Aneddoti dal set', 'La cicatrice di Carl Weathers', 'Durante la preparazione atletica per il film, Carl Weathers pretese di allenarsi rigorosamente come un vero campione dei pesi massimi, arrivando a pretendere sessioni di sparring con pugili professionisti. Questo rigore estremo gli causò una leggera lesione muscolare alla spalla che richiese cure mediche immediate prima di girare la spettacolare sequenza d''ingresso a Las Vegas.', 'Intervista a Carl Weathers nel making-of ''The Making of Rocky IV''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:52:41.351759+00:00'),
('b5602f16-ce1f-4699-915c-ec0daac17358', 55, 'Segreti di produzione', 'Il budget record della saga', 'Con un budget stimato intorno ai 28 milioni di dollari, Rocky IV fu il film più costoso dell''intera franchise fino a quel momento. Tale cifra fu giustificata dai complessi spostamenti logistici tra Stati Uniti, Canada e le sequenze con effetti speciali avanzati per l''epoca.', 'Report finanziario della United Artists del 1985', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:52:41.351759+00:00'),
('659b5d46-8769-4f00-adc8-ef1b874e0b35', 64, 'Casting & Scelte', 'La voce doppiata di Little John', 'L''attore Alan Hale Sr., che interpretava Little John, aveva una voce considerata troppo acuta per l''imponente stazza del personaggio, così in post-produzione parte dei suoi dialoghi fu ridoppiata da un attore vocale con un tono più baritonale.', 'Note d''archivio Warner Bros. e biografie della produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:54:10.120391+00:00'),
('e82e3289-67fb-4bd2-b0a0-f11355ec7f2d', 56, 'Segreti di produzione', 'La finta copertina della rivista Ring', 'Nel film appare una copertina della prestigiosa rivista ''The Ring'' che ritrae Apollo Creed e Rocky Balboa. Per realizzarla senza violare i marchi registrati o pagare diritti, la produzione creò una versione personalizzata della rivista, modificando la grafica ma mantenendo l''aspetto autentico grazie alla collaborazione di esperti del settore.', 'Note di produzione e scenografia ufficiali di Rocky II', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:52:47.759302+00:00'),
('c8c39cba-37cb-4e49-b202-380d51c0f4ec', 56, 'Curiosità & Retroscena', 'La nascita del celebre grido ''Yo, Adrian!''', 'La celebre battuta urlata da Rocky fuori dalla sua casa, ''Yo, Adrian!'', è diventata una delle citazioni cinematografiche più famose della storia. Sylvester Stallone ha rivelato nelle interviste che la frase nacque in modo quasi estemporaneo sul set per riassumere l''affetto goffo e genuino del personaggio verso la moglie.', 'Intervista retrospettiva a Sylvester Stallone (Edizione speciale Blu-ray)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:47.759302+00:00'),
('f8190a7b-a1a9-4e4b-ae26-a7bfe656ac5c', 56, 'Casting & Scelte', 'Il vero campione di sollevamento pesi come comparsa', 'Durante le sequenze ambientate nella palestra di Mickey, Stallone volle inserire atleti autentici per dare credibilità visiva. Tra le comparse figurava Ken Patera, noto sollevatore di pesi olimpico e lottatore professionista, che apparve in brevi sequenze di contorno sullo sfondo degli allenamenti.', 'Archivio del casting e documentario sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:47.759302+00:00'),
('65e35546-83fa-45b7-9804-95302f6ffeda', 96, 'Effetti speciali & Trucco', 'L''uso pionieristico di Blender nel cinema', 'Mantenendo la sua identità digitale originaria, la produzione ha fatto un uso massiccio del software open-source Blender per la ricostruzione fotorealistica degli spazi liminali e delle geometrie impossibili delle Backrooms.', 'Report tecnico di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 5, 3, '2026-11-02T17:56:29.865565+00:00'),
('e2f98295-31df-429b-b2e2-b53bd3fc416f', 57, 'Segreti di produzione', 'La scelta del compositore sostituito in extremis', 'Inizialmente il regista Gore Verbinski aveva ingaggiato il compositore Alan Silvestri per la colonna sonora del film, ma in seguito a divergenze creative con la produzione, Silvestri fu sostituito da Klaus Badelt pochi mesi prima dell''uscita, affidando poi i temi principali a Hans Zimmer.', 'Note di produzione ufficiali Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:52:54.47692+00:00'),
('e8674594-b27f-4e88-bb28-f18ffb6ecea8', 57, 'Aneddoti dal set', 'Il malore sul set di Keira Knightley', 'Durante le riprese della sequenza iniziale sull''isola caraibica, l''attrice Keira Knightley ha dovuto affrontare un forte colpo di calore causato dal pesante abito d''epoca e dal clima tropicale della Repubblica Dominicana, richiedendo brevi pause mediche.', 'Documentario dietro le quinte ''An Epic At Sea''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:52:54.47692+00:00'),
('0cdc422e-37cc-4f2b-985e-3dbf5fab6b1f', 57, 'Curiosità & Retroscena', 'L''improvvisazione dell''abbraccio di Jack Sparrow', 'La scena in cui Jack Sparrow abbraccia con entusiasmo Elizabeth Swann dopo che lei accetta la sua proposta non era originariamente sceneggiata in quel modo; Johnny Depp improvvisò il gesto per esasperare la reazione di sorpresa di Keira Knightley.', 'Special TV ''Making of Pirates of the Caribbean'' (2003)', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:52:54.47692+00:00'),
('a7100404-2d04-4f1e-be52-ae3d60a84006', 58, 'Effetti speciali & Trucco', 'La rimozione digitale dei denti d''oro di Johnny Depp', 'Durante le riprese, Johnny Depp manteneva applicati permanentemente diversi denti d''oro. Poiché nel primo film la continuità non prevedeva che il personaggio li avesse in quel numero, la Industrial Light & Magic ha dovuto rimuovere digitalmente i denti d''oro in moltissimi fotogrammi del film.', 'Commento audio del regista Gore Verbinski e dei produttori nel Blu-ray ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:53:32.868908+00:00'),
('6614f180-7834-4742-baf7-efcb9412e8c4', 58, 'Segreti di produzione', 'La scena della ruota mulino costruita interamente dal vero', 'Il duello a tre sulla gigantesca ruota del mulino in movimento non fu realizzato in CGI. La produzione fece costruire una struttura meccanica reale alta oltre 9 metri dal team di scenografia, in cui gli stuntmen e gli attori combattevano realmente mentre la ruota girava.', 'Documentario ufficiale ''Mastering the Blade'' nei contenuti speciali del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:53:32.868908+00:00'),
('c8eb1ef2-6152-4f24-a358-a87247d72d30', 58, 'Aneddoti dal set', 'La ferita al polso di Johnny Depp causata dalla spada', 'Durante la sequenza d''azione iniziale a Port Royal, Johnny Depp subì una ferita al polso sinistro dopo che la sua spada si era impigliata in una corda di sicurezza, costringendo la troupe a fermare temporaneamente le riprese per medicare l''attore.', 'Note di produzione ufficiali della Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:53:32.868908+00:00'),
('b75d4de5-55ca-430d-97e5-9a524477ebf9', 58, 'Curiosità & Retroscena', 'La genesi del nome e del design della ruota di Hades', 'L''isola dei cannifoglia (Pelegostos) e il sacrificio a cui Jack Sparrow è destinato traggono ispirazione visiva dai dipinti di Howard Pyle e dalle prime bozze scartate per l''attrazione originale dei Parchi Disney risalenti agli anni ''50.', 'Libro ''The Art of Pirates of the Caribbean'' di Ramin Zahed', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:53:32.868908+00:00'),
('d584256e-4d20-4e04-8867-b7c9072ec569', 58, 'Aneddoti dal set', 'L''utilizzo delle vere sanguisughe nella scena della palude', 'Nella sequenza in cui la ciurma visita Tia Dalma nella sua capanna nella palude, la troupe ha dovuto utilizzare centinaia di sanguisughe vive messe a contatto con gli abiti degli attori, sebbene siano state impiegate precauzioni sanitarie rigorose supervisionate da medici sul set.', 'Diario di bordo della produzione e interviste al reparto costumi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:53:32.868908+00:00'),
('f30a8b98-50ef-4e0a-bfdf-40769a6e1dee', 59, 'Casting & Scelte', 'Il cameo dei Rolling Stones quasi svanito', 'Mick Jagger aveva espresso un forte interesse per un ruolo nel film dopo il successo del coinvolgimento di Keith Richards, ma l''agenda fitta del tour dei Rolling Stones rese purtroppo impossibile la sua partecipazione.', 'Dichiarazioni ufficiali della produzione e del produttore Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:53:39.054782+00:00'),
('b6b5ac87-0bed-4c3c-b74f-3718f75ec63b', 59, 'Segreti di produzione', 'La riproduzione in miniatura della Empress', 'Per le complesse sequenze d''azione in mare e i combattimenti nel maelstrom, gli esperti di effetti speciali della Industrial Light & Magic hanno costruito un modello fisico in scala della nave di Sao Feng, lunga circa sei metri, testato in un''enorme vasca d''acqua.', 'Documentario ''Mastering the Maelstrom'' nel DVD bonus', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:53:39.054782+00:00'),
('7d6f7b4a-a72b-44a1-9171-a0127282a61e', 59, 'Aneddoti dal set', 'L''infortunio di Geoffrey Rush protetto dal copione', 'Durante le riprese, Geoffrey Rush soffriva di forti dolori a un gomito a causa di una vecchia lesione, e i costumisti dovettero modificare leggermente le maniche e i movimenti di Barbossa per permettergli di brandire la spada senza aggravare l''infortunio.', 'Commento audio del regista Gore Verbinski e del co-sceneggiatore Terry Rossio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:53:39.054782+00:00'),
('0fa23223-3657-4588-af49-b4119ad9ec0e', 60, 'Casting & Scelte', 'L''addio di Keira Knightley e Orlando Bloom', 'Questo è il primo film della saga che non vede la partecipazione di Keira Knightley e Orlando Bloom nei ruoli di Elizabeth Swann e Will Turner. La decisione fu presa di comune accordo con gli sceneggiatori, i quali ritennero che l''arco narrativo dei due personaggi fosse giunto a una conclusione naturale nel terzo capitolo.', 'Dichiarazione ufficiale del produttore Jerry Bruckheimer', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:53:45.479312+00:00'),
('93a32a0e-f7fc-4598-8bd3-6f035f4395cc', 60, 'Segreti di produzione', 'La scelta di Terry Rossio come unico sceneggiatore', 'A differenza dei primi tre capitoli scritti a quattro mani insieme a Ted Elliott, Terry Rossio è stato l''unico autore accreditato per la sceneggiatura di questo quarto film. Il copione è stato parzialmente adattato dal romanzo ''Mari stregati'' (On Stranger Tides) dello scrittore Tim Powers.', 'Note di produzione ufficiali della Walt Disney Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:53:45.479312+00:00'),
('9e21c9e4-0104-497b-bea1-62470d4c8b19', 60, 'Effetti speciali & Trucco', 'La conversione in 3D nativo sul set', 'Il direttore della fotografia Dariusz Wolski ha girato l''intero film utilizzando telecamere appositamente progettate per il sistema 3D nativo, rifiutando la conversione digitale in post-produzione. Per fare ciò, la troupe ha impiegato rig di ripresa duali simili a quelli utilizzati da James Cameron per ''Avatar''.', 'Intervista tecnica al direttore della fotografia Dariusz Wolski', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:53:45.479312+00:00'),
('7978632b-3a06-4f4e-868d-fc48ba1939e8', 60, 'Casting & Scelte', 'L''ispirazione per il personaggio di Angelica', 'Per il personaggio di Angelica, interpretato da Penélope Cruz, gli autori si sono ispirati ai vecchi film d''avventura di Hollywood e alla dinamica amorosa tra Katharine Hepburn e Spencer Tracy in ''La donna del giorno''. Il personaggio rappresenta l''unica figura femminile in grado di tenere testa a Jack Sparrow grazie a pari astuzia e abilità nel borseggio.', 'Audio commento del regista Rob Marshall', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:53:45.479312+00:00'),
('fd11be21-3240-4420-aaac-b069a4d96fa4', 65, 'Aneddoti dal set', 'La ferita al dito di Sean Connery', 'Durante le prove della sequenza del duello con la spada contro Robert Shaw, Sean Connery si procurò una dolorosa ferita a un dito che rese necessario l''uso di una controfigura per alcune inquadrature ravvicinate delle mani.', 'Note di produzione e biografie ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:54:16.225937+00:00'),
('3cf910ac-9d8a-4f8e-ac1f-9dd52fd92821', 61, 'Casting & Scelte', 'Il cameo sfumato di Keith Richards', 'Keith Richards, chitarrista dei Rolling Stones e principale fonte di ispirazione per la gestualità di Jack Sparrow, avrebbe dovuto riprendere il ruolo del padre Teague nel film. Tuttavia, a causa di conflitti di programmazione con il tour della band, la sua presenza è saltata, aprendo la strada all''apparizione di Paul McCartney come zio.', 'Intervista ai registi Joachim Rønning ed Espen Sandberg per Entertainment Weekly', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:53:52.393501+00:00'),
('b4d889a9-e030-4636-9d12-a2f53ab6a677', 61, 'Segreti di produzione', 'La riproduzione in scala della ghigliottina', 'Per la sequenza in cui Jack Sparrow rischia la decapitazione nella piazza di Saint Martin, la produzione ha costruito una ghigliottina perfettamente funzionante e bilanciata meccanicamente. Johnny Depp ha insistito per girare la scena con la testa realmente posizionata sotto la lama (ovviamente bloccata da appositi sistemi di sicurezza), rifiutando la controfigura.', 'Note di produzione ufficiali Disney e featurette del Blu-ray', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:53:52.393501+00:00'),
('225ca92c-e03e-4b8d-8920-699a3360267a', 61, 'Effetti speciali & Trucco', 'Il ritorno di Orlando Bloom e la protesi facciale', 'Per riprendere i panni di Will Turner dopo l''assenza nel quarto capitolo, Orlando Bloom ha dovuto sottoporsi a lunghe sessioni giornaliere di trucco prostetico. Gli artisti degli effetti speciali guidati da Joel Harlow hanno applicato alghe, conchiglie e barnacoli finti sul suo volto per simulare la maledizione simbiotica dell''Olandese Volante.', 'Dietro le quinte ufficiale del making-of ''Dead Men Tell No Tales: A Return to the Sea''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:53:52.393501+00:00'),
('b17372a4-e189-4db8-8f41-2a79f3d33e53', 61, 'Aneddoti dal set', 'La banca trainata dai cavalli a Gold Coast', 'La spettacolare scena in cui i cavalli trascinano via l''intero edificio della banca di Saint Martin è stata girata costruendo una facciata mobile pesante diverse tonnellate su un set all''aperto a Helensvale, nel Queensland. Per la sequenza sono stati impiegati oltre sessanta stuntmen e una squadra dedicata di dodici addestratori di animali per gestire i cavalli in sicurezza.', 'Reportage di produzione del Courier-Mail sui set australiani', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:53:52.393501+00:00'),
('2c185550-c37e-4e21-961b-0bb9b03d4478', 62, 'Curiosità & Retroscena', 'La consulenza del vero Jordan Belfort', 'Il vero Jordan Belfort ha lavorato a stretto contatto con Leonardo DiCaprio durante la pre-produzione, aiutandolo a perfezionare i comportamenti da tossicodipendente e le posture corporee sotto l''effetto di sostanze stupefacenti.', 'Interviste promozionali ufficiali del cast', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:53:59.452359+00:00'),
('e1399b47-785f-4e75-9521-1e3d200f1548', 62, 'Aneddoti dal set', 'L''improvvisazione della canzone dei marinai', 'La sequenza in cui Matthew McConaughey e Leonardo DiCaprio canticchiano e battono ritmicamente il petto nel ristorante non era originariamente nel copione: era un rituale di riscaldamento che McConaughey usava realmente nella vita privata prima di girare.', 'Audio commento e interviste di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:53:59.452359+00:00'),
('2959cce8-30d7-419e-8a3b-9d5f9970a730', 157, 'Casting & Scelte', 'Il ritorno confermato di Tom Hanks e Tim Allen', 'Nonostante l''età avanzata dei due storici doppiatori, Tom Hanks e Tim Allen sono stati ufficialmente confermati per riprendere i ruoli di Woody e Buzz Lightyear, garantendo la continuità vocale che caratterizza la saga dal 1995.', 'Annuncio ufficiale Disney Investor Day e note di produzione Pixar', TRUE, 'IA (Admin)', 'IA Verificata', 1, 1, '2026-11-02T17:57:49.396051+00:00'),
('18cbfdb2-3e86-4935-82e3-a5fa29f3238e', 62, 'Segreti di produzione', 'Il rifiuto del rating R e i tagli evitati', 'Il montaggio iniziale del film ricevette un divieto ai minori severo (NC-17) dalla MPAA per i contenuti sessuali espliciti; Martin Scorsese dovette sfumare digitalmente alcune inquadrature per ottenere il visto censura R, necessario per la distribuzione commerciale.', 'Report di settore cinematografico', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:53:59.452359+00:00'),
('8c2d6524-8bb4-4791-884d-f383ed5f5b8c', 62, 'Effetti speciali & Trucco', 'Il ghepardo vivo sul set', 'Nella scena in cui Jordan Belfort cammina con un ghepardo al guinzaglio, la produzione ha utilizzato un vero animale vivo per alcuni piani sequenza, per poi sostituirlo digitalmente con un esemplare in CGI nelle inquadrature più pericolose insieme agli attori.', 'Special TV sul backstage del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:53:59.452359+00:00'),
('c7f4096d-4c9b-43fc-9b84-745629078ea8', 157, 'Segreti di produzione', 'La transizione tematica verso l''era digitale', 'Il regista e CCO della Pixar Andrew Stanton ha impostato la trama centrale del film sulla competizione tra i giocattoli tradizionali e i dispositivi elettronici smart, riflettendo le reali problematiche dei bambini contemporanei nell''era degli smartphone e dei tablet.', 'D23 Expo e interviste ufficiali ad Andrew Stanton', TRUE, 'IA (Admin)', 'IA Verificata', 4, 2, '2026-11-02T17:57:49.396051+00:00'),
('a67a72bd-7e1e-4949-b804-7b95922c64d7', 157, 'Curiosità & Retroscena', 'La genesi del progetto annunciata da Bob Iger', 'Il film è stato annunciato ufficialmente dal CEO della Walt Disney Company Bob Iger nel febbraio 2023, durante una chiamata con gli azionisti, come parte della strategia aziendale di puntare sui franchise più forti e sicuri della società.', 'Comunicato finanziario ufficiale The Walt Disney Company, febbraio 2023', TRUE, 'IA (Admin)', 'IA Verificata', 1, 3, '2026-11-02T17:57:49.396051+00:00'),
('c8e9efad-d1a2-4ef0-b415-3f270e9ad24f', 157, 'Segreti di produzione', 'Il ritorno di Andrew Stanton alla regia', 'Andrew Stanton, già vincitore di due premi Oscar per la regia di ''Alla ricerca di Nemo'' e ''WALL-E'' e sceneggiatore di tutti i capitoli precedenti di Toy Story, è stato scelto per dirigere personalmente questo quinto capitolo della saga.', 'Crediti di produzione ufficiali Pixar Animation Studios', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T17:57:49.396051+00:00'),
('3ee1c43b-a0cc-4411-90a8-fcf0286a86f6', 64, 'Aneddoti dal set', 'L''infortunio di Basil Rathbone alle riprese', 'Basil Rathbone, provetto schermidore e campione di sciabola, rischiò seriamente di essere ferito ad un occhio durante le prove preliminari delle coreografie di combattimento, costringendo la produzione ad adottare ulteriori accorgimenti di sicurezza.', 'Memorie di Basil Rathbone e documentario sul set del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:54:10.120391+00:00'),
('c71d828f-43bf-4223-81ff-ac4acf2be11a', 344, 'Casting & Scelte', 'Il coinvolgimento di Lucy Boynton come protagonista e produttrice esecutiva', 'Lucy Boynton non solo è stata scelta per interpretare la protagonista Harriet, ma ha anche assunto il ruolo di produttrice esecutiva del film, contribuendo attivamente allo sviluppo emotivo del personaggio lungo tutto il percorso di lavorazione.', 'Note di produzione ufficiali Searchlight Pictures', TRUE, 'IA (Admin)', 'IA Verificata', 4, 1, '2026-11-02T17:58:49.075301+00:00'),
('95b2a478-4138-4e2a-ba7a-37e1f22736fd', 344, 'Casting & Scelte', 'Justin H. Min nel ruolo di co-protagonista', 'L''attore Justin H. Min, noto al grande pubblico per la serie The Umbrella Academy, è stato scelto per interpretare David, l''uomo che nel presente offre a Harriet una nuova prospettiva sentimentale e musicale.', 'Comunicato stampa ufficiale del cast', TRUE, 'IA (Admin)', 'IA Verificata', 3, 2, '2026-11-02T17:58:49.075301+00:00'),
('1b71c092-ed09-41ac-a5f4-6527dbca637e', 344, 'Curiosità & Retroscena', 'La genesi del progetto legata alla musicoterapia e al lutto', 'Il regista e sceneggiatore Ned Benson ha ideato la storia partendo da studi scientifici e aneddoti reali sulla cosiddetta ''memoria olfattiva e uditiva'', esplorando come determinate canzoni possano agire esattamente come ancore temporali per chi soffre di un trauma da perdita.', 'Intervista al regista su Deadline Hollywood', TRUE, 'IA (Admin)', 'IA Verificata', 4, 3, '2026-11-02T17:58:49.075301+00:00'),
('38c94d0b-613d-440a-9260-f7b007bf3990', 344, 'Segreti di produzione', 'Le riprese nei quartieri storici di Los Angeles', 'Per ricreare l''atmosfera malinconica e nostalgica del film, la troupe ha girato in location reali tra i negozi di dischi indipendenti e le strade di Los Angeles, cercando scorci urbani capaci di riflettere lo stato d''animo della protagonista.', 'Giornale di bordo della troupe e reportage di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 5, 4, '2026-11-02T17:58:49.075301+00:00'),
('4d3db534-c237-4d97-9e07-3a3f70d93b8b', 344, 'Curiosità & Retroscena', 'L''importanza della colonna sonora come motore narrativo', 'A differenza di molti drammi romantici dove la musica è un accompagnamento in post-produzione, in The Greatest Hits i brani d''epoca (inclusi brani iconici e tracce originali) sono stati scelti meticolosamente prima dell''inizio delle riprese per permettere agli attori di recitare sincronizzati con i ricordi musicali.', 'Note del supervisore musicale del film', TRUE, 'IA (Admin)', 'IA Verificata', 4, 5, '2026-11-02T17:58:49.075301+00:00'),
('d231e877-0587-46ef-8938-52b7ec7242d8', 65, 'Segreti di produzione', 'La scelta della Spagna per rimpiazzare la foresta di Sherwood', 'Le riprese principali si svolsero interamente in Spagna, tra le province di Madrid, Castiglia e León e Cuenca, poiché la produzione ritenne i paesaggi spagnoli più adatti e incontaminati rispetto a un''Inghilterra ormai troppo moderna.', 'Dichiarazioni del regista Richard Lester nel documentario d''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:54:16.225937+00:00'),
('40f6d044-b92b-4ae3-a8a9-8ca6e9892412', 65, 'Casting & Scelte', 'Il compenso record per il ritorno di Audrey Hepburn', 'Per convincere Audrey Hepburn a tornare sul set dopo nove anni, la produzione le offrì un compenso stimato intorno al milione di dollari dell''epoca, cifra considerevole per gli standard della United Artists per quel tipo di produzione.', 'Archivi storici della United Artists', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:54:16.225937+00:00'),
('d9cd11b1-f03b-4bfd-9b29-72b81f41703d', 66, 'Curiosità & Retroscena', 'Il compenso di Sean Connery devoluto in beneficenza', 'Per il suo breve cammeo di due giorni nei panni di Re Riccardo, Sean Connery pretese un compenso di 250.000 dollari. L''attore scozzese mantenne la parola data e devolse l''intera cifra in beneficenza a un fondo sanitario in Scozia.', 'Note di produzione ufficiali Warner Bros. / Interviste dell''epoca', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:54:50.669859+00:00'),
('70d7eba0-1116-4d7b-975f-6548af697f16', 66, 'Curiosità & Retroscena', 'L''iconico albero di Sycamore Gap', 'La celebre scena in cui Robin incontra l''albero isolato lungo il cammino per Locksley venne girata al Sycamore Gap Tree, lungo il Vallo di Adriano nel Northumberland. Quell''acero secolare è diventato da allora famoso in tutto il mondo con il soprannome di ''Robin Hood''s Tree''.', 'Documentario sulle location britanniche del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:54:50.669859+00:00'),
('793514bd-70f2-463c-81cb-1e896a98d2d4', 66, 'Segreti di produzione', 'La rottura tra Kevin Reynolds e Kevin Costner in montaggio', 'Durante la fase di montaggio finale emersero duri contrasti tra il regista Kevin Reynolds e Kevin Costner. Temendo che le esilaranti improvvisazioni di Alan Rickman oscurassero il protagonista, la produzione e Costner ridussero il minutaggio dello Sceriffo, spingendo Reynolds ad abbandonare la post-produzione prima della premiere.', 'Intervista al regista Kevin Reynolds / Retroscena di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:54:50.669859+00:00'),
('ebf1498d-aa65-4e2d-af10-96e1bfbf5d21', 66, 'Citazioni & Easter Egg', 'L''anacronismo storico del telescopio di Azeem', 'Nel film il personaggio di Azeem (Morgan Freeman) mostra a Robin un telescopio portatile per avvistare i nemici a distanza. Dal punto di vista storico si tratta di un anacronismo di oltre quattro secoli, dato che la storia è ambientata nel 1194 e i primi cannocchiali vennero brevettati solo nel 1608.', 'Commento audio della produzione / Analisi storiche cinematografiche', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:54:50.669859+00:00'),
('bdcd5c04-6a2c-416b-9380-7d69358d6c7d', 66, 'Segreti di produzione', 'La riluttanza del compositore Michael Kamen', 'Il celebre compositore Michael Kamen inizialmente non voleva curare la colonna sonora del film, scontento del primo montaggio grezzo mostratogli dalla produzione. Dopo essersi ricreduto accettò l''incarico, componendo una delle colonne sonore orchestrali più iconiche degli anni ''90 e ricevendo una candidatura agli Oscar.', 'Intervista a Michael Kamen / Note dell''album della colonna sonora', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:54:50.669859+00:00'),
('c0cb8aca-bdcb-4097-8b29-d01092fea14b', 66, 'Aneddoti dal set', 'Le riprese gelide alla cascata di Hardraw Force', 'La sequenza in cui Robin si lava nudo sotto la cascata venne girata presso Hardraw Force nel North Yorkshire. L''acqua era così fredda che le riprese dovettero essere effettuate a ritmi serrati e con il supporto temporaneo di una controfigura per evitare l''ipotermia dell''attore.', 'Making-of ufficiale della pellicola / Note di regia', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:54:50.669859+00:00'),
('4bed8adc-16fe-48f7-83ee-a649353c76e7', 66, 'Effetti speciali & Trucco', 'L''uso di armi d''assedio reali e funzionanti', 'Le catapulte e i trabucchi impiegati durante l''attacco dei mercenari al campo e l''assalto finale non erano modellini o ricostruzioni scenografiche passive, ma vere armi d''assedio funzionanti a grandezza naturale, costruite seguendo fedelmente progetti di ingegneria medievale del XIII secolo.', 'Featurette speciale ''Behind the Scenes'' della Warner Bros.', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 6, '2026-11-02T09:54:50.669859+00:00'),
('883a5473-d380-44f0-89e5-88c47a7ce5ec', 67, 'Curiosità & Retroscena', 'L''ispirazione iniziale nata da Errol Flynn', 'Mel Brooks ha più volte dichiarato nelle interviste promozionali del film di aver concepito l''idea di una parodia definitiva su Robin Hood fin da quando era bambino, rimanendo folgorato dal classico del 1938 ''Le avventure di Robin Hood'' interpretato da Errol Flynn.', 'Audio commento del regista e interviste d''archivio', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:54:58.030734+00:00'),
('a6ff1690-bf44-4705-8e4e-08c33d702783', 67, 'Segreti di produzione', 'La riscrittura del finale con la lettera della regina', 'La scena in cui compare improvvisamente la Regina Giovanna (interpretata da Megan Cavanagh) che consegna un''inaspettata grazia reale non era presente nelle prime bozze della sceneggiatura, ma fu aggiunta all''ultimo minuto da Mel Brooks e dal co-sceneggiatore J.D. Shapiro per accelerare una chiusura comica e surreale della trama.', 'Note di produzione e sceneggiatura originale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:54:58.030734+00:00'),
('d70ba549-7847-4c15-806f-52d533ecc709', 67, 'Casting & Scelte', 'La partecipazione speciale di Dom DeLuise', 'Il celebre attore e collaboratore di lunga data di Mel Brooks, Dom DeLuise, avrebbe dovuto avere un cameo più esteso nel film nei panni di un frate, ma a causa di conflitti di programmazione la sua apparizione fu drasticamente ridotta.', 'Cronache di produzione del set di Los Angeles', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:54:58.030734+00:00'),
('f568a14b-cc4d-4264-846b-bd8b1f4361e6', 68, 'Segreti di produzione', 'La scelta del budget e l''investimento di Lionsgate', 'Il film è stato finanziato principalmente da Lionsgate con un budget di circa 100 milioni di dollari, una cifra considerevole per una rilettura moderna e d''azione di un classico della letteratura inglese. La produzione puntava a replicare il successo di franchise in stile ''Hunger Games'' o ''Assassin''s Creed'', puntando fortemente sul mercato internazionale.', 'Variety Production Report 2018', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:04.899189+00:00'),
('3703d37a-14f6-49f4-bd72-d1e035d09d13', 68, 'Curiosità & Retroscena', 'La progettazione dei costumi tra passato e presente', 'La costumista Julian Day ha ideato un guardaroba volutamente anacronistico per fondere l''immaginario medievale con l''estetica punk e moderna. Per il personaggio di Ben Mendelsohn (lo Sceriffo di Nottingham), Day si è ispirata ai magnati della moda contemporanea e ai dittatori moderni, utilizzando pellicce e cappotti sartoriali rigidi per accentuare la sua aura autoritaria.', 'Note di produzione ufficiali Lionsgate', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:04.899189+00:00'),
('f8ddc0ed-8754-4a0e-b339-442346eb3a99', 68, 'Aneddoti dal set', 'L''infortunio sul set di Taron Egerton', 'Durante le riprese delle sequenze d''azione più impegnative, Taron Egerton ha riportato diversi lividi e piccoli infortuni muscolari, data la richiesta fisica costante delle coreografie di lotta. L''attore ha insistito per girare gran parte dei combattimenti corpo a corpo senza l''ausilio di controfigure per mantenere alta la verosimiglianza visiva voluta dal regista.', 'Behind the scenes featurette ufficiale', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:04.899189+00:00'),
('926c5b4d-7049-4642-8fc3-6bc0938aa0e8', 68, 'Segreti di produzione', 'La scelta di Budapest per le riprese principali', 'Sebbene la storia sia ambientata in Inghilterra, gran parte delle riprese del film si è svolta a Budapest e dintorni, in Ungheria, tra febbraio e maggio 2017. La capitale ungherese è stata scelta sia per i generosi incentivi fiscali offerti dalla produzione locale sia per la versatilità delle sue architetture storiche e dei teatri di posa.', 'The Hollywood Reporter location report', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:04.899189+00:00'),
('e064368f-1b8f-44aa-9aa3-9494a0eb1ee0', 69, 'Aneddoti dal set', 'L''infortunio di Russell Crowe durante un salto', 'Durante le riprese della sequenza della battaglia iniziale, Russell Crowe si è infortunato saltando da un castello di prua di una nave senza l''uso di una protezione adeguata per attutire l''impatto, riportando la rottura di entrambi i tendini d''Achille che ha nascosto alla produzione per mesi per evitare interruzioni.', 'Intervista ufficiale di Russell Crowe a 60 Minutes', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:11.451672+00:00'),
('355f13a9-2519-4b2d-a2f0-698f25c6f052', 69, 'Segreti di produzione', 'Il rifiuto iniziale del compositore e l''arrivo di Marc Streitenfeld', 'Ridley Scott aveva inizialmente contattato il celebre compositore Harry Gregson-Williams per la colonna sonora, ma a causa di conflitti di scheduling il progetto fu affidato a Marc Streitenfeld, collaboratore di lunga data del regista, che ha integrato strumenti medievali autentici registrati con ensemble storici.', 'Note di produzione e press kit ufficiale Universal Pictures', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:11.451672+00:00'),
('70d6c11b-e187-482e-aad4-c3710fccec96', 69, 'Effetti speciali & Trucco', 'L''uso di veri fabbri medievali per le armature', 'Per garantire la massima accuratezza storica ed evitare l''aspetto troppo patinato di Hollywood, il reparto costumi guidato da Janty Yates ha collaborato con fabbri professionisti per forgiare centinaia di vere cotte di maglia e piastre d''acciaio pesanti anziché utilizzare controparti in plastica o gomma piuma.', 'Featurette ''Designing the Epoch'' nel Blu-ray ufficiale del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:11.451672+00:00'),
('33116e5b-fd4f-461a-9103-080d9341dfb2', 69, 'Segreti di produzione', 'Il taglio della versione cinematografica e l''edizione Director''s Cut', 'Il film ha subito tagli significativi prima dell''uscita nelle sale per rientrare nella durata commerciale imposta dallo studio, portando Ridley Scott a rilasciare successivamente una Director''s Cut che ripristina 15 minuti di sequenze politiche e drammatiche cruciali per comprendere le motivazioni dei baroni.', 'Commento audio del regista Ridley Scott nell''edizione home video', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:11.451672+00:00'),
('ea5ec709-8f9c-4fff-9fe0-6f1b3198f136', 71, 'Aneddoti dal set', 'Il malore di Kenny Baker all''interno di R2-D2', 'Durante le riprese nelle zone paludose ricostruite agli Elstree Studios per ambientare Dagobah, l''attore Kenny Baker rimase intrappolato dentro il costume di R2-D2 per ore. A causa dell''umidità e del fango, l''attore svenne all''interno del robot e fu salvato in extremis dalla troupe che aprì la struttura per farlo respirare.', 'Intervista retrospettiva a Kenny Baker e documentario Classic Creatures: Return of the Jedi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:19.290946+00:00'),
('eb38261c-1d84-4233-af42-2cbf2c9d2fdf', 71, 'Effetti speciali & Trucco', 'La finta mano tagliata sul set di Cloud City', 'Nel celebre duello nella Città delle Nuvole, Mark Hamill indossava una protesi in lattice per simulare la mano mozzata da Darth Vader. La scena richiese l''uso di tubicini nascosti nella manica per spruzzare sangue finto e il coordinatore degli stuntman prese il posto dell''attore nei piani d''ascolto più pericolosi.', 'Note di produzione e making-of d''archivio della Industrial Light & Magic', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:19.290946+00:00'),
('c6417dd7-e399-4ef7-b633-60838c206c91', 71, 'Segreti di produzione', 'Il congelamento improvisato nella carbonite', 'Per ottenere l''effetto realistico del vapore e della foschia attorno al blocco di carbonite in cui viene ibernato Ian Solo, la produzione utilizzò una combinazione di fumo denso e luci stroboscopiche nascoste sotto la piattaforma. Harrison Ford dovette trattenere il respiro mentre la lastra metallica veniva fatta scendere nel pavimento.', 'The Making of The Empire Strikes Back di J.W. Rinzler', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:19.290946+00:00'),
('d543baca-9d97-4296-81e9-ec810dae8700', 71, 'Casting & Selezioni', 'Il provino segreto di Jeremy Bulloch per Boba Fett', 'Jeremy Bulloch ottenne la parte del cacciatore di taglie Boba Fett quasi per caso, venendo chiamato sul set all''ultimo minuto perché il costume su misura calzava perfettamente alla sua taglia. L''attore non aveva mai letto un copione prima di indossare l''armatura e dovette basare i suoi movimenti sulla postura del personaggio.', 'Intervista ufficiale a Jeremy Bulloch nel documentario The Making of Star Wars', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:19.290946+00:00'),
('55b616a9-a622-417d-bda7-e83c5b46c6dc', 72, 'Segreti di produzione', 'Il titolo originale che spoilerava la fine', 'Il film era originariamente intitolato ''Revenge of the Jedi'' (La vendetta dello Jedi), e la 20th Century Fox arrivò a stampare migliaia di poster con questo titolo prima che George Lucas lo cambiasse all''ultimo minuto. Lucas decise che la parola ''vendetta'' non si addiceva alla filosofia dei Jedi, poiché la vendetta appartiene tradizionalmente al Lato Oscuro della Forza.', 'Note di produzione ufficiali e documentario ''Empire of Dreams''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:27.157598+00:00'),
('8a47b7be-38d2-4c82-a6a6-43a21f8cf2e5', 72, 'Casting & Scelte', 'La scelta del nome di Yoda', 'Il leggendario maestro Jedi Yoda, le cui scene finali e cruciali furono girate per questo capitolo, ha quasi rischiato di avere un nome completamente diverso. Nelle prime bozze di sceneggiatura della trilogia, il personaggio veniva chiamato ''Minch Yoda'', prima che gli sceneggiatori decidessero di accorciare il nome.', 'Archivi storici di Lucasfilm e bozze di sceneggiatura originali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:27.157598+00:00'),
('d3b1054b-e2a7-4d09-a547-83a47cf35985', 72, 'Citazioni & Easter Egg', 'Il cameo nascosto di John Landis', 'Il celebre regista di Hollywood John Landis visitò il set di ''Il ritorno dello Jedi'' durante le riprese e ottenne un cameo speciale. Indossando il costume completo di una delle guardie di sicurezza di Jabba the Hutt (un guardiano gamorreano), Landis appare brevemente nel palazzo di Jabba su Tatooine.', 'Commento audio del regista Richard Marquand e registri di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:27.157598+00:00'),
('3f8a5c93-ea20-44c7-9a05-0d5d12a06b79', 72, 'Effetti speciali & Trucco', 'La vera identità della voce di Jabba the Hutt', 'Il famigerato idioma parlato da Jabba the Hutt, noto come Huttese, non era un suono casuale ma fu ideato dal progettista del suono Ben Burtt basandosi sulla fonetica della lingua Quechua parlata dalle popolazioni indigene delle Ande. La voce profonda e gutturale fu registrata dall''attore di doppiaggio Larry Ward che parlava attraverso un apposito amplificatore.', 'Making-of ufficiale e documentazione del reparto sonoro Skywalker Sound', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:27.157598+00:00'),
('df364594-6b02-4ddc-9296-90c1530b9e6a', 73, 'Casting & Scelte', 'La voce di Yoda affidata a Frank Oz', 'Frank Oz è tornato a doppiare e manovrare il maestro Yoda in questo film, ma a differenza della trilogia originale in cui Yoda era un burattino analogico, qui è stato realizzato in CGI per gran parte della pellicola, fatta eccezione per alcune scene in cui è stato ricreato un burattino fisico basato sul design originale.', 'Documentario ''The Beginning: Making Episode I''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:35.05565+00:00'),
('71ab808a-290d-42ac-8be4-ad599fde1e28', 73, 'Effetti speciali & Trucco', 'La sedia da dentista usata per il trucco di Liam Neeson', 'Per applicare le complesse protesi auricolari e il trucco facciale che donavano a Liam Neeson l''aspetto del Maestro Jedi Qui-Gon Jinn, l''attore ha dovuto trascorrere ore su una sedia da dentista modificata nei Leavesden Studios durante ogni giorno di ripresa.', 'Note di produzione ufficiali e interviste al reparto trucco', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:35.05565+00:00'),
('1561d209-09f9-4187-b058-ec62ede7c1ea', 73, 'Curiosità & Retroscena', 'Il cameo di Sofia Coppola come ancella', 'La celebre regista e sceneggiatrice Sofia Coppola ha fatto un cameo nel film interpretando Saché, una delle ancelle della Regina Amidala (Natalie Portman), accettando il ruolo dopo aver visitato il set durante le riprese in Italia.', 'Crediti del film e archivi di produzione Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:35.05565+00:00');
INSERT INTO public.movie_trivia ("id", "film_id", "categoria", "titolo", "descrizione", "fonte", "approvato", "inserito_da", "provenienza", "likes", "ordine", "created_at") VALUES
('abc2c3d4-baaa-4420-b66e-0cd041880d49', 73, 'Segreti di produzione', 'Le riprese italiane alla Reggia di Caserta', 'Per gli interni del Palazzo Reale di Naboo, la produzione ha girato estensivamente all''interno della Reggia di Caserta in Italia, ottenendo il permesso speciale di filmare nelle sale storiche nonostante le rigide restrizioni per la conservazione del patrimonio artistico.', 'Cronache di produzione e backstage ufficiali', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:35.05565+00:00'),
('d4580cef-99c3-4940-91b1-109c9bcd2cc5', 73, 'Aneddoti dal set', 'L''infortunio alla schiena di Ahmed Best', 'Ahmed Best, l''attore che ha dato voce e movimento a Jar Jar Binks indossando una tuta per il motion capture e un costume di gommapiuma, ha subito un grave infortunio alla schiena durante le riprese a causa del peso della testa del costume e dei movimenti acrobatici richiesti.', 'Intervista retrospettiva ad Ahmed Best', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:55:35.05565+00:00'),
('e9644778-f1ac-444b-bca0-a32c365b37a8', 73, 'Curiosità & Retroscena', 'La partecipazione dei figli di George Lucas nel film', 'Tutti e tre i figli di George Lucas (Jet, Amanda e Katie) hanno fatto piccoli camei non accreditati nel film: Jet appare come un giovane padawan di nome Whie Malreaux, Amanda interpreta una bambina di Coruscant e Katie compare come una ragazza nel negozio di Watto.', 'Archivio ufficiale Star Wars e crediti estesi', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 5, '2026-11-02T09:55:35.05565+00:00'),
('519b4f23-e811-423b-b0b6-90078eccaa2a', 165, 'Curiosità & Retroscena', 'Il ritorno in lingua inglese di Iñárritu', 'Il progetto segna il ritorno alla regia in lingua inglese per Alejandro González Iñárritu a distanza di oltre dieci anni dal successo di The Revenant (2015), dopo aver realizzato nel 2022 la commedia drammatica autobiografica Bardo - La cronaca falsa di alcune verità in lingua spagnola.', 'Variety / Comunicato Warner Bros.', TRUE, 'IA (Admin)', 'IA Verificata', 4, 1, '2026-11-02T18:12:12.349084+00:00'),
('ef300ad6-c66a-4a79-a97e-3c805eb68f1f', 165, 'Casting & Scelte', 'Il patto strategico tra Tom Cruise e Warner', 'Il lungometraggio è il primo titolo sviluppato da Tom Cruise nell''ambito della partnership strategica e produttiva stipulata nel gennaio 2024 con Warner Bros. Motion Picture Group, guidata dai co-presidenti e CEO Michael De Luca e Pam Abdy.', 'The Hollywood Reporter', TRUE, 'IA (Admin)', 'IA Verificata', 2, 2, '2026-11-02T18:12:12.349084+00:00'),
('fa4e14fb-6505-4509-8266-92d38ba5aa56', 165, 'Segreti di produzione', 'La reunion del team di sceneggiatori di Birdman', 'Per la scrittura della sceneggiatura originale, Iñárritu ha riunito i co-autori argentini Alexander Dinelaris e Nicolás Giacobone, con i quali aveva vinto l''Oscar alla miglior sceneggiatura originale nel 2015 per Birdman, coinvolgendo nel processo creativo anche la drammaturga messicana Sabina Berman.', 'Deadline Hollywood', TRUE, 'IA (Admin)', 'IA Verificata', 3, 3, '2026-11-02T18:12:12.349084+00:00'),
('694e6950-606b-44d5-99f3-8d5d8d7375cb', 165, 'Casting & Scelte', 'Il prestigioso cast corale internazionale', 'Attorno a Cruise la produzione ha assemblato un cast di acclamati interpreti internazionali, includendo l''attrice tedesca Sandra Hüller reduce dal successo critico di Anatomia di una caduta e La zona d''interesse, insieme a John Goodman, Jesse Plemons, Michael Stuhlbarg, Sophie Wilde e Riz Ahmed.', 'Deadline Hollywood / Note di produzione', TRUE, 'IA (Admin)', 'IA Verificata', 2, 4, '2026-11-02T18:12:12.349084+00:00'),
('bc0fe5c0-e952-442f-9e24-533cb4f28a62', 165, 'Segreti di produzione', 'L''alleanza finanziaria con Legendary Entertainment', 'Il film è nato come una coproduzione ad alto budget tra Warner Bros. Pictures e Legendary Entertainment, sviluppata sotto la più rigorosa segretezza prima dell''avvio delle riprese principali stabilite in teatri di posa e location del Regno Unito.', 'Production Weekly / Variety', TRUE, 'IA (Admin)', 'IA Verificata', 3, 5, '2026-11-02T18:12:12.349084+00:00'),
('37108bdb-94a4-4f46-a5a3-a8bd80af8c49', 74, 'Casting & Scelte', 'La cicatrice di Harrison Ford prestata ad Anakin', 'Durante la fase di concezione del design di Anakin Skywalker per questo capitolo, George Lucas decise di aggiungere una vistosa cicatrice sul volto del personaggio. La cicatrice sul sopracciglio destro fu modellata esattamente sulla base di quella reale che Harrison Ford si era procurato in gioventù a causa di un incidente d''auto.', 'Documentario ''From Puppets to Pixels: The Making of Episode II'' e note di produzione', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:42.895145+00:00'),
('b73181a4-f4a7-42f0-a3d8-665f0ed4d072', 74, 'Aneddoti dal set', 'La ferita alla mano di Christopher Lee evitata grazie alla CGI', 'Durante le prove del duello finale, Christopher Lee colpì accidentalmente una parete con la mano, ferendosi gravemente alle dita. Poiché l''attore aveva 79 anni e la produzione temeva ritardi, il supervisore degli effetti visivi John Knoll dovette rimuovere digitalmente i lividi e i cerotti dalle mani di Lee nelle scene girate immediatamente dopo.', 'Commento audio ufficiale del Blu-ray del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:42.895145+00:00'),
('83916b22-3643-4ece-8995-9636754f4551', 74, 'Segreti di produzione', 'Il braccio bionico in gomma di Anakin', 'Nelle scene in cui Anakin Skywalker mostra il suo braccio protesico meccanico, Hayden Christensen non indossava un rig di metallo ma una protesi in gomma e poliuretano molto scomoda. L''attore doveva mantenere posizioni innaturali per ore, mentre la troupe applicava manualmente gli effetti di usura per simulare il metallo esposto.', 'Special report della rivista Cinefex sul making-of del film', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:42.895145+00:00'),
('a811ea5f-cba7-4142-b6c8-a4e49e4f5488', 74, 'Casting & Scelte', 'La richiesta di Samuel L. Jackson per la spada laser', 'Samuel L. Jackson chiese espressamente a George Lucas di avere una spada laser di colore viola per il suo personaggio, Mace Windu, in modo da poterlo individuare facilmente in mezzo alla grande mischia dei Jedi nell''arena di Geonosis. Lucas acconsentì alla richiesta, rompendo la tradizione che voleva spade solo blu, verdi o rosse.', 'Intervista d''archivio a Samuel L. Jackson per il talk show di Graham Norton', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:42.895145+00:00'),
('14fa7cfb-169e-4363-9c63-52498f01ecc2', 74, 'Citazioni & Easter Egg', 'Il cameo vocale di Silas Carson come vicario e cavaliere', 'L''attore Silas Carson, oltre a interpretare fisicamente il Viceré Nute Gunray della Federazione dei Mercanti, ha prestato la sua voce in un breve cameo vocale non accreditato per il Maestro Jedi Ki-Adi-Mundi in alcune scene chiave del Consiglio Jedi.', 'Credits ufficiali e guide enciclopediche della Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:55:42.895145+00:00'),
('7649daca-5cd1-43fd-aef5-2990a2c87e43', 75, 'Effetti speciali & Trucco', 'La voce modificata del Generale Grievous', 'Per ottenere la caratteristica voce roca e metallica del Generale Grievous, il sound designer Matthew Wood ha dovuto superare una forte laringite che lo aveva colpito durante i provini, registrando la sua voce e filtrandola poi attraverso un ventilatore e altri modulatori digitali.', 'Documentario ''It''s All for Real'' - Special Features del DVD', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 0, '2026-11-02T09:55:51.128514+00:00'),
('eff40c7b-a320-4f74-a285-36d5ae658db8', 75, 'Aneddoti dal set', 'La polmonite sul set di Ewan McGregor', 'Durante le riprese delle sequenze subacquee e di combattimento sul pianeta Utapau, l''attore Ewan McGregor contrasse una grave forma di bronchite che rischiò di bloccare la produzione, costringendo la troupe a riorganizzare il piano di lavoro per permettergli le cure necessarie.', 'Audio Commento del regista e della troupe', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 1, '2026-11-02T09:55:51.128514+00:00'),
('81f0be71-fecf-4178-83ed-6ba7cd9d4fae', 75, 'Citazioni & Easter Egg', 'Il cameo di Rick McCallum nei panni di un senatore', 'Il produttore storico della trilogia prequel, Rick McCallum, appare brevemente in un cameo non accreditato nel film, interpretando il Senatore Itt Austin durante le sedute del Senato Galattico.', 'Archivi ufficiali di produzione Star Wars', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 2, '2026-11-02T09:55:51.128514+00:00'),
('21ee8fe0-ffd6-4e82-a94b-d20ff6fb654a', 75, 'Segreti di produzione', 'Il record di set digitali e bluescreen', 'La vendetta dei Sith stabilì un record mondiale per l''epoca con ben 2.151 inquadrature in CGI, superando qualsiasi altra produzione precedente e utilizzando set completamente virtuali costruiti interamente presso gli studi Fox di Sydney.', 'Making-of ufficiale ''Star Wars: Episode III - The Making of the Movie''', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 3, '2026-11-02T09:55:51.128514+00:00'),
('151a9d6a-a045-4d9b-aa4c-73ca18e93f68', 75, 'Casting & Scelte', 'La nascita del nome di Darth Vader in lingua italiana', 'Sebbene il nome Vader sia ormai iconico, durante le prime fasi di sviluppo e traduzione dei dialoghi della trilogia originale e dei prequel, i produttori dovettero gestire le specifiche linee guida di George Lucas per mantenere intatta la fonetica minacciosa del personaggio in tutte le lingue, incluso l''adattamento italiano curato da Filippo Ottoni.', 'Note di edizione e doppiaggio italiano Lucasfilm', TRUE, 'IA (Daily Sync)', 'IA Verificata', 0, 4, '2026-11-02T09:55:51.128514+00:00'),
('23838912-d885-4027-8a17-4b81c2fe5dab', 132, 'Segreti di produzione', 'Il ritorno del duo McKenna e Sommers alla sceneggiatura', 'La stesura del copione è stata affidata nuovamente a Chris McKenna ed Erik Sommers, già co-sceneggiatori di ''Spider-Man: Homecoming'', ''Far From Home'' e ''No Way Home''. I produttori Kevin Feige e Amy Pascal hanno confermato la scelta per garantire una continuità narrativa coerente dopo il finale di ''No Way Home''.', 'Deadline Hollywood (Settembre 2024)', TRUE, 'IA (Admin)', 'IA Verificata', 5, 2, '2026-11-02T18:13:07.658225+00:00'),
('2a868221-71da-41e7-8dc6-d797dd8ace15', 132, 'Curiosità & Retroscena', 'La lettura congiunta della bozza con Zendaya', 'Nell''ottobre 2024, durante un''intervista al podcast di Rich Roll, Tom Holland ha rivelato di aver letto una prima versione della sceneggiatura insieme a Zendaya. L''attore ha raccontato che la lettura li ha entusiasmati al punto da farli saltare in salotto, confermando che la bozza rispondeva pienamente agli standard richiesti per proseguire la storia di Peter Parker.', 'Intervista di Tom Holland al podcast ''Rich Roll'' (Ottobre 2024)', TRUE, 'IA (Admin)', 'IA Verificata', 4, 3, '2026-11-02T18:13:07.658225+00:00'),
('eef812ea-1bbe-41d8-ae9c-75d02c920a01', 132, 'Segreti di produzione', 'L''annuncio del calendario delle riprese da Jimmy Fallon', 'Ospite al ''Tonight Show Starring Jimmy Fallon'' nell''ottobre 2024, Tom Holland ha confermato per la prima volta in televisione l''avvio della produzione per l''estate successiva. Pochi giorni dopo, Sony Pictures ha fissato ufficialmente la data d''uscita nelle sale per il 24 luglio 2026.', 'The Tonight Show Starring Jimmy Fallon (Ottobre 2024)', TRUE, 'IA (Admin)', 'IA Verificata', 5, 4, '2026-11-02T18:13:07.658225+00:00');
